#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct ChannelQualityIndication {
    float signal_strength;
    float noise_level;
    float interference_level;
} ChannelQualityIndication;

typedef struct FrameMetadata {
    int frame_id;
    time_t timestamp;
    ChannelQualityIndication *indicators;
    size_t num_indicators;
} FrameMetadata;

typedef struct ListNode {
    FrameMetadata *data;
    struct ListNode *next;
} ListNode;

typedef struct LinkedList {
    pthread_mutex_t lock;
    ListNode *head;
    ListNode *tail;
} LinkedList;

LinkedList* linked_list_create() {
    LinkedList *list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void linked_list_destroy(LinkedList *list) {
    ListNode *current = list->head;
    while (current != NULL) {
        ListNode *next = current->next;
        free(current->data->indicators);
        free(current->data);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void linked_list_append(LinkedList *list, FrameMetadata *metadata) {
    pthread_mutex_lock(&list->lock);
    ListNode *new_node = (ListNode*)malloc(sizeof(ListNode));
    new_node->data = metadata;
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

FrameMetadata* linked_list_get_by_id(LinkedList *list, int frame_id) {
    pthread_mutex_lock(&list->lock);
    ListNode *current = list->head;
    while (current != NULL) {
        if (current->data->frame_id == frame_id) {
            FrameMetadata *result = current->data;
            pthread_mutex_unlock(&list->lock);
            return result;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

// Add more functions as needed for your library, including filtering and metric computation

int main() {
    LinkedList *list = linked_list_create();

    // Example usage
    FrameMetadata *metadata = (FrameMetadata*)malloc(sizeof(FrameMetadata));
    metadata->frame_id = 1;
    metadata->timestamp = time(NULL);
    metadata->indicators = (ChannelQualityIndication*)malloc(sizeof(ChannelQualityIndication));
    metadata->num_indicators = 1;
    metadata->indicators[0].signal_strength = 95.0;
    metadata->indicators[0].noise_level = -20.0;
    metadata->indicators[0].interference_level = -30.0;

    linked_list_append(list, metadata);

    FrameMetadata *retrieved_metadata = linked_list_get_by_id(list, 1);
    if (retrieved_metadata != NULL) {
        printf("Retrieved frame ID: %d\n", retrieved_metadata->frame_id);
        printf("Signal Strength: %.2f\n", retrieved_metadata->indicators[0].signal_strength);
    }

    linked_list_destroy(list);

    return 0;
}
