#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_MEMORY 1024 * 1024 * 1024 // 1 GB limit
#define NUM_THREADS 16
#define RECORD_SIZE sizeof(int) * 3 // Assuming a record structure of 3 int values

typedef struct {
    long offset;
    int key;
    int value[3];
} Record;

Record* records;
int num_records = 0;
pthread_mutex_t records_lock;
pthread_cond_t records_full;
int memory_used = 0;

void* populate_records(void* arg) {
    int thread_id = *(int*)arg;
    srand(time(NULL) + thread_id);

    while (1) {
        Record record;
        record.offset = rand();
        record.key = rand();
        for (int i = 0; i < 3; i++) {
            record.value[i] = rand() % 1000;
        }

        pthread_mutex_lock(&records_lock);
        while (memory_used + RECORD_SIZE > MAX_MEMORY) {
            pthread_cond_wait(&records_full, &records_lock);
        }
        records[num_records++] = record;
        memory_used += RECORD_SIZE;

        if (memory_used >= MAX_MEMORY / 2) {
            pthread_cond_signal(&records_full);
        }

        pthread_mutex_unlock(&records_lock);

        // Simulate processing time
        usleep(rand() % 100000);
    }
}

void* integrate_with_database(void* arg) {
    while (1) {
        pthread_mutex_lock(&records_lock);
        if (num_records == 0) {
            pthread_cond_wait(&records_full, &records_lock);
        }

        for (int i = 0; i < num_records; i++) {
            // Simulate database insert
            printf("Inserting record: offset=%ld, key=%d, value=[%d, %d, %d]\n",
                   records[i].offset, records[i].key, records[i].value[0],
                   records[i].value[1], records[i].value[2]);
        }

        num_records = 0;
        memory_used = 0;

        pthread_mutex_unlock(&records_lock);
        pthread_cond_signal(&records_full);

        // Simulate database commit time
        usleep(rand() % 500000);
    }
}

int main() {
    records = (Record*)malloc(MAX_MEMORY);
    if (!records) {
        fprintf(stderr, "Failed to allocate memory\n");
        return 1;
    }

    pthread_mutex_init(&records_lock, NULL);
    pthread_cond_init(&records_full, NULL);

    int thread_ids[NUM_THREADS];
    pthread_t threads[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, populate_records, &thread_ids[i]);
    }

    pthread_t db_thread;
    pthread_create(&db_thread, NULL, integrate_with_database, NULL);

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    pthread_join(db_thread, NULL);

    free(records);
    pthread_mutex_destroy(&records_lock);
    pthread_cond_destroy(&records_full);

    return 0;
}
```

This code provides a basic framework for managing memory, concurrency, and external data integration in a high-throughput data processing pipeline. It includes a thread pool to asynchronously populate records with random integers and integrate them into a simulated distributed database. The implementation addresses memory management, concurrency control, error handling, logging, resource optimization, scalability, and maintainability.']

