            fprintf(stderr, "Error opening input file %s\n", argv[1]);
            return 1;
        }
    } else if (argc < 2) {
        printf("Usage: %s [-f input_file] [-o output_file] [--manpage]\n", argv[0]);
        return 1;
    }

    // Main processing loop
