#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define constants
#define MAX_INPUT_SIZE 1024
#define BUFFER_INCREMENT 1024

// Function prototypes
int readIntegers(int **array);
void processIntegers(int *array, int count);

int main() {
    int *array = NULL;
    int count = readIntegers(&array);

    if (count > 0) {
        processIntegers(array, count);
    }

    free(array);
    return 0;
}

// Function to read integers from standard input
int readIntegers(int **array) {
    char buffer[MAX_INPUT_SIZE];
    int count = 0;
    size_t arraySize = BUFFER_INCREMENT;

    *array = (int *)malloc(arraySize * sizeof(int));
    if (*array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    while (fgets(buffer, MAX_INPUT_SIZE, stdin) != NULL) {
        char *token = strtok(buffer, " \n\t");
        while (token != NULL && sscanf(token, "%d", &(*array)[count]) == 1) {
            count++;

            if (count >= arraySize) {
                arraySize += BUFFER_INCREMENT;
                void *newArray = realloc(*array, arraySize * sizeof(int));
                if (newArray == NULL) {
                    fprintf(stderr, "Memory reallocation failed\n");
                    free(*array);
                    *array = NULL;
                    return -1;
                }
                *array = newArray;
            }

            token = strtok(NULL, " \n\t");
        }
    }

    if (feof(stdin)) {
        printf("End of file reached.\n");
    } else if (ferror(stdin)) {
        perror("Error reading from standard input");
    }

    return count;
}

// Function to process integers and find the largest one
void processIntegers(int *array, int count) {
    if (count == 0) {
        printf("No integers processed.\n");
        return;
    }

    // Simple linear search for the largest integer
    int largest = array[0];
    for (int i = 1; i < count; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}
