// Import necessary libraries
import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import com.fasterxml.jackson.databind.ObjectMapper;

public class PokemonService {

    private static final String API_URL = "https://pokeapi.co/api/v2/pokemon/{pokemonName}";
    private static final HttpClient client = HttpClient.newHttpClient();
    private static final ObjectMapper mapper = new ObjectMapper();

    public static void main(String[] args) {
        try {
            String pokemonDetails = getPokemonDetails("pikachu");
            System.out.println(pokemonDetails);
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    public static String getPokemonDetails(String pokemonName) throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(API_URL.replace("{pokemonName}", pokemonName)))
                .GET()
                .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

        if (response.statusCode() == 200) {
            PokemonResponse pokemonResponse = mapper.readValue(response.body(), PokemonResponse.class);
            return "Name: " + pokemonResponse.getName() +
                    ", Type: " + String.join(", ", pokemonResponse.getTypes().stream()
                            .map(Type::getTypeName)
                            .toArray(String[]::new)) +
                    ", Height: " + pokemonResponse.getHeight() +
                    ", Weight: " + pokemonResponse.getWeight();
        } else {
            throw new IOException("Failed to fetch Pokemon details. Status code: " + response.statusCode());
        }
    }

    // Define classes for deserializing JSON response
    static class PokemonResponse {
        private String name;
        private int height;
        private int weight;
        private List<Type> types;

        public String getName() {
            return name;
        }

        public List<Type> getTypes() {
            return types;
        }

        public int getHeight() {
            return height;
        }

        public int getWeight() {
            return weight;
        }
    }

    static class Type {
        private PokemonType type;

        public PokemonType getType() {
            return type;
        }

        static class PokemonType {
            private String name;

            public String getTypeName() {
                return name;
            }
        }
    }
}
