#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

typedef struct {
    char *name;
    void (*hash)(const unsigned char *, size_t, unsigned char *);
    void (*cipher_encrypt)(unsigned char *, const unsigned char *, const unsigned char *);
    void (*cipher_decrypt)(unsigned char *, const unsigned char *, const unsigned char *);
} CryptoAlgorithm;

typedef struct {
    CryptoAlgorithm **algorithms;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int dirty;
} AlgorithmCache;

AlgorithmCache *cache = NULL;

void init_cache(size_t initial_capacity) {
    cache = (AlgorithmCache *)malloc(sizeof(AlgorithmCache));
    cache->algorithms = (CryptoAlgorithm **)calloc(initial_capacity, sizeof(CryptoAlgorithm *));
    cache->count = 0;
    cache->capacity = initial_capacity;
    pthread_mutex_init(&cache->lock, NULL);
    pthread_cond_init(&cache->cond, NULL);
    cache->dirty = 1;
}

void destroy_cache() {
    for (size_t i = 0; i < cache->count; ++i) {
        free(cache->algorithms[i]->name);
        free(cache->algorithms[i]);
    }
    free(cache->algorithms);
    pthread_mutex_destroy(&cache->lock);
    pthread_cond_destroy(&cache->cond);
    free(cache);
}

void update_cache() {
    // Simulate fetching algorithms from the remote service
    pthread_mutex_lock(&cache->lock);
    if (!cache->dirty) {
        pthread_cond_wait(&cache->cond, &cache->lock);
    }
    cache->algorithms[0] = (CryptoAlgorithm *)malloc(sizeof(CryptoAlgorithm));
    cache->algorithms[0]->name = strdup("SHA-256");
    cache->algorithms[0]->hash = sha256_hash;
    cache->algorithms[1] = (CryptoAlgorithm *)malloc(sizeof(CryptoAlgorithm));
    cache->algorithms[1]->name = strdup("AES-256-CBC");
    cache->algorithms[1]->cipher_encrypt = aes_256_cbc_encrypt;
    cache->algorithms[1]->cipher_decrypt = aes_256_cbc_decrypt;
    cache->count = 2;
    cache->dirty = 0;
    pthread_cond_signal(&cache->cond);
    pthread_mutex_unlock(&cache->lock);
}

CryptoAlgorithm *get_algorithm(const char *name) {
    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->count; ++i) {
        if (strcmp(cache->algorithms[i]->name, name) == 0) {
            pthread_mutex_unlock(&cache->lock);
            return cache->algorithms[i];
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

void *cache_thread(void *arg) {
    while (1) {
        update_cache();
        sleep(60); // Update every minute
    }
    return NULL;
}

int main() {
    init_cache(2);
    pthread_t cache_tid;
    pthread_create(&cache_tid, NULL, cache_thread, NULL);

    // Example usage
    CryptoAlgorithm *algo = get_algorithm("SHA-256");
    if (algo) {
        unsigned char hash[32];
        algo->hash((unsigned char *)"hello", 5, hash);
        printf("Hash: ");
        for (int i = 0; i < 32; ++i) {
            printf("%02x", hash[i]);
        }
        printf("\n");
    }

    pthread_join(cache_tid, NULL);
    destroy_cache();
    return 0;
}
```

