#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    sem_t *sem;
    int max_threads;
} Semaphore;

Semaphore* semaphore_init(int initial_value, int max_threads) {
    Semaphore *s = (Semaphore*)malloc(sizeof(Semaphore));
    if (!s) return NULL;
    s->max_threads = max_threads;
    if (sem_init(s->sem, 0, initial_value) != 0) {
        free(s);
        return NULL;
    }
    return s;
}

void semaphore_destroy(Semaphore *s) {
    sem_destroy(s->sem);
    free(s);
}

void semaphore_wait(Semaphore *s) {
    if (sem_wait(s->sem) != 0) {
        fprintf(stderr, "Semaphore wait failed\n");
        exit(EXIT_FAILURE);
    }
}

void semaphore_signal(Semaphore *s) {
    if (sem_post(s->sem) != 0) {
        fprintf(stderr, "Semaphore signal failed\n");
        exit(EXIT_FAILURE);
    }
}

// Unit tests
#include <assert.h>
#include <unistd.h>

void test_semaphore() {
    Semaphore *s = semaphore_init(3, 10000);
    assert(s);

    for (int i = 0; i < 4; ++i) {
        semaphore_wait(s);
    }

    for (int i = 0; i < 2; ++i) {
        semaphore_signal(s);
    }

    semaphore_destroy(s);
    printf("All tests passed.\n");
}

int main() {
    test_semaphore();
    return 0;
}
```

