#include <atomic>
#include <mutex>

struct DependencyVersion {
    std::string version;
    DependencyVersion* parent;

    DependencyVersion(std::string v) : version(v), parent(nullptr) {}
};

class DependencyManager {
public:
    void appendOrLogDependency(
        std::forward_list<DependencyVersion>& list,
        const std::string& targetVersion,
        const std::string& newVersion,
        bool logFlag
    ) {
        auto it = list.begin();
        auto end = list.end();

        // Find the first occurrence of the target version
        while (it != end && it->version != targetVersion) {
            ++it;
        }

        if (it == end) {
            // Target not found, append at the end
            DependencyVersion* newVersionPtr = new DependencyVersion(newVersion);
            newVersionPtr->parent = nullptr; // Assuming no parent for the last version
            list.push_front(*newVersionPtr);
        } else {
            // Target found, append as a child
            DependencyVersion* newVersionPtr = new DependencyVersion(newVersion);
            newVersionPtr->parent = &(*it);
            it = list.insert_after(it, *newVersionPtr); // Insert after the target
        }

        if (logFlag) {
            logDependencyOperation(targetVersion, newVersion, list);
        }
    }

private:
    void logDependencyOperation(
        const std::string& targetVersion,
        const std::string& newVersion,
        const std::forward_list<DependencyVersion>& list
    ) {
        // Placeholder for external API logging logic
        try {
            // Simulate network request
            std::this_thread::sleep_for(std::chrono::seconds(1));
            std::cout << "Logged: Target=" << targetVersion << ", New=" << newVersion << std::endl;
        } catch (const std::exception& e) {
            // Handle error and retry logic here
            std::cerr << "Failed to log dependency operation: " << e.what() << std::endl;
        }
    }
};
