// SecureRandomService.h

#pragma once

#include <cstdint>
#include <cstddef>
#include <cstring>

#ifdef __cplusplus
extern "C" {
#endif

typedef struct SecureRandomService SecureRandomService;
typedef enum SecureRandomError SecureRandomError;

SecureRandomService* secure_random_service_create();
void secure_random_service_destroy(SecureRandomService* service);
SecureRandomError secure_random_service_seed_from_user(SecureRandomService* service, const uint8_t* seed, size_t seed_length);
SecureRandomError secure_random_service_seed_from_system(SecureRandomService* service);
SecureRandomError secure_random_service_generate(SecureRandomService* service, uint8_t* output, size_t output_length);

enum SecureRandomError {
    SECURE_RANDOM_SUCCESS = 0,
    SECURE_RANDOM_ERROR_INVALID_SEED = -1,
    SECURE_RANDOM_ERROR_INSUFFICIENT_ENTROPY = -2,
    SECURE_RANDOM_ERROR_NETWORK_FAILURE = -3
};

#ifdef __cplusplus
}
#endif

// secure_random_service.cpp

#include "SecureRandomService.h"
#include <mutex>
#include <random>

struct SecureRandomService {
    std::mt19937_64 mt;
    std::mutex mutex;
    bool seeded;

    SecureRandomService() : seeded(false) {}
};

SecureRandomService* secure_random_service_create() {
    return new SecureRandomService();
}

void secure_random_service_destroy(SecureRandomService* service) {
    delete service;
}

SecureRandomError secure_random_service_seed_from_user(SecureRandomService* service, const uint8_t* seed, size_t seed_length) {
    if (!service || !seed || seed_length == 0) {
        return SECURE_RANDOM_ERROR_INVALID_SEED;
    }
    std::lock_guard<std::mutex> lock(service->mutex);
    service->mt.seed(std::hash<std::string>()(std::string(reinterpret_cast<const char*>(seed), seed_length)));
    service->seeded = true;
    return SECURE_RANDOM_SUCCESS;
}

SecureRandomError secure_random_service_seed_from_system(SecureRandomService* service) {
    if (!service) {
        return SECURE_RANDOM_ERROR_INVALID_SEED;
    }
    std::lock_guard<std::mutex> lock(service->mutex);
    if (service->seeded) {
        return SECURE_RANDOM_SUCCESS;
    }
    std::random_device rd;
    try {
        service->mt.seed(rd());
        service->seeded = true;
    } catch (...) {
        return SECURE_RANDOM_ERROR_INSUFFICIENT_ENTROPY;
    }
    return SECURE_RANDOM_SUCCESS;
}

SecureRandomError secure_random_service_generate(SecureRandomService* service, uint8_t* output, size_t output_length) {
    if (!service || !output || output_length == 0) {
        return SECURE_RANDOM_ERROR_INVALID_SEED;
    }
    std::lock_guard<std::mutex> lock(service->mutex);
    if (!service->seeded) {
        if (secure_random_service_seed_from_system(service) != SECURE_RANDOM_SUCCESS) {
            return SECURE_RANDOM_ERROR_INSUFFICIENT_ENTROPY;
        }
    }
    std::uniform_int_distribution<> dis(0, 255);
    for (size_t i = 0; i < output_length; ++i) {
        output[i] = static_cast<uint8_t>(dis(service->mt));
    }
    return SECURE_RANDOM_SUCCESS;
}
