using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Diagnostics;
using System.Linq;
using Microsoft.Extensions.Logging;

public class DynamicSqlService
{
    private readonly ILogger<DynamicSqlService> _logger;
    private static readonly Dictionary<string, SqlCommand> _queryCache = new();
    private const int MaxRetries = 3;
    private const int RetryDelay = 500; // milliseconds

    public DynamicSqlService(ILogger<DynamicSqlService> logger)
    {
        _logger = logger;
    }

    public List<DataRow> ExecuteQueries(List<string> queries, string connectionString, Dictionary<string, object> parameters)
    {
        ValidateConnectionString(connectionString);
        var results = new List<DataRow>();

        foreach (var query in queries)
        {
            var sqlCommand = CreateSqlCommand(query, connectionString, parameters);
            var dataTable = ExecuteQuery(sqlCommand);
            results.AddRange(dataTable.Rows.Cast<DataRow>());
        }

        return results;
    }

    private static void ValidateConnectionString(string connectionString)
    {
        if (string.IsNullOrEmpty(connectionString))
        {
            throw new ArgumentException("Connection string cannot be empty or null.");
        }

        // Add checks for necessary authentication details and data source credentials
    }

    private SqlCommand CreateSqlCommand(string query, string connectionString, Dictionary<string, object> parameters)
    {
        var sqlCommand = _queryCache.ContainsKey(query) ? _queryCache[query] : new SqlCommand(query);
        if (!_queryCache.ContainsKey(query))
        {
            _queryCache[query] = sqlCommand;
        }

        foreach (var param in parameters)
        {
            sqlCommand.Parameters.AddWithValue(param.Key, param.Value);
        }

        return sqlCommand;
    }

    private static DataTable ExecuteQuery(SqlCommand command)
    {
        var dataTable = new DataTable();
        int retryCount = 0;

        while (retryCount < MaxRetries)
        {
            try
            {
                using (var connection = new SqlConnection(command.Connection.ConnectionString))
                {
                    connection.Open();
                    using (var adapter = new SqlDataAdapter(command))
                    {
                        adapter.Fill(dataTable);
                    }
                    return dataTable;
                }
            }
            catch (SqlException ex)
            {
                _logger.LogError(ex, "SQL error occurred during query execution.");
                retryCount++;
                if (retryCount >= MaxRetries) throw;
                Thread.Sleep(RetryDelay);
            }
        }

        throw new Exception("Max retries exceeded. Unable to execute query.");
    }

    public void LogQueryExecution(string query, TimeSpan executionTime)
    {
        _logger.LogInformation($"Query: {query} executed in {executionTime.TotalMilliseconds} ms");
