using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading.Tasks;

public class WeatherService
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, (double temperature, DateTime cacheTime)> _weatherCache;
    private readonly string _apiUrl;
    private readonly int _cacheEvictionIntervalMinutes;

    public WeatherService(string apiUrl, int cacheEvictionIntervalMinutes)
    {
        _httpClient = new HttpClient();
        _weatherCache = new ConcurrentDictionary<string, (double temperature, DateTime cacheTime)>();
        _apiUrl = apiUrl;
        _cacheEvictionIntervalMinutes = cacheEvictionIntervalMinutes;
    }

    public async Task SetTemperatureAsync(string environmentName, string city)
    {
        double temperature = await GetWeatherDataAsync(city);
        _weatherCache.TryAdd(environmentName, (temperature, DateTime.UtcNow));
    }

    private async Task<double> GetWeatherDataAsync(string city)
    {
        string cacheKey = $"weather_{city}";
        if (_weatherCache.TryGetValue(cacheKey, out var cachedData) && 
            DateTime.UtcNow - cachedData.cacheTime < TimeSpan.FromMinutes(_cacheEvictionIntervalMinutes))
        {
            return cachedData.temperature;
        }

        try
        {
            HttpResponseMessage response = await _httpClient.GetAsync($"{_apiUrl}/weather?q={city}");
            response.EnsureSuccessStatusCode();
            string responseBody = await response.Content.ReadAsStringAsync();
            double temperature = ParseTemperatureFromResponse(responseBody);
            _weatherCache.TryAdd(cacheKey, (temperature, DateTime.UtcNow));
            return temperature;
        }
        catch (HttpRequestException ex)
        {
            // Log the error and provide fallback mechanism
            Console.WriteLine($"Error fetching weather data: {ex.Message}");
            return 20; // Default fallback temperature
        }
    }

    private double ParseTemperatureFromResponse(string responseBody)
    {
        // Implement parsing logic based on the API response format
        return 15.5; // Placeholder value
    }

    public void EvictCache()
    {
        _weatherCache.Clear();
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        string apiUrl = "https://api.weatherapi.com/v1";
        int cacheEvictionIntervalMinutes = 5;
        WeatherService weatherService = new WeatherService(apiUrl, cacheEvictionIntervalMinutes);

        // Simulate setting temperature for multiple environments
        string[] cities = { "London", "New York", "Tokyo" };
        foreach (string city in cities)
        {
            await weatherService.SetTemperatureAsync(city.ToLower(), city);
        }

        // Periodically evict cache to refresh data
        Task.Run(async () =>
        {
            while (true)
            {
                await Task.Delay(TimeSpan.FromMinutes(cacheEvictionIntervalMinutes));
                weatherService.EvictCache();
                Console.WriteLine("Cache evicted");
            }
        });

        // Keep the application running
        await Task.Delay(Timeout.Infinite);
    }
}
