using System.Threading.Tasks;

[ApiController]
[Route("api/[controller]")]
public class ResourceController : ControllerBase
{
    private readonly IResourceService _resourceService;
    private readonly ILogger<ResourceController> _logger;
    private static readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1, 1);

    public ResourceController(IResourceService resourceService, ILogger<ResourceController> logger)
    {
        _resourceService = resourceService;
        _logger = logger;
    }

    [HttpPut("{id}")]
    public async Task<IActionResult> UpdateAsync(int id, [FromBody] ResourceDto resourceDto)
    {
        if (!ModelState.IsValid)
            return BadRequest(ModelState);

        try
        {
            await _semaphore.WaitAsync();
            var updatedResource = await _resourceService.UpdateAsync(id, resourceDto);
            _logger.LogInformation($"Updated resource: {updatedResource}");
            return Ok(updatedResource);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating resource");
            return StatusCode(500, "Internal server error");
        }
        finally
        {
            _semaphore.Release();
        }
    }

    [HttpDelete("{id}")]
    public async Task<IActionResult> DeleteAsync(int id)
    {
        try
        {
            await _resourceService.DeleteAsync(id);
            _logger.LogInformation($"Deleted resource: {id}");
            return NoContent();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error deleting resource");
            return StatusCode(500, "Internal server error");
        }
    }
}

