public class XmlConfigComponent
{
    private readonly ConcurrentDictionary<string, string> _cache = new ConcurrentDictionary<string, string>();
    private XNamespace _namespace;
    private HttpClient _configClient;

    public XmlConfigComponent(string configUrl)
    {
        _configClient = new HttpClient();
        LoadConfiguration(configUrl);
    }

    public async Task<string> GetKeyValueAsync(string key)
    {
        if (_cache.TryGetValue(key, out var value))
        {
            return value;
        }
        else
        {
            lock (_namespace)
            {
                var xmlString = await DownloadConfigAsync();
                var xmlDoc = XDocument.Parse(xmlString);
                var element = xmlDoc.Descendants(_namespace + key).FirstOrDefault();
                if (element != null)
                {
                    _cache.TryAdd(key, element.Value);
                    return element.Value;
                }
            }
        }
        throw new KeyNotFoundException($"Key '{key}' not found in configuration.");
    }

    private async Task<string> DownloadConfigAsync()
    {
        try
        {
            var response = await _configClient.GetAsync("http://example.com/config", HttpCompletionOption.ResponseHeadersRead);
            response.EnsureSuccessStatusCode();
            using (var stream = await response.Content.ReadAsStreamAsync())
            using (var reader = new StreamReader(stream))
            {
                return await reader.ReadToEndAsync();
            }
        }
        catch (HttpRequestException ex)
        {
            // Log the error and provide a fallback mechanism
            throw new InvalidOperationException("Failed to download configuration.", ex);
        }
    }

    private void LoadConfiguration(string configUrl)
    {
        try
        {
            var xmlString = DownloadConfigAsync().Result;
            var xmlDoc = XDocument.Parse(xmlString);
            _namespace = xmlDoc.Root.GetDefaultNamespace();
            // Initialize cache with default values if needed
        }
