    }

    [HttpPost("update")]
    public async Task<IActionResult> UpdateOctreeElementAsync(
        string pageSectionId,
        string elementId,
        string htmlContent,
        int featureSize,
        int numberOfLeafNodes)
    {
        try
        {
            var result = await _octreeService.UpdateElementAsync(pageSectionId, elementId, htmlContent, featureSize, numberOfLeafNodes);
            if (result.IsSuccessful)
            {
                return Ok(new { Success = true, Details = "Element updated successfully." });
            }
            else
            {
                return StatusCode(500, new { Success = false, Details = result.ErrorMessage });
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating octree element.");
            return StatusCode(500, new { Success = false, Details = "Internal server error." });
        }
    }
}

public interface IOctreeService
{
    Task<UpdateResult> UpdateElementAsync(string pageSectionId, string elementId, string htmlContent, int featureSize, int numberOfLeafNodes);
}

public class OctreeService : IOctreeService
{
    private readonly IOctreeClient _octreeClient;
    private readonly ILocalMemoryStorage _localMemoryStorage;

    public OctreeService(IOctreeClient octreeClient, ILocalMemoryStorage localMemoryStorage)
    {
        _octreeClient = octreeClient ?? throw new ArgumentNullException(nameof(octreeClient));
        _localMemoryStorage = localMemoryStorage ?? throw new ArgumentNullException(nameof(localMemoryStorage));
    }

    public async Task<UpdateResult> UpdateElementAsync(string pageSectionId, string elementId, string htmlContent, int featureSize, int numberOfLeafNodes)
    {
        try
        {
            // Attempt to update via external octree service
            var result = await _octreeClient.UpdateElementAsync(pageSectionId, elementId, htmlContent, featureSize, numberOfLeafNodes);
            if (result.IsSuccessful)
                return result;

            // Fallback to local memory storage if external service is unavailable
            _localMemoryStorage.UpdateElement(pageSectionId, elementId, htmlContent, featureSize, numberOfLeafNodes);
            return new UpdateResult { IsSuccessful = true, ErrorMessage = null };
        }
        catch (Exception ex)
        {
            return new UpdateResult { IsSuccessful = false, ErrorMessage = "Failed to update octree element." };
        }
    }
}

public class OctreeClient : IOctreeClient
{
    private readonly HttpClient _httpClient;
    public OctreeClient(HttpClient httpClient)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
    }

    public async Task<UpdateResult> UpdateElementAsync(string pageSectionId, string elementId, string htmlContent, int featureSize, int numberOfLeafNodes)
    {
        var requestUrl = "https://api.externaloctreeservice.com/update";
        var requestBody = new { PageSectionId = pageSectionId, ElementId = elementId, HtmlContent = htmlContent, FeatureSize = featureSize, NumberOfLeafNodes = numberOfLeafNodes };
        var response = await _httpClient.PostAsJsonAsync(requestUrl, requestBody);

        if (response.IsSuccessStatusCode)
            return new UpdateResult { IsSuccessful = true, ErrorMessage = null };

        var errorMessage = await response.Content.ReadAsStringAsync();
        return new UpdateResult { IsSuccessful = false, ErrorMessage = errorMessage };
    }
}

public interface IOctreeClient
{
    Task<UpdateResult> UpdateElementAsync(string pageSectionId, string elementId, string htmlContent, int featureSize, int numberOfLeafNodes);
}

public class LocalMemoryStorage : ILocalMemoryStorage
{
    private readonly ConcurrentDictionary<string, ElementData> _storage = new ConcurrentDictionary<string, ElementData>();

    public void UpdateElement(string pageSectionId, string elementId, string htmlContent, int featureSize, int numberOfLeafNodes)
    {
        var key = $"{pageSectionId}_{elementId}";
        _storage[key] = new ElementData
        {
            HtmlContent = htmlContent,
            FeatureSize = featureSize,
            NumberOfLeafNodes = numberOfLeafNodes
        };
    }
}

public interface ILocalMemoryStorage
{
    void UpdateElement(string pageSectionId, string elementId, string htmlContent, int featureSize, int numberOfLeafNodes);
}

public class ElementData
{
    public string HtmlContent { get; set; }
    public int FeatureSize { get; set; }
    public int NumberOfLeafNodes { get; set; }
}

public class UpdateResult
{
    public bool IsSuccessful { get; set; }
    public string ErrorMessage { get; set; }
}
