# Import necessary libraries
import re
from concurrent.futures import ThreadPoolExecutor
import gzip
import os
from datetime import datetime
import requests

class LogAnalyzer:
    def __init__(self, config):
        self.config = config
        self.error_patterns = self.load_error_patterns()

    def load_error_patterns(self):
        patterns = {}
        with open(self.config['error_patterns_path'], 'r') as file:
            for line in file:
                key, pattern = line.strip().split(':')
                patterns[key] = re.compile(pattern)
        return patterns

    def process_log_entry(self, entry):
        errors = []
        for key, pattern in self.error_patterns.items():
            if pattern.search(entry):
                errors.append((key, entry))
        return errors

    def read_logs(self, file_path):
        if file_path.endswith('.gz'):
            with gzip.open(file_path, 'rt') as file:
                for line in file:
                    yield line
        else:
            with open(file_path, 'r') as file:
                for line in file:
                    yield line

    def process_files(self, files):
        with ThreadPoolExecutor(max_workers=self.config['max_workers']) as executor:
            future_to_file = {executor.submit(self.process_log_entry, entry): file for file in files for entry in self.read_logs(file)}
            results = []
            for future in concurrent.futures.as_completed(future_to_file):
                file_path = future_to_file[future]
                try:
                    errors = future.result()
                    if errors:
                        results.append((file_path, errors))
                except Exception as e:
                    print(f'Error processing {file_path}: {e}')
            return results

    def send_summary(self, summary):
        headers = {'Content-Type': 'application/json'}
        response = requests.post(self.config['external_api_url'], json=summary, headers=headers)
        if response.status_code != 200:
            print(f'Failed to send summary: {response.text}')

    def analyze_logs(self, files):
        errors = self.process_files(files)
        summary = self.summarize_errors(errors)
        self.send_summary(summary)

    def summarize_errors(self, errors):
        error_counts = {}
        for file_path, error_list in errors:
            for key, entry in error_list:
                if key not in error_counts:
                    error_counts[key] = 0
                error_counts[key] += 1
        return error_counts

if __name__ == "__main__":
    config = {
        'error_patterns_path': 'error_patterns.txt',
        'max_workers': 5,
        'external_api_url': 'https://api.monitoring.service/summary'
    }

    analyzer = LogAnalyzer(config)
    log_files = ['log1.log', 'log2.gz']
    analyzer.analyze_logs(log_files)
```']

