// Function to generate a unique key for each script
function generateUniqueKey() {
    const timestamp = Date.now();
    const randomNumber = Math.floor(Math.random() * 1000);
    const contentHash = CryptoJS.SHA256(scriptContent).toString(CryptoJS.enc.Hex);
    return `${timestamp}-${randomNumber}-${contentHash}`;
}

// Function to validate the script content
function isValidScript(scriptContent) {
    try {
        new Function(scriptContent);
        return true;
    } catch (e) {
        return false;
    }
}

// Function to dynamically load external scripts asynchronously
async function loadExternalScript(url, key) {
    const script = document.createElement('script');
    script.src = url;
    script.async = true;
    script.onload = () => {
        console.log(`Script ${key} loaded successfully`);
    };
    script.onerror = () => {
        console.error(`Failed to load script ${key}`);
    };
    return new Promise((resolve, reject) => {
        script.onload = resolve;
        script.onerror = reject;
        document.head.appendChild(script);
    });
}

// Function to render footer scripts
async function renderFooterScripts(scripts) {
    let htmlString = '';
    const promises = [];

    for (const script of scripts) {
        const key = generateUniqueKey();
        if (!isValidScript(script)) {
            console.error(`Invalid script content: ${script}`);
            continue;
        }

        if (script.startsWith('http') || script.startsWith('//')) {
            // External resource
            promises.push(loadExternalScript(script, key));
        } else {
            // Inline script
            const scriptTag = document.createElement('script');
            scriptTag.text = script;
            scriptTag.async = true;
            htmlString += scriptTag.outerHTML;
        }
    }

    await Promise.all(promises);

    return htmlString;
}
```

