const oldTestamentBooks = [
    'Genesis', 'Exodus', 'Leviticus', 'Numbers', 'Deuteronomy',
    'Joshua', 'Judges', 'Ruth', '1 Samuel', '2 Samuel', '1 Kings', '2 Kings',
    '1 Chronicles', '2 Chronicles', 'Ezra', 'Nehemiah', 'Esther', 'Job', 'Psalms',
    'Proverbs', 'Ecclesiastes', 'Song of Solomon', 'Isaiahu', 'Jeremiah', 'Lamentations',
    'Ezekiel', 'Daniel', 'Hosea', 'Joel', 'Amos', 'Obadiah', 'Jonah', 'Micah', 'Nahum',
    'Habakkuk', 'Zephaniah', 'Haggai', 'Zechariah', 'Malachi'
];

const bookRegex = new RegExp(`\\b(${oldTestamentBooks.join('|')})\\b`, 'gi');

function refreshDialogFields(resourceId, url) {
    const dialogFields = document.querySelectorAll('[dialog-field]'); // Assuming fields have a custom attribute
    let bookOccurrences = {};

    dialogFields.forEach(field => {
        if (field.hasAttribute('refresh-on-id')) {
            if (field.getAttribute('refresh-on-id') === resourceId) {
                field.classList.add('loading');
                const fieldName = field.getAttribute('name');

                fetch(url)
                    .then(response => response.json())
                    .then(data => {
                        field.innerText = data[fieldName];
                        field.classList.remove('loading');
                        field.dispatchEvent(new CustomEvent('field-refreshed', { detail: { fieldName } }));
                    })
                    .catch(error => {
                        console.error(`Error refreshing ${fieldName}:`, error);
                        field.classList.remove('loading');
                    });
            }
        }
    });

    dialogFields.forEach(field => {
        const textContent = field.innerText;
        const matches = textContent.match(bookRegex);
        if (matches) {
            bookOccurrences = matches.reduce((acc, match) => {
                acc[match] = (acc[match] || 0) + 1;
                return acc;
            }, bookOccurrences);
        }
    });

    return bookOccurrences;
}
