const express = require('express');
const path = require('path');
const fs = require('fs').promises;
const { createRequire } = require('module');

const app = express();
const requireFunction = createRequire(import.meta.url);

app.use(express.json());

// Define a cache for modules
const moduleCache = new Map();

// Function to load and execute modules dynamically
async function loadModule(modulePath) {
  if (moduleCache.has(modulePath)) {
    return moduleCache.get(modulePath);
  }

  try {
    const content = await fs.readFile(modulePath, 'utf8');
    const moduleContent = `
      (function(require, module, exports) { ${content} })();
      return module.exports;
    `;

    const func = new Function('require', 'module', 'exports', moduleContent);
    const moduleInstance = {};
    const moduleWrapper = {
      exports: moduleInstance,
    };

    func(requireFunction, moduleWrapper, moduleInstance);

    moduleCache.set(modulePath, moduleInstance);
    return moduleInstance;
  } catch (error) {
    console.error(`Error loading module ${modulePath}:`, error);
    throw new Error(`Failed to load module ${modulePath}`);
  }
}

// Example endpoint to demonstrate dynamic module execution
app.post('/executeModule', async (req, res) => {
  const { moduleName, args } = req.body;

  try {
    // Load and execute the module dynamically
    const moduleInstance = await loadModule(`./modules/${moduleName}.js`);
    const result = moduleInstance.default(...args);
    res.json(result);
  } catch (error) {
    console.error('Error executing module:', error);
    res.status(500).json({ error: 'An error occurred while executing the module' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
```

