impl HttpClient {
    pub async fn new() -> Result<HttpClient, Error> {
        let auth_token = env::var("AUTH_TOKEN").expect("AUTH_TOKEN environment variable must be set");
        let api_version = env::var("API_VERSION").unwrap_or_else(|_| "v1".to_string());
        let cache_size = env::var("CACHE_SIZE")
            .ok()
            .and_then(|s| s.parse().ok())
            .unwrap_or(1024);

        Ok(HttpClient {
            client: Client::new(),
            config: client_config::ClientConfig {
                auth_token,
                api_version,
                cache_size,
            },
        })
    }

    pub async fn get(&self, url: &str) -> Result<String, Error> {
        let response = self.client.get(url).send().await?;
        response.text().await
    }

    pub async fn post(&self, url: &str, data: String) -> Result<String, Error> {
        let response = self.client.post(url).body(data).send().await?;
        response.text().await
    }
}

fn main() {
    tokio::runtime::Runtime::new().unwrap().block_on(async move {
        let client = HttpClient::new().await.unwrap();
        let url = "https://api.example.com/data";
        let data = "{ \"key\": \"value\" }";

        match client.get(url).await {
            Ok(response) => println!("GET Response: {}", response),
            Err(e) => eprintln!("GET Error: {:?}", e),
        }

        match client.post(url, data.to_string()).await {
            Ok(response) => println!("POST Response: {}", response),
            Err(e) => eprintln!("POST Error: {:?}", e),
        }
    });
}
