class UserProfileService {

    private $httpClient;
    private $cacheClient;
    private $rateLimiter;

    public function __construct(HttpClient $httpClient, Client $cacheClient, RateLimiter $rateLimiter) {
        $this->httpClient = $httpClient;
        $this->cacheClient = $cacheClient;
        $this->rateLimiter = $rateLimiter;
    }

    public function getUserProfile(string $email): Response {
        // Validate email format
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            throw new NotFoundHttpException('Invalid email format');
        }

        // Generate unique session token
        $sessionToken = bin2hex(random_bytes(32));

        // Check rate limit
        if (!$this->rateLimiter->allowRequest()) {
            return new Response('Rate limit exceeded', 429);
        }

        // Try to fetch user data from cache
        $userData = $this->cacheClient->get($email);
        if ($userData) {
            return new Response($userData, 200, ['Content-Type' => 'application/json']);
        }

        // Fetch user data from external API
        try {
            $response = $this->httpClient->request('GET', 'https://api.example.com/user?email=' . urlencode($email));
            $userData = $response->getBody()->getContents();
        } catch (\Exception $e) {
            return new Response('Failed to fetch user data from API', 500);
        }

        // Store user data in cache with configurable expiration
        $this->cacheClient->setex($email, 3600, $userData); // 1 hour expiration

        return new Response($userData, 200, ['Content-Type' => 'application/json']);
    }
}

class RateLimiter {
    public function allowRequest(): bool {
        // Implement rate limiting logic here
        return true;
    }
}

// Usage example in a web application context
$request = Request::createFromGlobals();
$userProfileService = new UserProfileService(
    new HttpClient(),
    new Client(['url' => 'redis://localhost']),
    new RateLimiter()
);

