    use std::error::Error;
    use tokio::sync::Mutex;
    use std::collections::HashMap;

    pub struct OAuthToPemConverter {
        client: oauth2::BasicClient,
        key_cache: Mutex<HashMap<String, (AccessToken, Pem)>>,
    }

    impl OAuthToPemConverter {
        pub fn new(client_id: String, client_secret: String) -> Self {
            let client = oauth2::BasicClient::new(
                ClientId::new(client_id),
                Some(ClientSecret::new(client_secret)),
                oauth2::AuthorizationUrl::from_static("https://example.com/oauth/token"),
                Some(oauth2::TokenUrl::from_static("https://example.com/oauth/token")),
            );
            OAuthToPemConverter {
                client,
                key_cache: Mutex::new(HashMap::new()),
            }
        }

        pub async fn fetch_key(&self, scope: Scope<'_>) -> Result<Pem, Box<dyn Error>> {
            let mut cache = self.key_cache.lock().await;
            if let Some((token, pem)) = cache.get(&scope.to_string()) {
                return Ok(pem.clone());
            }
            let token_response = self.client.exchange_client_credentials(scope).await?;
            let token = token_response.access_token();
            let resp = reqwest::get("https://example.com/api/key").await?.text().await?;
            let pem = Pem::from_string(&resp)?;
            cache.insert(token.to_string(), (token.clone(), pem.clone()));
            Ok(pem)
        }

        pub fn generate_ir(&self, input: &str) -> Result<Module, String> {
            // Custom lexer and parser code here
            // Use LLVM IR API to generate code
            unimplemented!()
        }
    }
}

