from flask import Flask, request, jsonify, abort
import requests
from functools import wraps
import jwt
import time

app = Flask(__name__)

# Configuration for OAuth 2.0 providers
IDP_CONFIGS = {
    'google': {
        'auth_url': 'https://accounts.google.com/o/oauth2/auth',
        'token_url': 'https://accounts.google.com/o/oauth2/token',
        'user_info_url': 'https://www.googleapis.com/oauth2/v1/userinfo'
    },
    'facebook': {
        'auth_url': 'https://www.facebook.com/dialog/oauth',
        'token_url': 'https://graph.facebook.com/v2.10/oauth/access_token',
        'user_info_url': 'https://graph.facebook.com/me?fields=id,name,email,picture'
    }
}

# JWT Secret Key
JWT_SECRET = 'your_jwt_secret_key'

def authenticate_with_idp(idp, access_token):
    response = requests.get(IDP_CONFIGS[idp]['user_info_url'], headers={'Authorization': f'Bearer {access_token}'})
    if response.status_code == 200:
        return response.json()
    else:
        abort(401)

def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            abort(401)

        try:
            data = jwt.decode(token, JWT_SECRET, algorithms=["HS256"])
            user_info = authenticate_with_idp(data['idp'], data['access_token'])
            return f(user_info, *args, **kwargs)
        except Exception as e:
            abort(401)

    return decorated

@app.route('/login', methods=['POST'])
def login():
    data = request.json
    idp = data.get('idp')
    code = data.get('code')

    if not idp or not code:
        abort(400)

    token_url = IDP_CONFIGS[idp]['token_url']
    auth_params = {
        'client_id': 'your_client_id',
        'redirect_uri': 'your_redirect_uri',
        'code': code,
        'grant_type': 'authorization_code'
    }

    response = requests.post(token_url, data=auth_params)
    if response.status_code == 200:
        access_token = response.json().get('access_token')
        user_info = authenticate_with_idp(idp, access_token)

        token = jwt.encode({
            'idp': idp,
            'user_info': user_info,
            'exp': time.time() + 3600
        }, JWT_SECRET, algorithm="HS256")

        return jsonify({'token': token})
    else:
        abort(401)

@app.route('/protected', methods=['GET'])
@token_required
def protected(user_info):
    return jsonify(user_info)

if __name__ == '__main__':
    app.run(debug=True)
```

This code provides a basic structure for an OAuth 2.0 authentication module using Flask. It includes endpoints for user login and accessing protected resources, with token-based authentication and error handling. The actual implementation of IDP interaction and data processing should be customized based on specific requirements and third-party API details.']

