    if (strlen(password) < MIN_PASSWORD_LENGTH) return 0;
    int hasLower = 0, hasUpper = 0, hasDigit = 0, hasSpecial = 0;
    for (size_t i = 0; i < strlen(password); ++i) {
        if (islower(password[i])) hasLower = 1;
        if (isupper(password[i])) hasUpper = 1;
        if (isdigit(password[i])) hasDigit = 1;
        if (!isalnum(password[i])) hasSpecial = 1;
    }
    return hasLower && hasUpper && hasDigit && hasSpecial;
}

void updatePasswordInDatabase(int userId, const char* newPassword) {
    // Implement database update logic here
}

void handlePasswordUpdateFailure(int userId, int errorCode) {
    // Implement fallback mechanism and logging for failures
}

void* updateUserPassword(void* arg) {
    PasswordUpdateRequest* request = (PasswordUpdateRequest*)arg;
    int userId = request->userId;
    const char* newPassword = request->newPassword;

    if (!validatePasswordStrength(newPassword)) {
        logOperation(userId, "Invalid password strength");
        handlePasswordUpdateFailure(userId, -1);
        return NULL;
    }

    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        updatePasswordInDatabase(userId, newPassword);
        exit(0);
    } else if (pid > 0) {
        // Parent process
        int status;
        wait(&status);
        if (WIFEXITED(status)) {
            logOperation(userId, "Password updated successfully");
        } else {
            handlePasswordUpdateFailure(userId, WEXITSTATUS(status));
        }
    } else {
        // Fork failed
        handlePasswordUpdateFailure(userId, -2);
    }

    return NULL;
}

void* threadFunction(void* arg) {
    PasswordUpdateRequest request = *(PasswordUpdateRequest*)arg;
    free(arg);

    pthread_t threadId;
    if (pthread_create(&threadId, NULL, updateUserPassword, &request) != 0) {
        // Handle thread creation failure
    }

    return NULL;
}

void enqueueUpdate(int userId, const char* newPassword) {
    PasswordUpdateRequest* request = malloc(sizeof(PasswordUpdateRequest));
    request->userId = userId;
    strncpy(request->newPassword, newPassword, sizeof(request->newPassword) - 1);
    request->newPassword[sizeof(request->newPassword) - 1] = '\0';

    pthread_t threadId;
    if (pthread_create(&threadId, NULL, threadFunction, request) != 0) {
        // Handle thread creation failure
        free(request);
    }
}

// Example usage
int main() {
    int userId = 12345;
    const char* newPassword = "NewP@ssw0rd!";

    enqueueUpdate(userId, newPassword);

    return 0;
}
