# data_processor.py

import json
import requests
from functools import lru_cache
from concurrent.futures import ThreadPoolExecutor

class JSONHandler:
    factory_registry = {}

    @staticmethod
    def register_factory(factory_id, factory_func):
        JSONHandler.factory_registry[factory_id] = factory_func

    @staticmethod
    def create_instance(json_data, factory_id):
        if factory_id not in JSONHandler.factory_registry:
            raise ValueError("Factory ID not registered")
        return JSONHandler.factory_registry[factory_id](json_data)

    @staticmethod
    def json_to_obj(json_str, factory_id):
        data = json.loads(json_str)
        return JSONHandler.create_instance(data, factory_id)

    @staticmethod
    def obj_to_json(obj):
        return json.dumps(obj.__dict__)

class ConfigReader:
    @staticmethod
    def read_config(file_path):
        try:
            with open(file_path, 'r') as file:
                data = file.readlines()
            sorted_data = sorted(data)
            sequence_number = int(sorted_data[-1].strip())
            return sequence_number
        except (FileNotFoundError, ValueError) as e:
            print(f"Error reading config: {e}")
            return None

class APIClient:
    BASE_URL = 'https://api.example.com/data'
    API_KEY = 'your_api_key_here'

    def __init__(self):
        self.session = requests.Session()
        self.session.headers.update({'Authorization': f'Bearer {APIClient.API_KEY}'})
        self.executor = ThreadPoolExecutor(max_workers=10)

    @lru_cache(maxsize=128)
    def fetch_data(self, endpoint):
        url = f"{APIClient.BASE_URL}{endpoint}"
        response = self.session.get(url)
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception(f"Failed to fetch data from {url}")

    def process_concurrently(self, endpoints):
        results = list(self.executor.map(self.fetch_data, endpoints))
        return results

# Testing
import unittest

class TestDataProcessor(unittest.TestCase):
    def test_json_handler(self):
        class SampleObject:
            def __init__(self, id, name):
                self.id = id
                self.name = name

        JSONHandler.register_factory('sample', lambda data: SampleObject(data['id'], data['name']))
        obj = JSONHandler.json_to_obj(json.dumps({'id': 1, 'name': 'Test'}), 'sample')
        self.assertEqual(obj.id, 1)
        self.assertEqual(obj.name, 'Test')

    def test_config_reader(self):
        sequence_number = ConfigReader.read_config('config.txt')
        self.assertIsNotNone(sequence_number)

    def test_api_client(self):
        client = APIClient()
        data = client.fetch_data('/endpoint')
        self.assertIn('key', data)

if __name__ == '__main__':
    unittest.main()
