StateList* create_state_list(int num_states, FSA* fsa) {
    StateList* list = (StateList*)malloc(sizeof(StateList));
    if (!list) {
        perror("Memory allocation failed for state list");
        return NULL;
    }
    memset(list, 0, sizeof(StateList));

    pthread_mutex_init(&list->lock, NULL);

    int last_state_id = num_states - 1;

    // Simulate asynchronous database operations
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, retrieve_states_from_db, (void*)fsa) != 0) {
        perror("Failed to create thread for state retrieval");
        free(list);
        return NULL;
    }

    pthread_join(thread_id, NULL);

    // Add states to the list
    State* current_state = NULL;
    for (int i = last_state_id; i >= 0; i--) {
        State* new_state = (State*)malloc(sizeof(State));
        if (!new_state) {
            perror("Memory allocation failed for state");
            cleanup_state_list(list);
            return NULL;
        }
        new_state->id = fsa->states[i];
        new_state->next = current_state;

        current_state = new_state;
    }

    list->head = current_state;

    return list;
}

void* retrieve_states_from_db(void* arg) {
    FSA* fsa = (FSA*)arg;
    // Simulate database retrieval
    // For demonstration, just ensure the FSA is not NULL
    if (!fsa) {
        perror("Invalid FSA pointer");
    }
    return NULL;
}

void cleanup_state_list(StateList* list) {
    State* current = list->head;
    while (current) {
        State* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);

    free(list);
}
