            bundle->data[i] = i + 1; // Simulated data
        }
    }
    return bundle;
}

int processResourceBundle(const char *filePath, const ReductionStrategy *reductionStrategy) {
    // Load resource bundle with default reduction strategy if none provided
    ResourceBundleConfig config = {filePath, FORMAT_JSON, reductionStrategy != NULL ? *reductionStrategy : (ReductionStrategy){sumReducer}};
    ResourceBundle *bundle = loadResourceBundle(&config);
    if (bundle == NULL) {
