#include <pthread.h>

// Function prototypes
char* process_log_message(const char* message, size_t max_length, int to_upper);
void log_attempt_failure();

// Global mutex for thread-safe operations
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Simulated external logging function with rate limiting and latency issues
int external_logging_service(char* message) {
    // Simulate service unavailability
    static int failure_count = 0;
    if (failure_count < 3) {
        failure_count++;
        return -1; // Service unavailable
    }
    // Simulate successful logging
    printf("Logged: %s\n", message);
    return 0;
}

// Function to process the log message
char* process_log_message(const char* message, size_t max_length, int to_upper) {
    pthread_mutex_lock(&log_mutex);

    // Allocate memory for the processed message
    char* buffer = (char*)malloc(max_length + 25); // Extra space for timestamp
    if (!buffer) {
        log_attempt_failure();
        pthread_mutex_unlock(&log_mutex);
        return NULL;
    }

    size_t len = strlen(message);
    if (len > max_length) {
        strncpy(buffer, message, max_length - 1);
        buffer[max_length] = '\0';
    } else {
        strcpy(buffer, message);
    }

    // Append timestamp in UTC format
    time_t now = time(NULL);
    struct tm* utc_time = gmtime(&now);
    strftime(buffer + len, max_length - len + 25, " %Y-%m-%dT%H:%M:%SZ", utc_time);

    // Convert to uppercase if required
    if (to_upper) {
        for (size_t i = 0; buffer[i]; i++) {
            buffer[i] = toupper(buffer[i]);
        }
    }

    int retries = 0;
    while (external_logging_service(buffer) != 0 && retries < 3) {
        log_attempt_failure();
        retries++;
        // Exponential backoff
        usleep((useconds_t)(pow(2, retries) * 100000));
    }

    if (retries == 3) {
        printf("Failed to log message after maximum retries.\n");
        free(buffer);
        buffer = NULL;
    } else {
        // Log successful
        printf("Log message processed successfully.\n");
    }

    pthread_mutex_unlock(&log_mutex);
    return buffer;
}

