#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define IV_LENGTH 16
#define KEY_LENGTH 32

typedef struct {
    unsigned char *key;
    unsigned char *iv;
    EVP_CIPHER_CTX *ctx;
} EncryptionContext;

EncryptionContext* create_encryption_context(const char *password, int iteration_count, const char *salt, int salt_length) {
    EncryptionContext *context = (EncryptionContext *)malloc(sizeof(EncryptionContext));
    context->key = (unsigned char *)malloc(KEY_LENGTH);
    context->iv = (unsigned char *)malloc(IV_LENGTH);

    // Generate secure IV
    if (!RAND_bytes(context->iv, IV_LENGTH)) {
        fprintf(stderr, "Error generating IV\n");
        exit(EXIT_FAILURE);
    }

    // Derive key using PBKDF2
    if (!PKCS5_PBKDF2_HMAC(password, strlen(password), (unsigned char *)salt, salt_length,
                            iteration_count, EVP_sha256(), KEY_LENGTH, context->key)) {
        fprintf(stderr, "Error deriving key\n");
        exit(EXIT_FAILURE);
    }

    // Initialize cipher context
    context->ctx = EVP_CIPHER_CTX_new();
    if (!context->ctx) {
        fprintf(stderr, "Error creating cipher context\n");
        exit(EXIT_FAILURE);
    }

    return context;
}

void encrypt_data(EncryptionContext *context, const unsigned char *plaintext, int plaintext_length, unsigned char *ciphertext) {
    if (1 != EVP_EncryptInit_ex(context->ctx, EVP_aes_256_cbc(), NULL, context->key, context->iv)) {
        fprintf(stderr, "Error initializing encryption\n");
        exit(EXIT_FAILURE);
    }

    int len;
    if (1 != EVP_EncryptUpdate(context->ctx, ciphertext, &len, plaintext, plaintext_length)) {
        fprintf(stderr, "Error encrypting data\n");
        exit(EXIT_FAILURE);
    }

    int ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(context->ctx, ciphertext + len, &len)) {
        fprintf(stderr, "Error finalizing encryption\n");
        exit(EXIT_FAILURE);
    }

    ciphertext_len += len;
}

void free_encryption_context(EncryptionContext *context) {
    EVP_CIPHER_CTX_free(context->ctx);
    free(context->key);
    free(context->iv);
    free(context);
}

int main() {
    const char *password = "secure_password";
    int iteration_count = 10000;
    const char *salt = "somesalt";
    int salt_length = strlen(salt);

    EncryptionContext *context = create_encryption_context(password, iteration_count, salt, salt_length);

    unsigned char plaintext[] = "Hello, World!";
    unsigned char ciphertext[sizeof(plaintext) + EVP_CIPHER_BLOCK_SIZE];

    encrypt_data(context, (unsigned char *)plaintext, sizeof(plaintext), ciphertext);

    printf("Ciphertext: ");
    for (int i = 0; i < sizeof(ciphertext); i++) {
        printf("%02x", ciphertext[i]);
    }
    printf("\n");

    free_encryption_context(context);

    return 0;
}
```

