using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

public class ManageWebSites
{
    private readonly ConcurrentDictionary<string, WebSite> _sites = new ConcurrentDictionary<string, WebSite>();
    private readonly IConfigurationService _configService;
    private readonly ILogger _logger;

    public ManageWebSites(IConfigurationService configService, ILogger logger)
    {
        _configService = configService;
        _logger = logger;
    }

    public void AddOrUpdateSite(string directoryPath)
    {
        if (!Directory.Exists(directoryPath) || !File.Exists(Path.Combine(directoryPath, "web.config")))
        {
            _logger.LogError($"Invalid site directory: {directoryPath}");
            return;
        }

        var config = LoadConfigFromWebConfig(directoryPath);
        if (config == null)
        {
            _logger.LogError("Failed to load valid web.config.");
            return;
        }

        WebSite site;
        if (_sites.TryGetValue(directoryPath, out site))
        {
            site.Update(config);
        }
        else
        {
            site = new WebSite(directoryPath, config);
            _sites.TryAdd(directoryPath, site);
        }

        Task.Run(site.StartAsync);
    }

    private WebSiteConfig LoadConfigFromWebConfig(string directoryPath)
    {
        try
        {
            var webConfigContent = File.ReadAllText(Path.Combine(directoryPath, "web.config"));
            return JsonConvert.DeserializeObject<WebSiteConfig>(webConfigContent);
        }
        catch (Exception ex)
        {
            _logger.LogError($"Failed to load web.config: {ex.Message}");
            return null;
        }
    }

    public void MonitorSites()
    {
        foreach (var site in _sites.Values)
        {
            Task.Run(site.MonitorAsync);
        }
    }
}

public class WebSite
{
    private readonly string _directoryPath;
    private readonly WebSiteConfig _config;
    private bool _isRunning;

    public WebSite(string directoryPath, WebSiteConfig config)
    {
        _directoryPath = directoryPath;
        _config = config;
    }

    public async Task StartAsync()
    {
        if (_isRunning) return;
        _isRunning = true;
        try
        {
            // Code to start the site using IIS or another web server
            await Task.Delay(1000); // Simulate startup time
        }
        catch (Exception ex)
        {
            _logger.LogError($"Failed to start site: {ex.Message}");
            await RestartAsync();
        }
    }

    public async Task MonitorAsync()
    {
        while (_isRunning)
        {
            try
            {
                if (!CheckHealth())
                {
                    await RestartAsync();
                }
                await Task.Delay(_config.HealthCheckInterval);
            }
            catch (Exception ex)
            {
                _logger.LogError($"Failed to monitor site: {ex.Message}");
                await RestartAsync();
            }
        }
    }

    private bool CheckHealth()
    {
        // Code to check the health of the site
        return true;
    }

    private async Task RestartAsync()
    {
        if (_isRunning)
        {
            try
            {
                // Code to restart the site
                await Task.Delay(1000); // Simulate restart time
            }
            catch (Exception ex)
            {
                _logger.LogError($"Failed to restart site: {ex.Message}");
            }
        }
    }

    public void Update(WebSiteConfig newConfig)
    {
        _config = newConfig;
    }
}

public class WebSiteConfig
{
    public string Binding { get; set; }
    public string ApplicationPool { get; set; }
    public int HealthCheckInterval { get; set; }
}
