        fprintf(stderr, "Error: Malformed access_token\n");
        free(token->access_token);
        return -1;
    }
    *token_end = '\0';

    // Extract and validate expires_in
    token->expires_in = atoi(expires_in_start + 16);
    if (token->expires_in <= 0) {
        fprintf(stderr, "Error: Invalid expires_in value\n");
        free(token->access_token);
        return -1;
    }

    // Extract and validate token_type
    token->token_type = strdup(token_type_start + 18);
    char *type_end = strchr(token->token_type, '"');
    if (!type_end || type_end == token->token_type) {
        fprintf(stderr, "Error: Malformed token_type\n");
        free(token->access_token);
        free(token->token_type);
        return -1;
    }
    *type_end = '\0';
    if (strcmp(token->token_type, "Bearer") != 0) {
        fprintf(stderr, "Error: Invalid token_type value\n");
        free(token->access_token);
        free(token->token_type);
        return -1;
    }

    // Optional fields handling
    const char *refresh_token_start = strstr(json, "\"refresh_token\":");
    if (refresh_token_start) {
        token->refresh_token = strdup(refresh_token_start + 20);
        char *rt_end = strchr(token->refresh_token, '"');
        if (!rt_end || rt_end == token->refresh_token) {
            fprintf(stderr, "Error: Malformed refresh_token\n");
            free(token->access_token);
            free(token->token_type);
            free(token->refresh_token);
            return -1;
        }
        *rt_end = '\0';
    } else {
        token->refresh_token = NULL;
    }

    const char *scope_start = strstr(json, "\"scope\":");
    if (scope_start) {
        token->scope = strdup(scope_start + 12);
        char *scope_end = strchr(token->scope, '"');
        if (!scope_end || scope_end == token->scope) {
            fprintf(stderr, "Error: Malformed scope\n");
            free(token->access_token);
            free(token->token_type);
            free(token->refresh_token);
            free(token->scope);
            return -1;
        }
        *scope_end = '\0';
    } else {
        token->scope = NULL;
    }

    // Placeholder for external authentication service integration
    // This is a simplified example to illustrate the function structure

    printf("Access Token: %s\n", token->access_token);
    printf("Expires In: %d\n", token->expires_in);
    printf("Token Type: %s\n", token->token_type);
    if (token->refresh_token) {
        printf("Refresh Token: %s\n", token->refresh_token);
    }
    if (token->scope) {
        printf("Scope: %s\n", token->scope);
    }

    return 0;
}

int main() {
    const char *json = "{\"access_token\":\"abc123\",\"expires_in\":3600,\"token_type\":\"Bearer\",\"refresh_token\":\"def456\",\"scope\":\"read,write\"}";
    OAuth2Token token;

    if (validate_access_token(json, &token) == 0) {
        printf("Token validation successful.\n");
    } else {
        printf("Token validation failed.\n");
    }

    // Clean up allocated memory
    free(token.access_token);
    free(token.token_type);
    if (token.refresh_token) {
        free(token.refresh_token);
    }
    if (token.scope) {
        free(token.scope);
    }

    return 0;
}
