['```csharp
using System;
using System.Data;
using System.Data.SqlClient;
using System.IO;
using System.Threading.Tasks;

public class DataIngestionPipeline
{
    private readonly string _connectionString;
    private readonly int _maxBatchSize;

    public DataIngestionPipeline(string connectionString, int maxBatchSize)
    {
        _connectionString = connectionString;
        _maxBatchSize = maxBatchSize;
    }

    public async Task IngestDataAsync(Stream dataStream, string tableName)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();

            var sqlBulkCopy = new SqlBulkCopy(connection)
            {
                DestinationTableName = tableName,
                BatchSize = _maxBatchSize,
                NotifyAfter = _maxBatchSize,
                EnableStreaming = true
            };

            sqlBulkCopy.SqlRowsCopied += (sender, e) =>
            {
                Console.WriteLine($"Copied {e.RowsCopied} rows so far.");
            };

            using (var reader = new BinaryReader(dataStream))
            {
                var dataTable = new DataTable();
                dataTable.Columns.Add("Data", typeof(byte[]));

                while (reader.BaseStream.Position < reader.BaseStream.Length)
                {
                    byte[] buffer = new byte[_maxBatchSize];
                    int bytesRead = reader.Read(buffer, 0, _maxBatchSize);

                    if (bytesRead == 0) break;

                    var row = dataTable.NewRow();
                    row["Data"] = buffer;
                    dataTable.Rows.Add(row);
                }

                await sqlBulkCopy.WriteToServerAsync(dataTable);
            }
        }
    }
}

// Usage example
public class Program
{
    public static async Task Main(string[] args)
    {
        string connectionString = "your_connection_string_here";
        int maxBatchSize = 1024 * 1024; // 1 MB

        var pipeline = new DataIngestionPipeline(connectionString, maxBatchSize);

        using (var fileStream = File.OpenRead("path_to_binary_file.bin"))
        {
            await pipeline.IngestDataAsync(fileStream, "YourTableName");
        }
    }
}
```

This code snippet demonstrates a basic implementation of the data ingestion pipeline. It uses `SqlBulkCopy` for efficient data transfer and handles large binary files by reading them in chunks. The `DataIngestionPipeline` class is designed to be modular and scalable, with considerations for error handling and performance optimization.

