using System;
using System.Security.Cryptography;
using System.Text;

public class HashGenerator
{
    private readonly ILogger _logger;

    public HashGenerator(ILogger logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public string GenerateMD5Hash(string input, bool formatAsHex = true)
    {
        if (string.IsNullOrEmpty(input))
            throw new ArgumentException("Input cannot be null or empty.", nameof(input));

        try
        {
            using (var md5 = MD5.Create())
            {
                var hashBytes = md5.ComputeHash(Encoding.UTF8.GetBytes(input));
                return formatAsHex ? BitConverter.ToString(hashBytes).Replace("-", "").ToLower() : Convert.ToBase64String(hashBytes);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error generating MD5 hash.");
            throw new InvalidOperationException("Failed to generate hash.", ex);
        }
    }

    public async Task<string> GenerateMD5HashAsync(string input, bool formatAsHex = true)
    {
        if (string.IsNullOrEmpty(input))
            throw new ArgumentException("Input cannot be null or empty.", nameof(input));

        try
        {
            using var md5 = MD5.Create();
            var hashBytes = await Task.Run(() => md5.ComputeHash(Encoding.UTF8.GetBytes(input)));
            return formatAsHex ? BitConverter.ToString(hashBytes).Replace("-", "").ToLower() : Convert.ToBase64String(hashBytes);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error generating MD5 hash.");
            throw new InvalidOperationException("Failed to generate hash.", ex);
        }
    }
}
