using System;
using System.IO;
using System.Security.Cryptography;
using Newtonsoft.Json;

namespace SecureDataLibrary
{
    public interface IDataHandler
    {
        byte[] Encrypt<T>(T data, byte[] key, byte[] iv);
        T Decrypt<T>(byte[] encryptedData, byte[] key, byte[] iv);
    }

    public class AESCipher : IDataHandler
    {
        private readonly KeyDerivationFunction _keyDerivationFunction;

        public AESCipher(KeyDerivationFunction keyDerivationFunction)
        {
            _keyDerivationFunction = keyDerivationFunction;
        }

        public byte[] Encrypt<T>(T data, byte[] key, byte[] iv)
        {
            using (var aes = Aes.Create())
            {
                aes.Key = key;
                aes.IV = iv;
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;

                using (var encryptor = aes.CreateEncryptor(aes.Key, aes.IV))
                {
                    using (var ms = new MemoryStream())
                    using (var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
                    using (var sw = new StreamWriter(cs))
                    {
                        var jsonString = JsonConvert.SerializeObject(data);
                        sw.Write(jsonString);
                    }
                    return ms.ToArray();
                }
            }
        }

        public T Decrypt<T>(byte[] encryptedData, byte[] key, byte[] iv)
        {
            try
            {
                using (var aes = Aes.Create())
                {
                    aes.Key = key;
                    aes.IV = iv;
                    aes.Mode = CipherMode.CBC;
                    aes.Padding = PaddingMode.PKCS7;

                    using (var decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
                    using (var ms = new MemoryStream(encryptedData))
                    using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                    using (var sr = new StreamReader(cs))
                    {
                        var jsonString = sr.ReadToEnd();
                        return JsonConvert.DeserializeObject<T>(jsonString);
                    }
                }
            }
            catch (Exception ex)
            {
                // Log and handle decryption errors
                Console.WriteLine($"Decryption error: {ex.Message}");
                throw;
            }
        }
    }

    public enum KeyDerivationFunction
    {
        PBKDF2,
        HMACSHA256
    }

    public static class DataHandlerFactory
    {
        public static IDataHandler GetDataHandler(KeyDerivationFunction keyDerivationFunction)
        {
            return new AESCipher(keyDerivationFunction);
        }
    }

    // Example usage:
    class Program
    {
        static void Main()
        {
            var data = new { Name = "John Doe", Age = 30 };
            var key = GenerateKey();
            var iv = GenerateIV();

            var handler = DataHandlerFactory.GetDataHandler(KeyDerivationFunction.PBKDF2);
            var encryptedData = handler.Encrypt(data, key, iv);

            var decryptedData = handler.Decrypt<dynamic>(encryptedData, key, iv);
            Console.WriteLine($"Decrypted data: {JsonConvert.SerializeObject(decryptedData)}");
        }

        static byte[] GenerateKey()
        {
            // Implement key generation logic
            return new byte[32]; // Example key size for AES-256
        }

        static byte[] GenerateIV()
        {
            // Implement IV generation logic
            return new byte[16]; // Example IV size for AES-CBC
        }
    }
}
