using System;
using System.IO;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Data.SqlClient;
using MassTransit;

public class LogProcessorService : BackgroundService
{
    private readonly string _logDirectory;
    private readonly string _databaseConnectionString;
    private readonly IBus _bus;
    private readonly ILogger<LogProcessorService> _logger;

    public LogProcessorService(string logDirectory, string databaseConnectionString, IBus bus, ILogger<LogProcessorService> logger)
    {
        _logDirectory = logDirectory;
        _databaseConnectionString = databaseConnectionString;
        _bus = bus;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        var filesToProcess = new Queue<string>();
        var processingTasks = new List<Task>();

        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                var file = GetNextLogFile(_logDirectory);
                if (file != null)
                {
                    filesToProcess.Enqueue(file);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to get next log file");
            }

            while (filesToProcess.Count > 0 && processingTasks.Count < Environment.ProcessorCount)
            {
                var file = filesToProcess.Dequeue();
                var task = ProcessLogFileAsync(file);
                processingTasks.Add(task);

                task.ContinueWith(t =>
                {
                    processingTasks.Remove(t);
                    if (!stoppingToken.IsCancellationRequested)
                    {
                        _logger.LogInformation("Processing of {File} completed", file);
                    }
                }, TaskScheduler.Default);
            }

            await Task.Delay(1000, stoppingToken); // Poll every second
        }

        await Task.WhenAll(processingTasks);
    }

    private string GetNextLogFile(string directory)
    {
        var files = Directory.GetFiles(directory, "*.bin", SearchOption.TopDirectoryOnly);
        Array.Sort(files);

        foreach (var file in files)
        {
            if (!IsProcessing(file))
            {
                return file;
            }
        }

        return null;
    }

    private bool IsProcessing(string file)
    {
        // Implement logic to check if the file is currently being processed
        return false;
    }

