        {
            var data = await DeserializeLogDataAsync(file);
            using (var connection = new SqlConnection(_databaseConnectionString))
            {
                await connection.OpenAsync();
                using (var transaction = connection.BeginTransaction())
                {
                    foreach (var record in data)
                    {
                        await InsertRecordAsync(connection, transaction, record);
                    }
                    transaction.Commit();
                }
            }

            await _bus.Publish(new LogFileProcessedEvent { FileName = file });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to process log file: {File}", file);
            // Implement retry logic with exponential backoff
        }
    }

    private async Task<LogData[]> DeserializeLogDataAsync(string file)
    {
        // Implement deserialization logic here
        return new LogData[] { };
    }

    private async Task InsertRecordAsync(SqlConnection connection, SqlTransaction transaction, LogData record)
    {
        using (var command = new SqlCommand("INSERT INTO Logs (Field1, Field2) VALUES (@Value1, @Value2)", connection, transaction))
        {
            command.Parameters.AddWithValue("@Value1", record.Field1);
            command.Parameters.AddWithValue("@Value2", record.Field2);
            await command.ExecuteNonQueryAsync();
        }
    }
}

public class LogData
{
    public string Field1 { get; set; }
    public int Field2 { get; set; }
}

public class LogFileProcessedEvent : IntegrationEvent
{
    public string FileName { get; set; }
}
