const axios = require('axios');
const fs = require('fs-extra');
const path = require('path');
const { v4: uuidv4 } = require('uuid');

// Mock external API and logging service
const uploadAPI = 'https://api.cloudstorage.com/upload';
const logService = 'https://logs.service.com/post';

async function validateFile(file) {
    const allowedTypes = ['application/pdf', 'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'image/jpeg', 'image/png'];
    if (!allowedTypes.includes(file.mimetype)) throw new Error('Invalid file type');
    if (file.size > 100 * 1024 * 1024) throw new Error('File size exceeds limit');
}

async function uploadFile(file, retries = 3) {
    const fileId = uuidv4();
    try {
        await validateFile(file);
        const formData = new FormData();
        formData.append('file', fs.createReadStream(file.path), { filename: file.name });
        await axios.post(uploadAPI, formData, {
            headers: formData.getHeaders(),
            maxContentLength: Infinity,
            maxBodyLength: Infinity
        });
        console.log(`File ${fileId} uploaded successfully`);
        fs.unlinkSync(file.path); // Clean up temporary file
    } catch (error) {
        if (retries > 0) {
            await new Promise(resolve => setTimeout(resolve, 1000)); // Wait before retrying
            return uploadFile(file, retries - 1);
        }
        console.error(`Failed to upload file ${fileId}:`, error.message);
        await axios.post(logService, { fileId, error: error.message });
    }
}

async function main() {
    const files = [
        // Simulate uploaded files
        { path: 'path/to/file1.pdf', name: 'file1.pdf' },
        { path: 'path/to/file2.jpg', name: 'file2.jpg' },
        // Add more files as needed
    ];
    for (const file of files) {
        await uploadFile(file);
    }
}

main();
