        if !data_dir.exists() {
            info!("Creating directory at {:?}", data_dir);
            std::fs::create_dir_all(&data_dir).map_err(|e| e.to_string())?;
        } else if !config.validate_path(&data_dir) {
            error!("Invalid path for DATA_DIR: {:?}", data_dir);
            return Err("Invalid path for DATA_DIR".to_string());
