import json
from abc import ABC, abstractmethod
from typing import Dict, Any, Type, Callable

class JSONModel(ABC):
    schema: dict = None

    @classmethod
    def validate_json(cls, json_data: str) -> bool:
        try:
            data = json.loads(json_data)
            return cls.schema.validate(data)
        except (json.JSONDecodeError, KeyError, TypeError):
            return False

    @abstractmethod
    def to_dict(self) -> dict:
        pass

class FactoryRegistry:
    registry: Dict[str, Callable] = {}

    @staticmethod
    def register_factory(schema_id: str, version: int, factory_func: Callable):
        if schema_id in FactoryRegistry.registry and FactoryRegistry.registry[schema_id].__version__ != version:
            raise ValueError(f"Schema conflict for {schema_id}")
        FactoryRegistry.registry[f"{schema_id}_{version}"] = factory_func

    @staticmethod
    def get_factory(schema_id: str, version: int) -> Callable:
        return FactoryRegistry.registry.get(f"{schema_id}_{version}")

class CustomAttributeMixin:
    _custom_attributes: Dict[str, Any] = {}

    def add_custom_attribute(self, key: str, value: Any):
        self._custom_attributes[key] = value

    def get_custom_attribute(self, key: str):
        return self._custom_attributes.get(key)

    def to_dict(self) -> dict:
        base_dict = super().to_dict()
        base_dict.update(self._custom_attributes)
        return base_dict

class User(JSONModel, CustomAttributeMixin):
    schema_id = "user"
    version = 1
    schema = {"type": "object", "properties": {"id": {"type": "integer"}, "name": {"type": "string"}}}

    @classmethod
    def from_json(cls, json_data: str) -> 'User':
        if not cls.validate_json(json_data):
            raise ValueError("Invalid JSON data for User model")
        data = json.loads(json_data)
        user = cls()
        user.id = data['id']
        user.name = data['name']
        return user

    def to_dict(self) -> dict:
        return {'id': self.id, 'name': self.name}

def factory_function(schema_id: str, version: int, json_data: str):
    if schema_id == User.schema_id and version == User.version:
        return User.from_json(json_data)
    raise ValueError("Unsupported schema or version")

FactoryRegistry.register_factory(User.schema_id, User.version, factory_function)

# Example usage
json_data = '{"id": 1, "name": "John Doe"}'
user_model = FactoryRegistry.get_factory(User.schema_id, User.version)(json_data)
print(user_model.to_dict())
