using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;

public class OAuthTokenValidator
{
    private readonly HttpClient _httpClient;
    private readonly ILogger _logger;
    private readonly IMessageBroker _messageBroker;
    private readonly ICacheService _cacheService;
    private readonly TokenValidationConfig _config;

    public OAuthTokenValidator(HttpClient httpClient, ILogger logger, IMessageBroker messageBroker, ICacheService cacheService, TokenValidationConfig config)
    {
        _httpClient = httpClient;
        _logger = logger;
        _messageBroker = messageBroker;
        _cacheService = cacheService;
        _config = config;
    }

    public async Task<bool> ValidateTokenAsync(string token)
    {
        try
        {
            var seedValues = await FetchSeedValuesAsync();
            if (!seedValues.Contains(token))
                return false;

            var payload = ParseTokenPayload(token);
            if (payload == null)
                return false;

            if (!IsValidTokenType(payload.TokenType) || !IsPositiveInteger(payload.ExpiresIn))
                return false;

            // Additional checks can be added here based on custom validation rules

            return true;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to validate token");
            await _messageBroker.PublishAsync("TokenValidationFailure", token);
            return false;
        }
    }

    private async Task<HashSet<string>> FetchSeedValuesAsync()
    {
        try
        {
            var cacheKey = "seed-values";
            if (_cacheService.Exists(cacheKey))
                return _cacheService.Get<HashSet<string>>(cacheKey);

            var response = await _httpClient.GetAsync("/api/seed-values");
            response.EnsureSuccessStatusCode();
            var seedValues = await response.Content.ReadAsAsync<HashSet<string>>();

            _cacheService.Set(cacheKey, seedValues, TimeSpan.FromMinutes(5));
            return seedValues;
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Failed to fetch seed values");
            await _messageBroker.PublishAsync("SeedValuesFetchFailure");
            throw new Exception("Unable to fetch seed values", ex);
        }
    }

    private TokenPayload ParseTokenPayload(string token)
    {
        try
        {
            var segments = token.Split('.');
            if (segments.Length != 3) return null;

            var payloadBase64 = Encoding.UTF8.GetString(Convert.FromBase64String(segments[1]));
            var payloadJson = JObject.Parse(payloadBase64);
            return new TokenPayload
            {
                AccessToken = payloadJson["access_token"].ToString(),
                ExpiresIn = (int?)payloadJson["expires_in"],
                TokenType = payloadJson["token_type"]?.ToString()
            };
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to parse token payload");
            return null;
        }
    }

    private bool IsValidTokenType(string tokenType) => tokenType == "Bearer";

    private bool IsPositiveInteger(int? value) => value.HasValue && value > 0;

    public class TokenPayload
    {
        public string AccessToken { get; set; }
        public int? ExpiresIn { get; set; }
        public string TokenType { get; set; }
    }

    public class TokenValidationConfig
    {
        public TimeSpan CacheTtl { get; set; }
        // Additional configurable parameters can be added here
    }
}

public interface ILogger
{
    void LogError(Exception ex, string message);
}

public interface IMessageBroker
{
    Task PublishAsync(string topic, object message);
}

public interface ICacheService
{
    bool Exists(string key);
    T Get<T>(string key) where T : class;
    void Set(string key, object value, TimeSpan ttl);
}
