#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef void (*callback_t)(const char*);

// Global mutex for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Cache to store frequently used strings
#define CACHE_SIZE 1024
static struct {
    const char* key;
    char* value;
} cache[CACHE_SIZE];
static int cache_index = 0;

char* process_string(const char* input, int size_limit, callback_t on_restriction_exceeded) {
    if (input == NULL || size_limit <= 0) {
        fprintf(stderr, "Invalid input or size limit\n");
        return NULL;
    }

    // Check cache
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].key != NULL && strcmp(cache[i].key, input) == 0) {
            pthread_mutex_lock(&mutex);
            char* result = strdup(cache[i].value);
            pthread_mutex_unlock(&mutex);
            return result;
        }
    }

    // Lock for thread safety
    pthread_mutex_lock(&mutex);

    // Check if input exceeds size limit
    if (strlen(input) > size_limit) {
        on_restriction_exceeded(input);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Allocate memory for modified string
    char* result = malloc(strlen(input) + 2); // +1 for '/', +1 for '\0'
    if (result == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Copy input and append '/'
    strcpy(result, input);
    result[strlen(input)] = '/';
    result[strlen(input) + 1] = '\0';

    // Update cache
    if (cache_index < CACHE_SIZE) {
        cache[cache_index].key = input;
        cache[cache_index].value = strdup(result);
        cache_index++;
    }

    pthread_mutex_unlock(&mutex);

    return result;
}
