#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <openssl/ssl.h>

#define PORT 8443
#define MAX_COMMANDS 100
#define MAX_PRIORITY 5
#define MAX_RESOURCE_QUOTA 1024

typedef struct {
    int id;
    char command[256];
    int priority;
    int resource_quota;
} Command;

Command commands[MAX_COMMANDS];

void* execute_command(void* arg) {
    // Simulate command execution
    printf("Executing command: %s\n", ((Command*)arg)->command);
    return NULL;
}

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    SSL_library_init();
    OpenSSL_add_all_algorithms();
    SSL_CTX* ssl_ctx = SSL_CTX_new(TLSv1_2_server_method());
    if (!ssl_ctx) {
        fprintf(stderr, "SSL context creation failed\n");
        return 1;
    }

    // Load certificates and private keys
    if (SSL_CTX_use_certificate_file(ssl_ctx, "server.crt", SSL_FILETYPE_PEM) <= 0 ||
        SSL_CTX_use_PrivateKey_file(ssl_ctx, "server.key", SSL_FILETYPE_PEM) <= 0) {
        fprintf(stderr, "Loading certificate or key failed\n");
        return 1;
    }

    if (socket(AF_INET, SOCK_STREAM, 0) == 0) {
        perror("Socket creation failed");
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        return 1;
    }

    if (listen(server_fd, MAX_COMMANDS) < 0) {
        perror("Listen failed");
        return 1;
    }

    printf("Listening on port %d\n", PORT);

    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("Accept failed");
            continue;
        }

        SSL* ssl = SSL_new(ssl_ctx);
        SSL_set_fd(ssl, new_socket);

        if (SSL_accept(ssl) <= 0) {
            ERR_print_errors_fp(stderr);
            SSL_free(ssl);
            close(new_socket);
            continue;
        }

        // Receive command from client
        char buffer[256];
        SSL_read(ssl, buffer, sizeof(buffer));

        // Parse and queue command
        if (buffer[0] == 'C') {
            int id = atoi(strchr(buffer, ':') + 1);
            strncpy(commands[id].command, strchr(buffer, ',') + 1, sizeof(commands[id].command) - 1);
            commands[id].priority = atoi(strchr(buffer, ';') + 1);
            commands[id].resource_quota = atoi(strchr(buffer, '*') + 1);

            // Execute command in separate thread
            pthread_t thread_id;
            pthread_create(&thread_id, NULL, execute_command, &commands[id]);
        }

        SSL_shutdown(ssl);
        SSL_free(ssl);
        close(new_socket);
    }

    SSL_CTX_free(ssl_ctx);
    return 0;
}
