#define MAX_NODES 10
#define MAX_CONNECTIONS_PER_NODE 5

typedef struct {
    int value;
} Record;

typedef struct {
    pthread_mutex_t lock;
    Record records[MAX_CONNECTIONS_PER_NODE];
} Node;

Node nodes[MAX_NODES];

void* process_data(void* arg) {
    int node_id = *(int*)arg;
    free(arg);

    // Simulate data processing
    for (int i = 0; i < MAX_CONNECTIONS_PER_NODE; i++) {
        pthread_mutex_lock(&nodes[node_id].lock);
        nodes[node_id].records[i].value += 1;
        pthread_mutex_unlock(&nodes[node_id].lock);
    }

    return NULL;
}

void initialize_pipeline() {
    for (int i = 0; i < MAX_NODES; i++) {
        pthread_mutex_init(&nodes[i].lock, NULL);

        // Simulate data initialization
        for (int j = 0; j < MAX_CONNECTIONS_PER_NODE; j++) {
            nodes[i].records[j].value = 0;
        }
    }

    int* args[MAX_NODES];
    for (int i = 0; i < MAX_NODES; i++) {
        args[i] = malloc(sizeof(int));
        *args[i] = i;

        pthread_t thread;
        pthread_create(&thread, NULL, process_data, args[i]);
    }
}

int main() {
    initialize_pipeline();

    // Simulate long-running pipeline
    sleep(10);

    return 0;
}
```

