void processLogMessage(const char *logMessage, size_t maxLength, int toUpperCase, LoggingServiceClient *client) {
    if (maxLength <= 0 || logMessage == NULL) return;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    char buffer[maxLength + 1];
    snprintf(buffer, maxLength, "%s", logMessage);

    if (strlen(buffer) >= maxLength) {
        appendTimestamp(buffer, maxLength);
    }

    if (toUpperCase) {
        for (int i = 0; buffer[i]; ++i) {
            buffer[i] = toupper((unsigned char)buffer[i]);
        }
    }

    int retryCount = 3;
    while (retryCount--) {
        // Simulate logging service call
        if (sendLogMessage(buffer, client)) {
            printf("Log message sent successfully.\n");
            break;
        } else {
            printf("Failed to send log message. Retrying...\n");
            sleep(1 << retryCount); // Exponential backoff
        }
    }

    if (retryCount == -1) {
        printf("Final failure: Log message not sent after retries.\n");
    }

    pthread_mutex_unlock(&mutex);
}

