#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct ChannelQualityIndication {
    int signal_strength;
    int noise_level;
    int interference_level;
} ChannelQualityIndication;

typedef struct FrameMetadata {
    int frame_id;
    long timestamp;
    ChannelQualityIndication *quality_indications;
    int quality_count;
    struct FrameMetadata *next;
} FrameMetadata;

typedef struct LinkedList {
    FrameMetadata *head;
    pthread_mutex_t mutex;
} LinkedList;

void init_linked_list(LinkedList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

void add_frame_metadata(LinkedList *list, int frame_id, long timestamp, ChannelQualityIndication *quality_indications, int quality_count) {
    pthread_mutex_lock(&list->mutex);
    FrameMetadata *new_frame = (FrameMetadata *)malloc(sizeof(FrameMetadata));
    new_frame->frame_id = frame_id;
    new_frame->timestamp = timestamp;
    new_frame->quality_indications = quality_indications;
    new_frame->quality_count = quality_count;
    new_frame->next = list->head;
    list->head = new_frame;
    pthread_mutex_unlock(&list->mutex);
}

void iterate_linked_list(LinkedList *list, void (*callback)(FrameMetadata *)) {
    pthread_mutex_lock(&list->mutex);
    FrameMetadata *current = list->head;
    while (current != NULL) {
        callback(current);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

void destroy_linked_list(LinkedList *list) {
    pthread_mutex_lock(&list->mutex);
    FrameMetadata *current = list->head;
    while (current != NULL) {
        FrameMetadata *temp = current;
        current = current->next;
        free(temp->quality_indications);
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
