#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <atomic>
#include <mutex>
#include <condition_variable>

class NetworkManager {
public:
    NetworkManager(size_t maxConnections)
        : maxConnections_(maxConnections), activeConnections_(0) {}

    void connect(const std::string& url, bool useAsync = true) {
        if (activeConnections_ >= maxConnections_) {
            throw std::runtime_error("Too many connections");
        }

        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this] { return activeConnections_ < maxConnections_; });

        activeConnections_++;
        // Simulate connection establishment
        std::cout << "Connecting to " << url << std::endl;

        if (useAsync) {
            asyncTask(url);
        } else {
            syncTask(url);
        }

        lock.unlock();
        cv_.notify_one();
    }

private:
    void syncTask(const std::string& url) {
        // Simulate synchronous task
        std::this_thread::sleep_for(std::chrono::seconds(1));
        std::cout << "Connected to " << url << " (sync)" << std::endl;
    }

    void asyncTask(const std::string& url) {
        // Simulate asynchronous task using a separate thread
        std::thread([url]() {
            std::this_thread::sleep_for(std::chrono::seconds(1));
            std::cout << "Connected to " << url << " (async)" << std::endl;
        }).detach();
    }

    size_t maxConnections_;
    std::atomic<size_t> activeConnections_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

int main() {
    NetworkManager manager(10);

    try {
        for (size_t i = 0; i < 15; ++i) {
            manager.connect("http://example.com/api", true);
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
