                logStatus("Decrypted Data: " + decryptedData);
                monitoringTool.trackPerformance();
            } catch (Exception e) {
                handleError(e);
            }
        });
    }

    public void generateKey(String keyId) {
        executorService.submit(() -> {
            try {
                String key = performKeyGeneration();
                keyManagementService.storeKey(keyId, key);
                logStatus("Generated Key: " + key);
                monitoringTool.trackPerformance();
            } catch (Exception e) {
                handleError(e);
            }
        });
    }

    public void verifyDigitalSignature(String data, String signature, String keyId) {
