            try {
                String key = keyManagementService.getKey(keyId);
                boolean isValid = performDigitalSignatureVerification(data, signature, key);
                logStatus("Signature Verification: " + isValid);
                monitoringTool.trackPerformance();
            } catch (Exception e) {
                handleError(e);
            }
        });
