#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_THREADS 10000

sem_t semaphore;
int thread_count = 0;

void* p_operation(void* arg) {
    sem_wait(&semaphore);
    // Critical section
    printf("Thread %ld entered critical section\n", (long)arg);
    pthread_yield(); // Simulate work
    printf("Thread %ld exited critical section\n", (long)arg);
    sem_post(&semaphore);
    return NULL;
}

void initialize_semaphore(int initial_value) {
    sem_init(&semaphore, 0, initial_value);
}

int main() {
    pthread_t threads[MAX_THREADS];

