// Mock InterfaceTable class for testing
class InterfaceTable {
public:
    virtual std::string FindVmUuidFromMetadataIp(const std::string& ip) = 0;
};

class MockInterfaceTable : public InterfaceTable {
public:
    MockInterfaceTable() {}

    std::string FindVmUuidFromMetadataIp(const std::string& ip) override {
        // Simulate different conditions
        if (ip == "192.168.1.1") return "vm1";
        else if (ip == "192.168.1.2") return "vm2";
        else return "unknown";
    }
};

// Service class managing the lifecycle
class Service {
private:
    std::mutex mutex_;
    std::condition_variable cv_;
    bool running_;

public:
    Service() : running_(false) {}

    void StartService(const InterfaceTable& interface_table, const std::string& ip) {
        std::lock_guard<std::mutex> lock(mutex_);
        running_ = true;
        // Simulate service start
        std::cout << "Starting service for IP: " << ip << std::endl;
        cv_.notify_all();
    }

    void StopService() {
        std::unique_lock<std::mutex> lock(mutex_);
        running_ = false;
        cv_.notify_all();
        // Simulate service stop
        std::cout << "Stopping service" << std::endl;
    }

    bool IsRunning() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return running_;
    }
};

// Application class managing the service lifecycle with variable delays
class Application {
private:
    Service service_;
    InterfaceTable* interface_table_;
    std::vector<std::thread> threads_;
    std::atomic<bool> stop_flag_;

public:
    Application(InterfaceTable* table) : interface_table_(table), stop_flag_(false) {}

    void Start() {
        for (int i = 0; i < 5; ++i) {
            threads_.emplace_back([this, i]() {
                while (!stop_flag_) {
                    if (service_.IsRunning()) {
                        std::string ip = "192.168.1." + std::to_string(i % 3);
                        service_.StartService(*interface_table_, ip);
                        std::this_thread::sleep_for(std::chrono::seconds(1 + i));
                        service_.StopService();
                    }
                    std::this_thread::sleep_for(std::chrono::seconds(1));
                }
            });
        }

        for (auto& thread : threads_) {
            if (thread.joinable()) thread.join();
        }
    }

    void Stop() {
        stop_flag_ = true;
    }
};

int main() {
    MockInterfaceTable mock_table;
    Application app(&mock_table);
    app.Start();

    // Simulate application running for 10 seconds
    std::this_thread::sleep_for(std::chrono::seconds(10));
    app.Stop();

    return 0;
}
```

