using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Polly;

public interface IDatabaseService
{
    Task<List<DataTable>> ExecuteQueriesAsync(List<string> queries, List<IDictionary<string, object>> parameters, string connectionString, int batchSize, int timeout);
}

public class DatabaseService : IDatabaseService
{
    private readonly ILogger _logger;
    private readonly IConnectionManager _connectionManager;

    public DatabaseService(ILogger<DatabaseService> logger, IConnectionManager connectionManager)
    {
        _logger = logger;
        _connectionManager = connectionManager;
    }

    public async Task<List<DataTable>> ExecuteQueriesAsync(List<string> queries, List<IDictionary<string, object>> parameters, string connectionString, int batchSize, int timeout)
    {
        var results = new List<DataTable>();

        foreach (var query in queries)
        {
            var parameterValues = parameters.FirstOrDefault(p => p.Keys.Contains(query))?.Values;
            using (var connection = await _connectionManager.GetConnectionAsync(connectionString))
            {
                try
                {
                    var command = new SqlCommand(query, connection);
                    if (parameterValues != null)
                    {
                        for (int i = 0; i < parameterValues.Count(); i++)
                        {
                            command.Parameters.AddWithValue($"@Param{i}", parameterValues.ElementAt(i));
                        }
                    }

                    command.CommandTimeout = timeout;
                    using (var adapter = new SqlDataAdapter(command))
                    {
                        var dataTable = new DataTable();
                        await Task.Run(() => adapter.Fill(dataTable));
                        results.Add(dataTable);
                    }
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error executing query: {Query}", query);
                    throw;
                }
            }
        }

        return results;
    }
}

public interface IConnectionManager
{
    Task<SqlConnection> GetConnectionAsync(string connectionString);
}

public class ConnectionManager : IConnectionManager
{
    private readonly ILogger _logger;

    public ConnectionManager(ILogger<ConnectionManager> logger)
    {
        _logger = logger;
    }

    public async Task<SqlConnection> GetConnectionAsync(string connectionString)
    {
        var retryPolicy = Policy.Handle<SqlException>()
                               .WaitAndRetryAsync(
                                   retryCount: 3,
                                   sleepDurationProvider: retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)),
                                   onRetry: (exception, retryCount, context) =>
                                   {
                                       _logger.LogWarning(exception, "Retrying connection attempt {RetryCount}", retryCount);
                                   });

        var connection = new SqlConnection(connectionString);

        await retryPolicy.ExecuteAsync(async () =>
        {
            if (string.IsNullOrEmpty(connectionString))
                throw new ArgumentException("Connection string cannot be null or empty.");

            try
            {
                await connection.OpenAsync();
            }
            catch (SqlException ex)
            {
                _logger.LogError(ex, "Failed to open connection with the following error: {Error}", ex.Message);
                throw;
            }
        });

        return connection;
    }
}
