public class EnvironmentControlService : IDisposable
{
    private readonly HttpClient _httpClient;
    private readonly IDistributedCache _cache;
    private readonly AsyncRetryPolicy _retryPolicy;

    public EnvironmentControlService(HttpClient httpClient, IDistributedCache cache)
    {
        _httpClient = httpClient;
        _cache = cache;
        _retryPolicy = Policy
            .Handle<HttpRequestException>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));
    }

    public async Task AdjustEnvironmentAsync(int environmentId, double temperature, double humidity, int airQuality)
    {
        var cacheKey = $"environment:{environmentId}";
        var dataToCache = new { Temperature = temperature, Humidity = humidity, AirQuality = airQuality };

        await _retryPolicy.ExecuteAsync(async () =>
        {
            await _cache.SetStringAsync(cacheKey, System.Text.Json.JsonSerializer.Serialize(dataToCache), new DistributedCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(1)
            });
        });

        // Simulate sending data to third-party APIs
        var apiUrl = "https://api.example.com/environment/control";
        var requestBody = new { EnvironmentId = environmentId, Temperature, Humidity, AirQuality };
        await _httpClient.PostAsJsonAsync(apiUrl, requestBody);
    }

    public void Dispose()
    {
        _httpClient.Dispose();
    }
}
