	subscriptions = make(map[string]UserSubscription)
	cache         Cache
)

func main() {
	r := chi.NewRouter()
	r.Use(middleware.Logger)
	r.Use(otelhttp.Middleware("user-subscription-service"))

	r.Post("/subscriptions", handleSubscribe)
	r.Put("/subscriptions/{user_id}", handleUpdate)
	r.Delete("/subscriptions/{user_id}", handleUnsubscribe)

	http.ListenAndServe(":8080", r)
}

func handleSubscribe(w http.ResponseWriter, r *http.Request) {
	var subscription UserSubscription
	if err := json.NewDecoder(r.Body).Decode(&subscription); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	if !validateSubscription(subscription) {
		http.Error(w, "Validation failed", http.StatusUnprocessableEntity)
		return
	}

	if err := processPayment(context.Background(), subscription.UserID, subscription.Plan); err != nil {
		http.Error(w, "Failed to process payment", http.StatusInternalServerError)
		return
	}

	subscriptions[subscription.UserID] = subscription
	cache.Set(subscription.UserID, subscription)

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(subscription)
}

func handleUpdate(w http.ResponseWriter, r *http.Request) {
	userID := chi.URLParam(r, "user_id")
	if userID == "" {
		http.Error(w, "User ID is required", http.StatusBadRequest)
		return
	}

	var subscription UserSubscription
	if err := json.NewDecoder(r.Body).Decode(&subscription); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	if !validateSubscription(subscription) {
		http.Error(w, "Validation failed", http.StatusUnprocessableEntity)
		return
	}

	if err := processPayment(context.Background(), userID, subscription.Plan); err != nil {
		http.Error(w, "Failed to process payment", http.StatusInternalServerError)
		return
	}

	subscriptions[userID] = subscription
	cache.Set(userID, subscription)

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(subscription)
}

func handleUnsubscribe(w http.ResponseWriter, r *http.Request) {
	userID := chi.URLParam(r, "user_id")
	if userID == "" {
		http.Error(w, "User ID is required", http.StatusBadRequest)
		return
	}

	subscription, exists := subscriptions[userID]
	if !exists {
		http.Error(w, "Subscription not found", http.StatusNotFound)
		return
	}

	if err := processRefund(context.Background(), subscription.UserID); err != nil {
		http.Error(w, "Failed to process refund", http.StatusInternalServerError)
		return
	}

	delete(subscriptions, userID)
	cache.Delete(userID)

	w.WriteHeader(http.StatusOK)
}

func validateSubscription(subscription UserSubscription) bool {
