using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Memory;
using Polly;
using Polly.Retry;

[ApiController]
[Route("api/[controller]")]
public class OctreeController : ControllerBase
{
    private readonly IMemoryCache _cache;
    private readonly IExternalOctreeService _externalOctreeService;
    private readonly AsyncRetryPolicy _retryPolicy;

    public OctreeController(IMemoryCache cache, IExternalOctreeService externalOctreeService)
    {
        _cache = cache;
        _externalOctreeService = externalOctreeService;
        _retryPolicy = Policy
            .Handle<Exception>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));
    }

    [HttpPost("update")]
    public async Task<IActionResult> UpdateOctreeElementAsync(
        int pageSectionId,
        int elementId,
        string htmlContent,
        double featureSize,
        int numberOfLeafNodes)
    {
        var cacheKey = $"pageSection_{pageSectionId}_element_{elementId}";

        try
        {
            await _retryPolicy.ExecuteAsync(async () =>
            {
                var octreeElement = await GetOctreeElementFromCacheOrServiceAsync(pageSectionId, elementId);

                if (octreeElement == null)
                {
                    return NotFound();
                }

                octreeElement.HtmlContent = htmlContent;
                octreeElement.FeatureSize = featureSize;
                octreeElement.NumberOfLeafNodes = numberOfLeafNodes;

                await UpdateOctreeElementInCacheAsync(octreeElement);
                await _externalOctreeService.UpdateOctreeElementAsync(octreeElement);

                return Ok();
            });
        }
        catch (Exception ex)
        {
            return StatusCode(500, $"Internal server error: {ex.Message}");
        }
    }

    private async Task<OctreeElement> GetOctreeElementFromCacheOrServiceAsync(int pageSectionId, int elementId)
    {
        var cacheKey = $"pageSection_{pageSectionId}_element_{elementId}";

        if (_cache.TryGetValue(cacheKey, out OctreeElement cachedElement))
        {
            return cachedElement;
        }

        try
        {
            var octreeElement = await _externalOctreeService.GetOctreeElementAsync(pageSectionId, elementId);
            _cache.Set(cacheKey, octreeElement, new MemoryCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5)
            });
            return octreeElement;
        }
        catch (Exception ex)
        {
            // Log the error or notify monitoring system
            return null;
        }
    }

    private async Task UpdateOctreeElementInCacheAsync(OctreeElement octreeElement)
    {
        var cacheKey = $"pageSection_{octreeElement.PageSectionId}_element_{octreeElement.ElementId}";
        _cache.Set(cacheKey, octreeElement, new MemoryCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5)
        });
    }
}

public class OctreeElement
{
    public int PageSectionId { get; set; }
    public int ElementId { get; set; }
    public string HtmlContent { get; set; }
    public double FeatureSize { get; set; }
    public int NumberOfLeafNodes { get; set; }
}

public interface IExternalOctreeService
{
    Task<OctreeElement> GetOctreeElementAsync(int pageSectionId, int elementId);
    Task UpdateOctreeElementAsync(OctreeElement octreeElement);
}

public class ExternalOctreeService : IExternalOctreeService
{
