// Import necessary libraries and dependencies
import axios from 'axios';
import LRU from 'lru-cache';

// Define the function to refresh dialog fields
function refreshDialogFields(config) {
  const { fields, url, cacheControl } = config;
  const fieldCache = new LRU(cacheControl.cacheSize);

  // Function to fetch data from the external API
  async function fetchData(field) {
    const cacheKey = `${field.name}_${field.version}`;
    if (fieldCache.has(cacheKey)) {
      return fieldCache.get(cacheKey);
    }

    try {
      const response = await axios.get(url, { params: { id: field.id } });
      const data = response.data;
      fieldCache.set(cacheKey, data);
      return data;
    } catch (error) {
      console.error(`Failed to fetch data for ${field.name}:`, error);
      throw new Error('Data fetching failed');
    }
  }

  // Function to update the dialog fields
  async function updateFields() {
    const updates = [];

    for (const field of fields) {
      try {
        const data = await fetchData(field);
        updates.push({ fieldName: field.name, version: field.version, data });
      } catch (error) {
        console.error(`Failed to update ${field.name}:`, error);
      }
    }

    // Send updates to the parent window
    for (const update of updates) {
      window.parent.postMessage(update, '*');
    }
  }

  // Function to count occurrences of Old Testament book names
  function countOldTestamentBooks(text) {
    const books = [
      'Genesis', 'Exodus', 'Leviticus', 'Numbers', 'Deuteronomy',
      'Joshua', 'Judges', 'Ruth', '1 Samuel', '2 Samuel',
      '1 Kings', '2 Kings', '1 Chronicles', '2 Chronicles',
      'Ezra', 'Nehemiah', 'Esther', 'Job', 'Psalms',
      'Proverbs', 'Ecclesiastes', 'Song of Songs', 'Isaiahu',
      'Jeremiah', 'Lamentations', 'Ezekiel', 'Daniel', 'Hosea',
      'Joel', 'Amos', 'Obadiah', 'Jonah', 'Micah',
      'Nahum', 'Habakkuk', 'Zephaniah', 'Haggai', 'Zechariah',
      'Malachi'
    ];

    const regex = new RegExp(`\\b(${books.join('|')})\\b`, 'gi');
    const matches = text.match(regex);
    return matches ? matches.length : 0;
  }

  // Function to handle errors and retries
  async function handleErrorAndRetry(func, retries = 3) {
    for (let i = 0; i < retries; i++) {
      try {
        await func();
        break;
      } catch (error) {
        if (i === retries - 1) throw error;
        console.warn(`Attempt ${i + 1} failed, retrying...`);
        await new Promise(resolve => setTimeout(resolve, 1000 * Math.pow(2, i)));
      }
    }
  }

  // Main function to execute the refresh process
  async function main() {
    try {
      handleErrorAndRetry(updateFields);
      const bookCount = countOldTestamentBooks(config.textContent);
      console.log(`Number of Old Testament books found: ${bookCount}`);
    } catch (error) {
      console.error('Failed to refresh dialog fields:', error);
      // Display a loading indicator or feedback message
    }
  }

  main();
}

// Example usage
const config = {
  fields: [
    { name: 'dialog_field_1', version: 1, id: '123' },
    { name: 'dialog_field_2', version: 1, id: '456' }
  ],
  url: 'https://api.example.com/data',
  cacheControl: { cacheSize: 100 },
  textContent: 'Lorem ipsum dolor sit amet...'
};

refreshDialogFields(config);
```

