import org.apache.spark.streaming.kafka010.KafkaUtils;
import org.apache.spark.streaming.kafka010.LocationStrategies;

public class IntegerStreamProcessor {

    private JavaSparkContext sparkContext;
    private int maxBatchSize;
    private long threshold;
    private String kafkaBrokers;
    private String kafkaTopic;

    public IntegerStreamProcessor(JavaSparkContext sparkContext, int maxBatchSize, long threshold, String kafkaBrokers, String kafkaTopic) {
        this.sparkContext = sparkContext;
        this.maxBatchSize = maxBatchSize;
        this.threshold = threshold;
        this.kafkaBrokers = kafkaBrokers;
        this.kafkaTopic = kafkaTopic;
    }

    public void startProcessing() {
        JavaInputDStream<String> stream = KafkaUtils.createDirectStream(
                sparkContext,
                LocationStrategies.PreferConsistent(),
                ConsumerStrategies.Subscribe(kafkaTopic, Map.of("bootstrap.servers", kafkaBrokers))
        );

        JavaPairDStream<Integer, Integer> integerStream = stream.mapToPair(line -> {
            // Parse line to Integer
            return new Tuple2<>(line.hashCode(), 1);
        });

        integerStream.foreachRDD(rdd -> {
            long startTime = System.currentTimeMillis();
            rdd.takeSample(false, maxBatchSize)
                .parallelize()
                .foreachPartition(partition -> {
                    partition.forEachRemaining(item -> {
                        // Process item
                    });
                });

            long processingTime = System.currentTimeMillis() - startTime;
            if (processingTime > threshold) {
                System.out.println("Warning: Processing time exceeded threshold.");
            }
        });

        sparkContext.start();
        try {
            sparkContext.awaitTermination();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        JavaSparkContext sparkContext = new JavaSparkContext(new SparkConf().setAppName("IntegerStreamProcessor"));
        IntegerStreamProcessor processor = new IntegerStreamProcessor(sparkContext, 5000, 500, "kafka-brokers", "integer-stream");
        processor.startProcessing();
    }
}
