public static CustomDataStructure LoadFromBinaryFile(string filePath)
{
    CustomDataStructure data = null;
    using (FileStream fileStream = new FileStream(filePath, FileMode.Open))
    {
        BinaryFormatter binaryFormatter = new BinaryFormatter();
        try
        {
            data = (CustomDataStructure)binaryFormatter.Deserialize(fileStream);
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error deserializing from binary file: " + ex.Message);
        }
    }
    return data;
}
