// Define the service manager for handling microservices and their dependencies
class ServiceManager {
    protected $services;
    protected $dependencies;

    public function __construct() {
        $this->services = [];
        $this->dependencies = [];
    }

    public function registerService($name, $version) {
        $service = new Microservice($name, $version);
        $this->services[$name] = $service;
    }

    public function addDependency($serviceName, $dependencyName, $dependencyVersion) {
        if (!isset($this->dependencies[$serviceName])) {
            $this->dependencies[$serviceName] = [];
        }
        $this->dependencies[$serviceName][$dependencyName] = $dependencyVersion;
    }

    public function getServiceDependencies($serviceName) {
        return isset($this->dependencies[$serviceName]) ? $this->dependencies[$serviceName] : [];
    }
}

// Example usage
$serviceManager = new ServiceManager();
$serviceManager->registerService('user-api', 'v1');
$serviceManager->addDependency('user-api', 'oauth2-service', 'v2.0');

$userApi = $serviceManager->getServiceDependencies('user-api');
foreach ($userApi as $dependency => $version) {
    echo "Service: $dependency, Version: $version\n";
}
