// Import necessary crates
extern crate reqwest;
extern crate tokio;
extern crate prometheus;

use reqwest::{Client, Error};
use tokio::task;
use prometheus::{Registry, GaugeVec};

// Define constants
const API_VERSION: &str = "v1";
const AUTH_URL: &str = "https://auth.example.com/token";

// Initialize Prometheus metrics
static REQUEST_LATENCY: GaugeVec = GaugeVec::new(
    "http_request_latency_seconds",
    "HTTP request latency in seconds.",
    &["method", "endpoint"],
).unwrap();

static SUCCESS_RATE: GaugeVec = GaugeVec::new(
    "http_success_rate",
    "Success rate of HTTP requests.",
    &["method", "endpoint"],
).unwrap();

// Define the client struct
pub struct HttpClient {
    client: Client,
    auth_token: String,
}

impl HttpClient {
    // Constructor for HttpClient
    pub async fn new() -> Result<HttpClient, Error> {
        let mut client = Client::new();
        let auth_token = get_auth_token().await?;
        Ok(HttpClient { client, auth_token })
    }

    // Async GET request
    pub async fn get(&self, url: &str) -> Result<String, Error> {
        let response = self.client.get(url).header("Authorization", format!("Bearer {}", self.auth_token)).send().await?;
        let latency = response.elapsed().as_secs_f64();
        REQUEST_LATENCY.with_label_values(&["GET", url]).set(latency);
        SUCCESS_RATE.with_label_values(&["GET", url]).inc();
        response.text().await
    }

    // Async POST request
    pub async fn post(&self, url: &str, data: String) -> Result<String, Error> {
        let response = self.client.post(url).header("Authorization", format!("Bearer {}", self.auth_token)).body(data).send().await?;
        let latency = response.elapsed().as_secs_f64();
        REQUEST_LATENCY.with_label_values(&["POST", url]).set(latency);
        SUCCESS_RATE.with_label_values(&["POST", url]).inc();
        response.text().await
    }
}

// Function to get authentication token
async fn get_auth_token() -> Result<String, Error> {
    let client = Client::new();
    let response = client.post(AUTH_URL).form(&[("grant_type", "client_credentials")]).send().await?;
    let json = response.json::<serde_json::Value>().await?;
    let token = json.get("access_token").unwrap().as_str().unwrap().to_string();
    Ok(token)
}

// Entry point for the library
#[tokio::main]
async fn main() {
    // Initialize Prometheus metrics registry
    let mut prometheus_registry = Registry::new();
    REQUEST_LATENCY.register(&prometheus_registry);
    SUCCESS_RATE.register(&prometheus_registry);

    // Create an instance of HttpClient
    let http_client = HttpClient::new().await.unwrap();

    // Example usage: Perform a GET request
    match http_client.get("https://api.example.com/data").await {
        Ok(result) => println!("GET Response: {}", result),
        Err(e) => eprintln!("Error during GET request: {}", e),
    }

    // Example usage: Perform a POST request
    let data = serde_json::json!({"key": "value"}).to_string();
    match http_client.post("https://api.example.com/data", data).await {
        Ok(result) => println!("POST Response: {}", result),
        Err(e) => eprintln!("Error during POST request: {}", e),
    }
}
```

This code snippet provides a basic implementation of an HTTP client library in Rust that supports asynchronous GET and POST requests, integrates with an authentication service, and handles dependencies on third-party crates like `reqwest` and `tokio`. It also includes Prometheus metrics for monitoring request latency and success rates.']

['```rust
use std::process::{Command, Stdio};
use log::{info, error, warn};

fn process_media_conversion(
    input_file: &str,
    output_format: &str,
    max_retries: u32,
    retry_delay: u64,
) -> Result<(), String> {
    let mut retries = 0;
    loop {
        match execute_conversion(input_file, output_format) {
            Ok(_) => return Ok(()),
            Err(e) => {
                if retries >= max_retries {
                    error!("Max retries reached. Giving up.");
                    return Err(format!("Conversion failed after {} attempts: {}", retries, e));
                }
                retries += 1;
                warn!("Attempt {} failed: {}. Retrying in {} seconds...", retries, e, retry_delay);
                std::thread::sleep(std::time::Duration::from_secs(retry_delay));
            }
        }
    }
}

fn execute_conversion(input_file: &str, output_format: &str) -> Result<(), String> {
    let mut command = Command::new("third_party_converter")
        .arg(input_file)
        .arg(output_format)
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| format!("Failed to start conversion: {}", e))?;

    let status = command.wait().map_err(|e| format!("Failed to wait for conversion: {}", e))?;
    if status.success() {
        Ok(())
    } else {
        let stderr = String::from_utf8(command.stderr.unwrap_or_default()).unwrap();
        Err(format!("Conversion failed with exit code {}: {}", status, stderr))
    }
}

fn main() {
    // Example usage
    match process_media_conversion("input.jpg", "pdf", 3, 5) {
        Ok(_) => info!("Conversion successful"),
        Err(e) => error!("Conversion failed: {}", e),
    }
}
