use std::env;
use std::time::{Duration, Instant};
use tokio;
use tokio::net::TcpStream;
use tokio::sync::mpsc;

#[derive(Debug)]
enum Error {
    NetworkError(std::io::Error),
    Timeout,
    ServiceUnavailable,
}

async fn send_request(clinic_id: &str) -> Result<(), Error> {
    let mut stream = TcpStream::connect("php_service_host:80").await.map_err(Error::NetworkError)?;
    stream.write_all(format!("UPDATE_CLINIC {}", clinic_id).as_bytes()).await.map_err(Error::NetworkError)?;
    stream.shutdown().await.map_err(Error::NetworkError)?;

    Ok(())
}

async fn worker(clinic_ids: mpsc::Receiver<String>, mut tx: mpsc::Sender<()>) {
    while let Some(clinic_id) = clinic_ids.recv().await {
        match send_request(&clinic_id).await {
            Ok(_) => println!("Request for clinic ID {} sent successfully", clinic_id),
            Err(e) => {
                eprintln!("Failed to send request for clinic ID {}: {:?}", clinic_id, e);
                // Implement retry logic with exponential backoff
            }
        }
    }

    tx.send(()).unwrap();
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <clinic_id>", args[0]);
        return Ok(());
    }

    let clinic_ids = vec![args[1].clone()];
    let (tx, mut rx) = mpsc::channel(32);

    tokio::spawn(worker(clinic_ids.into_iter().collect(), tx.clone()));

    // Implement mechanism to handle and log errors
    // Optimize resource usage and ensure scalability

    while rx.recv().await.is_none() {
        tokio::time::sleep(Duration::from_secs(1)).await;
    }

    Ok(())
}
```

