#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sqlite3.h>

#define MAX_HOSTNAME_LEN 256
#define CACHE_SIZE 1000

typedef struct {
    char hostname[MAX_HOSTNAME_LEN];
    char ip[MAX_HOSTNAME_LEN];
} DNSRecord;

DNSRecord cache[CACHE_SIZE];
int cache_count = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

sqlite3 *db_connection = NULL;

void* db_thread(void *arg) {
    while (1) {
        // Simulate asynchronous database update operations
        pthread_mutex_lock(&cache_lock);
        for (int i = 0; i < cache_count; i++) {
            char query[256];
            snprintf(query, sizeof(query), "UPDATE dns_table SET ip='%s' WHERE hostname='%s'", cache[i].ip, cache[i].hostname);
            sqlite3_exec(db_connection, query, NULL, NULL, NULL);
        }
        pthread_mutex_unlock(&cache_lock);

        // Sleep for a while before the next update
        sleep(10);
    }
    return NULL;
}

int resolve_hostname(const char *hostname, char *ip) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_count; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            strcpy(ip, cache[i].ip);
            pthread_mutex_unlock(&cache_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    // Simulate DNS resolution
    snprintf(ip, MAX_HOSTNAME_LEN, "127.0.0.1");

    // Update cache asynchronously
    pthread_t db_thread_id;
    if (pthread_create(&db_thread_id, NULL, db_thread, NULL) != 0) {
        perror("Failed to create database thread");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize SQLite3
    sqlite3_open("dns_database.db", &db_connection);
    if (db_connection == NULL) {
        fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(db_connection));
        sqlite3_close(db_connection);
        return 1;
    }

    // Example usage
    char ip[MAX_HOSTNAME_LEN];
    resolve_hostname("example.com", ip);
    printf("IP for example.com: %s\n", ip);

    // Cleanup
    sqlite3_close(db_connection);

    return 0;
}
```

