#include <condition_variable>
#include <chrono>
#include <fstream>
#include <openssl/md5.h>

// Transaction structure
struct Transaction {
    uint64_t timestamp;
    double amount;
};

// Custom deserializer
Transaction deserializeTransaction(const std::string& data) {
    // Implement custom deserialization logic here
    return {0, 0.0};
}

// Metrics tracking
class MetricsTracker {
public:
    void recordTransaction(const Transaction& tx) {
        std::lock_guard<std::mutex> lock(mutex_);
        total_transactions_++;
        total_amount_ += tx.amount;
        if (tx.timestamp > max_timestamp_) {
            max_timestamp_ = tx.timestamp;
        }
        weighted_sum_ += tx.amount * (max_timestamp_ - tx.timestamp);
    }

    // Implement getter functions for metrics
private:
    std::mutex mutex_;
    uint64_t total_transactions_ = 0;
    double total_amount_ = 0.0;
    uint64_t max_timestamp_ = 0;
    double weighted_sum_ = 0.0;
};

// Transaction Processor
class TransactionProcessor {
public:
    TransactionProcessor(size_t numThreads) : stop_(false) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers_.emplace_back([this] {
                while (true) {
                    std::unique_lock<std::mutex> lock(mutex_);
                    condition_.wait(lock, [this]{ return stop_ || !tasks_.empty(); });
                    if (stop_ && tasks_.empty()) {
                        break;
                    }
                    Transaction task = std::move(tasks_.front());
                    tasks_.pop();
                    lock.unlock();

                    // Process transaction
                    metrics_.recordTransaction(task);
                }
            });
        }
    }

    ~TransactionProcessor() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stop_ = true;
        }
        condition_.notify_all();
        for (std::thread& worker : workers_) {
            worker.join();
        }
    }

    void addTransaction(const Transaction& tx) {
        std::lock_guard<std::mutex> lock(mutex_);
        tasks_.push(tx);
        condition_.notify_one();
    }

private:
    std::vector<std::thread> workers_;
    std::queue<Transaction> tasks_;
    std::mutex mutex_;
    std::condition_variable condition_;
    bool stop_;
    MetricsTracker metrics_;
};

// MD5 Hashing
std::string calculateMD5(const std::string& input) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)input.c_str(), input.size(), (unsigned char*)&digest);
    char mdString[33];
    for(int i = 0; i < 16; ++i)
        sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);
    return std::string(mdString);
}

// Testing and Validation
void runTests() {
    // Implement test cases here
}
