AsyncSessionLocal = sessionmaker(engine, class_=AsyncSession, expire_on_commit=False)

class TextDocument(BaseModel):
    id: int
    content: str

async def get_db():
    async with AsyncSessionLocal() as db:
        yield db

@app.websocket("/edit")
async def edit_text(websocket: WebSocket, db: AsyncSession = Depends(get_db)):
    await websocket.accept()
    doc_id = await websocket.receive_text()
    doc = await db.execute(select(TextDocument).where(TextDocument.id == doc_id)).scalar_one_or_none()
    if not doc:
        # Handle document creation
        pass

    async with AIOKafkaProducer(bootstrap_servers='localhost:9092') as producer:
        while True:
            message = await websocket.receive_text()
            await db.execute(update(TextDocument).where(TextDocument.id == doc_id).values(content=message))
            await producer.send_and_wait('document_updates', value=message.encode())

