public class DataIngestionPipeline
{
    private readonly IHttpClientFactory _httpClientFactory;
    private readonly ILogger<DataIngestionPipeline> _logger;
    private readonly IDatabaseService _databaseService;

    public DataIngestionPipeline(IHttpClientFactory httpClientFactory, ILogger<DataIngestionPipeline> logger, IDatabaseService databaseService)
    {
        _httpClientFactory = httpClientFactory;
        _logger = logger;
        _databaseService = databaseService;
    }

    public async Task UploadDataAsync(List<byte[]> dataBatches)
    {
        foreach (var batch in dataBatches)
        {
            try
            {
                await ProcessBatchAsync(batch);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing data batch");
            }
        }
    }

    private async Task ProcessBatchAsync(byte[] dataBatch)
    {
        var client = _httpClientFactory.CreateClient();
        using (var content = new ByteArrayContent(dataBatch))
        {
            content.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue("application/octet-stream");
            var response = await client.PostAsync("https://api.example.com/upload", content);

            if (!response.IsSuccessStatusCode)
                throw new Exception($"Failed to upload data: {response.ReasonPhrase}");
        }

        _logger.LogInformation("Data batch uploaded successfully");
    }
}

public interface IDatabaseService
{
    Task SaveDataAsync(byte[] data);
}

public class DatabaseService : IDatabaseService
{
    private readonly string _connectionString;

    public DatabaseService(string connectionString)
    {
        _connectionString = connectionString;
    }

    public async Task SaveDataAsync(byte[] data)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            var command = new SqlCommand("INSERT INTO Data (BinaryData) VALUES (@BinaryData)", connection);
            command.Parameters.Add(new SqlParameter("@BinaryData", data));
            await command.ExecuteNonQueryAsync();
        }
    }
}

public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        services.AddTransient<IHttpClientFactory, HttpClientFactory>();
        services.AddSingleton<ILogger<DataIngestionPipeline>, LoggerFactory().CreateLogger<DataIngestionPipeline>>();
        services.AddSingleton<IDatabaseService, DatabaseService>("Server=myServerAddress;Database=myDataBase;User Id=myUsername;Password=myPassword;");
        services.AddScoped<DataIngestionPipeline>();
    }

    private static ILoggerFactory LoggerFactory()
    {
        // Configure and return the logger factory
        throw new NotImplementedException();
    }
}
