public class HashService : IHashService
{
    private readonly ILogger<HashService> _logger;
    private readonly ConcurrentDictionary<string, int> _rateLimits = new();
    private readonly HttpClient _loggingClient;

    public HashService(ILogger<HashService> logger)
    {
        _logger = logger;
        _loggingClient = new HttpClient(new HttpClientHandler());
    }

    public async Task<string> ComputeHashAsync(string input, string user, string outputFormat = "hex")
    {
        if (string.IsNullOrEmpty(input) || input.Length > 1024 || !IsAlphanumericHyphen(input))
        {
            throw new ArgumentException("Invalid input. Input must be alphanumeric and hyphens only.");
        }

        var ip = GetClientIp(); // Implement this method to get the client's IP address

        if (!await CheckRateLimitAsync(ip, user))
        {
            _logger.LogWarning("Rate limit exceeded for user: {User}", user);
            throw new RateLimitException("Too many requests. Please try again later.");
        }

        var hash = ComputeMd5Hash(input);

        if (outputFormat == "hex")
        {
            return BitConverter.ToString(hash).Replace("-", "").ToLower();
        }
        else
        {
            throw new ArgumentException("Unsupported output format.");
        }
    }

    private byte[] ComputeMd5Hash(string input)
    {
        using var md5 = MD5.Create();
        return md5.ComputeHash(Encoding.UTF8.GetBytes(input));
    }

    private async Task<bool> CheckRateLimitAsync(string ip, string user)
    {
        if (!_rateLimits.TryGetValue(user, out var count))
        {
            _rateLimits[user] = 1;
            return true;
        }

        if (count >= 60) // 1 request per minute
        {
            return false;
        }

        _rateLimits[user]++;
        return true;
    }

    private string GetClientIp()
    {
        // Implement logic to get the client's IP address
        return "127.0.0.1";
    }
}

public interface IHashService
{
    Task<string> ComputeHashAsync(string input, string user, string outputFormat = "hex");
}

public class RateLimitException : Exception
{
    public RateLimitException(string message) : base(message)
    {
    }
}
