using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json.Linq;

namespace OAuth2TokenLibrary
{
    public interface IDecryptionStrategy
    {
        string Decrypt(string ciphertext, byte[] key, byte[] iv);
    }

    public class AesCbcDecryptionStrategy : IDecryptionStrategy
    {
        public string Decrypt(string ciphertext, byte[] key, byte[] iv)
        {
            using (Aes aes = Aes.Create())
            {
                aes.Key = key;
                aes.IV = iv;
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;

                ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
                using (MemoryStream msDecrypt = new MemoryStream(Convert.FromBase64String(ciphertext)))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                        {
                            return srDecrypt.ReadToEnd();
                        }
                    }
                }
            }
        }
    }

    public class TokenValidator
    {
        public bool ValidateToken(string token)
        {
            JObject jObject = JObject.Parse(token);
            if (!jObject.ContainsKey("access_token") || !jObject.ContainsKey("expires_in") ||
                !jObject.ContainsKey("token_type"))
            {
                return false;
            }

            string accessToken = (string)jObject["access_token"];
            int expiresInSeconds = (int)jObject["expires_in"];
            string tokenType = (string)jObject["token_type"];

            if (tokenType != "Bearer" || expiresInSeconds <= 0)
            {
                return false;
            }

            return true;
        }
    }

    public interface ITokenService
    {
        Task<string> GetDecryptedAccessTokenAsync(string ciphertext, byte[] key, byte[] iv);
    }

    public class TokenService : ITokenService
    {
        private readonly IDecryptionStrategy _decryptionStrategy;
        private readonly TokenValidator _tokenValidator;

        public TokenService(IDecryptionStrategy decryptionStrategy, TokenValidator tokenValidator)
        {
            _decryptionStrategy = decryptionStrategy;
            _tokenValidator = tokenValidator;
        }

        public async Task<string> GetDecryptedAccessTokenAsync(string ciphertext, byte[] key, byte[] iv)
        {
            string decryptedToken = _decryptionStrategy.Decrypt(ciphertext, key, iv);
            if (!_tokenValidator.ValidateToken(decryptedToken))
            {
                throw new ArgumentException("Invalid token");
            }

            return decryptedToken;
        }
    }

    public class TokenCache
    {
        private readonly Dictionary<string, string> _cache = new Dictionary<string, string>();
        private readonly object _lock = new object();

        public async Task<string> GetDecryptedAccessTokenAsync(string ciphertext, byte[] key, byte[] iv)
        {
            lock (_lock)
            {
                if (!_cache.ContainsKey(ciphertext))
                {
                    var tokenService = new TokenService(new AesCbcDecryptionStrategy(), new TokenValidator());
                    string decryptedToken = await tokenService.GetDecryptedAccessTokenAsync(ciphertext, key, iv);
                    _cache[ciphertext] = decryptedToken;
                }
            }

            return _cache[ciphertext];
        }
    }

    public class OAuth2TokenLibrary
    {
        private readonly TokenCache _tokenCache;

        public OAuth2TokenLibrary()
        {
            _tokenCache = new TokenCache();
        }

        public async Task<string> GetDecryptedAccessTokenAsync(string ciphertext, byte[] key, byte[] iv)
        {
            return await _tokenCache.GetDecryptedAccessTokenAsync(ciphertext, key, iv);
        }
    }
}
