using Microsoft.Extensions.Logging;

public class BinaryLogService : IHostedService
{
    private readonly ILogger<BinaryLogService> _logger;
    private readonly string _logDirectory;
    private readonly ConcurrentDictionary<string, LogFileProcessor> _fileProcessors = new();
    private readonly SemaphoreSlim _globalLock = new(1);

    public BinaryLogService(string logDirectory, ILogger<BinaryLogService> logger)
    {
        _logDirectory = logDirectory;
        _logger = logger;
    }

    public Task StartAsync(CancellationToken cancellationToken)
    {
        _logger.LogInformation("Starting Binary Log Service");

        var files = Directory.GetFiles(_logDirectory);
        foreach (var file in files)
        {
            _fileProcessors.TryAdd(file, new LogFileProcessor(file, _globalLock, _logger));
            _fileProcessors[file].StartProcessing(cancellationToken);
        }

        return Task.CompletedTask;
    }

    public Task StopAsync(CancellationToken cancellationToken)
    {
        _logger.LogInformation("Stopping Binary Log Service");

        foreach (var processor in _fileProcessors.Values.ToList())
        {
            processor.StopProcessing(cancellationToken);
        }

        _globalLock.Dispose();

        return Task.CompletedTask;
    }
}

public class LogFileProcessor
{
    private readonly string _filePath;
    private readonly SemaphoreSlim _fileLock = new(1);
    private readonly ILogger<LogFileProcessor> _logger;

    public LogFileProcessor(string filePath, SemaphoreSlim globalLock, ILogger<LogFileProcessor> logger)
    {
        _filePath = filePath;
        _globalLock = globalLock;
        _logger = logger;
    }

    public void StartProcessing(CancellationToken cancellationToken)
    {
        Task.Run(async () =>
        {
            while (!cancellationToken.IsCancellationRequested)
            {
                try
                {
                    await ProcessLogFile(cancellationToken);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error processing log file: {FilePath}", _filePath);
                }
                finally
                {
                    await Task.Delay(1000, cancellationToken); // Adjust interval as needed
                }
            }
        });
    }

    public void StopProcessing(CancellationToken cancellationToken)
    {
        // Implement stop logic if necessary
    }

    private async Task ProcessLogFile(CancellationToken cancellationToken)
    {
        try
        {
            using (await _fileLock.LockAsync(cancellationToken))
            using (var stream = new FileStream(_filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite, bufferSize: 4096, useAsync: true))
            using (var reader = new BinaryReader(stream))
            {
                while (!cancellationToken.IsCancellationRequested && reader.BaseStream.Position < reader.BaseStream.Length)
