                    var data = await reader.ReadBytesAsync(1024); // Adjust chunk size as needed
                    var processedData = Deserialize(data);
                    Persist(processedData);
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing log file: {FilePath}", _filePath);
            throw;
