const cache = {};
async function handleFileUpload(file, idempotencyKey) {
  if (cache[idempotencyKey]) return cache[idempotencyKey];

  try {
    await uploadFile(file);
    cache[idempotencyKey] = true;
    return true;
  } catch (error) {
    throw error;
  }
}

