  function uploadFileWithRateLimiter(file) {
    if (activeUploads.size < concurrencyLimit) {
      activeUploads.add(file);
      robustUpload(file).finally(() => activeUploads.delete(file));
    } else {
      throw new Error('Concurrency limit reached');
    }
  }

  return uploadFileWithRateLimiter;
}

