import requests
from queue import Queue
from threading import Thread

# Mock API endpoints and authentication tokens
API_ENDPOINTS = {
    'aws': 'https://api.aws.com/monitoring',
    'azure': 'https://api.azure.com/monitoring'
}

TOKENS = {
    'aws': 'Bearer AwsToken123',
    'azure': 'Bearer AzureToken456'
}

ALERT_THRESHOLD = 90

def fetch_server_status(region, api_endpoint):
    headers = {'Authorization': TOKENS[region]}
    response = requests.get(api_endpoint, headers=headers)
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"Failed to fetch status for {region}")

def update_server_health(data):
    # Logic to update server health in the database
    print("Updating server health:", data)

def trigger_alert(server_name, region):
    # Logic to trigger alert based on server status
    print(f"Alert triggered for {server_name} in {region}")

def worker(q):
    while True:
        region = q.get()
        try:
            data = fetch_server_status(region, API_ENDPOINTS[region])
            update_server_health(data)
            if data['health'] < ALERT_THRESHOLD:
                trigger_alert(data['name'], region)
        except Exception as e:
            print(f"Error processing {region}: {e}")
        finally:
            q.task_done()

def start_monitoring():
    q = Queue()
    threads = []
    for _ in range(10):  # Number of worker threads
        t = Thread(target=worker, args=(q,))
        t.start()
        threads.append(t)

    for region in API_ENDPOINTS.keys():
        q.put(region)

    q.join()

if __name__ == "__main__":
    start_monitoring()
