        }
    }

    async fn acquire(&self) -> Result<(), String> {
        let mut lock = self.lock.lock().await;
        *lock += 1;
        Ok(())
    }

    async fn release(&self) -> Result<(), String> {
        let mut lock = self.lock.lock().await;
        if *lock > 0 {
            *lock -= 1;
        }
        Ok(())
    }
}

#[derive(Debug)]
struct DataStorageManager {
    config: Arc<RwLock<Config>>,
    lock_manager: LockManager,
}

impl DataStorageManager {
    fn new(data_dir: PathBuf) -> Self {
        let config = Config::new(data_dir);
        DataStorageManager {
            config: Arc::new(RwLock::new(config)),
            lock_manager: LockManager::new(),
        }
    }

    async fn initialize(&self) -> Result<(), String> {
        let mut config = self.config.write().await;
        config.get_data_dir().await?;
        Ok(())
    }

    async fn set_data_dir(&self, new_dir: PathBuf) -> Result<(), String> {
        self.lock_manager.acquire().await?;
        let mut config = self.config.write().await;
        if config.data_dir != new_dir {
            fs::remove_dir_all(&config.data_dir).map_err(|e| format!("Failed to remove old data directory: {}", e))?;
            fs::create_dir_all(&new_dir).map_err(|e| format!("Failed to create new data directory: {}", e))?;
            config.data_dir = new_dir;
        }
        self.lock_manager.release().await?;
        Ok(())
    }

    async fn get_data_dir(&self) -> Result<PathBuf, String> {
        let config = self.config.read().await;
        config.get_data_dir().await
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_init_and_get_data_dir() {
        let data_dir = PathBuf::from("/tmp/test_dir");
        let manager = DataStorageManager::new(data_dir.clone());
        manager.initialize().await.unwrap();
        assert_eq!(manager.get_data_dir().await.unwrap(), data_dir);
    }

    #[tokio::test]
    async fn test_set_and_get_data_dir() {
        let old_dir = PathBuf::from("/tmp/test_dir_old");
        let new_dir = PathBuf::from("/tmp/test_dir_new");
        let manager = DataStorageManager::new(old_dir.clone());
        manager.initialize().await.unwrap();
        assert_eq!(manager.get_data_dir().await.unwrap(), old_dir);
        manager.set_data_dir(new_dir.clone()).await.unwrap();
        assert_eq!(manager.get_data_dir().await.unwrap(), new_dir);
    }
}
