    elasticsearch_logger = ElasticsearchLogger(es_client)
    cloudwatch_logger = CloudWatchLogger(cloudwatch_client)

    log_router1 = LogRouter({'console': console_logger})
    log_router2 = LogRouter({'elasticsearch': elasticsearch_logger, 'cloudwatch': cloudwatch_logger})

    file_storage = FileLogStorage('logs.txt')
    es_storage = ElasticsearchLogStorage(es_client)

    log_processor = LogProcessor()

    logging_framework = LoggingFramework([log_router1, log_router2], [file_storage, es_storage], log_processor)

    logging_framework.log("This is a test log message", 'console')
    logging_framework.log("This is another log message", 'elasticsearch')
    logging_framework.log("Yet another log message", 'cloudwatch')
