import json

class JSONParser:
    factories = {}

    @staticmethod
    def register_factory(factory_id, factory_function):
        JSONParser.factories[factory_id] = factory_function

    @staticmethod
    def create_instance(json_data):
        data = json.loads(json_data)
        factory_id = data['type']
        if factory_id in JSONParser.factories:
            return JSONParser.factories[factory_id](data)
        else:
            raise ValueError("Factory not found for ID: {}".format(factory_id))

class ExampleClass(JSONParser):
    def __init__(self, data):
        self.data = data

    @staticmethod
    def from_json(json_data):
        return ExampleClass(data=json.loads(json_data))

