import redis
from tenacity import retry, stop_after_attempt, wait_exponential
import time

class DistributedCache:
    def __init__(self, host='localhost', port=6379, db=0):
        self.redis_client = redis.Redis(host=host, port=port, db=db)

    @retry(stop=stop_after_attempt(5), wait=wait_exponential(multiplier=2))
    def get(self, key):
        return self.redis_client.get(key)

    @retry(stop=stop_after_attempt(5), wait=wait_exponential(multiplier=2))
    def set(self, key, value, ex=None):
        return self.redis_client.set(key, value, ex=ex)

    @retry(stop=stop_after_attempt(5), wait=wait_exponential(multiplier=2))
    def delete(self, key):
        return self.redis_client.delete(key)

# Usage example
cache = DistributedCache()

# Store data in cache with expiration time of 300 seconds
cache.set('product:1', '{"name": "Laptop", "price": 999}', ex=300)

# Retrieve data from cache
product_info = cache.get('product:1')
print(product_info)

# Delete data from cache
cache.delete('product:1')
