#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    // Define fields as needed
} NFAPI_CRC_INDICATION_PDU_T;

// Define the vertex data structure for the graph
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T ue_info;
    int rx_ue_info_tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    int crcflag;
} VertexData;

// Define the edge data structure for the graph
typedef struct {
    int latency;
    double bandwidth;
} EdgeData;

// Define the adjacency list node structure
typedef struct AdjListNode {
    int dest;
    EdgeData *edge_data;
    struct AdjListNode* next;
} AdjListNode;

// Define the adjacency list structure
typedef struct AdjList {
    AdjListNode *head;  // Pointer to head node of list
} AdjList;

// Define the graph structure
typedef struct Graph{
    int V; // Number of vertices
    AdjList* array; // Array of adjacency lists
} Graph;

// Function to create a new adjacency list node
AdjListNode* newAdjListNode(int dest, EdgeData *edge_data) {
    AdjListNode* newNode = (AdjListNode*) malloc(sizeof(AdjListNode));
    newNode->dest = dest;
    newNode->edge_data = edge_data;
    newNode->next = NULL;
    return newNode;
}

// Function to create a graph with V vertices
Graph* createGraph(int V) {
    Graph* graph = (Graph*) malloc(sizeof(Graph));
    graph->V = V;

    // Create an array of adjacency lists. Size of array will be V
    graph->array = (AdjList*) malloc(V * sizeof(AdjList));

    // Initialize each adjacency list as empty by making head as NULL
    int i;
    for (i = 0; i < V; ++i)
        graph->array[i].head = NULL;

    return graph;
}

// Function to add an edge to the graph
void addEdge(Graph* graph, int src, int dest, EdgeData *edge_data) {
    // Add an edge from src to dest. A new node is added to the adjacency list of src.
    AdjListNode* newNode = newAdjListNode(dest, edge_data);
    newNode->next = graph->array[src].head; 
    graph->array[src].head = newNode;

    // Since graph is undirected, add an edge from dest to src also
    newNode = newAdjListNode(src, edge_data);
    newNode->next = graph->array[dest].head;
    graph->array[dest].head = newNode;
}

// Function to free the memory allocated for the graph
void freeGraph(Graph* graph) {
    if (graph == NULL) return;

    // Free each adjacency list
    int i;
    for (i = 0; i < graph->V; ++i) {
        AdjListNode *curr = graph->array[i].head;
        while (curr != NULL) {
            AdjListNode *next = curr->next;
            free(curr);
            curr = next;
        }
    }

    // Free the array of adjacency lists
    free(graph->array);

    // Free the graph structure itself
    free(graph);
}

// Example usage
int main() {
    int V = 5; // Number of vertices

    Graph* graph = createGraph(V);

    EdgeData edge_data1;
    edge_data1.latency = 20;
    edge_data1.bandwidth = 5.0;

    addEdge(graph, 0, 1, &edge_data1);
    addEdge(graph, 0, 4, &edge_data1);
    addEdge(graph, 1, 2, &edge_data1);
    addEdge(graph, 1, 3, &edge_data1);
    addEdge(graph, 1, 4, &edge_data1);
    addEdge(graph, 2, 3, &edge_data1);
    addEdge(graph, 3, 4, &edge_data1);

    // Free the graph when done
    freeGraph(graph);

    return 0;
}
