// Import necessary libraries
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.TimeUnit;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Retryable;
import org.springframework.web.client.RestClientException;
import org.springframework.web.client.RestTemplate;

// Define the service class
public class ResourceManagementService {

    @Autowired
    private MongoTemplate mongoTemplate;

    @Autowired
    private RestTemplate restTemplate;

    // Method to get MD5 hash with retry mechanism and rate limiting
    @Retryable(
        value = {NetworkErrorException.class, DatabaseConnectionException.class}, 
        maxAttempts = 3, 
        backoff = @Backoff(delay = 1000, multiplier = 2)
    )
    public String getMD5Hash(String id) throws NetworkErrorException, DatabaseConnectionException {
        // Retrieve data from the database
        Resource resource = mongoTemplate.findById(id, Resource.class);
        if (resource == null) throw new DatabaseConnectionException("Resource not found");

        // Calculate MD5 hash
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(resource.getData().getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if(hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new NetworkErrorException("Failed to calculate MD5 hash");
        }
    }

    // Method to update resource with conflict resolution and rate limiting
    public ResponseEntity<String> updateResource(String id, String requestBody) {
        try {
            Resource existingResource = mongoTemplate.findById(id, Resource.class);
            if (existingResource == null) return ResponseEntity.status(HttpStatus.NOT_FOUND).body("Resource not found");

            // Call external API to update resource
            ResponseEntity<String> apiResponse = restTemplate.postForEntity("http://external-api/update", requestBody, String.class);

            // Update database with new data
            existingResource.setData(requestBody);
            mongoTemplate.save(existingResource);

            return ResponseEntity.ok("Resource updated successfully");
        } catch (RestClientException e) {
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body("Failed to update resource in external API");
        }
    }

    // Method to delete resource with soft-deletion and rate limiting
    public ResponseEntity<String> deleteResource(String id) {
        try {
            Resource resource = mongoTemplate.findById(id, Resource.class);
            if (resource == null) return ResponseEntity.status(HttpStatus.NOT_FOUND).body("Resource not found");

            // Mark resource as deleted in database
            resource.setDeleted(true);
            mongoTemplate.save(resource);

            // Call external API to delete resource
            restTemplate.postForEntity("http://external-api/delete", id, String.class);

            return ResponseEntity.ok("Resource marked for deletion");
        } catch (RestClientException e) {
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body("Failed to mark resource for deletion in external API");
        }
    }

    // Custom exceptions
    public static class NetworkErrorException extends RuntimeException { ... }
    public static class DatabaseConnectionException extends RuntimeException { ... }
}

// Define the Resource class
class Resource {
    private String id;
    private boolean deleted;
    private String data;

    // Getters and setters
}
