int init_cipher(void *ctx, CipherMode mode, const unsigned char *key, const unsigned char *iv) {
    switch (mode) {
        case CIPHER_DES:
            DES_set_key_checked((DES_cblock *)key, (DES_key_schedule *)ctx);
            break;
        case CIPHER_3DES_EDE:
            DES_ede3_set_key_checked((DES_cblock *)key, (DES_ede_key *)ctx);
            break;
        case CIPHER_3DES_EDE3:
            DES_ede3_set_key_triple_checked((DES_cblock *)key, (DES_ede_key *)ctx);
            break;
        case CIPHER_CFB:
            // Initialize CFB mode
            break;
        default:
            return -1; // Invalid cipher mode
    }
    return 0;
}

// Function to encrypt/decrypt data using a given cipher context
int process_cipher(void *ctx, CipherMode mode, unsigned char *data, size_t length, int encrypt) {
    switch (mode) {
        case CIPHER_DES:
            if (encrypt)
                DES_cbc_encrypt(data, data, length, ctx, NULL, 1);
            else
                DES_cbc_encrypt(data, data, length, ctx, NULL, 0);
            break;
        case CIPHER_3DES_EDE:
            if (encrypt)
                DES_ede3_cbc_encrypt(data, data, length, ctx, NULL, 1);
            else
                DES_ede3_cbc_encrypt(data, data, length, ctx, NULL, 0);
            break;
        case CIPHER_3DES_EDE3:
            if (encrypt)
                DES_ede3_cbc_encrypt(data, data, length, ctx, NULL, 1);
            else
                DES_ede3_cbc_encrypt(data, data, length, ctx, NULL, 0);
            break;
        case CIPHER_CFB:
            // Process CFB mode
            break;
        default:
            return -1; // Invalid cipher mode
    }
    return 0;
}

