#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

// Function to derive a key using PBKDF2 with configurable iteration counts and hash algorithms
void pbkdf2_key_derivation(const char *password, const char *salt, int iterations, unsigned int key_len, unsigned char *out) {
    EVP_PKEY_CTX *ctx;
    ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_PBKDF2, NULL);
    if (!ctx) exit(EXIT_FAILURE);

    // Set the hash algorithm to SHA-256
    if (EVP_PKEY_CTX_set_hkdf_md(ctx, EVP_sha256()) != 1) exit(EXIT_FAILURE);

    // Set the key derivation function to PBKDF2
    if (EVP_PKEY_CTX_set_kdf(ctx, EVP_KDF_pbkdf2()) != 1) exit(EXIT_FAILURE);

    // Set the password and salt
    if (EVP_PKEY_CTX_set1_passphrase(ctx, (unsigned char *)password, strlen(password)) != 1) exit(EXIT_FAILURE);
    if (EVP_PKEY_CTX_add1_id_keymgmt(ctx, EVP_PKEY_HKDF, NULL, (const unsigned char *)salt, strlen(salt), NULL) != 1) exit(EXIT_FAILURE);

    // Set the iteration count
    if (EVP_PKEY_CTX_set_pbkdf2_iter(ctx, iterations) != 1) exit(EXIT_FAILURE);

    // Generate the key
    if (EVP_PKEY_derive(ctx, out, &key_len) != 1) exit(EXIT_FAILURE);

    EVP_PKEY_CTX_free(ctx);
}

// Function to generate a cryptographic secure IV
void generate_iv(unsigned char *iv, int iv_length) {
    if (!RAND_bytes(iv, iv_length)) exit(EXIT_FAILURE);
}

int main() {
    const char *password = "my_password";
    const char *salt = "my_salt";
    int iterations = 10000;
    unsigned int key_len = 32; // 256-bit key
    unsigned char key[key_len];
    unsigned char iv[16]; // AES block size

    pbkdf2_key_derivation(password, salt, iterations, key_len, key);
    generate_iv(iv, sizeof(iv));

    printf("Derived Key: ");
    for (int i = 0; i < key_len; i++) {
        printf("%02x", key[i]);
    }
    printf("\nIV: ");
    for (int i = 0; i < sizeof(iv); i++) {
        printf("%02x", iv[i]);
    }
    printf("\n");

    return 0;
}
```

