#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_THREADS 10
#define MAX_REQUESTS 100

typedef void (*callback_t)(const char*);

typedef struct {
    const char* input;
    int size_limit;
    callback_t on_restriction_exceeded;
} request_t;

typedef struct {
    request_t requests[MAX_REQUESTS];
    int front, rear, count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} queue_t;

queue_t request_queue;
pthread_t worker_threads[MAX_THREADS];

void* process_request(void* arg) {
    while (1) {
        pthread_mutex_lock(&request_queue.mutex);
        while (request_queue.count == 0) {
            pthread_cond_wait(&request_queue.cond, &request_queue.mutex);
        }
        request_t req = request_queue.requests[request_queue.front];
        request_queue.front = (request_queue.front + 1) % MAX_REQUESTS;
        request_queue.count--;
        pthread_mutex_unlock(&request_queue.mutex);

        if (strlen(req.input) <= req.size_limit) {
            char* new_str = malloc(strlen(req.input) + 2);
            strcpy(new_str, req.input);
            new_str[strlen(req.input)] = '/';
            new_str[strlen(req.input) + 1] = '\0';
            // Return or use new_str as needed
        } else {
            req.on_restriction_exceeded(req.input);
        }
    }
}

void init_request_queue() {
    memset(&request_queue, 0, sizeof(request_queue));
    pthread_mutex_init(&request_queue.mutex, NULL);
    pthread_cond_init(&request_queue.cond, NULL);
}

void enqueue_request(const char* input, int size_limit, callback_t on_restriction_exceeded) {
    pthread_mutex_lock(&request_queue.mutex);
    while (request_queue.count == MAX_REQUESTS) {
        pthread_cond_wait(&request_queue.cond, &request_queue.mutex);
    }
    request_t req = {input, size_limit, on_restriction_exceeded};
    request_queue.requests[request_queue.rear] = req;
    request_queue.rear = (request_queue.rear + 1) % MAX_REQUESTS;
    request_queue.count++;
    pthread_cond_signal(&request_queue.cond);
    pthread_mutex_unlock(&request_queue.mutex);
}

void start_worker_threads() {
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&worker_threads[i], NULL, process_request, NULL);
    }
}

void stop_worker_threads() {
    // Signal all worker threads to exit
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_cancel(worker_threads[i]);
    }
    // Wait for all worker threads to finish
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(worker_threads[i], NULL);
    }
}

void on_restriction_exceeded(const char* input) {
    printf("Restriction exceeded: %s\n", input);
    // Add cleanup code here if necessary
}

int main() {
    init_request_queue();
    start_worker_threads();

    enqueue_request("hello", 10, on_restriction_exceeded);
    enqueue_request("world", 5, on_restriction_exceeded);

    stop_worker_threads();
    pthread_mutex_destroy(&request_queue.mutex);
    pthread_cond_destroy(&request_queue.cond);
    return 0;
}
