using System;
using System.Collections.Generic;
using System.Linq;
using Microsoft.Extensions.Configuration;

public class OAuthTokenValidator
{
    private readonly IConfiguration _config;
    private readonly ILogger _logger;
    private readonly IMessageBroker _messageBroker;
    private readonly ICachingService _cachingService;

    public OAuthTokenValidator(IConfiguration config, ILogger logger, IMessageBroker messageBroker, ICachingService cachingService)
    {
        _config = config;
        _logger = logger;
        _messageBroker = messageBroker;
        _cachingService = cachingService;
    }

    public bool ValidateAccessToken(string accessToken, out string errorMessage)
    {
        if (string.IsNullOrEmpty(accessToken))
        {
            errorMessage = "Access token is missing.";
            return false;
        }

        // Fetch token details from cache
        var tokenDetails = _cachingService.GetTokenDetails(accessToken);
        if (tokenDetails == null || DateTime.UtcNow > tokenDetails.ExpiryTime)
        {
            errorMessage = "Access token has expired or is invalid.";
            _logger.LogWarning("Invalid access token: {AccessToken}", accessToken);
            return false;
        }

        // Validate token properties
        if (string.IsNullOrEmpty(tokenDetails.TokenType) || tokenDetails.TokenType != "Bearer")
        {
            errorMessage = "Token type must be 'Bearer'.";
            return false;
        }

        if (tokenDetails.ExpiryTime <= DateTime.UtcNow)
        {
            errorMessage = "Access token has expired.";
            _logger.LogWarning("Expired access token: {AccessToken}", accessToken);
            return false;
        }

        // Update cache if necessary
        _cachingService.RefreshTokenCache(accessToken);

        errorMessage = string.Empty;
        return true;
    }
}

public interface IConfiguration
{
    string GetSection(string key);
}

public interface ILogger
{
    void LogWarning(string message, params object[] args);
}

public interface IMessageBroker
{
    void PublishMessage(string message);
}

public interface ICachingService
{
    TokenDetails GetTokenDetails(string accessToken);
    void RefreshTokenCache(string accessToken);
}

public class TokenDetails
{
    public string TokenType { get; set; }
    public DateTime ExpiryTime { get; set; }
}
