    using ProbabilityMap = std::unordered_map<Attack, double>;
    using TimePoint = std::chrono::system_clock::time_point;

    CombatStrategy(double defaultCooldown, const ProbabilityMap& defaultProbabilities)
        : cooldown(defaultCooldown), probabilities(defaultProbabilities), lastActionTime(TimePoint::min()) {}

    void setCooldown(double newCooldown) {
        std::lock_guard<std::mutex> lock(mutex);
        cooldown = newCooldown;
    }

    Attack getNextAttack() {
        std::unique_lock<std::mutex> lock(mutex);
        while (std::chrono::system_clock::now() < lastActionTime + std::chrono::duration<double>(cooldown)) {
            cv.wait(lock);
        }
        auto attack = selectRandomAttack(probabilities);
        lastActionTime = std::chrono::system_clock::now();
        logCombatAction(attack);
        return attack;
    }

    void resetCooldownManually() {
        std::lock_guard<std::mutex> lock(mutex);
        lastActionTime = TimePoint::min();
    }

private:
    double cooldown;
    ProbabilityMap probabilities;
    TimePoint lastActionTime;
    std::mutex mutex;
    std::condition_variable cv;

    Attack selectRandomAttack(const ProbabilityMap& probs) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::discrete_distribution<> dist(probs.begin()->second, probs.rbegin()->second);
        int index = dist(gen);
        return static_cast<Attack>(index);
    }

    void logCombatAction(Attack attack) {
        auto now = std::chrono::system_clock::now();
        auto tp = std::chrono::system_clock::to_time_t(now);
        std::ostringstream oss;
        oss << std::put_time(std::localtime(&tp), "%Y-%m-%d %H:%M:%S")
            << " Attack: " << static_cast<int>(attack) << std::endl;
        std::lock_guard<std::mutex> lock(logMutex);
        logFile << oss.str();
    }

private:
    mutable std::mutex logMutex;
    std::ofstream logFile("combat_log.txt.gz", std::ios::app | std::ios_base::binary);
};

int main() {
    CombatStrategy strategy(5.0, {{CombatStrategy::Slash, 0.4}, {CombatStrategy::Pierce, 0.3}, {CombatStrategy::Block, 0.3}});
    for (int i = 0; i < 10; ++i) {
        auto attack = strategy.getNextAttack();
        std::cout << "Selected Attack: " << static_cast<int>(attack) << std::endl;
    }
    return 0;
}
