from abc import ABC, abstractmethod
import logging
from opentelemetry import trace
from kafka import KafkaProducer

class Logger(ABC):
    @abstractmethod
    def log(self, message: str):
        pass

class StructuredLogger(Logger):
    def log(self, message: dict):
        # Log structured data as JSON
        pass

class UnstructuredLogger(Logger):
    def log(self, message: str):
        # Log unstructured text messages
        pass

class DistributedTracer:
    tracer = trace.get_tracer(__name__)

    @staticmethod
    def inject_span_id(message: dict) -> dict:
        with DistributedTracer.tracer.start_as_current_span("log_processing"):
            span = trace.get_current_span()
            message['trace_id'] = span.context.trace_id
            return message

class LogPublisher(ABC):
    @abstractmethod
    def publish(self, message: str):
        pass

class KafkaLogPublisher(LogPublisher):
    def __init__(self, bootstrap_servers: list, topic: str):
        self.producer = KafkaProducer(bootstrap_servers=bootstrap_servers)

    def publish(self, message: bytes):
        self.producer.send(topic="logs", value=message)

class LogFramework:
    def __init__(self, logger: Logger, publisher: LogPublisher, tracer: DistributedTracer = None):
        self.logger = logger
        self.publisher = publisher
        self.tracer = tracer

    def log(self, message):
        if isinstance(message, dict):
            message = DistributedTracer.inject_span_id(message)
        structured_message = self.logger.log(message)
        self.publisher.publish(structured_message.encode('utf-8'))

# Usage example
struct_logger = StructuredLogger()
unstruct_logger = UnstructuredLogger()
kafka_publisher = KafkaLogPublisher(bootstrap_servers=['localhost:9092'], topic='logs')
framework = LogFramework(logger=unstruct_logger, publisher=kafka_publisher, tracer=DistributedTracer())

framework.log("This is an unstructured log message")
framework.log({"user_id": 123, "event": "login"})
