#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <unistd.h>

#define MAX_NODES 10
#define MAX_SERVICES 4

typedef struct {
    int value;
} Record;

typedef struct {
    pthread_mutex_t lock;
    Record *data;
    size_t size;
    size_t capacity;
} ThreadSafeVector;

typedef struct {
    char name[256];
    int reliability;
} ServiceInfo;

ThreadSafeVector *create_vector(size_t initial_capacity);
void destroy_vector(ThreadSafeVector *vector);
void vector_push(ThreadSafeVector *vector, Record item);
Record vector_pop(ThreadSafeVector *vector);

ServiceInfo *service_info[MAX_SERVICES] = {
    {"ServiceA", 90},
    {"ServiceB", 85},
    {"ServiceC", 75},
    {"ServiceD", 65}
};

void process_pipeline() {
    ThreadSafeVector *data_vector = create_vector(1024);
    // Initialize data processing pipeline
    for (int i = 0; i < MAX_NODES; i++) {
        pthread_t thread;
        pthread_create(&thread, NULL, node_thread, data_vector);
        pthread_detach(thread);
    }
    destroy_vector(data_vector);
}

void *node_thread(void *arg) {
    ThreadSafeVector *vector = (ThreadSafeVector *)arg;
    Record item;
    while (1) {
        vector_lock(vector);
        if (vector_size(vector) > 0) {
            item = vector_pop(vector);
            vector_unlock(vector);
            // Process item using external services
            process_item(item, service_info);
        } else {
            vector_unlock(vector);
            sleep(1); // Wait for data
        }
    }
    return NULL;
}

void process_item(Record item, ServiceInfo *services[MAX_SERVICES]) {
    int chosen_service = select_service(services);
    switch (chosen_service) {
        case 0: call_service_a(item); break;
        case 1: call_service_b(item); break;
        case 2: call_service_c(item); break;
        case 3: call_service_d(item); break;
    }
}

int select_service(ServiceInfo *services[MAX_SERVICES]) {
    int selected = -1;
    int max_reliability = -1;
    for (int i = 0; i < MAX_SERVICES; i++) {
        if (services[i]->reliability > max_reliability) {
            max_reliability = services[i]->reliability;
            selected = i;
        }
    }
    return selected;
}

void call_service_a(Record item) { /* Implementation */ }
void call_service_b(Record item) { /* Implementation */ }
void call_service_c(Record item) { /* Implementation */ }
void call_service_d(Record item) { /* Implementation */ }

// Thread-safe vector functions
ThreadSafeVector *create_vector(size_t initial_capacity) {
    ThreadSafeVector *vector = (ThreadSafeVector *)malloc(sizeof(ThreadSafeVector));
    vector->data = (Record *)calloc(initial_capacity, sizeof(Record));
    vector->size = 0;
    vector->capacity = initial_capacity;
    pthread_mutex_init(&vector->lock, NULL);
    return vector;
}

void destroy_vector(ThreadSafeVector *vector) {
    free(vector->data);
    pthread_mutex_destroy(&vector->lock);
    free(vector);
}

void vector_push(ThreadSafeVector *vector, Record item) {
    pthread_mutex_lock(&vector->lock);
    if (vector->size == vector->capacity) {
        size_t new_capacity = vector->capacity * 2;
        vector->data = realloc(vector->data, new_capacity * sizeof(Record));
        vector->capacity = new_capacity;
    }
    vector->data[vector->size++] = item;
    pthread_mutex_unlock(&vector->lock);
}

Record vector_pop(ThreadSafeVector *vector) {
    Record item;
    pthread_mutex_lock(&vector->lock);
    if (vector->size > 0) {
        item = vector->data[--vector->size];
    } else {
        item.value = -1; // Error value
    }
    pthread_mutex_unlock(&vector->lock);
    return item;
}

void vector_lock(ThreadSafeVector *vector) { pthread_mutex_lock(&vector->lock); }
void vector_unlock(ThreadSafeVector *vector) { pthread_mutex_unlock(&vector->lock); }
size_t vector_size(ThreadSafeVector *vector) { return vector->size; }

int main() {
    process_pipeline();
    return 0;
}
