#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_LENGTH 2048
#define RETRY_COUNT 5

typedef struct {
    // Define the LoggingServiceClient structure here
} LoggingServiceClient;

void appendTimestamp(char *buffer, int length, int logLevel) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[30];

    if (logLevel >= 5) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);
    } else {
        strftime(timestamp, sizeof(timestamp), "%H:%M:%S", tm_info);
    }

    strncat(buffer, timestamp, length - strlen(buffer));
}

int processLogMessage(const char *message, int maxLength, int toUpperCase, LoggingServiceClient *client, int logLevel) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    char buffer[MAX_LOG_LENGTH];

    pthread_mutex_lock(&lock);

    strncpy(buffer, message, maxLength - 1);
    buffer[maxLength - 1] = '\0';

    if (strlen(buffer) >= maxLength) {
        buffer[maxLength - 9] = '\0'; // Ensure space for timestamp
        appendTimestamp(buffer, maxLength, logLevel);
    }

    if (toUpperCase && logLevel > 3) {
        strupr(buffer); // Convert to uppercase
    }

    int retries = 0;
    while (retries < RETRY_COUNT) {
        if (LoggingServiceClient_SendMessage(client, buffer)) {
            break; // Success
        }

        retries++;
        if (logLevel >= 4) {
            printf("LogService unavailable, retrying (%d/%d)\n", retries, RETRY_COUNT);
        }

        struct timespec delay = {1 << retries, 0};
        nanosleep(&delay, NULL);
    }

    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to log message after %d retries\n", RETRY_COUNT);
    }

    pthread_mutex_unlock(&lock);
    return 0;
}
