// Include necessary headers
#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <memory>
#include <unistd.h>
#include <signal.h>
#include <sys/wait.h>

// Define a class for command execution and monitoring
class CommandExecutor {
public:
    // Constructor
    CommandExecutor(size_t tenantId) : m_tenantId(tenantId), m_exit(false) {}

    // Method to execute a shell command
    void ExecuteCommand(const std::string& command) {
        // Create a child process to run the command
        pid_t pid = fork();
        if (pid == -1) {
            std::cerr << "Failed to create child process" << std::endl;
            return;
        } else if (pid == 0) {
            // Child process
            execl("/bin/sh", "sh", "-c", command.c_str(), nullptr);
            std::cerr << "Failed to execute command: " << command << std::endl;
            _exit(1);
        } else {
            // Parent process
            m_processMap[pid] = {command, false};
            int status;
            waitpid(pid, &status, 0);
            if (WIFEXITED(status)) {
                std::cout << "Command executed successfully" << std::endl;
            } else {
                std::cerr << "Command failed with status: " << WEXITSTATUS(status) << std::endl;
            }
        }
    }

    // Method to handle command completion
    void HandleCompletion(pid_t pid, int status) {
        if (m_processMap.find(pid) != m_processMap.end()) {
            m_processMap[pid].second = true;
            m_condition.notify_one();
        }
    }

    // Method to wait for all commands to complete
    void WaitForAllCommands() {
        std::unique_lock<std::mutex> lock(m_mutex);
        while (true) {
            if (m_exit && m_processMap.empty()) break;
            m_condition.wait(lock, [this] { return m_exit || !m_processMap.empty(); });
        }
    }

    // Destructor
    ~CommandExecutor() {
        m_exit = true;
        WaitForAllCommands();
    }

private:
    size_t m_tenantId;
    std::map<pid_t, std::pair<std::string, bool>> m_processMap;
    std::mutex m_mutex;
    std::condition_variable m_condition;
    bool m_exit;
};

// JavaScript function to execute shell commands using a child process
void ExecuteShellCommand(const std::string& command) {
    // Create an instance of CommandExecutor for the current tenant
    size_t tenantId = 1; // Replace with actual tenant ID retrieval logic
    CommandExecutor executor(tenantId);

    // Execute the command
    executor.ExecuteCommand(command);
}

// Example usage
int main() {
    // Example command to execute
    std::string command = "ls -l";

    // Execute the shell command
    ExecuteShellCommand(command);

    return 0;
}
