const { exec } = require('child_process');
const axios = require('axios');
const express = require('express');
const bodyParser = require('body-parser');
const winston = require('winston');

const app = express();
app.use(bodyParser.json());

// Configure Winston for logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// Middleware for logging requests
app.use((req, res, next) => {
  logger.info(`Request ${req.method} ${req.url}`);
  next();
});

// Route to execute a command
app.post('/execute', async (req, res) => {
  const { command } = req.body;

  try {
    return new Promise((resolve, reject) => {
      exec(command, (error, stdout, stderr) => {
        if (error) {
          logger.error(`Error executing command: ${command}, Error: ${error.message}`);
          reject(error);
        }
        if (stderr) {
          logger.warn(`Stderr: ${stderr}`);
          res.status(200).send({ message: 'Command executed with warnings', stderr });
        } else {
          logger.info(`Command executed successfully: ${command}, Output: ${stdout}`);
          res.status(200).send({ message: 'Command executed successfully', stdout });
        }
      });
    });
  } catch (error) {
    return res.status(500).send({ error: 'Internal Server Error' });
  }
});

// Route to integrate with external API
app.post('/api-integration', async (req, res) => {
  const { endpoint, data } = req.body;

  try {
    const response = await axios.post(endpoint, data);
    logger.info(`API Integration successful: ${endpoint}`);
    return res.status(200).send(response.data);
  } catch (error) {
    logger.error(`API Integration failed: ${endpoint}, Error: ${error.message}`);
    return res.status(500).send({ error: 'Failed to integrate with external API' });
  }
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});
```"]

