#include <cstddef>

class CachingSystem {
public:
    void fetchDataAsync(const std::string& url) {
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = cache_.find(url);
        if (it == cache_.end()) {
            auto future = std::async(std::launch::async, [this, url]() {
                // Simulate fetching data from an API
                return fetchDataFromApi(url);
            });
            futures_[url] = std::move(future);
        } else {
            it->second.set_value_if_not_present(fetchDataFromApi(url));
        }
    }

    void updateCache(const std::string& url, const std::string& data) {
        std::unique_lock<std::mutex> lock(mutex_);
        cache_[url] = data;
        futures_.erase(url);
        cond_.notify_all();
    }

private:
    std::unordered_map<std::string, std::future<std::string>> futures_;
    std::unordered_map<std::string, std::string> cache_;
    std::mutex mutex_;
    std::condition_variable cond_;

    std::string fetchDataFromApi(const std::string& url) {
        // Simulate fetching data from an API
        return "Data for " + url;
    }
};

int main() {
    CachingSystem cachingSystem;

    // Fetch data asynchronously
    cachingSystem.fetchDataAsync("https://api.example.com/data1");
    cachingSystem.fetchDataAsync("https://api.example.com/data2");

    std::this_thread::sleep_for(std::chrono::seconds(2));

    // Update cache with new data
    cachingSystem.updateCache("https://api.example.com/data1", "Updated data for data1");

    return 0;
}
