#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef void (*Callback)(const char*);

char* process_string(const char* input, int size_limit, Callback on_restriction_exceeded) {
    int input_length = strlen(input);
    if (input_length <= size_limit) {
        char* new_input = malloc((input_length + 2) * sizeof(char));
        strcpy(new_input, input);
        new_input[input_length] = '/';
        new_input[input_length + 1] = '\0';
        return new_input;
    } else {
        on_restriction_exceeded(input);
        return NULL;
    }
}

void restriction_exceeded_callback(const char* input) {
    printf("Restriction exceeded for input: %s\n", input);
    free((char*)input);  // Assuming input is dynamically allocated
}

int main() {
    const char* test_input = "example";
    int limit = 10;
    char* result = process_string(test_input, limit, restriction_exceeded_callback);
    if (result) {
        printf("Processed string: %s\n", result);
        free(result);
    }
    return 0;
}
