    return {"message": "Environment created successfully"}

@app.put("/environments/{env_name}")
async def update_environment(env_name: str, env: ApplicationEnvironment):
    redis_client.set(f"environment:{env_name}", env.json())
    return {"message": "Environment updated successfully"}

@app.delete("/environments/{env_name}")
async def delete_environment(env_name: str):
    redis_client.delete(f"environment:{env_name}")
    return {"message": "Environment deleted successfully"}
