from flask import Flask, request, jsonify
import requests
from functools import wraps
import time

app = Flask(__name__)

# Rate limiting decorator
def rate_limit(limit=50, period=60):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = f"{request.remote_addr}_{func.__name__}"
            if request.environ.get("RATE_LIMIT") is None:
                request.environ["RATE_LIMIT"] = []
            request.environ["RATE_LIMIT"].append(time.time())
            request.environ["RATE_LIMIT"] = [t for t in request.environ["RATE_LIMIT"] if time.time() - t < period]
            if len(request.environ["RATE_LIMIT"]) > limit:
                return jsonify({"error": "Rate limit exceeded"}), 429
            return func(*args, **kwargs)
        return wrapper
    return decorator

# Circuit breaker pattern for third-party APIs
class CircuitBreaker:
    def __init__(self, max_failures=3, reset_timeout=60):
        self.max_failures = max_failures
        self.reset_timeout = reset_timeout
        self.failures = 0
        self.last_failure_time = None

    def __call__(self, func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if self.failures >= self.max_failures and time.time() - self.last_failure_time < self.reset_timeout:
                return jsonify({"error": "Circuit breaker open"}), 503
            try:
                result = func(*args, **kwargs)
                self.failures = 0
                return result
            except Exception as e:
                self.failures += 1
                self.last_failure_time = time.time()
                raise
        return wrapper

# Unified API client for third-party logistics providers
@CircuitBreaker()
@rate_limit(limit=5, period=60)
def get_inventory_data(provider):
    response = requests.get(f"https://api.{provider}.com/inventory")
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception("Failed to fetch inventory data")

# Route to handle order fulfillment
@app.route("/fulfillment", methods=["POST"])
@rate_limit(limit=10, period=60)
def fulfill_order():
    data = request.get_json()
    provider = data["provider"]
    inventory_data = get_inventory_data(provider)
    # Process the order using the retrieved inventory data
    return jsonify({"status": "Order fulfilled successfully"})

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
