        try {
            // Check if the key is in cache
            byte[] cachedKey = cache.get(seedId);
            if (cachedKey != null) {
                return cachedKey;
            }

            // Fetch seed value from external data source
            byte[] seedValue = dataFetcher.fetchSeed(seedId);
            if (seedValue == null) {
                throw new IllegalStateException("Failed to fetch seed value for " + seedId);
            }

            // Generate key using KMS
            KeyPair keyPair = kms.generateKeyFromSeed(seedValue);
            cache.put(seedId, keyPair.getPrivate().getEncoded());

            return keyPair.getPublic().getEncoded();
