#include <pthread.h>
#include <semaphore.h>

typedef struct {
    sem_t semaphore;
    int value;
} Semaphore;

Semaphore* create_semaphore(int initial_value) {
    Semaphore* sem = (Semaphore*)malloc(sizeof(Semaphore));
    sem->value = initial_value;
    sem_init(&sem->semaphore, 0, initial_value);
    return sem;
}

void semaphore_wait(Semaphore* sem) {
    sem_wait(&sem->semaphore);
    sem->value--;
}

void semaphore_signal(Semaphore* sem) {
    sem->value++;
    sem_post(&sem->semaphore);
}

void destroy_semaphore(Semaphore* sem) {
    sem_destroy(&sem->semaphore);
    free(sem);
}
