        if (ip == "192.168.1.1") return "vm-uuid-1";
        if (ip == "192.168.1.2") return "vm-uuid-2";
        return "unknown";
    }
};

class ServiceManager {
private:
    std::mutex mutex_;
    std::condition_variable cv_;
    bool stop_ = false;
    std::queue<std::function<void()>> tasks_;
    std::vector<std::thread> workers_;

public:
    ServiceManager(size_t num_workers) : workers_(num_workers) {
        for (auto& w : workers_) {
            w = std::thread(&ServiceManager::worker, this);
        }
    }

    ~ServiceManager() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stop_ = true;
        }
        cv_.notify_all();
        for (auto& w : workers_) {
            w.join();
        }
    }

    void add_task(std::function<void()> task) {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            tasks_.push(task);
        }
        cv_.notify_one();
    }

private:
    void worker() {
        while (true) {
            std::function<void()> task;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                cv_.wait(lock, [this] { return stop_ || !tasks_.empty(); });
                if (stop_ && tasks_.empty()) {
                    return;
                }
                task = std::move(tasks_.front());
                tasks_.pop();
            }
            task();
        }
    }
};

