                    services.AddSingleton<IRestApiConnector>(provider => new RestApiConnector());
                    services.AddSingleton<IMessageBrokerConnector>(provider => new MessageBrokerConnector());
                    services.AddSingleton<ILegacyDatabaseConnector>(provider => new LegacyDatabaseConnector());

                    // Add data transformation and storage services
                    services.AddScoped<IDataTransformer, DataTransformer>();
                    services.AddScoped<IStorageService, StorageService>();

                    // Configure event-driven architecture
                    services.AddSingleton<IEventBusListener>(provider =>
                        new EventBusListener(provider.GetService<IEventBus>(), provider.GetService<ICdcMechanism>()));
                });
