            {
                return creator();
            }
            throw new ArgumentException("Invalid connector type");
        }
    }

    public interface IEventBus { void Publish(Event @event); }
    public class EventBus : IEventBus
    {
        private readonly List<Event> _events = new List<Event>();
        private readonly Dictionary<string, Action<Event>> _subscribers;

        public EventBus()
        {
            _subscribers = new Dictionary<string, Action<Event>>();
        }

        public void Publish(Event @event)
        {
            foreach (var subscriber in _subscribers.Values)
            {
                subscriber(@event);
            }
            _events.Add(@event);
        }

        public void Subscribe(string eventType, Action<Event> handler)
        {
            if (!_subscribers.ContainsKey(eventType))
            {
                _subscribers[eventType] = null;
            }
            _subscribers[eventType] += handler;
        }

        public IEnumerable<Event> GetEvents() => _events;
    }

