from flask import Flask, request, jsonify, abort
from flask_cors import CORS
import uuid

app = Flask(__name__)
CORS(app)

class DocumentVersion:
    def __init__(self, content):
        self.content = content
        self.version_id = str(uuid.uuid4())

document_versions = {}

@app.route('/documents', methods=['POST'])
def create_document():
    data = request.json
    if not data.get('content'):
        abort(400, description="Content is required")
    document_versions[data['content']] = DocumentVersion(data['content'])
    return jsonify({'version_id': document_versions[data['content']].version_id}), 201

@app.route('/documents/<document_content>', methods=['GET', 'PUT', 'DELETE'])
def manage_document(document_content):
    if document_content not in document_versions:
        abort(404, description="Document not found")

    version = document_versions[document_content]
    if request.method == 'GET':
        return jsonify({'content': version.content, 'version_id': version.version_id}), 200
    elif request.method == 'PUT':
        new_data = request.json
        if not new_data.get('content'):
            abort(400, description="Content is required")
        new_version = DocumentVersion(new_data['content'])
        document_versions[new_data['content']] = new_version
        return jsonify({'version_id': new_version.version_id}), 201
    elif request.method == 'DELETE':
        del document_versions[document_content]
        return '', 204

if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0')
```

