using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Xml.Linq;
using System.Xml.Schema;

public class ConfigManager
{
    private ConcurrentDictionary<string, string> cache = new ConcurrentDictionary<string, string>();
    private XDocument xmlDoc;
    private readonly string configFilePath;
    private readonly string externalConfigServiceUrl;
    private DateTime lastExternalCheckTime;
    private bool isExternalConfigServiceAvailable;

    public ConfigManager(string configFilePath, string externalConfigServiceUrl)
    {
        this.configFilePath = configFilePath;
        this.externalConfigServiceUrl = externalConfigServiceUrl;
        LoadConfiguration();
    }

    private void LoadConfiguration()
    {
        try
        {
            xmlDoc = XDocument.Load(configFilePath);
            ValidateXml(xmlDoc);
            UpdateCacheFromXml();
        }
        catch (Exception ex)
        {
            LogError(ex);
            // Rollback strategy: use last known good configuration or default values
        }

        ScheduleExternalConfigCheck();
    }

    private void ValidateXml(XDocument xmlDoc)
    {
        var schemaSet = new XmlSchemaSet();
        var namespaceManager = new XmlNamespaceManager(xmlDoc.NameTable);

        foreach (var element in xmlDoc.Root.Elements())
        {
            var schemaLocation = element.GetAttributeValue("schemaLocation", "");
            if (!string.IsNullOrEmpty(schemaLocation))
            {
                var parts = schemaLocation.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
                for (int i = 0; i < parts.Length; i += 2)
                {
                    schemaSet.Add(parts[i], parts[i + 1]);
                }
            }
        }

        xmlDoc.Validate(schemaSet, (sender, e) =>
        {
            LogError(e.Exception.Message);
            throw new XmlSchemaValidationException(e.Exception.Message);
        });
    }

    private void UpdateCacheFromXml()
    {
        foreach (var element in xmlDoc.Root.Elements())
        {
            var key = element.Attribute("key").Value;
            var value = element.Value;
            cache.TryAddOrUpdate(key, value, (k, v) => value);
        }
    }

    private async void ScheduleExternalConfigCheck()
    {
        while (true)
        {
            await Task.Delay(60 * 1000); // Check every minute
            if ((DateTime.Now - lastExternalCheckTime).TotalMinutes >= 5 && isExternalConfigServiceAvailable)
            {
                try
                {
                    // Fetch new configuration from external service
                    var newXml = await FetchExternalConfiguration();
                    ValidateXml(newXml);
                    UpdateCacheFromXml(xmlDoc = newXml);

                    lastExternalCheckTime = DateTime.Now;
                }
                catch (Exception ex)
                {
                    LogError(ex);
                    isExternalConfigServiceAvailable = false;
                }
            }
        }
    }

    private async Task<XDocument> FetchExternalConfiguration()
    {
        // Implement logic to fetch XML from external service
        throw new NotImplementedException();
    }

    public string GetConfigValue(string key)
    {
        return cache.TryGetValue(key, out var value) ? value : null;
    }

    private void LogError(Exception ex)
    {
        Console.WriteLine($"Error: {ex.Message}");
        // Implement more detailed logging logic here
    }
}
