const express = require('express');
const bodyParser = require('body-parser');
const axios = require('axios');
const Redis = require('ioredis');
const uuid = require('uuid');

const app = express();
app.use(bodyParser.json());

const redis = new Redis();
const maxConcurrency = 10;
let currentConcurrency = 0;

async function processFile(file) {
    if (currentConcurrency >= maxConcurrency) {
        return new Promise((resolve, reject) => {
            redis.lpush('fileQueue', JSON.stringify(file), () => {
                resolve();
            });
        });
    }

    try {
        currentConcurrency++;
        const response = await validateFile(file);
        console.log(`Processed file: ${file.id} - Status: ${response.status}`);
    } catch (error) {
        console.error(`Error processing file: ${file.id}`, error);
    } finally {
        currentConcurrency--;
        processPendingFiles();
    }
}

async function validateFile(file) {
    const schemaResponse = await axios.get('https://schema-api.example.com/schema');
    const validationRequest = {
        id: file.id,
        data: file.data,
        schema: schemaResponse.data
    };

    return axios.post('https://validation-api.example.com/validate', validationRequest);
}

async function processPendingFiles() {
    if (currentConcurrency >= maxConcurrency) {
        return;
    }

    const pendingFile = await redis.lpop('fileQueue');
    if (pendingFile) {
        const file = JSON.parse(pendingFile);
        processFile(file);
    }
}

app.post('/upload', async (req, res) => {
    const file = req.body;
    file.id = uuid.v4();
    file.status = 'QUEUED';

    await redis.lpush('fileQueue', JSON.stringify(file));
    processPendingFiles();

    res.status(202).send({ message: 'File queued for processing' });
});

app.listen(3000, () => {
    console.log('Server is running on port 3000');
});
```"]

