  constructor(maxConcurrentTests) {
    this.moduleManager = new ModuleManager();
    this.testRunner = new TestRunner(maxConcurrentTests);
    this.mockingLibrary = new MockingLibrary();
    this.errorHandler = new ErrorHandler();
    this.logger = new Logger();
    this.scalingMechanism = new ScalingMechanism();
  }

