from queue import Queue

class LogAnalyzer:
    def __init__(self, log_dir, output_api):
        self.log_dir = log_dir
        self.output_api = output_api
        self.log_queue = Queue()

    def start_processing(self):
        threads = [Thread(target=self.process_logs) for _ in range(10)]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join()

    def process_logs(self):
        while True:
            log_file = self.log_queue.get()
            if log_file is None:
                break
            self.parse_log(log_file)

    def parse_log(self, log_file):
        with gzip.open(log_file, 'rt') as file:
            for line in file:
                if self.is_error_line(line):
                    error_data = self.extract_error_data(line)
                    self.output_api.send_report(error_data)

    def is_error_line(self, line):
        return re.search(r'ERROR|CRITICAL', line) is not None

    def extract_error_data(self, line):
        # Extract relevant data from the log line
        # This is a simplified example; actual implementation may vary
        return {
            'message': line,
            'timestamp': self.extract_timestamp(line),
            'source': self.extract_source(line)
        }

    def extract_timestamp(self, line):
        # Example timestamp extraction logic
        return line.split(' ')[0]

    def extract_source(self, line):
        # Example source extraction logic
        return line.split(' ')[1]

