use std::collections::HashSet;
use std::time::{Instant, SystemTime};
use rustc_driver::{catch_with_exit_code, early_error};
use std::env;

fn renderFooterScripts(scripts: Vec<String>) -> Result<String, String> {
    let mut valid_scripts = HashSet::new();
    let start_time = Instant::now();

    for script in scripts {
        if is_valid_javascript(&script) {
            let unique_key = generate_unique_key(&script);
            valid_scripts.insert(unique_key);
        }
    }

    let end_time = Instant::now();
    println!("Compilation time: {:?}", end_time.duration_since(start_time));

    let html = valid_scripts.iter().map(|key| format!("<script id=\"{}\" src=\"/scripts/{}.js\"></script>", key, key)).collect();
    Ok(html)
}

fn is_valid_javascript(script: &str) -> bool {
    // Simple validation for demonstration purposes
    !script.contains("alert('XSS')") && script.starts_with("function")
}

fn generate_unique_key(script_content: &str) -> String {
    let timestamp = SystemTime::now().duration_since(SystemTime::UNIX_EPOCH).unwrap().as_secs();
    let random_number: u32 = rand::random();
    let hash = md5::compute(script_content);
    format!("{}-{}-{:x}", timestamp, random_number, hash)
}

fn main() {
    let scripts = vec![
        String::from("function greet() { alert('Hello'); }"),
        String::from("function alertXSS() { alert('XSS'); }"),
        // Add more scripts as needed
    ];

    match renderFooterScripts(scripts) {
        Ok(html) => println!("{}", html),
        Err(err) => eprintln!("Error: {}", err),
    }
}
