import java.io.IOException;
import java.net.URL;
import java.util.concurrent.ConcurrentHashMap;

public class ResourceLoader {
    private final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private final HttpClient httpClient;
    private final CacheManager cacheManager;
    private final RateLimiter rateLimiter;

    public ResourceLoader(HttpClient httpClient, CacheManager cacheManager, RateLimiter rateLimiter) {
        this.httpClient = httpClient;
        this.cacheManager = cacheManager;
        this.rateLimiter = rateLimiter;
    }

    public String loadResource(String uri, boolean forceReload) throws IOException {
        if (!forceReload && cache.containsKey(uri)) {
            return cache.get(uri);
        }

        if (rateLimiter.isAllowed(uri)) {
            URL url = new URL(uri);
            String resourceContent = httpClient.fetch(url);

            if (resourceContent != null) {
                cacheManager.store(uri, resourceContent);
            }
            return resourceContent;
        } else {
            throw new IOException("Rate limit exceeded for URI: " + uri);
        }
    }

    // Additional methods and classes for HttpClient, CacheManager, RateLimiter, etc.
}
