['```rust
use std::fs::{File, OpenOptions};
use std::io::{self, Write};
use std::os::unix::process::StdioExt;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::time::{Instant, Duration};

extern crate libc;
extern crate memusage;

fn compile_projects(project_paths: Vec<PathBuf>, log_directory: PathBuf) -> Vec<(i32, String)> {
    let mut reports = Vec::new();
    let shared_state = Arc::new(Mutex::new(LogState {
        log_file_sizes: Default::default(),
        memory_threshold: 50 * 1024 * 1024,
    }));

    for path in project_paths {
        let report = compile_project(&path, &log_directory, &shared_state);
        reports.push(report);
    }

    reports
}

fn compile_project(
    project_path: &PathBuf,
    log_directory: &PathBuf,
    shared_state: &Arc<Mutex<LogState>>,
) -> (i32, String) {
    let start_time = Instant::now();
    let mut child_process = std::process::Command::new("cargo")
        .arg("build")
        .current_dir(project_path)
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .spawn()
        .expect("Failed to start cargo build process");

    let stdout = child_process.stdout.take().unwrap();
    let stderr = child_process.stderr.take().unwrap();

    let mut report = String::new();
    let mut log_file_path = log_directory.join(format!("build_logs_{}.log", project_path.file_stem().unwrap().to_str().unwrap()));
    ensure_log_file_size(&mut log_file_path, shared_state);

    {
        let mut log_state = shared_state.lock().unwrap();
        log_state.log_file_sizes.insert(log_file_path.clone(), 0);
    }

    io::copy(&mut stdout, &mut File::create(&log_file_path).expect("Failed to create log file"))
        .expect("Failed to copy stdout");
    io::copy(&mut stderr, &mut File::create(&log_file_path).expect("Failed to create log file"))
        .expect("Failed to copy stderr");

    let exit_code = child_process.wait().expect("Failed to wait for process").code().unwrap();
    let compile_time = start_time.elapsed();

    if let Some(rss) = memusage::get_resident_set_size() {
        if rss > shared_state.lock().unwrap().memory_threshold {
            report += &format!("Warning: Memory usage exceeded 50 MB\n");
        }
    }

    report.push_str(&format!("Project: {}\n", project_path.display()));
    report.push_str(&format!("Compilation time: {:?}", compile_time));
    report.push_str(&format!("Exit code: {}\n", exit_code));

    (exit_code, report)
}

fn ensure_log_file_size(path: &mut PathBuf, shared_state: &Arc<Mutex<LogState>>) {
    let mut log_state = shared_state.lock().unwrap();
    if log_state.log_file_sizes.get(path).unwrap() > &1 * 1024 * 1024 {
        *path = path.with_extension("old");
        *log_state.log_file_sizes.entry(*path).or_insert(0) = 0;
    }
}

#[derive(Default)]
struct LogState {
    log_file_sizes: std::collections::HashMap<PathBuf, usize>,
    memory_threshold: usize,
}
```']

