import requests
from flask import Flask, request, jsonify
from functools import wraps

app = Flask(__name__)

# OAuth 2.0 Configuration
OAUTH_PROVIDERS = {
    'google': {'url': 'https://accounts.google.com/o/oauth2/auth', 'client_id': 'your_google_client_id'},
    'facebook': {'url': 'https://www.facebook.com/v13.0/dialog/oauth', 'client_id': 'your_facebook_client_id'}
}

def oauth_required(func):
    @wraps(func)
    def decorated_function(*args, **kwargs):
        provider = request.args.get('provider')
        if provider not in OAUTH_PROVIDERS:
            return jsonify({'error': 'Invalid provider'}), 400

        redirect_uri = request.args.get('redirect_uri')
        scope = request.args.get('scope', 'email')

        oauth_url = f"{OAUTH_PROVIDERS[provider]['url']}?client_id={OAUTH_PROVIDERS[provider]['client_id']}&redirect_uri={redirect_uri}&response_type=code&scope={scope}"

        return jsonify({'oauth_url': oauth_url})

    return decorated_function

@app.route('/callback', methods=['GET'])
def callback():
    provider = request.args.get('provider')
    code = request.args.get('code')

    if provider not in OAUTH_PROVIDERS:
        return jsonify({'error': 'Invalid provider'}), 400

    token_url = f"{OAUTH_PROVIDERS[provider]['url']}/token"
    data = {
        'grant_type': 'authorization_code',
        'code': code,
        'redirect_uri': request.args.get('redirect_uri'),
        'client_id': OAUTH_PROVIDERS[provider]['client_id'],
        'client_secret': 'your_client_secret'
    }

    response = requests.post(token_url, data=data)
    if response.status_code != 200:
        return jsonify({'error': 'Failed to get access token'}), 400

    access_token = response.json().get('access_token')
    return jsonify({'access_token': access_token})

if __name__ == '__main__':
    app.run(debug=True)
```

This code snippet provides a basic implementation of an OAuth 2.0 authentication module using Flask, handling requests from different IDPs and providing access tokens upon successful authentication.']

