#include <iostream>
#include <thread>
#include <atomic>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <vector>
#include <array>
#include <chrono>
#include <memory>

class Transaction {
public:
    double amount;
    std::time_t timestamp;

    Transaction(double a, std::time_t t) : amount(a), timestamp(t) {}
};

class TransactionProcessor {
private:
    using TransactionQueue = std::queue<Transaction>;
    using Metrics = std::array<std::atomic<double>, 3>;

    struct DeserializedTransaction {
        double amount;
        int age_in_seconds;

        DeserializedTransaction(double a, int age) : amount(a), age_in_seconds(age) {}
    };

    std::mutex queue_mutex_;
    std::condition_variable cond_var_;
    TransactionQueue transaction_queue_;

    Metrics metrics_{0.0, 0.0, 0.0}; // total transactions, average amount, highest weighted sum

    std::atomic<bool> running_ = true;

    void process_transactions() {
        while (running_) {
            std::unique_lock<std::mutex> lock(queue_mutex_);
            cond_var_.wait(lock, [this] { return !transaction_queue_.empty(); });
            Transaction transaction = transaction_queue_.front();
            transaction_queue_.pop();
            lock.unlock();

            DeserializedTransaction deserialized_transaction = deserialize_binary(transaction.amount);

            update_metrics(deserialized_transaction);
        }
    }

    DeserializedTransaction deserialize_binary(double binary_data) {
        // Implement your custom deserialization logic here
        return DeserializedTransaction(binary_data, 0);
    }

    void update_metrics(const DeserializedTransaction& transaction) {
        std::lock_guard<std::mutex> lock(metrics_mutex_);
        metrics_[0] += 1.0;
        metrics_[1] = (metrics_[1] * (metrics_[0] - 1) + transaction.amount) / metrics_[0];
        double weighted_sum = transaction.amount * transaction.age_in_seconds;
        if (weighted_sum > metrics_[2]) {
            metrics_[2] = weighted_sum;
        }
    }

public:
    TransactionProcessor() {
        // Start processing thread
        std::thread([this]() { process_transactions(); }).detach();
    }

    ~TransactionProcessor() {
        running_ = false;
        cond_var_.notify_all();
        for (auto& worker : workers_) {
            if (worker.joinable()) {
                worker.join();
            }
        }
    }

    void add_transaction(double binary_data) {
        std::lock_guard<std::mutex> lock(queue_mutex_);
        transaction_queue_.push(Transaction(binary_data, std::time(nullptr)));
        cond_var_.notify_one();
    }

    double get_total_transactions() const { return metrics_[0].load(); }
    double get_average_amount() const { return metrics_[1].load(); }
    double get_highest_weighted_sum() const { return metrics_[2].load(); }
};

int main() {
    TransactionProcessor processor;
    processor.add_transaction(100.5);
    processor.add_transaction(200.75);

    std::cout << "Total Transactions: " << processor.get_total_transactions() << std::endl;
    std::cout << "Average Amount: " << processor.get_average_amount() << std::endl;
    std::cout << "Highest Weighted Sum: " << processor.get_highest_weighted_sum() << std::endl;

    return 0;
}
