// C code for low-latency data collection

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_CONNECTIONS 10000
#define DATA_RATE_HZ 100

void* collect_data(void* conn_id) {
    // Simulate data collection at high rate
    for (int i = 0; i < DATA_RATE_HZ; ++i) {
        char* data = malloc(1024);
        if (data) {
            // Collect sensor data
            snprintf(data, 1024, "Data from connection %d", *(int*)conn_id);
            // Send data to Python component or cloud service
            // ...
            free(data);
        }
    }
    return NULL;
}

int main() {
    pthread_t* threads = (pthread_t*)malloc(MAX_CONNECTIONS * sizeof(pthread_t));
    int* conn_ids = (int*)malloc(MAX_CONNECTIONS * sizeof(int));

    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        conn_ids[i] = i;
        pthread_create(&threads[i], NULL, collect_data, &conn_ids[i]);
    }

    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
    free(conn_ids);

    return 0;
}
