import threading
from queue import Queue
import time

class DataProcessor:
    def __init__(self, max_connections):
        self.max_connections = max_connections
        self.data_queue = Queue(maxsize=max_connections * 10)
        self.threads = [threading.Thread(target=self.process_data) for _ in range(4)]

        for thread in self.threads:
            thread.start()

    def process_data(self):
        while True:
            data = self.data_queue.get()
            if data is None:
                break
            # Process data (e.g., analyze, store)
            print(f"Processing {data}")
            self.data_queue.task_done()

    def add_data(self, data):
        if not self.data_queue.full():
            self.data_queue.put(data)

    def stop(self):
        for _ in range(len(self.threads)):
            self.data_queue.put(None)
        for thread in self.threads:
            thread.join()

# Usage example
processor = DataProcessor(MAX_CONNECTIONS)

for i in range(MAX_CONNECTIONS * 100):  # Simulate high data volume
    processor.add_data(f"Data point {i}")

processor.stop()
