import concurrent.futures
from PIL import Image
import io
import requests
import logging

# Configure logging
logging.basicConfig(level=logging.INFO)

class ImageProcessor:
    def __init__(self, max_workers=10):
        self.executor = concurrent.futures.ThreadPoolExecutor(max_workers=max_workers)

    def process_image(self, image_url):
        try:
            response = requests.get(image_url, timeout=5)
            if response.status_code == 200:
                with Image.open(io.BytesIO(response.content)) as img:
                    # Resize and compress the image
                    resized_img = img.resize((800, 600), Image.ANTIALIAS).convert("RGB")
                    output = io.BytesIO()
                    resized_img.save(output, format='PNG', optimize=True)
                    return output.getvalue(), resized_img.info['metadata']
            else:
                logging.error(f"Failed to fetch image: {image_url}")
        except requests.exceptions.RequestException as e:
            logging.error(f"Request error for {image_url}: {e}")
        except Exception as e:
            logging.error(f"Error processing image: {e}")

    def submit_task(self, image_url):
        return self.executor.submit(self.process_image, image_url)

def main():
    processor = ImageProcessor(max_workers=50)
    urls = [
        'https://example.com/image1.jpg',
        'https://example.com/image2.png',
        # Add more URLs here
    ]

    futures = [processor.submit_task(url) for url in urls]
    results = []

    for future in concurrent.futures.as_completed(futures):
        try:
            result = future.result()
            if result:
                results.append(result)
        except Exception as e:
            logging.error(f"Task failed: {e}")

    # Store the processed images and metadata
    for image_data, metadata in results:
        store_image(image_data, metadata)

def store_image(image_data, metadata):
    # Implement storage logic here (e.g., using a distributed file system)
    pass

if __name__ == "__main__":
    main()
```

This code provides a basic implementation of the image processing pipeline. It uses Python's `concurrent.futures` module to handle concurrency and the Pillow library for image manipulation. The `ImageProcessor` class manages a thread pool and submits tasks to resize and compress images from given URLs. Error handling is implemented using try-except blocks, and logging is used for detailed error tracking.

The `main` function demonstrates how to use the `ImageProcessor` class to process multiple image URLs concurrently. The results are stored in the `results` list, which can be further processed or stored as needed.

This code does not include all the features mentioned in the task (e.g., real-time logging, metadata extraction, etc.), but it provides a starting point for building a scalable and maintainable image processing pipeline.']

