  async handleUpload(file, userId) {
    if (this.cache.exists(file.name)) {
      return 'Duplicate upload detected';
    }
    this.cache.set(file.name, true);
    try {
      await this.uploadToCloud(file, userId);
      return 'Upload successful';
    } catch (error) {
      this.cache.remove(file.name);
      throw error;
    }
