// Define the RedisCache class
class RedisCache {
  constructor() {
    this.client = new redis.createClient();
    this.client.connect();
  }

  exists(key) {
    return new Promise((resolve, reject) => {
      this.client.exists(key, (err, reply) => {
        if (err) reject(err);
        resolve(reply === 1);
      });
    });
  }

  set(key, value) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, (err) => {
        if (err) reject(err);
        resolve();
      });
    });
  }

  remove(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err) => {
        if (err) reject(err);
        resolve();
      });
    });
  }
}

