# Import necessary libraries
from flask import Flask, request, jsonify
import jwt
import os
from datetime import datetime, timedelta
from pymongo import MongoClient
import requests
from kafka import KafkaProducer

app = Flask(__name__)

# Load environment variables and configure JWT secret key
JWT_SECRET_KEY = os.getenv('JWT_SECRET_KEY')
MONGODB_URI = os.getenv('MONGODB_URI')

# MongoDB client configuration
client = MongoClient(MONGODB_URI)
db = client['server_health']
health_collection = db['health']

# Kafka producer configuration
producer = KafkaProducer(bootstrap_servers='kafka:9092', value_serializer=lambda v: v.encode('utf-8'))

# Function to generate JWT token
def generate_token(user_id):
    payload = {
        'user_id': user_id,
        'exp': datetime.utcnow() + timedelta(hours=1)
    }
    return jwt.encode(payload, JWT_SECRET_KEY, algorithm='HS256')

# Route for obtaining a new JWT token
@app.route('/auth', methods=['POST'])
def auth():
    username = request.json.get('username')
    password = request.json.get('password')
    # Assume authentication is successful and user_id is retrieved
    user_id = authenticate_user(username, password)
    if user_id:
        return jsonify({'token': generate_token(user_id)}), 200
    else:
        return jsonify({'error': 'Invalid credentials'}), 401

# Function to refresh JWT token
def refresh_token(token):
    try:
        payload = jwt.decode(token, JWT_SECRET_KEY, algorithms=['HS256'])
        if datetime.utcnow() < payload['exp']:
            user_id = payload['user_id']
            return generate_token(user_id)
    except jwt.ExpiredSignatureError:
        pass
    except jwt.InvalidTokenError:
        pass
    return None

# Route for refreshing JWT token
@app.route('/refresh', methods=['POST'])
def refresh():
    token = request.json.get('token')
    new_token = refresh_token(token)
    if new_token:
        return jsonify({'token': new_token}), 200
    else:
        return jsonify({'error': 'Invalid or expired token'}), 401

# Route to update server health status
@app.route('/health', methods=['POST'])
def update_health():
    token = request.headers.get('Authorization').split()[1]
    try:
        payload = jwt.decode(token, JWT_SECRET_KEY, algorithms=['HS256'])
        if datetime.utcnow() < payload['exp']:
            user_id = payload['user_id']
            # Assume authentication is successful and data is valid
            server_data = request.json
            health_collection.insert_one(server_data)
            producer.send('health_updates', value=json.dumps(server_data).encode('utf-8'))
            return jsonify({'message': 'Health status updated successfully'}), 200
    except jwt.ExpiredSignatureError:
        pass
    except jwt.InvalidTokenError:
        pass
    return jsonify({'error': 'Invalid or expired token'}), 401

# Function to authenticate user
