use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use tokio::fs as async_fs;
use tokio::task;

static WORKSPACE_SET: AtomicBool = AtomicBool::new(false);
static WORKSPACE_PATH: Arc<Mutex<Option<PathBuf>>> = Arc::new(Mutex::new(None));

async fn setup_workspace() -> Result<(), Box<dyn std::error::Error>> {
    if WORKSPACE_SET.swap(true, Ordering::SeqCst) {
        return Ok(());
    }

    let workspace_path = get_workspace_path();
    if !workspace_path.exists() {
        fs::create_dir_all(&workspace_path)?;
    }

    export_to_ci_cd(&workspace_path)?;

    ensure_disk_space()?;
    handle_temp_storage_overflow()?;

    WORKSPACE_PATH.lock().unwrap().replace(workspace_path);
    Ok(())
}

fn get_workspace_path() -> PathBuf {
    if let Some(path) = env::var("WORKSPACE_PATH").ok() {
        let path = Path::new(&path);
        if path.exists() && fs::metadata(path).unwrap().is_dir() && fs::OpenOptions::new().write(true).open(path).is_ok() {
            return path.to_path_buf();
        }
    }

    #[cfg(target_family = "unix")]
    let default_path = PathBuf::from("/tmp/workspace");
    #[cfg(not(target_family = "unix"))]
    let default_path = PathBuf::from(r"C:\Users\Public\Workspace");

    if !default_path.exists() {
        fs::create_dir_all(&default_path).unwrap();
    }

    default_path
}

async fn export_to_ci_cd(path: &Path) -> Result<(), Box<dyn std::error::Error>> {
