using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using StackExchange.Redis;

public class OAuthTokenValidator
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<OAuthTokenValidator> _logger;
    private readonly IDatabase _redisDatabase;
    private readonly IConnectionMultiplexer _redisMultiplexer;

    public OAuthTokenValidator(IConfiguration configuration, ILogger<OAuthTokenValidator> logger)
    {
        var redisConfiguration = ConfigurationOptions.Parse(configuration.GetSection("Redis").GetConnectionString());
        _redisMultiplexer = ConnectionMultiplexer.Connect(redisConfiguration);
        _redisDatabase = _redisMultiplexer.GetDatabase();
        _httpClient = new HttpClient();
        _logger = logger;
    }

    public async Task<ValidationResult> ValidateTokenAsync(string token)
    {
        try
        {
            var response = await _httpClient.GetAsync($"https://your-oauth-provider.com/oauth2/tokeninfo?access_token={token}");
            response.EnsureSuccessStatusCode();
            var tokenInfo = await response.Content.ReadAsAsync<TokenInfo>();

            if (tokenInfo == null || !IsValidToken(tokenInfo))
            {
                return new ValidationResult { IsValid = false, Error = "Invalid token" };
            }

            if (IsTokenExpired(tokenInfo.ExpiresIn))
            {
                return new ValidationResult { IsValid = false, Error = "Token expired" };
            }

            return new ValidationResult { IsValid = true };
        }
        catch (HttpRequestException e)
        {
            _logger.LogError(e, "Failed to validate token");
            return new ValidationResult { IsValid = false, Error = "Validation failed due to network error" };
        }
    }

    private bool IsValidToken(TokenInfo tokenInfo)
    {
        return !string.IsNullOrEmpty(tokenInfo.AccessToken) &&
               !string.IsNullOrEmpty(tokenInfo.TokenType) &&
               tokenInfo.TokenType == "Bearer" &&
               tokenInfo.ExpiresIn > 0;
    }

    private bool IsTokenExpired(int expiresIn)
    {
        var cachedExpiration = _redisDatabase.StringGet("token_expiration");
        if (cachedExpiration.IsNullOrEmpty)
        {
            _redisDatabase.StringSet("token_expiration", DateTime.UtcNow.AddSeconds(expiresIn).ToString());
            return false;
        }

        var expirationDateTime = DateTime.Parse(cachedExpiration);
        if (expirationDateTime < DateTime.UtcNow)
        {
            _redisDatabase.KeyDelete("token_expiration");
            return true;
        }

        return false;
    }
}

public class TokenInfo
{
    public string AccessToken { get; set; }
    public int ExpiresIn { get; set; }
    public string TokenType { get; set; }
    public string RefreshToken { get; set; }
}

public class ValidationResult
{
    public bool IsValid { get; set; }
    public string Error { get; set; }
}
```

