import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ResourceManagementService {

    private final ExecutorService executor = Executors.newFixedThreadPool(10);
    private final Map<String, String> resourceCache = new ConcurrentHashMap<>();
    private final ExternalAPIClient apiClient;
    private final DistributedDB db;
    private final MessageBroker messageBroker;

    public ResourceManagementService(ExternalAPIClient apiClient, DistributedDB db, MessageBroker messageBroker) {
        this.apiClient = apiClient;
        this.db = db;
        this.messageBroker = messageBroker;
    }

    public String getMD5Hash(String id) throws IOException, InterruptedException {
        if (resourceCache.containsKey(id)) {
            return resourceCache.get(id);
        }

        for (int attempt = 0; attempt < 3; attempt++) {
            try {
                String data = db.fetchResourceData(id);
                String hash = calculateMD5(data);
                resourceCache.putIfAbsent(id, hash);
                return hash;
            } catch (IOException e) {
                if (attempt == 2) throw new IOException("Failed to fetch MD5 hash after retries", e);
                Thread.sleep((long) Math.pow(2, attempt) * 100); // Exponential backoff
            }
        }
        return null; // Unreachable due to exception handling
    }

    public void updateResource(String id, String requestBody) throws IOException {
        CompletableFuture.runAsync(() -> {
            try {
                String existingData = db.fetchResourceData(id);
                if (existingData == null) throw new IOException("Resource not found");
                String updatedData = mergeUpdates(existingData, requestBody);
                boolean success = db.updateResourceData(id, updatedData);
                apiClient.updateResource(id, updatedData);
                if (!success) throw new IOException("Failed to update database");
                messageBroker.sendNotification(id, "Updated data: " + updatedData);
            } catch (IOException e) {
                handleUpdateFailure(e);
            }
        }, executor);
    }

    private void deleteResource(String id) throws IOException {
        CompletableFuture.runAsync(() -> {
            try {
                boolean dbSuccess = db.markResourceAsDeleted(id);
                apiClient.deleteResource(id);
                if (!dbSuccess || !apiClient.isDeletionConfirmed(id)) {
                    throw new IOException("Failed to fully delete resource");
                }
                messageBroker.sendNotification(id, "Resource deleted");
            } catch (IOException e) {
                handleDeletionFailure(e);
            }
        }, executor);
    }

    private String calculateMD5(String data) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] digest = md.digest(data.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : digest) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private String mergeUpdates(String existingData, String requestBody) {
        // Implement merge logic here
        return requestBody;
    }

    private void handleUpdateFailure(IOException e) {
        // Log and notify about update failure
    }

    private void handleDeletionFailure(IOException e) {
        // Log and notify about deletion failure
    }
}
