// Define a microservice architecture using Spring Boot and Netflix OSS components
@SpringBootApplication
@EnableDiscoveryClient
public class MicroservicesApplication {
    public static void main(String[] args) {
        SpringApplication.run(MicroservicesApplication.class, args);
    }
}

// Authentication Service - OAuth2 Integration
@Configuration
public class AuthConfig extends AuthorizationServerConfigurerAdapter {
    @Override
    public void configure(ClientDetailsServiceConfigurer clients) throws Exception {
        clients.inMemory()
            .withClient("clientId")
            .secret(passwordEncoder().encode("clientSecret"))
            .authorizedGrantTypes("authorization_code", "refresh_token", "password")
            .scopes("openid", "profile");
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }
}

// Payment Processing Service - External API Integration with Circuit Breaker
@Service
public class PaymentService {
    private final RestTemplate restTemplate;
    private final CircuitBreakerFactory circuitBreakerFactory;

    @Autowired
    public PaymentService(RestTemplate restTemplate, CircuitBreakerFactory circuitBreakerFactory) {
        this.restTemplate = restTemplate;
        this.circuitBreakerFactory = circuitBreakerFactory;
    }

    @CircuitBreaker(name = "paymentService", fallbackMethod = "fallbackPayment")
    public ResponseEntity<String> processPayment(PaymentRequest request) {
        return restTemplate.postForEntity("https://api.paymentgateway.com/charge", request, String.class);
    }

    private ResponseEntity<String> fallbackPayment(PaymentRequest request, Throwable throwable) {
        // Fallback logic for payment processing
        return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE).body("Payment service unavailable");
    }
}

// Analytics Service - External API Integration with Caching
@Service
public class AnalyticsService {
    @Autowired
    private CacheManager cacheManager;

    public void trackEvent(Event event) {
        String cacheKey = "event:" + event.getId();
        if (!cacheManager.getCache("events").getNativeCache().containsKey(cacheKey)) {
            // Call external analytics API and cache the result
            ExternalAnalyticsClient.sendEvent(event);
            cacheManager.getCache("events").put(cacheKey, true);
        }
    }
}

// Notification Service - External API Integration with Rate-Limiting
@Service
public class NotificationService {
    private final RestTemplate restTemplate;
    private final TokenBucket tokenBucket;

    @Autowired
    public NotificationService(RestTemplate restTemplate, TokenBucket tokenBucket) {
        this.restTemplate = restTemplate;
        this.tokenBucket = tokenBucket;
    }

    public void sendNotification(Notification notification) {
        if (tokenBucket.tryConsumeToken()) {
            restTemplate.postForObject("https://api.notificationservice.com/send", notification, Void.class);
        } else {
            throw new RuntimeException("Rate limit exceeded");
        }
    }
}

