// Include necessary headers
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <restinio/all.hpp>

// Define a class for cryptographic operations
class CryptoManager {
public:
    enum class Algorithm { DES_ECB, DES_EDE, DES_EDE3, CFB, NULL_ENCRYPTION };

    CryptoManager(Algorithm algorithm) : m_algorithm(algorithm) {}

    // Encrypt data using selected algorithm
    std::vector<unsigned char> encrypt(const std::vector<unsigned char>& key, const std::vector<unsigned char>& iv, const std::string& data) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (ctx == nullptr) throw std::runtime_error("Failed to create encryption context");

        int len;
        int ciphertext_len;
        std::vector<unsigned char> ciphertext(data.size() + EVP_CIPHER_block_size(getCipher()) + 1);

        switch (m_algorithm) {
            case Algorithm::DES_ECB: EVP_EncryptInit_ex(ctx, EVP_des_ecb(), nullptr, key.data(), iv.data()); break;
            case Algorithm::DES_EDE: EVP_EncryptInit_ex(ctx, EVP_des_ede3_cbc(), nullptr, key.data(), iv.data()); break;
            case Algorithm::DES_EDE3: EVP_EncryptInit_ex(ctx, EVP_des_ede3_cbc(), nullptr, key.data(), iv.data()); break;
            case Algorithm::CFB: EVP_EncryptInit_ex(ctx, EVP_des_cfb8(), nullptr, key.data(), iv.data()); break;
            case Algorithm::NULL_ENCRYPTION: return data; // No encryption
        }

        if (!EVP_EncryptUpdate(ctx, ciphertext.data(), &len, data.c_str(), data.size())) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Encryption failed");
        }
        ciphertext_len = len;

        if (!EVP_EncryptFinal_ex(ctx, ciphertext.data() + len, &len)) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Final encryption failed");
        }
        ciphertext_len += len;

        ciphertext.resize(ciphertext_len);
        EVP_CIPHER_CTX_free(ctx);

        return ciphertext;
    }

private:
    Algorithm m_algorithm;

    // Get the OpenSSL cipher handle based on the selected algorithm
    const EVP_CIPHER* getCipher() {
        switch (m_algorithm) {
            case Algorithm::DES_ECB: return EVP_des_ecb();
            case Algorithm::DES_EDE: return EVP_des_ede3_cbc();
            case Algorithm::DES_EDE3: return EVP_des_ede3_cbc();
            case Algorithm::CFB: return EVP_des_cfb8();
            default: throw std::runtime_error("Unsupported algorithm");
        }
    }
};

