    Edge** edges;
    int edge_count;
} Node;

Node* create_node() {
    Node* node = (Node*)malloc(sizeof(Node));
    node->edges = NULL;
    node->edge_count = 0;
    return node;
}

void add_edge(Node* node, Node* neighbor, double latency, double bandwidth) {
    Edge* edge = (Edge*)malloc(sizeof(Edge));
    edge->latency = latency;
    edge->bandwidth = bandwidth;

    node->edges = realloc(node->edges, sizeof(Edge*) * (node->edge_count + 1));
    node->edges[node->edge_count++] = edge;
}

void* thread_function(void* arg) {
    int id = *(int*)arg;
    srand(time(NULL) + id);
    Node* node = create_node();
    node->data.RX_UE_INFORMATION_TAG = rand() % 100;
    node->data.RNTI = rand() % 1000;
    node->data.CRC_INDICATION_REL8_TAG = rand() % 100;
    node->data.CRCFLAG = rand() % 2;

    for (int i = 0; i < id; i++) {
        Node* neighbor = create_node();
        add_edge(node, neighbor, (double)(rand() % 10), (double)(rand() % 10));
        pthread_join(neighbor->thread_id, NULL);
    }

    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];
    int thread_ids[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; i++) {
        thread_ids[i] = i;
