#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SESSIONS 10000
#define MAX_PACKETS 1000000

typedef struct {
    time_t timestamp;
    int packet_id;
    char* payload;
} DataPacket;

typedef struct {
    DataPacket** packets;
    size_t count;
    pthread_mutex_t lock;
} PacketList;

typedef struct {
    int session_id;
    PacketList* list;
} SessionData;

void initialize_packet_list(PacketList* list) {
    list->packets = (DataPacket**)malloc(MAX_PACKETS * sizeof(DataPacket*));
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_packet_list(PacketList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->packets[i]->payload);
        free(list->packets[i]);
    }
    free(list->packets);
    pthread_mutex_destroy(&list->lock);
}

void insert_packet(PacketList* list, DataPacket* packet) {
    pthread_mutex_lock(&list->lock);
    list->packets[list->count++] = packet;
    pthread_mutex_unlock(&list->lock);
}

DataPacket* get_packet(PacketList* list, int index) {
    DataPacket* packet = NULL;
    pthread_mutex_lock(&list->lock);
    if (index >= 0 && index < list->count) {
        packet = list->packets[index];
    }
    pthread_mutex_unlock(&list->lock);
    return packet;
}

void delete_packet(PacketList* list, int index) {
    pthread_mutex_lock(&list->lock);
    if (index >= 0 && index < list->count) {
        free(list->packets[index]->payload);
        free(list->packets[index]);
        for (; index + 1 < list->count; ++index) {
            list->packets[index] = list->packets[index + 1];
        }
        --list->count;
    }
    pthread_mutex_unlock(&list->lock);
}

void* session_thread(void* arg) {
    SessionData* data = (SessionData*)arg;
    PacketList* list = data->list;
    // Simulate packet generation and insertion
    DataPacket* packet = (DataPacket*)malloc(sizeof(DataPacket));
    time_t now = time(NULL);
    packet->timestamp = now;
    packet->packet_id = rand();
    packet->payload = (char*)malloc(1024 * sizeof(char));
    sprintf(packet->payload, "Payload for session %d at %ld", data->session_id, now);
    insert_packet(list, packet);

    // Simulate packet retrieval and deletion
    DataPacket* retrieved_packet = get_packet(list, 0);
    if (retrieved_packet) {
        printf("Retrieved Packet ID: %d\n", retrieved_packet->packet_id);
        delete_packet(list, 0);
    }

    return NULL;
}

int main() {
    PacketList packet_list;
    initialize_packet_list(&packet_list);

    pthread_t sessions[MAX_SESSIONS];
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        SessionData data = {i, &packet_list};
        if (pthread_create(&sessions[i], NULL, session_thread, &data) != 0) {
            perror("Failed to create thread");
            return 1;
        }
    }

    for (int i = 0; i < MAX_SESSIONS; ++i) {
        pthread_join(sessions[i], NULL);
    }

    destroy_packet_list(&packet_list);

    return 0;
}
