#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <atomic>
#include <chrono>
#include <cmath>
#include <zlib.h>

struct DataPacket {
    std::time_t timestamp;
    int packetID;
    std::string payload;

    // Constructor
    DataPacket(std::time_t ts, int id, const std::string& p)
        : timestamp(ts), packetID(id), payload(p) {}

    // Method to compress payload
    static std::vector<unsigned char> compress(const std::string& data) {
        z_stream stream;
        stream.zalloc = Z_NULL;
        stream.zfree = Z_NULL;
        stream.opaque = Z_NULL;
        deflateInit(&stream, Z_BEST_SPEED);
        std::vector<unsigned char> output(data.size() + 128);
        stream.avail_in = data.size();
        stream.next_in = (unsigned char*)data.c_str();
        stream.avail_out = output.size();
        stream.next_out = output.data();
        deflate(&stream, Z_FINISH);
        deflateEnd(&stream);
        output.resize(output.size() - stream.avail_out);
        return output;
    }

    // Method to decompress payload
    static std::string decompress(const std::vector<unsigned char>& data) {
        z_stream stream;
        stream.zalloc = Z_NULL;
        stream.zfree = Z_NULL;
        stream.opaque = Z_NULL;
        inflateInit(&stream);
        std::vector<char> output(data.size() * 3); // Maximum possible expansion
        stream.avail_in = data.size();
        stream.next_in = (unsigned char*)data.data();
        stream.avail_out = output.size();
        stream.next_out = (unsigned char*)output.data();
        inflate(&stream, Z_FINISH);
        inflateEnd(&stream);
        return std::string(output.begin(), output.end() - stream.total_out);
    }
};

class PacketManager {
private:
    std::queue<DataPacket> packetQueue;
    std::mutex queueMutex;
    std::condition_variable cv;
    std::atomic<bool> running;

public:
    PacketManager() : running(true) {}

    ~PacketManager() {
        running.store(false);
        cv.notify_all();
        for (auto& thread : workerThreads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void startWorkers(int numThreads) {
        for (int i = 0; i < numThreads; ++i) {
            workerThreads.emplace_back(&PacketManager::processPackets, this);
        }
    }

    void enqueuePacket(const DataPacket& packet) {
        std::lock_guard<std::mutex> lock(queueMutex);
        packetQueue.push(packet);
        cv.notify_one();
    }

private:
    std::vector<std::thread> workerThreads;

    void processPackets() {
        while (running.load()) {
            std::unique_lock<std::mutex> lock(queueMutex);
            cv.wait(lock, [this] { return !packetQueue.empty() || !running.load(); });

            if (!running.load()) break;

            DataPacket packet = packetQueue.front();
            packetQueue.pop();
            lock.unlock();

            // Simulate packet transmission with retry mechanism
            for (int retries = 0; retries < 5; ++retries) {
                try {
                    transmitPacket(packet);
                    break;
                } catch (const std::exception& e) {
                    if (retries == 4) {
                        std::cerr << "Failed to transmit packet after " << retries + 1 << " attempts: " << e.what() << std::endl;
                        // Log error
                        break;
                    }
                    std::this_thread::sleep_for(std::chrono::milliseconds(static_cast<int>(std::pow(2, retries) * 100)));
                }
            }
        }
    }

    void transmitPacket(const DataPacket& packet) {
        // Simulate external API call with potential errors
        if (rand() % 2 == 0) { // Simulating failure
            throw std::runtime_error("External API error");
        }
        std::cout << "Transmitted packet ID: " << packet.packetID << std::endl;
    }
};

int main() {
    PacketManager manager;
    manager.startWorkers(10);

    for (int i = 0; i < 50000; ++i) {
        DataPacket packet(std::time(nullptr), i, "Sample payload");
        manager.enqueuePacket(packet);
    }

    return 0;
}
