class PacketManager {
public:
    PacketManager(size_t max_sessions) : sessions(max_sessions), active_sessions(0) {}

    void insertPacket(const DataPacket& packet) {
        std::lock_guard<std::mutex> lock(mutex);
        packets.push(packet);
        cv.notify_one();
    }

    bool retrievePacket(DataPacket& packet, std::chrono::milliseconds timeout = std::chrono::seconds(1)) {
        std::unique_lock<std::mutex> lock(mutex);
        if (cv.wait_for(lock, timeout, [this] { return !packets.empty() || active_sessions == sessions; })) {
            if (!packets.empty()) {
                packet = packets.front();
                packets.pop();
                return true;
            }
            return false;
        }
        return false;
    }

    void deletePacket(const DataPacket& packet) {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto it = packets.begin(); it != packets.end(); ++it) {
            if (it->id == packet.id && it->timestamp == packet.timestamp) {
                packets.erase(it);
                break;
            }
        }
    }

