#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

typedef void (*error_callback_t)(const char*);

// Thread-safe cache for frequently reused strings
#define CACHE_SIZE 1024
static const char* string_cache[CACHE_SIZE];
static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to safely access the cache
const char* safe_cache_access(size_t index) {
    pthread_mutex_lock(&cache_lock);
    const char* result = string_cache[index];
    pthread_mutex_unlock(&cache_lock);
    return result;
}

// Function to safely store a string in the cache
void safe_cache_store(const char* str, size_t index) {
    if (str == NULL) {
        return; // Handle invalid input
    }
    pthread_mutex_lock(&cache_lock);
    free((void*)string_cache[index]); // Free existing entry
    string_cache[index] = strdup(str); // Duplicate and store new entry
    pthread_mutex_unlock(&cache_lock);
}

// Function to remove a string from the cache
void safe_cache_remove(size_t index) {
    pthread_mutex_lock(&cache_lock);
    free((void*)string_cache[index]); // Free existing entry
    string_cache[index] = NULL; // Clear entry
    pthread_mutex_unlock(&cache_lock);
}

// Function to process the string based on size limit and error handling callback
const char* process_string(const char* input, int size_limit, error_callback_t on_restriction_exceeded) {
    if (input == NULL || size_limit <= 0) {
        return NULL; // Handle invalid input
    }

    const char* cached_result = safe_cache_access(input[0] % CACHE_SIZE);
    if (cached_result != NULL && strcmp(cached_result, input) == 0) {
        return cached_result; // Return cached result if available
    }

    size_t len = strlen(input);
    if (len <= size_limit) {
        char* modified_str = malloc(len + 2); // Allocate memory for new string with forward slash and null terminator
        if (modified_str == NULL) {
            return NULL; // Handle memory allocation failure
        }
        strcpy(modified_str, input);
        modified_str[len] = '/';
        modified_str[len + 1] = '\0';
        safe_cache_store(modified_str, input[0] % CACHE_SIZE); // Cache the new string
        return modified_str;
    } else {
        on_restriction_exceeded(input); // Invoke error handling callback
        for (int i = 0; i < 3; ++i) { // Retry up to three times with exponential backoff
            usleep((1 << i) * 100000); // Exponential backoff
            const char* result = process_string(input, size_limit, on_restriction_exceeded);
            if (result != NULL) {
                return result; // Return result if successful retry
            }
        }
        // If cleanup fails persistently, log a warning and proceed without cleanup
        fprintf(stderr, "Warning: Persistent failure during cleanup.\n");
    }

    return input; // Fallback to original string in case of all failures
}
