#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the cache node structure for LRU eviction policy
typedef struct CacheNode {
    char *key;
    void *data;
    size_t size;
    time_t timestamp;
    struct CacheNode *next;
    struct CacheNode *prev;
} CacheNode;

// Define the cache structure
typedef struct Cache {
    CacheNode *head;
    CacheNode *tail;
    size_t count;
    size_t limit;
    pthread_mutex_t lock;
} Cache;

// Callback function prototype for fetch failure
typedef void (*FetchFailureCallback)(const char *key);

// Function to initialize the cache
Cache* init_cache(size_t cache_limit) {
    Cache *cache = (Cache*)malloc(sizeof(Cache));
    if (!cache) return NULL;
    cache->head = cache->tail = NULL;
    cache->count = 0;
    cache->limit = cache_limit;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

// Function to free the cache
void free_cache(Cache *cache) {
    CacheNode *current = cache->head;
    while (current) {
        CacheNode *next = current->next;
        free(current->key);
        free(current->data);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

// Function to get data from cache
void* get_from_cache(Cache *cache, const char *key) {
    CacheNode *current = cache->head;
    while (current) {
        if (strcmp(current->key, key) == 0) {
            return current->data;
        }
        current = current->next;
    }
    return NULL;
}

// Function to add data to the cache
void add_to_cache(Cache *cache, const char *key, void *data, size_t size) {
    pthread_mutex_lock(&cache->lock);
    if (cache->count >= cache->limit) {
        // Evict least recently used item
        CacheNode *to_evict = cache->tail;
        free(to_evict->key);
        free(to_evict->data);
        if (to_evict == cache->head) {
            cache->head = NULL;
        } else {
            to_evict->prev->next = NULL;
        }
        cache->tail = to_evict->prev;
        cache->count--;
    }
    CacheNode *new_node = (CacheNode*)malloc(sizeof(CacheNode));
    if (!new_node) {
        pthread_mutex_unlock(&cache->lock);
        return;
    }
    new_node->key = strdup(key);
    new_node->data = data;
    new_node->size = size;
    new_node->timestamp = time(NULL);
    new_node->next = cache->head;
    new_node->prev = NULL;
    if (cache->head) {
        cache->head->prev = new_node;
    } else {
        cache->tail = new_node;
    }
    cache->head = new_node;
    cache->count++;
    pthread_mutex_unlock(&cache->lock);
}

// Function to fetch and cache data
void* fetch_and_cache_data(const char *key, size_t cache_limit, FetchFailureCallback on_fetch_failure, int timeout_ms) {
    Cache *cache = init_cache(cache_limit);
    if (!cache) return NULL;

    void *cached_data = get_from_cache(cache, key);
    if (cached_data) {
        free_cache(cache);
        return cached_data;
    }

    // Simulate data fetching from an external API
    int retries = 0;
    while (retries < 5) {
        // Fetch data from API and handle errors
        // If successful, add to cache
        break; // Placeholder for actual fetch logic
    }

    if (!cached_data) {
        on_fetch_failure(key);
        free_cache(cache);
        return NULL;
    }

    add_to_cache(cache, key, cached_data, strlen(cached_data));
    free_cache(cache);
    return cached_data;
}
