app.use(rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
}));

// External API integration with a caching layer
async function fetchBookFromExternalAPI(isbn) {
  const cacheKey = `book:${isbn}`;
  try {
    let book = await redisClient.get(cacheKey);
    if (!book) {
      book = await axios.get(`https://api.example.com/books/${isbn}`);
      await redisClient.setex(cacheKey, 3600, JSON.stringify(book));
    }
    return JSON.parse(book);
  } catch (error) {
    console.error('Error fetching book:', error);
    throw error;
  }
}

// Patron management with RBAC
