  ADMIN: 'admin',
  USER: 'user'
};

app.post('/patrons', async (req, res) => {
  const { username, password, role } = req.body;
  if (!roles.includes(role)) {
    return res.status(403).json({ message: 'Invalid role' });
  }
  // Logic to save patron data securely
  res.json({ message: 'Patron registered successfully' });
});

// Book borrowing system with due date calculations and notifications
app.post('/borrow', async (req, res) => {
  const { isbn, patronId } = req.body;
  try {
    const book = await fetchBookFromExternalAPI(isbn);
    if (book.available) {
      // Logic to update book status and send borrowing notification
      channel.sendToQueue('notifications', Buffer.from(JSON.stringify({ type: 'borrow', book, patronId })));
      res.json({ message: 'Book borrowed successfully' });
    } else {
      res.status(400).json({ message: 'Book is not available' });
    }
  } catch (error) {
    console.error('Error borrowing book:', error);
    res.status(500).json({ message: 'Internal server error' });
  }
});

