using System;
using System.Diagnostics;
using System.IO;

public class WebsiteManager
{
    public Process AddAndStartWebsite(string directoryPath, string siteName)
    {
        // Check if web.config file exists in the directory
        string configFilePath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(configFilePath))
        {
            return null;
        }

        try
        {
            // Create a new process to start the website
            ProcessStartInfo startInfo = new ProcessStartInfo
            {
                WorkingDirectory = directoryPath,
                FileName = Path.Combine(directoryPath, siteName),
                RedirectStandardOutput = true,
                UseShellExecute = false,
                CreateNoWindow = true
            };

            Process process = new Process { StartInfo = startInfo };
            process.Start();

            // Log the start of the website
            Console.WriteLine($"Website started: {siteName} at {directoryPath}");

            return process;
        }
        catch (Exception ex)
        {
            // Handle exceptions and log errors
            Console.Error.WriteLine($"Failed to start website: {ex.Message}");
            return null;
        }
    }
}
```

