from tenacity import retry, stop_after_attempt, wait_exponential

# Define a Redis cache for product details with TTL (Time To Live)
product_cache = TTLCache(maxsize=1000, ttl=3600)

# Connect to the Redis server
redis_client = redis.StrictRedis(host='localhost', port=6379, db=0)

@retry(stop=stop_after_attempt(5), wait=wait_exponential(multiplier=2))
def get_product_details(product_id):
    # Try to fetch product details from the cache
    if product_id in product_cache:
        return product_cache[product_id]

    # If not found, fetch from external inventory API and store in cache
    product_details = fetch_from_inventory_api(product_id)
    if product_details:
        product_cache[product_id] = product_details

    return product_details

@retry(stop=stop_after_attempt(5), wait=wait_exponential(multiplier=2))
def update_product_stock(product_id, quantity):
    # Update stock in external inventory API
    if not update_inventory_api(product_id, quantity):
        raise Exception("Failed to update inventory")

    # Remove product from cache or decrement quantity
    if quantity == 0:
        if product_id in product_cache:
            del product_cache[product_id]
    else:
        product_details = product_cache.get(product_id)
        if product_details:
            product_details['stock'] -= quantity
            product_cache[product_id] = product_details

def fetch_from_inventory_api(product_id):
    # Simulate fetching product details from an external API
    return {"id": product_id, "name": "Product Name", "price": 10.99, "stock": 50}

def update_inventory_api(product_id, quantity):
    # Simulate updating inventory in an external API
    print(f"Updating inventory for product {product_id} by {quantity}")
    return True

# Example usage
try:
    product_details = get_product_details("12345")
    print(product_details)

    update_product_stock("12345", 10)
except Exception as e:
    print(f"Error: {e}")
