#include <stdlib.h>
#include <pthread.h>

#define MAX_CRC_INDICATIONS 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t pool_index;
    pthread_mutex_t lock;
} CRCIndicationPool;

void init_crc_indication_pool(CRCIndicationPool *pool, size_t size) {
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->pool_size = size;
    pool->pool_index = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

void destroy_crc_indication_pool(CRCIndicationPool *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
}

NFAPI_CRC_INDICATION_PDU_T *allocate_crc_indication(CRCIndicationPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->pool_index >= pool->pool_size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool is full
    }
    NFAPI_CRC_INDICATION_PDU_T *indication = &pool->pool[pool->pool_index++];
    pthread_mutex_unlock(&pool->lock);
    return indication;
}

void free_crc_indication(CRCIndicationPool *pool, NFAPI_CRC_INDICATION_PDU_T *indication) {
    pthread_mutex_lock(&pool->lock);
    size_t index = (size_t)(indication - pool->pool);
    if (index >= pool->pool_index) {
        pthread_mutex_unlock(&pool->lock);
        return; // Not a valid allocation
    }
    pool->pool[index].RX_UE_INFORMATION_TAG = 0;
    pool->pool[index].RNTI = 0;
    pool->pool[index].CRCFLAG = 0;
    pool->pool_index--;
    pthread_mutex_unlock(&pool->lock);
}

void process_crc_indications(CRCIndicationPool *pool, size_t num_indications) {
    for (size_t i = 0; i < num_indications; i++) {
        NFAPI_CRC_INDICATION_PDU_T *indication = allocate_crc_indication(pool);
        if (!indication) {
            // Handle allocation failure
            continue;
        }
        // Populate the indication with random data
        indication->RX_UE_INFORMATION_TAG = rand() % 1024;
        indication->RNTI = rand() % 16384;
        indication->CRCFLAG = rand() % 2;
    }
}

int main() {
    CRCIndicationPool pool;
    init_crc_indication_pool(&pool, MAX_CRC_INDICATIONS);

    // Simulate processing a large number of CRC indications
    process_crc_indications(&pool, 1000000);

    destroy_crc_indication_pool(&pool);
    return 0;
}
