#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <errno.h>

#define MAX_UE_INSTANCES 10000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    // Additional fields if needed
} UEInstance;

static UEInstance ue_instances[MAX_UE_INSTANCES];
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int next_instance_id = 0;
static int num_active_instances = 0;

int allocate_ue_instance() {
    pthread_mutex_lock(&mutex);
    if (num_active_instances >= MAX_UE_INSTANCES) {
        pthread_mutex_unlock(&mutex);
        return -ENOMEM; // Not enough space for new instance
    }
    int id = next_instance_id++;
    num_active_instances++;
    pthread_mutex_unlock(&mutex);
    return id;
}

void free_ue_instance(int id) {
    pthread_mutex_lock(&mutex);
    if (id >= next_instance_id || id < 0) {
        pthread_mutex_unlock(&mutex);
        fprintf(stderr, "Invalid UE instance ID\n");
        return;
    }
    num_active_instances--;
    pthread_mutex_unlock(&mutex);
}

int update_ue_instance(int id, NFAPI_CRC_INDICATION_PDU_T new_pdu) {
    pthread_mutex_lock(&mutex);
    if (id >= next_instance_id || id < 0) {
        pthread_mutex_unlock(&mutex);
        fprintf(stderr, "Invalid UE instance ID\n");
        return -EINVAL;
    }
    ue_instances[id].pdu = new_pdu;
    pthread_mutex_unlock(&mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T get_ue_instance(int id) {
    pthread_mutex_lock(&mutex);
    if (id >= next_instance_id || id < 0) {
        pthread_mutex_unlock(&mutex);
        fprintf(stderr, "Invalid UE instance ID\n");
        static NFAPI_CRC_INDICATION_PDU_T default_pdu = {0};
        return default_pdu;
    }
    NFAPI_CRC_INDICATION_PDU_T pdu = ue_instances[id].pdu;
    pthread_mutex_unlock(&mutex);
    return pdu;
}

void* cleanup_thread(void* arg) {
    while (1) {
        sleep(60); // Cleanup every minute
        pthread_mutex_lock(&mutex);
        for (int i = 0; i < next_instance_id; i++) {
            if (ue_instances[i].pdu.is_active == 0) {
                free_ue_instance(i);
                i--; // Adjust index after removal
            }
        }
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

int main() {
    pthread_t cleanup_tid;
    pthread_create(&cleanup_tid, NULL, cleanup_thread, NULL);

    // Example usage
    int id = allocate_ue_instance();
    if (id >= 0) {
        NFAPI_CRC_INDICATION_PDU_T new_pdu = {0};
        update_ue_instance(id, new_pdu);
        NFAPI_CRC_INDICATION_PDU_T pdu = get_ue_instance(id);
        free_ue_instance(id);
    }

    pthread_join(cleanup_tid, NULL);
    return 0;
}
