#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_LOG_LENGTH 1024

typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

typedef struct {
    CURL *handle;
    char *api_url;
    pthread_mutex_t lock;
} LoggingService;

typedef struct {
    LogLevel level;
    char message[MAX_LOG_LENGTH];
} LogMessage;

LoggingService *init_logging_service(const char *api_url) {
    LoggingService *service = malloc(sizeof(LoggingService));
    service->handle = curl_easy_init();
    service->api_url = strdup(api_url);
    pthread_mutex_init(&service->lock, NULL);
    return service;
}

void destroy_logging_service(LoggingService *service) {
    curl_easy_cleanup(service->handle);
    free(service->api_url);
    pthread_mutex_destroy(&service->lock);
    free(service);
}

char *prepare_log_message(LogLevel level, const char *message) {
    static char buffer[MAX_LOG_LENGTH];
    time_t now = time(NULL);
    struct tm utc_time;
    gmtime_r(&now, &utc_time);

    int length = snprintf(buffer, sizeof(buffer), "%s [%d] %s", 
                         asctime_gmt(&utc_time), level, message);

    if (length >= sizeof(buffer)) {
        buffer[sizeof(buffer) - 1] = '/';
    }

    return buffer;
}

void log_message(LoggingService *service, const LogMessage *msg) {
    pthread_mutex_lock(&service->lock);

    char *prepared_message = prepare_log_message(msg->level, msg->message);

    if (prepared_message == NULL) {
        printf("Log message too long.\n");
        pthread_mutex_unlock(&service->lock);
        return;
    }

    curl_easy_setopt(service->handle, CURLOPT_URL, service->api_url);
    curl_easy_setopt(service->handle, CURLOPT_POSTFIELDS, prepared_message);

    CURLcode res = curl_easy_perform(service->handle);

    if (res != CURLE_OK) {
        printf("Failed to send log message: %s\n", curl_easy_strerror(res));
        pthread_mutex_unlock(&service->lock);
        return;
    }

    printf("Log message sent successfully.\n");

    pthread_mutex_unlock(&service->lock);
}

// Unit tests and stress tests would go here
