#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <memory>
#include <chrono>

class TCPConnection {
    // Simulated TCP connection class
};

class ConnectionPool {
private:
    std::vector<std::unique_ptr<TCPConnection>> connections;
    std::mutex poolMutex;
    std::condition_variable notFull;

public:
    ConnectionPool(size_t size) : connections(size) {}

    TCPConnection* getConnection() {
        std::unique_lock<std::mutex> lock(poolMutex);
        notFull.wait(lock, [this] { return !connections.empty(); });
        TCPConnection* conn = connections.back().release();
        connections.pop_back();
        return conn;
    }

    void returnConnection(TCPConnection* conn) {
        std::lock_guard<std::mutex> lock(poolMutex);
        connections.push_back(std::unique_ptr<TCPConnection>(conn));
        notFull.notify_one();
    }
};

class ConnectionManager {
private:
    ConnectionPool pool;
    std::vector<std::thread> threads;
    std::queue<std::function<void(TCPConnection*)>> tasks;

public:
    ConnectionManager(size_t poolSize, size_t numThreads) : pool(poolSize), threads(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            threads[i] = std::thread(&ConnectionManager::worker, this);
        }
    }

    ~ConnectionManager() {
        tasks.push(nullptr); // Signal workers to exit
        for (auto& t : threads) {
            t.join();
        }
    }

    void addTask(std::function<void(TCPConnection*)> task) {
        std::lock_guard<std::mutex> lock(pool.poolMutex);
        tasks.push(task);
    }

private:
    void worker() {
        while (true) {
            std::function<void(TCPConnection*)> task;
            {
                std::unique_lock<std::mutex> lock(pool.poolMutex);
                pool.notFull.wait(lock, [this] { return !tasks.empty(); });
                task = tasks.front();
                tasks.pop();
            }
            if (!task) break; // Exit signal
            TCPConnection* conn = pool.getConnection();
            try {
                task(conn);
            } catch (...) {
                std::cerr << "Task failed" << std::endl;
            }
            pool.returnConnection(conn);
        }
    }
};

int main() {
    ConnectionManager manager(10, 5); // Pool size of 10 and 5 worker threads
    // Simulate adding tasks
    for (int i = 0; i < 20; ++i) {
        manager.addTask([](TCPConnection* conn) {
            // Task logic using the connection
        });
    }
    return 0;
}
```

This code provides a basic structure for managing a pool of TCP connections in a multi-threaded environment. It includes a `ConnectionPool` class for managing the pool of connections and a `ConnectionManager` class that assigns tasks to worker threads, utilizing the connection pool. The actual logic for handling network operations is left as an exercise for the developer.']

