using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;

public class DynamicOAuth2TokenValidator : IDynamicOAuth2TokenValidator
{
    private readonly HttpClient _httpClient;
    private readonly IValidationRuleCache _validationRuleCache;

    public DynamicOAuth2TokenValidator(HttpClient httpClient, IValidationRuleCache validationRuleCache)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _validationRuleCache = validationRuleCache ?? throw new ArgumentNullException(nameof(validationRuleCache));
    }

    public async Task<bool> ValidateAccessTokenAsync(string token)
    {
        if (string.IsNullOrEmpty(token))
        {
            throw new ArgumentException("Token cannot be null or empty", nameof(token));
        }

        try
        {
            var rules = await _validationRuleCache.GetValidationRulesAsync();
            foreach (var rule in rules)
            {
                switch (rule.RuleType)
                {
                    case "IntegerRange":
                        if (!IsInRange(rule.Value, token))
                            return false;
                        break;
                    case "FloatRange":
                        if (!IsInFloatRange(rule.Value, token))
                            return false;
                        break;
                    // Add more rule types as needed
                }
            }
        }
        catch (HttpRequestException ex)
        {
            // Log error and implement retry strategy
            Console.WriteLine($"Error fetching validation rules: {ex.Message}");
            throw;
        }

        return true;
    }

    private bool IsInRange(string ruleValue, string token)
    {
        var parts = ruleValue.Split(',');
        if (parts.Length != 3 || !int.TryParse(parts[0], out int min) || !int.TryParse(parts[1], out int max) ||
            !bool.TryParse(parts[2], out bool isExclusive))
        {
            throw new ArgumentException("Invalid range format", nameof(ruleValue));
        }

        var value = Convert.ToInt32(token);
        if (isExclusive)
            return value > min && value < max;
        else
            return value >= min && value <= max;
    }

    private bool IsInFloatRange(string ruleValue, string token)
    {
        var parts = ruleValue.Split(',');
        if (parts.Length != 3 || !double.TryParse(parts[0], out double min) || !double.TryParse(parts[1], out double max) ||
            !bool.TryParse(parts[2], out bool isExclusive))
        {
            throw new ArgumentException("Invalid float range format", nameof(ruleValue));
        }

        var value = Convert.ToDouble(token);
        if (isExclusive)
            return value > min && value < max;
        else
            return value >= min && value <= max;
    }
}

public interface IDynamicOAuth2TokenValidator
{
    Task<bool> ValidateAccessTokenAsync(string token);
}

public class ValidationRuleCache : IValidationRuleCache
{
    private readonly HttpClient _httpClient;
    private List<ValidationRule> _validationRules;

    public ValidationRuleCache(HttpClient httpClient)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _validationRules = new List<ValidationRule>();
    }

    public async Task<List<ValidationRule>> GetValidationRulesAsync()
    {
        if (_validationRules.Any())
            return _validationRules;

        try
        {
            var response = await _httpClient.GetAsync("/api/validation-rules");
            response.EnsureSuccessStatusCode();
            var rules = await response.Content.ReadAsAsync<List<ValidationRule>>();
            _validationRules.AddRange(rules);
            return rules;
        }
        catch (HttpRequestException ex)
        {
            // Log error and implement retry strategy
            Console.WriteLine($"Error fetching validation rules: {ex.Message}");
            throw;
        }
    }
}

public class ValidationRule
{
    public string RuleType { get; set; }
    public string Value { get; set; }
}
