#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_UE_INSTANCES 10000

typedef struct {
    int id;
    // Other fields as per NFAPI_CRC_INDICATION_PDU_T structure
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *ue_instances;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t mutex;
} UE_Manager;

UE_Manager* ue_manager_init() {
    UE_Manager *manager = (UE_Manager*)malloc(sizeof(UE_Manager));
    if (!manager) return NULL;

    manager->ue_instances = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_UE_INSTANCES, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->ue_instances) {
        free(manager);
        return NULL;
    }

    manager->allocated_size = MAX_UE_INSTANCES;
    manager->used_size = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

int ue_manager_add_instance(UE_Manager *manager, NFAPI_CRC_INDICATION_PDU_T instance) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->used_size >= manager->allocated_size) {
        size_t new_size = manager->allocated_size * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_instances = realloc(manager->ue_instances, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_instances) {
            pthread_mutex_unlock(&manager->mutex);
            return -1;
        }
        manager->ue_instances = new_instances;
        manager->allocated_size = new_size;
    }
    memcpy(&manager->ue_instances[manager->used_size], &instance, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->used_size++;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

