def create_resource():
    data = request.get_json()
    try:
        save_to_database(data)
        send_to_queue(data)
        return jsonify({'message': 'Resource created successfully'}), 201
    except SQLAlchemyError as e:
        db.session.rollback()
        logging.error(f'Error creating resource: {e}')
        return jsonify({'error': str(e)}), 500

