# Caching
cache = {}

@app.route('/resources/<int:id>', methods=['GET'])
def read_resource_cached(id):
    if id in cache:
        return jsonify(cache[id])
    else:
        resource = Resource.query.filter_by(id=id).first()
        if resource:
            cache[id] = resource.data
