#include <yaml.h>

// Function to load configuration from YAML file
void load_config(const char *filename, EVP_CIPHER **cipher, int *mode, unsigned char **key, unsigned char **iv) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open config file");
        return;
    }

    yaml_parser_t parser;
    yaml_event_t event;

    yaml_parser_initialize(&parser);
    yaml_parser_set_input_file(&parser, file);

    while (1) {
        if (!yaml_parser_parse(&parser, &event)) {
            fprintf(stderr, "Failed to parse YAML\n");
            break;
        }

        switch (event.type) {
            case YAML_KEY_EVENT:
                // Parse key
                break;
            case YAML_VALUE_EVENT:
                // Parse value based on key
                break;
            case YAML_STREAM_END_EVENT:
                goto end;
            default:
                break;
        }
    }

end:
    yaml_parser_delete(&parser);
    fclose(file);
}

// Function to encrypt data using the loaded configuration
int encrypt_data(const unsigned char *plaintext, int plaintext_len, unsigned char **ciphertext, unsigned char **iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create context\n");
        return -1;
    }

    if (1 != EVP_EncryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Encryption failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (1 != EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintext_len)) {
        fprintf(stderr, "Update failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, (*ciphertext) + len, &len)) {
        fprintf(stderr, "Finalize failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    return 0;
}

// Function to decrypt data using the loaded configuration
int decrypt_data(const unsigned char *ciphertext, int ciphertext_len, unsigned char **plaintext, unsigned char **iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create context\n");
        return -1;
    }

    if (1 != EVP_DecryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Decryption failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (1 != EVP_DecryptUpdate(ctx, *plaintext, &len, ciphertext, ciphertext_len)) {
        fprintf(stderr, "Update failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, (*plaintext) + len, &len)) {
        fprintf(stderr, "Finalize failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return 1;
    }

    EVP_CIPHER *cipher = NULL;
    int mode = 0;
    unsigned char *key = NULL;
    unsigned char *iv = NULL;

    load_config(argv[1], &cipher, &mode, &key, &iv);

    unsigned char plaintext[] = "This is a secret message";
    int plaintext_len = strlen((char *)plaintext);
    unsigned char ciphertext[1024];
    unsigned char decryptedtext[1024];

    if (encrypt_data(plaintext, plaintext_len, &ciphertext, iv) == 0) {
        printf("Encrypted data: %s\n", ciphertext);

        if (decrypt_data(ciphertext, strlen((char *)ciphertext), &decryptedtext, iv) == 0) {
            printf("Decrypted data: %s\n", decryptedtext);
        } else {
            fprintf(stderr, "Decryption failed\n");
        }
    } else {
        fprintf(stderr, "Encryption failed\n");
    }

    EVP_CIPHER_free(cipher);
    free(key);
    free(iv);

    return 0;
}
