// Command Execution Service
const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

class CommandExecutionService {
  constructor(persistenceStrategy) {
    this.persistenceStrategy = persistenceStrategy;
  }

  async execute(command, args, options, callback) {
    const process = spawn(command, args, { ...options, stdio: 'pipe' });

    let output = '';
    process.stdout.on('data', chunk => {
      output += chunk.toString();
    });

    process.stderr.on('data', chunk => {
      callback(new Error(chunk.toString()));
    });

    process.on('close', (code) => {
      if (code !== 0) {
        callback(new Error(`Command exited with code ${code}`));
      } else {
        this.persistenceStrategy.save(output, (err) => {
          if (err) {
            callback(err);
          } else {
            callback(null, output);
          }
        });
      }
    });

    return new Promise((resolve, reject) => {
      process.stdin.end();
      process.stdout.on('end', () => resolve(output));
    });
  }

  async fetchOutput(command, args, options) {
    return await this.execute(command, args, options, (err, output) => {
      if (err) throw err;
      console.log(`Command Output: ${output}`);
    });
  }
}

// Persistence Strategies
class FilePersistenceStrategy {
  constructor(directory) {
    this.directory = directory;
  }

  save(data, callback) {
    const filePath = path.join(this.directory, `output_${Date.now()}.txt`);
    fs.writeFile(filePath, data, 'utf8', callback);
  }
}

class CloudStoragePersistenceStrategy {
