#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <unistd.h>

#define MAX_CHANNELS 10

typedef struct ChannelQualityIndication {
    int signal_strength;
    int noise_level;
    int interference_level;
} ChannelQualityIndication;

typedef struct FrameMetadata {
    char frame_id[256];
    time_t timestamp;
    ChannelQualityIndication channels[MAX_CHANNELS];
    // Other metadata fields
} FrameMetadata;

typedef struct Node {
    FrameMetadata data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    pthread_mutex_t lock;
    Node* head;
} LinkedList;

void initialize_list(LinkedList* list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
}

void insert_frame(LinkedList* list, FrameMetadata metadata) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    memcpy(&new_node->data, &metadata, sizeof(FrameMetadata));
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void iterate_list(LinkedList* list, void (*callback)(FrameMetadata)) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        callback(current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void cleanup_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
```

