#include <stdlib.h>
#include <pthread.h>

// Define the FrameMetadata structure
typedef struct {
    int frame_id;
    time_t timestamp;
    // Add other members as needed
} FrameMetadata;

// Define the ChannelQualityIndication structure
typedef struct {
    float signal_strength;
    float noise_level;
    float interference_level;
    // Add other members as needed
} ChannelQualityIndication;

// Define the DistributedLinkedList structure
typedef struct DistributedLinkedList {
    FrameMetadata* data;
    size_t length;
    size_t capacity;
    pthread_mutex_t lock;
    // Add other members as needed
} DistributedLinkedList;

// Initialize a new distributed linked list
DistributedLinkedList* dlist_init(size_t initial_capacity) {
    DistributedLinkedList* list = (DistributedLinkedList*)malloc(sizeof(DistributedLinkedList));
    list->data = (FrameMetadata*)calloc(initial_capacity, sizeof(FrameMetadata));
    list->length = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Free the memory used by a distributed linked list
void dlist_free(DistributedLinkedList* list) {
    free(list->data);
    free(list);
}

// Add an element to the distributed linked list asynchronously
void dlist_add_async(DistributedLinkedList* list, FrameMetadata* metadata) {
    pthread_mutex_lock(&list->lock);
    if (list->length == list->capacity) {
        list->capacity *= 2;
        list->data = (FrameMetadata*)realloc(list->data, list->capacity * sizeof(FrameMetadata));
    }
    list->data[list->length++] = *metadata;
    pthread_mutex_unlock(&list->lock);
}

// Remove an element from the distributed linked list asynchronously
void dlist_remove_async(DistributedLinkedList* list, int frame_id) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->length; ++i) {
        if (list->data[i].frame_id == frame_id) {
            for (size_t j = i; j < list->length - 1; ++j) {
                list->data[j] = list->data[j + 1];
            }
            list->length--;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

// Iterate over the distributed linked list and compute aggregate metrics
void dlist_compute_metrics(DistributedLinkedList* list, float* avg_signal_strength, float* avg_noise_level, float* avg_interference) {
    *avg_signal_strength = 0;
    *avg_noise_level = 0;
    *avg_interference = 0;

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->length; ++i) {
        // Assuming ChannelQualityIndication is part of FrameMetadata
        *avg_signal_strength += list->data[i].channel_quality_indication.signal_strength;
        *avg_noise_level += list->data[i].channel_quality_indication.noise_level;
        *avg_interference += list->data[i].channel_quality_indication.interference_level;
    }
    pthread_mutex_unlock(&list->lock);

    *avg_signal_strength /= list->length;
    *avg_noise_level /= list->length;
    *avg_interference /= list->length;
}

// Example usage
int main() {
