// DistributedLinkedList.c
#include "DistributedLinkedList.h"
#include <stdlib.h>
#include <string.h>

void dl_init(DistributedLinkedList *list) {
    list->head = NULL;
    list->size = 0;
}

void dl_destroy(DistributedLinkedList *list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->size = 0;
}

int dl_insert(DistributedLinkedList *list, FrameMetadata *metadata) {
    Node *new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        return -1; // Memory allocation failed
    }
    new_node->metadata = metadata;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    return 0;
}

FrameMetadata* dl_get_by_id(DistributedLinkedList *list, int frame_id) {
    Node *current = list->head;
    while (current != NULL) {
        if (current->metadata->frame_id == frame_id) {
            return current->metadata;
        }
        current = current->next;
    }
    return NULL; // Frame not found
}

void dl_remove_by_id(DistributedLinkedList *list, int frame_id) {
    Node *current = list->head;
    Node *prev = NULL;
    while (current != NULL) {
        if (current->metadata->frame_id == frame_id) {
            if (prev != NULL) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            list->size--;
            return;
        }
        prev = current;
        current = current->next;
    }
}

size_t dl_size(DistributedLinkedList *list) {
    return list->size;
}

