    FrameMetadata metadata;
    struct Node *next;
} Node;

typedef struct LinkedList {
    Node *head;
    pthread_mutex_t lock;
} LinkedList;

void init_linkedList(LinkedList *list);
void insert_metadata(LinkedList *list, FrameMetadata *metadata);
void remove_metadata(LinkedList *list, int frame_id);
FrameMetadata* get_metadata(LinkedList *list, int frame_id);
