```c
// frame_processor.c

#include "frame_processor.h"

void init_linkedList(LinkedList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void insert_metadata(LinkedList *list, FrameMetadata *metadata) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->metadata = *metadata;
    new_node->next = list->head;
    list->head = new_node;
}

void remove_metadata(LinkedList *list, int frame_id) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    Node *previous = NULL;

    while (current != NULL && current->metadata.frame_id != frame_id) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list->lock);
}

FrameMetadata* get_metadata(LinkedList *list, int frame_id) {
    Node *current = list->head;
    while (current != NULL && current->metadata.frame_id != frame_id) {
        current = current->next;
    }
    return current ? &current->metadata : NULL;
}

void free_list(LinkedList *list) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}
