```java
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class UnionFind {
    private Map<Integer, Integer> parent = new HashMap<>();
    private Map<Integer, Integer> rank = new HashMap<>();

    public int find(int x) {
        if (!parent.containsKey(x)) {
            parent.put(x, x);
            rank.put(x, 0);
        }
        if (parent.get(x) != x) {
            parent.put(x, find(parent.get(x)));
        }
        return parent.get(x);
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY) return;

        if (rank.get(rootX) < rank.get(rootY)) {
            parent.put(rootX, rootY);
        } else if (rank.get(rootX) > rank.get(rootY)) {
            parent.put(rootY, rootX);
        } else {
            parent.put(rootY, rootX);
            rank.put(rootX, rank.get(x) + 1);
        }
    }

    public int countDisjointPairs(int[] array) {
        for (int i = 0; i < array.length; i++) {
            union(array[i], array[i] - 1);
            union(array[i], array[i] + 1);
        }

        Map<Integer, Integer> disjointSets = new HashMap<>();
        for (int value : parent.keySet()) {
            int root = find(value);
            disjointSets.put(root, disjointSets.getOrDefault(root, 0) + 1);
        }

        return disjointSets.size();
    }
}
