// CloudStorageClient.java
public interface CloudStorageClient {
    void uploadFile(String provider, String filePath, byte[] data);
    byte[] downloadFile(String provider, String filePath) throws IOException;
    CompletableFuture<byte[]> downloadFileAsync(String provider, String filePath);
    void deleteFile(String provider, String filePath);
}

// AWSStorageClient.java
public class AWSStorageClient implements CloudStorageClient {
    private AmazonS3 s3Client;

    public AWSStorageClient() {
        this.s3Client = AmazonS3ClientBuilder.defaultClient();
    }

    @Override
    public void uploadFile(String provider, String filePath, byte[] data) {
        s3Client.putObject(provider, filePath, new ByteArrayInputStream(data));
    }

    @Override
    public byte[] downloadFile(String provider, String filePath) throws IOException {
        S3Object object = s3Client.getObject(provider, filePath);
        return IOUtils.toByteArray(object.getObjectContent());
    }

    @Override
    public CompletableFuture<byte[]> downloadFileAsync(String provider, String filePath) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                return downloadFile(provider, filePath);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        });
    }

    @Override
    public void deleteFile(String provider, String filePath) {
        s3Client.deleteObject(provider, filePath);
    }
}

// GoogleStorageClient.java
public class GoogleStorageClient implements CloudStorageClient {
    private Storage storage;

    public GoogleStorageClient() {
        this.storage = StorageOptions.getDefaultInstance().getService();
    }

    @Override
    public void uploadFile(String provider, String filePath, byte[] data) {
        BlobId blobId = BlobId.of(provider, filePath);
        BlobInfo blobInfo = BlobInfo.newBuilder(blobId).build();
        storage.create(blobInfo, data);
    }

    @Override
    public byte[] downloadFile(String provider, String filePath) throws IOException {
        Blob blob = storage.get(BlobId.of(provider, filePath));
        return blob.getContent().readAllBytes();
    }

    @Override
    public CompletableFuture<byte[]> downloadFileAsync(String provider, String filePath) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                return downloadFile(provider, filePath);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        });
    }

    @Override
    public void deleteFile(String provider, String filePath) {
        storage.delete(BlobId.of(provider, filePath));
    }
}
