import java.nio.channels.AsynchronousSocketChannel;
import java.util.concurrent.Future;

public class CryptoService {

    private AsynchronousSocketChannel clientChannel;

    public void connect(String host, int port) throws Exception {
        this.clientChannel = AsynchronousSocketChannel.open();
        Future<Void> future = clientChannel.connect(new InetSocketAddress(host, port));
        future.get(); // Wait for the connection to complete
    }

    public void sendData(ByteBuffer buffer) throws Exception {
        Future<Integer> result = clientChannel.write(buffer);
        int bytesWritten = result.get();
        System.out.println("Bytes written: " + bytesWritten);
    }

    public ByteBuffer receiveData(int size) throws Exception {
        ByteBuffer buffer = ByteBuffer.allocate(size);
        Future<Integer> future = clientChannel.read(buffer);
        int bytesRead = future.get();
        buffer.flip(); // Prepare the buffer to read from
        return buffer;
    }

    public void close() throws Exception {
        clientChannel.close();
    }
}
```

