#include <semaphore.h>
#include <thread>
#include <vector>
#include <atomic>
#include <memory>
#include <mutex>
#include <condition_variable>
#include <queue>

class SemaphoreSystem {
public:
    SemaphoreSystem(size_t initial_count) : count(initial_count), max_count(initial_count) {}

    void acquire() {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [this]() { return count > 0; });
        --count;
    }

    void release() {
        std::lock_guard<std::mutex> lock(mutex);
        ++count;
        if (count <= max_count / 2) {
            max_count = count * 2;
        }
        condition.notify_one();
    }

private:
    size_t count;
    size_t max_count;
    std::mutex mutex;
    std::condition_variable condition;
};

int main() {
    SemaphoreSystem semaphore(10);

    auto worker = [&semaphore]() {
        for (size_t i = 0; i < 1000; ++i) {
            semaphore.acquire();
            // Critical section
            semaphore.release();
        }
    };

    std::vector<std::thread> threads;
    for (size_t i = 0; i < 100; ++i) {
        threads.emplace_back(worker);
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
```

