#include <functional>
#include <future>

struct DependencyVersion {
    std::string version;
    DependencyVersion* parent;
    // Additional metadata fields

    DependencyVersion(std::string ver, DependencyVersion* p = nullptr) : version(ver), parent(p) {}
};

class ExternalServiceClient {
public:
    void logDependency(const std::string& operation, const std::forward_list<DependencyVersion>& versions);
    // Additional methods for external service interaction
};

void appendOrLogDependency(std::forward_list<DependencyVersion>& dependencyList,
                          const std::string& targetVersion,
                          const std::string& newVersion,
                          bool logFlag,
                          ExternalServiceClient& client,
                          ConnectionPool& connectionPool) {
    std::mutex listMutex;
    std::lock_guard<std::mutex> lock(listMutex);

    auto& [parent, found] = findParent(dependencyList, targetVersion);
    if (found) {
        dependencyList.push_front(DependencyVersion(newVersion, parent));
    } else {
        dependencyList.push_front(DependencyVersion(newVersion, nullptr));
    }

    if (!logFlag || !client.isServiceAvailable()) return;

    std::atomic<bool> logSuccess(false);
    auto logTask = [&dependencyList, &client, &logSuccess]() {
        for (int attempt = 0; attempt < 5; ++attempt) {
            try {
                client.logDependency("Append or Log", dependencyList);
                logSuccess.store(true);
                break;
            } catch (const std::exception& e) {
                if (attempt == 4) throw;
                std::this_thread::sleep_for(std::chrono::milliseconds(1 << attempt));
            }
        }
    };

    auto future = std::async(std::launch::async, logTask);

    // Wait for the logging task to complete or be canceled
    future.wait();
}
