#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <future>
#include <unistd.h>

class SecureDynamicRandomService {
public:
    SecureDynamicRandomService() : running(true) {
        workerThread = std::thread(&SecureDynamicRandomService::work, this);
    }

    ~SecureDynamicRandomService() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            running = false;
        }
        condition.notify_all();
        workerThread.join();
    }

    void executeCommandAsync(const std::string& command) {
        {
            std::lock_guard<std::mutex> lock(mutex);
            commands.push(command);
        }
        condition.notify_one();
    }

private:
    void work() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this]{ return !commands.empty() || !running; });
            if (!running && commands.empty()) {
                break;
            }
            auto command = std::move(commands.front());
            commands.pop();
            lock.unlock();

            executeCommand(command);
        }
    }

    void executeCommand(const std::string& command) {
        pid_t pid = fork();
        if (pid == -1) {
            // Handle error
            return;
        } else if (pid == 0) {
            // Child process
            execl("/bin/sh", "sh", "-c", command.c_str(), nullptr);
            _exit(1); // Only reached on failure
        } else {
            // Parent process
            int status;
            waitpid(pid, &status, 0);
        }
    }

    std::mutex mutex;
    std::condition_variable condition;
    std::queue<std::string> commands;
    bool running;
    std::thread workerThread;
};
