    public async Task UpdateEnvironmentAsync(int environmentId, float temperature, float humidity, int airQuality)
    {
        var data = new { EnvironmentId = environmentId, Temperature = temperature, Humidity = humidity, AirQuality = airQuality };
        await _cache.SetStringAsync(CacheKey, System.Text.Json.JsonSerializer.Serialize(data), new DistributedCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(2)
        });

        try
        {
            var response = await _httpClient.PostAsJsonAsync($"api/environments/{environmentId}", data);
            if (!response.IsSuccessStatusCode)
            {
                _logger.LogError("Failed to update environment settings.");
                // Implement fallback mechanism or degrade gracefully
            }
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Network error occurred while updating environment settings.");
            // Implement retry logic with exponential backoff and circuit breaker pattern
        }
    }

    public async Task<EnvironmentData> GetEnvironmentDataAsync(int environmentId)
    {
        if (_cache.TryGetValue(CacheKey, out string cachedData))
        {
            var data = System.Text.Json.JsonSerializer.Deserialize<EnvironmentData>(cachedData);
            return data;
        }

        try
        {
            var response = await _httpClient.GetAsync($"api/environments/{environmentId}");
            if (response.IsSuccessStatusCode)
            {
                var data = await response.Content.ReadAsAsync<EnvironmentData>();
                await _cache.SetStringAsync(CacheKey, System.Text.Json.JsonSerializer.Serialize(data), new DistributedCacheEntryOptions
                {
                    AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(2)
                });
                return data;
            }
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Network error occurred while fetching environment data.");
            // Implement fallback mechanism or degrade gracefully
        }

        throw new InvalidOperationException("Environment data not available.");
    }
}

