package main

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"time"

	"github.com/gorilla/mux"
	"go.mongodb.org/mongo-driver/bson/primitive"
)

type Document struct {
	ID         primitive.ObjectID `bson:"_id,omitempty"`
	Version    int                `json:"version"`
	Title      string             `json:"title"`
	Content    string             `json:"content"`
	CreatedAt  time.Time          `json:"created_at"`
	UpdatedAt  time.Time          `json:"updated_at"`
	Owner      string             `json:"owner"`
}

var documents = map[string]Document{}

func main() {
	router := mux.NewRouter()
	router.HandleFunc("/documents", getDocuments).Methods("GET")
	router.HandleFunc("/documents/{id}", getDocument).Methods("GET")
	router.HandleFunc("/documents", createDocument).Methods("POST")
	router.HandleFunc("/documents/{id}", updateDocument).Methods("PUT")
	router.HandleFunc("/documents/{id}", deleteDocument).Methods("DELETE")

	http.ListenAndServe(":8080", router)
}

func getDocuments(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(documents)
}

func getDocument(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	id := vars["id"]
	document, ok := documents[id]
	if !ok {
		http.Error(w, "Document not found", http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(document)
}

func createDocument(w http.ResponseWriter, r *http.Request) {
	var document Document
	err := json.NewDecoder(r.Body).Decode(&document)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	document.ID = primitive.NewObjectID()
	document.Version = 1
	document.CreatedAt = time.Now()
	document.UpdatedAt = time.Now()
	documents[document.ID.Hex()] = document
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(document)
}

func updateDocument(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	id := vars["id"]
	document, ok := documents[id]
	if !ok {
		http.Error(w, "Document not found", http.StatusNotFound)
		return
	}
	err := json.NewDecoder(r.Body).Decode(&document)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	document.Version++
	document.UpdatedAt = time.Now()
	documents[id] = document
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(document)
}

func deleteDocument(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	id := vars["id"]
	delete(documents, id)
	w.WriteHeader(http.StatusNoContent)
}
`
  }
}
