import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cache.annotation.EnableCaching;

@SpringBootApplication
@EnableCaching
public class ConfigServiceApplication {
    public static void main(String[] args) {
        SpringApplication.run(ConfigServiceApplication.class, args);
    }
}

@Service
public class ConfigurationService {
    @Autowired
    private JsonValidator jsonValidator;

    @Autowired
    private ExternalConfigApi externalConfigApi;

    @Autowired
    private CacheManager cacheManager;

    public Map<String, Object> getConfig(String serviceId) {
        try {
            // Fetch latest version of configuration from external API
            String configJson = externalConfigApi.fetchLatestConfig(serviceId);

            // Validate the JSON against dynamic schema
            if (!jsonValidator.validate(configJson)) {
                log.error("Invalid JSON received: {}", configJson);

                // Attempt to recover partial data using fallback mechanism
                Map<String, Object> fallbackData = jsonValidator.getFallbackData();
                cacheManager.putInCache(serviceId, fallbackData);
                return fallbackData;
            }

            // Cache the valid configuration
            Map<String, Object> configData = parseJson(configJson);
            cacheManager.putInCache(serviceId, configData);
            return configData;
        } catch (Exception e) {
            log.error("Failed to fetch or validate configuration for service: {}", serviceId, e);

            // Use local fallback strategy if external API is unavailable
            Map<String, Object> fallbackData = cacheManager.getFromCache(serviceId);
            if (fallbackData == null) {
                fallbackData = jsonValidator.getDefaultConfig();
                cacheManager.putInCache(serviceId, fallbackData);
            }
            return fallbackData;
        }
    }

    private Map<String, Object> parseJson(String json) throws JsonProcessingException {
        // Use a streaming parser to process large JSON files
        ObjectMapper objectMapper = new ObjectMapper();
        return objectMapper.readValue(json, Map.class);
    }
}

@Component
public class JsonValidator {
    private Schema currentSchema;

    public boolean validate(String json) {
        try {
            JsonNode rootNode = new ObjectMapper().readTree(json);
            JsonSchemaFactory factory = JsonSchemaFactory.byDefault();
            JsonSchema schema = factory.getSchema(currentSchema);
            JsonPointer.Factory pointerFactory = JsonPointer.Factory.instance;
            JsonValidator validator = JsonValidator.from(schema, pointerFactory);
            return validator.validate(new JsonNodeReader(rootNode));
        } catch (Exception e) {
            log.error("Failed to validate JSON against schema: {}", currentSchema, e);
            return false;
        }
    }

    public Map<String, Object> getFallbackData() {
        // Implement fallback data recovery logic
        return Collections.emptyMap();
    }

    public Map<String, Object> getDefaultConfig() {
        // Provide default configuration if no valid data is available
        return Collections.emptyMap();
    }

    public void updateSchema(Schema newSchema) {
        this.currentSchema = newSchema;
    }
}

@Component
public class ExternalConfigApi {
    @Autowired
    private RestTemplate restTemplate;

    public String fetchLatestConfig(String serviceId) {
        try {
            ResponseEntity<String> response = restTemplate.getForEntity("https://api.config.com/config/" + serviceId, String.class);
            return response.getBody();
        } catch (Exception e) {
            log.error("Failed to fetch configuration from external API: {}", serviceId, e);
            throw new ConfigServiceException("Failed to fetch configuration", e);
        }
    }
}

@Component
public class CacheManager {
    private Map<String, Object> cache = new ConcurrentHashMap<>();

    public void putInCache(String key, Object value) {
        cache.put(key, value);
    }

    public Object getFromCache(String key) {
        return cache.get(key);
    }
}
