using Microsoft.AspNetCore.Mvc;
using System.Threading.Tasks;

[ApiController]
[Route("[controller]")]
public class OctreeController : ControllerBase
{
    private readonly IOctreeService _octreeService;
    private readonly ICircuitBreaker _circuitBreaker;
    private readonly ILogger<OctreeController> _logger;

    public OctreeController(IOctreeService octreeService, ICircuitBreaker circuitBreaker, ILogger<OctreeController> logger)
    {
        _octreeService = octreeService;
        _circuitBreaker = circuitBreaker;
        _logger = logger;
    }

    [HttpPost("update")]
    public async Task<IActionResult> UpdateOctreeElementAsync([FromBody] OctreeUpdateRequest request)
    {
        try
        {
            if (_circuitBreaker.AllowCall)
            {
                await _octreeService.UpdateElementAsync(request);
                return Ok(new { message = "Update successful" });
            }
            else
            {
                // Fallback to local in-memory octree
                _logger.LogWarning("Circuit breaker open, falling back to local storage.");
                // Perform update operation using local in-memory storage
                return Ok(new { message = "Update successful via fallback" });
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating octree element");
            return StatusCode(500, new { message = "Internal server error", error = ex.Message });
        }
    }
}
