import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ResourceManagementService {

    private ExecutorService executorService = Executors.newFixedThreadPool(10);

    public String getMD5Hash(String id) {
        return executorService.submit(() -> {
            try {
                // Simulate database access
                TimeUnit.MILLISECONDS.sleep(200);
                String data = fetchDataFromDatabase(id);
                return generateMD5Hash(data);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException("Interrupted while fetching data from database", e);
            }
        }).join();
    }

    private String fetchDataFromDatabase(String id) {
        // Simulate database fetch
        return "data-for-id-" + id;
    }

    private String generateMD5Hash(String data) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(data.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Failed to generate MD5 hash", e);
        }
    }

