void create_directory(const char *name) {
    pthread_mutex_lock(&mutex);
    if (dir_path == NULL) {
        dir_path = strdup(name);
        mkdir(dir_path, 0777);
        setenv("NF_API_DIR", dir_path, 1);
    }
    pthread_mutex_unlock(&mutex);
}

void populate_pdu_list(int N) {
    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&mutex);
        if (pdu_count >= MAX_DIRS) {
            fprintf(stderr, "Error: Maximum number of PDU structures reached.\n");
