#define MAX_STRUCTS 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* manage_structs(void* arg) {
    int thread_id = *(int*)arg;
    srand(time(NULL) + thread_id);
    for (int i = 0; i < MAX_STRUCTS / MAX_THREADS; i++) {
        pthread_mutex_lock(&lock);
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand() % 1024;
        pdu.CRC_INDICATION_REL8_TAG = rand();
        pdu.CRCFLAG = rand() % 2;
        pthread_mutex_unlock(&lock);
        // Simulate service communication and directory creation
        sleep(rand() % 2);
    }
    return NULL;
}

int main() {
    pthread_t threads[MAX_THREADS];
    int thread_ids[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, manage_structs, &thread_ids[i]);
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
