function renderFooterScripts(scripts) {
    return new Promise((resolve, reject) => {
        const loadScript = (scriptUrl, callback) => {
            const script = document.createElement('script');
            script.src = scriptUrl;
            script.onload = () => callback(null, script);
            script.onerror = (error) => callback(error, null);
            document.body.appendChild(script);
        };

        const resolveDependencies = (scripts, dependencies, resolvedScripts = []) => {
            if (dependencies.length === 0) return Promise.resolve(resolvedScripts);
            const [dependency] = dependencies;
            return loadScript(dependency.url, (error, script) => {
                if (error) {
                    console.error(`Failed to load dependency: ${dependency.url}`, error);
                    reject(error);
                } else {
                    resolvedScripts.push(script);
                    return resolveDependencies(scripts, scripts.filter(s => s.dependencies.includes(dependency.id)), resolvedScripts);
                }
            });
        };

        resolveDependencies(scripts, scripts).then(resolvedScripts => {
            console.log('All dependencies loaded successfully:', resolvedScripts);
            resolve(resolvedScripts);
        }).catch(error => {
            console.error('Failed to load dependencies:', error);
            reject(error);
        });
    });
}
