#include "consul/ConsulClient.h"
#include "cache/LRUCache.h"

class ConfigManager {
public:
    ConfigManager(const std::string& consul_url, int cache_size) 
        : consul_client(consul_url), config_cache(cache_size) {}

    void updateConfig(const std::string& key, const Json::Value& value) {
        // Update configuration in Consul and cache
        consul_client.put(key, value);
        config_cache.update(key, value);
    }

    Json::Value getConfig(const std::string& key) {
        // Retrieve configuration from cache first, then Consul if not found
        auto cached_value = config_cache.get(key);
        if (cached_value != nullptr) {
            return *cached_value;
        }
        auto value_from_consul = consul_client.get(key);
        if (!value_from_consul.isNull()) {
            config_cache.update(key, value_from_consul);
        }
        return value_from_consul;
    }

    void rollbackConfig(const std::string& key, int version) {
        // Rollback configuration to a previous version
        Json::Value old_value = consul_client.rollback(key, version);
        config_cache.update(key, old_value);
    }

private:
    ConsulClient consul_client;
    LRUCache<std::string, Json::Value> config_cache;
};

int main() {
    ConfigManager config_manager("http://consul:8500", 100);

    // Example usage
    Json::Value config;
    config["database_url"] = "mongodb://localhost:27017";
    config_manager.updateConfig("app_config", config);

    auto retrieved_config = config_manager.getConfig("app_config");
    std::cout << retrieved_config << std::endl;

    return 0;
}
