    let isCircuitOpen = false;
    const circuitBreakerTimeout = 5000; // ms
    const maxAttempts = 3;

    // Caching layer for attribute metadata
    const cache = {};
    const cacheSizeLimit = 1000; // Max number of cached attributes

    // Configuration for concurrent refresh requests per session
