      fetchUserProfile(ctrl.userId)
        .then(data => {
          if (isCircuitOpen) {
            $timeout(() => {
              ctrl.refreshProfile();
            }, circuitBreakerTimeout);
            return;
          }
          const changedFields = Object.keys(data).filter(key => data[key] !== ctrl.userAttributes[key]);
          angular.merge(ctrl.userAttributes, data);
          console.log(`Refreshed fields: ${changedFields.join(', ')}`);
        })
        .catch(error => {
          if (error.message === 'Service unavailable') {
            isCircuitOpen = true;
            $timeout(() => {
              isCircuitOpen = false;
            }, circuitBreakerTimeout);
          } else {
            console.error('Failed to fetch user profile:', error);
          }
        });
    };

    // Function to update cache with attribute metadata
    function updateCache(metadata) {
      if (Object.keys(cache).length >= cacheSizeLimit) {
        Object.keys(cache).shift();
      }
      angular.merge(cache, metadata);
    }

    // Function to retrieve cached attribute metadata
