public class ResourceLoader
{
    private Dictionary<string, IResourceProvider> providers;

    public ResourceLoader()
    {
        providers = new Dictionary<string, IResourceProvider>();
    }

    public void RegisterProvider(string protocol, IResourceProvider provider)
    {
        providers[protocol] = provider;
    }

    public async Task<IDataReader> LoadResourceAsync(string uri, string connectionString, List<Parameter> parameters)
    {
        var parts = Uri.TryCreate(uri, UriKind.Absolute, out var parsedUri) ? parsedUri.Scheme : "";
        if (providers.ContainsKey(parts))
        {
            return await providers[parts].LoadResourceAsync(parsedUri.ToString(), connectionString, parameters);
        }
        throw new NotSupportedException($"Protocol '{parts}' not supported.");
    }
}

