interface HashFunction {
  hash(data: string): string;
}

interface BlockCipher {
  encrypt(data: string, key: string): string;
  decrypt(encryptedData: string, key: string): string;
}

// Plugin system to dynamically load and initialize cryptographic functions
class CryptographicServiceProvider {
  private providers: { [key: string]: HashFunction | BlockCipher } = {};

  public registerProvider(name: string, provider: HashFunction | BlockCipher) {
    this.providers[name] = provider;
  }

  public getProvider(name: string): HashFunction | BlockCipher | undefined {
    return this.providers[name];
  }
}

// Example implementations of cryptographic functions
class SHA256Hash implements HashFunction {
  hash(data: string): string {
    return createHash('sha256').update(data).digest('hex');
  }
}

class AESBlockCipher implements BlockCipher {
  encrypt(data: string, key: string): string {
    const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(key), Buffer.alloc(16));
    let encrypted = cipher.update(data);
    encrypted = Buffer.concat([encrypted, cipher.final()]);
    return encrypted.toString('hex');
  }

  decrypt(encryptedData: string, key: string): string {
    const decipher = crypto.createDecipheriv('aes-256-cbc', Buffer.from(key), Buffer.alloc(16));
    let decrypted = decipher.update(Buffer.from(encryptedData, 'hex'));
    decrypted = Buffer.concat([decrypted, decipher.final()]);
    return decrypted.toString();
  }
}

// Cryptographic service implementation
class CryptographicService {
  private provider: HashFunction | BlockCipher;
  private serviceProvider: CryptographicServiceProvider;

  constructor(serviceProvider: CryptographicServiceProvider) {
    this.serviceProvider = serviceProvider;
    // Initially load a default provider (e.g., SHA256)
    this.provider = new SHA256Hash();
  }

  public setProvider(name: string) {
    const provider = this.serviceProvider.getProvider(name);
    if (provider) {
      this.provider = provider;
    } else {
      throw new Error(`Provider ${name} not found`);
    }
  }

  public hash(data: string): string {
    return this.provider.hash(data);
  }

  public encrypt(data: string, key: string): string {
    if (this.provider instanceof BlockCipher) {
      return this.provider.encrypt(data, key);
    } else {
      throw new Error('Provider does not support encryption');
    }
  }

  public decrypt(encryptedData: string, key: string): string {
    if (this.provider instanceof BlockCipher) {
      return this.provider.decrypt(encryptedData, key);
    } else {
      throw new Error('Provider does not support decryption');
    }
  }
}

// Usage example
const serviceProvider = new CryptographicServiceProvider();
serviceProvider.registerProvider('SHA256', new SHA256Hash());
serviceProvider.registerProvider('AES', new AESBlockCipher());

const service = new CryptographicService(serviceProvider);
console.log(service.hash('test data')); // Output: 9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08
service.setProvider('AES');
console.log(service.encrypt('sensitive data', 'my-secret-key')); // Output: Encrypted data (hex)
