const express = require('express');
const cors = require('cors');
const { createRequire } = require('module');
const path = require('path');

const app = express();
app.use(cors());
const requireFunction = createRequire(import.meta.url);

let moduleCache = {};

// Function to load a module dynamically
async function loadModule(modulePath) {
  if (moduleCache[modulePath]) {
    return moduleCache[modulePath];
  }

  try {
    const module = await import(path.resolve(__dirname, modulePath));
    moduleCache[modulePath] = module;
    return module;
  } catch (error) {
    console.error(`Failed to load module ${modulePath}:`, error);
    throw error;
  }
}

// Endpoint to execute a module
app.get('/execute', async (req, res) => {
  const { modulePath, functionName, args } = req.query;

  if (!modulePath || !functionName) {
    return res.status(400).send('Missing required parameters');
  }

  try {
    const module = await loadModule(modulePath);
    if (typeof module[functionName] !== 'function') {
      throw new Error(`Function ${functionName} not found in module`);
    }
    const result = await module[functionName](...args.map(JSON.parse));
    res.json(result);
  } catch (error) {
    console.error('Execution error:', error);
    res.status(500).send('Error executing module');
  }
});

// Endpoint to handle third-party API requests with retries
app.get('/api', async (req, res) => {
  const { apiUrl } = req.query;

  if (!apiUrl) {
    return res.status(400).send('Missing required parameters');
  }

  const maxRetries = 3;
  let attempt = 0;
  while (attempt < maxRetries) {
    try {
      const response = await fetch(apiUrl);
      if (!response.ok) {
        throw new Error(`API request failed with status ${response.status}`);
      }
      const data = await response.json();
      return res.json(data);
    } catch (error) {
      console.warn(`Attempt ${attempt + 1} failed:`, error);
      attempt++;
    }
    await new Promise(resolve => setTimeout(resolve, 500)); // Exponential backoff
  }

  return res.status(503).send('Service unavailable');
});

// Endpoint to handle Rust function compilation and execution
app.post('/rust', async (req, res) => {
  const { rustCode } = req.body;

  if (!rustCode) {
    return res.status(400).send('Missing required parameters');
  }

  try {
    // Assuming a function `compileAndRunRust` exists that handles compilation and execution
    const result = await compileAndRunRust(rustCode);
    res.json(result);
  } catch (error) {
    console.error('Rust compilation and execution error:', error);
    res.status(500).send('Error compiling or running Rust code');
  }
});

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
```

