use reqwest::{Client, Url};
use tokio::sync::mpsc;
use tokio_tungstenite::{connect_async, tungstenite::protocol::Message};

struct HttpClient {
    client: Client,
    pool_size: usize,
    timeout: std::time::Duration,
}

impl HttpClient {
    fn new(pool_size: usize, timeout: std::time::Duration) -> Self {
        let client = Client::builder()
            .pool_max_idle_per_host(pool_size)
            .timeout(timeout)
            .build()
            .expect("Failed to create HTTP client");

        HttpClient { client, pool_size, timeout }
    }

    async fn send_request(&self, url: &Url) -> Result<String, reqwest::Error> {
        self.client.get(url).send().await?.text().await
    }
}

struct LoggingService {
    endpoint: String,
}

impl LoggingService {
    fn new(endpoint: String) -> Self {
        LoggingService { endpoint }
    }

    async fn log_message(&self, message: &str) -> Result<(), reqwest::Error> {
        let client = Client::new();
        let url = Url::parse(&self.endpoint).expect("Invalid logging service URL");
        client.post(url).json(&message).send().await?;
        Ok(())
    }
}

struct HttpModule {
    http_client: HttpClient,
    logging_service: LoggingService,
}

impl HttpModule {
    fn new(pool_size: usize, timeout: std::time::Duration, log_endpoint: String) -> Self {
        let http_client = HttpClient::new(pool_size, timeout);
        let logging_service = LoggingService::new(log_endpoint);

        HttpModule { http_client, logging_service }
    }

    async fn send_request_and_log(&self, url: &Url) -> Result<String, reqwest::Error> {
        match self.http_client.send_request(url).await {
            Ok(response) => {
                self.logging_service.log_message(&response).await?;
                Ok(response)
            },
            Err(e) => {
                self.logging_service.log_message(&e.to_string()).await?;
                Err(e)
            }
        }
    }
}

#[tokio::main]
async fn main() {
    let pool_size = 10;
    let timeout = std::time::Duration::from_secs(5);
    let log_endpoint = "http://example.com/log".to_string();

    let http_module = HttpModule::new(pool_size, timeout, log_endpoint);

    let url = Url::parse("https://api.example.com/data").expect("Invalid URL");

    match http_module.send_request_and_log(&url).await {
        Ok(response) => println!("Response: {}", response),
        Err(e) => println!("Error: {}", e),
    }
}
