use std::env;
use std::process::{Command, Stdio};
use std::time::{Instant, Duration};
use std::collections::HashMap;

mod logging;
mod resource_manager;
mod error_handler;
mod cache;
mod concurrency;
mod configuration;

fn main() {
    let config = configuration::load();
    let target_architecture = env::var("TARGET_ARCHITECTURE").unwrap_or_else(|_| "x86_64".to_string());
    let compiler_version = env::var("COMPILER_VERSION").unwrap_or_else(|_| "stable".to_string());
    let build_directory = env::var("BUILD_DIRECTORY").unwrap_or_else(|_| "target".to_string());

    logging::setup(&config.log_level);

    for project in &config.projects {
        compile_project(
            &project.name,
            &target_architecture,
            &compiler_version,
            &build_directory,
        );
    }
}

fn compile_project(
    name: &str,
    target_architecture: &str,
    compiler_version: &str,
    build_directory: &str,
) {
    let start_time = Instant::now();

    match run_cargo_build(name, target_architecture, compiler_version, build_directory) {
        Ok(_) => {
            let duration = start_time.elapsed();
            logging::info(&format!("Project {} compiled successfully in {:?}", name, duration));
        }
        Err(e) => {
            error_handler::handle_error(&e);
        }
    }
}

fn run_cargo_build(
    project_name: &str,
    target_architecture: &str,
    compiler_version: &str,
    build_directory: &str,
) -> Result<(), String> {
    let mut command = Command::new("cargo");
    command
        .arg("build")
        .arg("--manifest-path")
        .arg(&format!("{}/Cargo.toml", project_name))
        .arg("--target")
        .arg(target_architecture)
        .arg("-Z")
        .arg(compiler_version)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());

    if let Some(env_vars) = environment_variables() {
        for (key, value) in env_vars {
            command.env(key, value);
        }
    }

    logging::info(&format!("Building project {}...", project_name));

    let output = command.output().map_err(|e| format!("Failed to run cargo build: {}", e))?;

    if output.status.success() {
        resource_manager::optimize_resources();
        Ok(())
    } else {
        error_handler::handle_error(&String::from_utf8_lossy(&output.stderr).into());
        Err(String::from_utf8_lossy(&output.stderr).into())
    }
}

fn environment_variables() -> Option<HashMap<String, String>> {
    let mut env_vars = HashMap::new();
    env_vars.insert("RUST_BACKTRACE".to_string(), "1".to_string());
    env_vars.insert("CARGO_TARGET_DIR".to_string(), build_directory.to_string());
    Some(env_vars)
}
