from flask import Flask, request, jsonify
import schedule
import time
import requests
from functools import wraps
import backoff

app = Flask(__name__)

# Rate limiting using a simple decorator for demonstration purposes
def rate_limited(max_calls=10, period=3600):
    def decorator(func):
        count = [0]

        @wraps(func)
        def wrapper(*args, **kwargs):
            if count[0] >= max_calls:
                raise Exception("Rate limit exceeded")
            count[0] += 1
            return func(*args, **kwargs)

        schedule.every(period).seconds.do(reset_count, count)
        return wrapper

    def reset_count(count):
        count[0] = 0

    return decorator

# Caching using a simple in-memory cache for demonstration purposes
cache = {}

@backoff.on_exception(backoff.expo, requests.exceptions.RequestException, max_tries=5)
def fetch_data(url):
    response = requests.get(url)
    response.raise_for_status()
    return response.json()

@app.route('/schedule_report', methods=['POST'])
def schedule_report():
    data = request.get_json()
    project_id = data['project_id']
    report_type = data['report_type']

    if project_id in cache:
        rate_limit_info = cache[project_id]
        current_time = time.time()
        if current_time - rate_limit_info['last_call'] < 60:  # Assuming a limit of one call per minute
            return jsonify({"error": "Rate limit exceeded"}), 429

    url = f"https://api.example.com/generate_report?project_id={project_id}&report_type={report_type}"
    report_data = fetch_data(url)

    cache[project_id] = {
        'last_call': time.time(),
        'data': report_data
    }

    schedule.every(1).minutes.do(send_report, project_id=project_id, report_data=report_data)

    return jsonify({"message": "Report scheduled successfully"}), 200

def send_report(project_id, report_data):
    # Logic to send the report data to a designated endpoint
    print(f"Sending report for project {project_id}: {report_data}")

if __name__ == '__main__':
    app.run(debug=True)
