<?php

class UserService {
    private $db;
    private $cache;

    public function __construct($db, $cache) {
        $this->db = $db;
        $this->cache = $cache;
    }

    public function updatePassword($userId, $newPassword) {
        // Validate password strength and uniqueness
        if (!$this->validatePassword($newPassword)) {
            throw new Exception('Invalid password');
        }

        // Check for password uniqueness
        if ($this->isPasswordUnique($userId, $newPassword)) {
            throw new Exception('Password already used');
        }

        // Use optimistic locking
        $currentVersion = $this->getCurrentVersion($userId);

        // Update password with atomic operation
        try {
            $stmt = $this->db->prepare("UPDATE users SET password = :password, version = :version WHERE id = :id AND version = :currentVersion");
            $stmt->execute([
                ':password' => password_hash($newPassword, PASSWORD_BCRYPT),
                ':version' => $currentVersion + 1,
                ':id' => $userId,
                ':currentVersion' => $currentVersion
            ]);

            if ($stmt->rowCount() === 0) {
                throw new Exception('Password update failed');
            }

            // Invalidate cache
            $this->cache->delete($userId);

        } catch (PDOException $e) {
            throw new Exception('Database error: ' . $e->getMessage());
        }
    }

    private function validatePassword($password) {
        // Implement password strength validation logic
        return strlen($password) >= 8 && preg_match('/[a-z]/', $password) && preg_match('/[A-Z]/', $password) && preg_match('/\d/', $password);
    }

    private function isPasswordUnique($userId, $newPassword) {
        // Check if password has been used before
        $stmt = $this->db->prepare("SELECT COUNT(*) FROM users WHERE password = :password");
        $stmt->execute([':password' => $newPassword]);
        return $stmt->fetchColumn() > 0;
    }

    private function getCurrentVersion($userId) {
        // Retrieve current version from database
        $stmt = $this->db->prepare("SELECT version FROM users WHERE id = :id");
        $stmt->execute([':id' => $userId]);
        return (int)$stmt->fetchColumn();
    }
}

