        if (empty($profileData['name']) || empty($profileData['email'])) {
            throw new Exception('Invalid profile data');
        }

        try {
            $stmt = $this->db->prepare("UPDATE profiles SET name = :name, email = :email WHERE user_id = :userId");
            $stmt->execute([
                ':name' => $profileData['name'],
                ':email' => $profileData['email'],
                ':userId' => $userId
            ]);

            if ($stmt->rowCount() === 0) {
                throw new Exception('Profile update failed');
            }

        } catch (PDOException $e) {
            throw new Exception('Database error: ' . $e->getMessage());
        }
    }
}

class ExternalServiceAdapter {
    public function sendPasswordResetEmail($userId, $email) {
        // Integrate with email provider
        try {
            Mail::send("password_reset", ['userId' => $userId], function ($message) use ($email) {
                $message->to($email)->subject('Password Reset');
            });
        } catch (Exception $e) {
            throw new Exception('Failed to send email: ' . $e->getMessage());
        }
    }

    public function processPayment($userId, $amount) {
        // Integrate with payment gateway
        try {
            PaymentGateway::process($userId, $amount);
        } catch (Exception $e) {
            throw new Exception('Payment processing failed: ' . $e->getMessage());
        }
    }

    public function authenticateWithSocialMedia($provider, $userData) {
        // Integrate with social media API
        try {
            return SocialMedia::authenticate($provider, $userData);
        } catch (Exception $e) {
            throw new Exception('Authentication failed: ' . $e->getMessage());
        }
    }
}
