use std::collections::{HashMap, HashSet};
use std::fs;
use std::path::{Path, PathBuf};
use tokio::task;
use log::{info, error};

mod config;
mod environment;

pub struct DirectoryManager {
    directories: HashMap<String, DirInfo>,
    env_vars: HashMap<String, String>,
}

struct DirInfo {
    path: PathBuf,
    dependencies: HashSet<String>,
}

impl DirectoryManager {
    pub fn new() -> Self {
        DirectoryManager {
            directories: HashMap::new(),
            env_vars: HashMap::new(),
        }
    }

    pub async fn add_directory(&mut self, name: String, path: PathBuf, dependencies: HashSet<String>) -> Result<(), Box<dyn std::error::Error>> {
        if self.directories.contains_key(&name) {
            return Err("Directory already exists".into());
        }

        let dir_info = DirInfo { path, dependencies };
        self.directories.insert(name, dir_info);
        info!("Added directory: {}", name);
        Ok(())
    }

    pub async fn remove_directory(&mut self, name: &str) -> Result<(), Box<dyn std::error::Error>> {
        if !self.directories.contains_key(name) {
            return Err("Directory does not exist".into());
        }

        let dir_info = self.directories.remove(name).unwrap();
        fs::remove_dir_all(&dir_info.path)?;
        info!("Removed directory: {}", name);
        Ok(())
    }

    pub async fn add_env_var(&mut self, key: String, value: String) -> Result<(), Box<dyn std::error::Error>> {
        if self.env_vars.contains_key(&key) {
            return Err("Environment variable already exists".into());
        }

        self.env_vars.insert(key, value);
        environment::set_env_var(&key, &value)?;
        info!("Added environment variable: {}", key);
        Ok(())
    }

    pub async fn remove_env_var(&mut self, key: &str) -> Result<(), Box<dyn std::error::Error>> {
        if !self.env_vars.contains_key(key) {
            return Err("Environment variable does not exist".into());
        }

        let value = self.env_vars.remove(key).unwrap();
        environment::remove_env_var(key)?;
        info!("Removed environment variable: {}", key);
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_directory_manager() -> Result<(), Box<dyn std::error::Error>> {
        let mut manager = DirectoryManager::new();

        manager.add_directory("my_dir".to_string(), PathBuf::from("/tmp/my_dir"), HashSet::from(["dep1".to_string()])).await?;
        manager.add_env_var("MY_VAR".to_string(), "my_value".to_string()).await?;

        manager.remove_directory("my_dir").await?;
        manager.remove_env_var("MY_VAR").await?;

        Ok(())
    }
}
