    void thread_function();
};

// NetworkStreamProcessor.cpp
#include "NetworkStreamProcessor.h"
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <cstring>
#include <openssl/err.h>

NetworkStreamProcessor::NetworkStreamProcessor(int port, const std::string& host) {
    // Initialize SSL context and other setup
}

NetworkStreamProcessor::~NetworkStreamProcessor() {
    stop();
}

void NetworkStreamProcessor::start() {
    running = true;
    worker_thread = std::thread(&NetworkStreamProcessor::thread_function, this);
}

void NetworkStreamProcessor::stop() {
    running = false;
    cv.notify_all();
    if (worker_thread.joinable()) {
        worker_thread.join();
    }
}

void NetworkStreamProcessor::processData(const std::string& data) {
    std::lock_guard<std::mutex> lock(queue_mutex);
    data_queue.push(data);
    cv.notify_one();
}

void NetworkStreamProcessor::thread_function() {
    while (running) {
        std::unique_lock<std::mutex> lock(queue_mutex);
        cv.wait(lock, [this] { return !data_queue.empty() || !running; });

        if (!running && data_queue.empty()) {
            break;
        }

        std::string data = data_queue.front();
        data_queue.pop();
        lock.unlock();

        // Process data
    }
}

// Main.cpp
#include "NetworkStreamProcessor.h"

int main() {
    NetworkStreamProcessor processor(8080, "127.0.0.1");
    processor.start();

    std::string data = "Sample data";
    processor.processData(data);

    processor.stop();
    return 0;
}
