#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <cmath>

class DataAggregator {
public:
    void AddDataPoint(const double value, const long timestamp) {
        std::unique_lock<std::mutex> lock(mutex_);
        data_points_.push({value, timestamp});
        cv_.notify_one();
    }

    double GetAverageValue() {
        std::lock_guard<std::mutex> lock(mutex_);
        return average_value_;
    }

    double GetHighestWeightedAverage() {
        std::lock_guard<std::mutex> lock(mutex_);
        return highest_weighted_average_;
    }

private:
    struct DataPoint {
        double value;
        long timestamp;
    };

    std::queue<DataPoint> data_points_;
    std::mutex mutex_;
    std::condition_variable cv_;
    double average_value_ = 0.0;
    double highest_weighted_average_ = 0.0;

    void ProcessData() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !data_points_.empty(); });

            DataPoint point = data_points_.front();
            data_points_.pop();

            // Calculate weighted average
            double weighted_average = point.value * point.timestamp;
            if (weighted_average > highest_weighted_average_) {
                highest_weighted_average_ = weighted_average;
            }

            // Update average value
            average_value_ += point.value / 50000.0;

            lock.unlock();
        }
    }

    std::thread worker_thread_;
};

int main() {
    DataAggregator aggregator;
    aggregator.worker_thread_ = std::thread(&DataAggregator::ProcessData, &aggregator);

    // Simulate adding data points
    for (long i = 1; i <= 50000; ++i) {
        aggregator.AddDataPoint(static_cast<double>(i), i);
        std::this_thread::sleep_for(std::chrono::microseconds(20));
    }

    aggregator.worker_thread_.join();

    std::cout << "Average Value: " << aggregator.GetAverageValue() << std::endl;
    std::cout << "Highest Weighted Average: " << aggregator.GetHighestWeightedAverage() << std::endl;

    return 0;
}
