        return -1;
    }
    // Additional processing to resize and convert the image
    avformat_close_input(&fmt_ctx);
    return 0;
}

void process_image_batch(const char** input_paths, int num_paths, const char* output_dir, Config config) {
    for (int i = 0; i < num_paths; i++) {
