        if (!_sites.TryAdd(siteId, new Site(siteId, path)))
        {
            throw new InvalidOperationException("Site already exists.");
        }

        var config = await GetConfigFromService(siteId);
        ApplyConfig(siteId, config);

        // Start monitoring the site
