class CDN:
    def __init__(self):
        self.edge_locations = {}
        self.caching_policy = {}
        self.load_balancer = LoadBalancer()
        self.security_module = SecurityModule()
        self.analytics_system = AnalyticsSystem()

    def add_edge_location(self, location_id, server):
        self.edge_locations[location_id] = server

    def update_caching_policy(self, content_type, policy):
        self.caching_policy[content_type] = policy

    def handle_request(self, request):
        if request.is_dynamic:
            response = self.process_dynamic_content(request)
        else:
            response = self.retrieve_cached_content(request)

        self.analytics_system.log_response_time(response.time_taken)
        return response

    def process_dynamic_content(self, request):
        result = self.load_balancer.distribute_request(request)
        if result.success:
            processed_data = self.edge_locations[result.server_id].process_content(result.data)
            self.update_cache(request.content_type, processed_data)
            return Response(processed_data, time_taken=result.time_taken)
        else:
            return Response(None, time_taken=0, success=False)

    def retrieve_cached_content(self, request):
        if self.is_content_cached(request.content_type, request.key):
            cached_data = self.edge_locations[self.get_cached_location(request.content_type)].retrieve_cache(request.key)
            return Response(cached_data, time_taken=self.caching_policy[request.content_type]['time_to_live'])
        else:
            return self.process_dynamic_content(request)

    def update_cache(self, content_type, data):
        for location in self.edge_locations.values():
            location.store_cache(content_type, data)

    def is_content_cached(self, content_type, key):
