using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Distributed;
using Microsoft.Extensions.Logging;
using Polly;

public interface IHashService
{
    Task<string> ComputeHashAsync(string input, string algorithm = "MD5");
}

public class HashService : IHashService
{
    private readonly ILogger<HashService> _logger;
    private readonly IDistributedCache _cache;
    private readonly HttpClient _httpClient;
    private readonly AsyncRetryPolicy _retryPolicy;

    public HashService(ILogger<HashService> logger, IDistributedCache cache, HttpClient httpClient)
    {
        _logger = logger;
        _cache = cache;
        _httpClient = httpClient;

        _retryPolicy = Policy
            .Handle<HttpRequestException>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));
    }

    public async Task<string> ComputeHashAsync(string input, string algorithm = "MD5")
    {
        if (string.IsNullOrEmpty(input))
            throw new ArgumentException("Input cannot be null or empty");

        var hashAlgorithm = GetHashAlgorithm(algorithm);

        return await _retryPolicy.ExecuteAsync(async () =>
        {
            try
            {
                // Compute hash synchronously for demonstration purposes
                using (var md5 = hashAlgorithm.Create())
                {
                    var hashBytes = md5.ComputeHash(System.Text.Encoding.UTF8.GetBytes(input));
                    return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error computing hash");
                throw;
            }
        });
    }

    private HashAlgorithm GetHashAlgorithm(string algorithm)
    {
        switch (algorithm.ToUpper())
        {
            case "SHA-256":
                return SHA256.Create();
            default:
                return MD5.Create();
        }
    }
}

public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        services.AddLogging(loggingBuilder =>
        {
            loggingBuilder.ClearProviders();
            loggingBuilder.AddConsole();
        });

        services.AddDistributedMemoryCache();

        services.AddScoped<IHashService, HashService>();
        services.AddHttpClient("ExternalLoggingService", client => 
        {
            client.BaseAddress = new Uri("https://example.com/api/");
        })
        .ConfigurePrimaryHttpMessageHandler(() =>
        {
            return new SocketsHttpHandler
            {
                ConnectTimeout = TimeSpan.FromSeconds(5),
                EnableMultipleHttp2Connections = true,
            };
        });
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        if (env.IsDevelopment())
        {
            app.UseDeveloperExceptionPage();
        }

        app.Run(async context =>
        {
            var hashService = context.RequestServices.GetRequiredService<IHashService>();
            var input = context.Request.Query["input"].FirstOrDefault() ?? "default";

            try
            {
                var result = await hashService.ComputeHashAsync(input);
                await context.Response.WriteAsync($"Hash: {result}");
            }
            catch (Exception ex)
            {
                await context.Response.WriteAsync($"Error: {ex.Message}");
            }
        });
    }
}
