from fastapi import FastAPI, HTTPException
import redis
from pydantic import BaseModel
from typing import Dict, Any, Optional

app = FastAPI()
cache = redis.StrictRedis(host='localhost', port=6379, db=0)

class CachePolicy(BaseModel):
    ttl: int
    max_size: int
    eviction_policy: str

class CacheItem(BaseModel):
    key: str
    value: Any
    policy: Optional[CachePolicy] = None

@app.post("/cache/", response_model=CacheItem)
async def set_cache_item(item: CacheItem):
    if item.policy:
        cache.setex(item.key, item.policy.ttl, item.value)
    else:
        cache.set(item.key, item.value)
    return {"key": item.key, "value": item.value, "policy": item.policy}

@app.get("/cache/{key}", response_model=CacheItem)
async def get_cache_item(key: str):
    value = cache.get(key)
    if value is None:
        raise HTTPException(status_code=404, detail="Item not found in cache")
    return {"key": key, "value": value}

@app.put("/cache/{key}", response_model=CacheItem)
async def update_cache_item(key: str, item: CacheItem):
    if item.policy:
        cache.setex(key, item.policy.ttl, item.value)
    else:
        cache.set(key, item.value)
    return {"key": key, "value": item.value, "policy": item.policy}

@app.delete("/cache/{key}")
async def delete_cache_item(key: str):
    if not cache.delete(key):
        raise HTTPException(status_code=404, detail="Item not found in cache")
    return {"key": key, "message": "Item deleted from cache"}
```

