import time

app = Flask(__name__)

# Configuration
CDN_URLS = ["cdn1.example.com", "cdn2.example.com"]
ENCODER_URL = "encoder.example.com"
DECODER_URL = "decoder.example.com"

# Metrics
request_counter = Counter('api_requests_total', 'Total number of API requests')
error_rate = Gauge('error_rate', 'Error rate for API requests')

def log_request(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        request_counter.inc()
        start_time = time.time()
        result = func(*args, **kwargs)
        duration = time.time() - start_time
        logging.info(f"Request {func.__name__} took {duration:.2f} seconds")
        return result
    return wrapper

def rate_limiter(max_requests=100, period=60):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            current_time = time.time()
            # Check recent requests
            for request in recent_requests:
                if current_time - request < period:
                    max_requests -= 1
                    break
            if max_requests <= 0:
                return jsonify({"error": "Rate limit exceeded"}), 429
            result = func(*args, **kwargs)
            recent_requests.append(current_time)
            return result
        recent_requests = []
        return wrapper
    return decorator

@app.route('/stream', methods=['GET'])
@log_request
@rate_limiter()
def stream():
    try:
        # Determine optimal CDN based on user location and network conditions
        optimal_cdn = determine_optimal_cdn(request.args)

        # Request content from the selected CDN
        response = requests.get(f"{optimal_cdn}/{request.args['content_id']}")

        if response.status_code == 200:
            return jsonify({"url": response.json()["stream_url"]})
        else:
            error_rate.inc()
            return jsonify({"error": "Failed to fetch content"}), response.status_code
    except Exception as e:
        error_rate.inc()
        logging.error(f"Error in stream: {e}")
        return jsonify({"error": "Internal server error"}), 500

