// This Java code snippet outlines the architecture of a real-time data processing pipeline
// that integrates with various external data sources using Apache Kafka and Apache Spark.

import org.apache.spark.sql.SparkSession;
import org.apache.spark.streaming.api.java.JavaDStream;
import org.apache.spark.streaming.api.java.JavaInputDStream;
import org.apache.spark.streaming.kafka010.ConsumerStrategies;
import org.apache.spark.streaming.kafka010.KafkaUtils;
import org.apache.spark.streaming.kafka010.LocationStrategies;

public class RealTimeDataProcessingPipeline {

    public static void main(String[] args) {
        // Create a Spark session
        SparkSession spark = SparkSession.builder()
                .appName("RealTimeDataProcessing")
                .master("local[*]")
                .getOrCreate();

        // Set up Kafka parameters
        Map<String, Object> kafkaParams = new HashMap<>();
        kafkaParams.put("bootstrap.servers", "localhost:9092");
        kafkaParams.put("key.deserializer", StringDeserializer.class);
        kafkaParams.put("value.deserializer", StringDeserializer.class);
        kafkaParams.put("group.id", "test-group");
        kafkaParams.put("auto.offset.reset", "latest");
        kafkaParams.put("enable.auto.commit", false);

        // Set up topics to subscribe
        Collection<String> topics = Collections.singletonList("iot-data");

        // Create a direct stream from Kafka
        JavaInputDStream<ConsumerRecord<String, String>> stream =
                KafkaUtils.createDirectStream(
                        spark.sparkContext(),
                        LocationStrategies.PreferConsistent(),
                        ConsumerStrategies.Subscribe(topics, kafkaParams)
                );

        // Process the incoming data
        JavaDStream<String> messages = stream.map(record -> record.value());

        // Perform complex transformations using Spark
        JavaDStream<String> processedData = messages.filter(message -> message.length() > 10)
                                                .mapToPair(message -> new Tuple2<>(message, 1))
                                                .reduceByKey((a, b) -> a + b);

        // Output the results
        processedData.print();

        // Start Spark streaming context
        spark.streamingContext().start();
        spark.streamingContext().awaitTermination();
    }
}
```

