void* handle_dns_request(void* arg) {
    char* hostname = (char*)arg;
    pthread_mutex_lock(&cache_mutex);

    for (int i = 0; i < MAX_HOSTNAMES; i++) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            printf("Resolved %s using cache: TTL=%d\n", hostname, dns_cache[i].ttl);
            pthread_mutex_unlock(&cache_mutex);
            return NULL;
        }
    }

