            dns_cache[i].ttl = ttl;
            strcpy(dns_cache[i].hostname, hostname);
            printf("Resolved %s using provider %d: TTL=%d\n", hostname, i + 1, ttl);
            pthread_mutex_unlock(&cache_mutex);
            return NULL;
        }
    }

    // Handle failure
    fprintf(stderr, "Failed to resolve %s\n", hostname);
    pthread_mutex_unlock(&cache_mutex);
    return NULL;
}

int simulate_dns_resolution(const char* hostname) {
    // Simulate a delay and return a TTL value
    sleep(1); // Simulating network latency
    if (strcmp(hostname, "example.com") == 0) {
        return 3600; // Return a TTL of 1 hour for example.com
    }
    return -1;
}

int main() {
    pthread_t threads[MAX_HOSTNAMES];
    char hostnames[MAX_HOSTNAMES][MAX_HOSTNAMES] = {"example.com", "test.com"};

    for (int i = 0; i < MAX_HOSTNAMES; i++) {
        if (strlen(hostnames[i]) > 0) {
            pthread_create(&threads[i], NULL, handle_dns_request, hostnames[i]);
        }
