                WorkingDirectory = directoryPath,
                RedirectStandardOutput = true,
                UseShellExecute = false,
                CreateNoWindow = true
            };

            Process process = Process.Start(startInfo);
            return process;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to start website: {ex.Message}");
            return null;
        }
    }
}
