#include <stdlib.h>
#include <pthread.h>

typedef struct ChannelQualityIndication {
    int signal_strength;
    int noise_level;
    int interference_level;
} ChannelQualityIndication;

typedef struct FrameMetadata {
    int frame_id;
    long timestamp;
    ChannelQualityIndication *cqis;
    size_t cqis_count;
} FrameMetadata;

typedef struct DoublyLinkedListNode {
    FrameMetadata *data;
    struct DoublyLinkedListNode *next;
    struct DoublyLinkedListNode *prev;
} DoublyLinkedListNode;

typedef struct DoublyLinkedList {
    DoublyLinkedListNode *head;
    DoublyLinkedListNode *tail;
    size_t count;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* doubly_linked_list_create() {
    DoublyLinkedList *list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (list) {
        list->head = list->tail = NULL;
        list->count = 0;
        pthread_mutex_init(&list->lock, NULL);
    }
    return list;
}

void doubly_linked_list_destroy(DoublyLinkedList *list) {
    pthread_mutex_lock(&list->lock);
    while (list->head) {
        DoublyLinkedListNode *node = list->head;
        list->head = node->next;
        free(node->data->cqis);
        free(node->data);
        free(node);
    }
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void doubly_linked_list_insert(DoublyLinkedList *list, FrameMetadata *frame_metadata) {
    pthread_mutex_lock(&list->lock);
    DoublyLinkedListNode *new_node = (DoublyLinkedListNode*)malloc(sizeof(DoublyLinkedListNode));
    if (new_node) {
        new_node->data = frame_metadata;
        new_node->next = NULL;
        new_node->prev = list->tail;

        if (!list->head) {
            list->head = new_node;
        } else {
            list->tail->next = new_node;
        }
        list->tail = new_node;
        list->count++;
    }
    pthread_mutex_unlock(&list->lock);
}

void doubly_linked_list_remove(DoublyLinkedList *list, int frame_id) {
    pthread_mutex_lock(&list->lock);
    DoublyLinkedListNode *current = list->head;
    while (current) {
        if (current->data->frame_id == frame_id) {
            if (current->prev) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current->next) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev;
            }
            free(current->data->cqis);
            free(current->data);
            free(current);
            list->count--;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

size_t doubly_linked_list_count(DoublyLinkedList *list) {
    size_t count = 0;
    pthread_mutex_lock(&list->lock);
    if (list->head) {
        DoublyLinkedListNode *current = list->head;
        do {
            count++;
            current = current->next;
        } while (current != list->head);
    }
    pthread_mutex_unlock(&list->lock);
    return count;
}

// Add more functions as needed for iteration, filtering, and other operations.
