#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <future>
#include <memory>
#include <functional>
#include <stdexcept>
#include <chrono>

class DataPipelineManager {
public:
    using Entry = std::string;
    using TransformFunc = std::function<Entry(const Entry&)>;
    using AggregationFunc = std::function<void(const Entry&)>;

    DataPipelineManager(size_t batchSize = 10, size_t numThreads = 4)
        : batchSize(batchSize), numThreads(numThreads), stop(false) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::queue<Entry> batch;
                    {
                        std::unique_lock<std::mutex> lock(mutex);
                        condition.wait(lock, [this]{ return stop || !tasks.empty(); });
                        if (stop && tasks.empty()) break;
                        for (size_t j = 0; j < batchSize && !tasks.empty(); ++j) {
                            batch.push(std::move(tasks.front()));
                            tasks.pop();
                        }
                    }
                    processBatch(batch);
                }
            });
        }
    }

    ~DataPipelineManager() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void addEntry(const Entry& entry) {
        std::unique_lock<std::mutex> lock(mutex);
        tasks.push(entry);
        condition.notify_one();
    }

    template<typename InputIt>
    void addEntries(InputIt first, InputIt last) {
        std::unique_lock<std::mutex> lock(mutex);
        for (; first != last; ++first) {
            tasks.push(*first);
        }
        condition.notify_all();
    }

    void setTransformPipeline(const std::vector<TransformFunc>& pipeline) {
        transformPipeline = pipeline;
    }

    void setAggregationFunction(const AggregationFunc& func) {
        aggregationFunc = func;
    }

private:
    size_t batchSize;
    size_t numThreads;
    bool stop;
    std::mutex mutex;
    std::condition_variable condition;
    std::queue<Entry> tasks;
    std::vector<std::thread> workers;
    std::vector<TransformFunc> transformPipeline;
    AggregationFunc aggregationFunc;

    void processBatch(const std::queue<Entry>& batch) {
        for (const Entry& entry : batch) {
            Entry transformedEntry = entry;
            for (const auto& transform : transformPipeline) {
                transformedEntry = transform(transformedEntry);
            }
            aggregationFunc(transformedEntry);
        }
    }
};
