// Define a class for managing multiple data sources and sinks
class DataPipeline {
private:
    std::vector<std::unique_ptr<DataProcessorBase>> processors;
    std::queue<DataEvent> eventQueue;
    std::mutex queueMutex;
    std::condition_variable queueCondVar;
    bool stopProcessing;

public:
    DataPipeline() : stopProcessing(false) {}

    void addProcessor(std::unique_ptr<DataProcessorBase> processor) {
        processors.push_back(std::move(processor));
    }

    void enqueueEvent(const DataEvent& event) {
        std::lock_guard<std::mutex> lock(queueMutex);
        eventQueue.push(event);
        queueCondVar.notify_one();
    }

    void startProcessing() {
        for (size_t i = 0; i < processors.size(); ++i) {
            std::thread([this, i]() {
                while (!stopProcessing) {
                    DataEvent event;
                    {
                        std::unique_lock<std::mutex> lock(queueMutex);
                        queueCondVar.wait(lock, [this]{ return !eventQueue.empty() || stopProcessing; });
                        if (stopProcessing && eventQueue.empty()) break;
                        event = eventQueue.front();
                        eventQueue.pop();
                    }
                    processors[i]->process(event.data);
                }
            }).detach();
        }
    }

    void stop() {
        stopProcessing = true;
        queueCondVar.notify_all();
    }
};

