import java.security.NoSuchAlgorithmException;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;

public class SecureStringProcessor {
    private final ExecutorService executorService;
    private final HashingStrategy hashingStrategy;
    private final String apiEndpoint;

    public SecureStringProcessor(int maxThreads, String apiEndpoint) {
        this.executorService = Executors.newFixedThreadPool(maxThreads);
        this.hashingStrategy = new ApiHashingStrategy(apiEndpoint);
        this.apiEndpoint = apiEndpoint;
    }

    public List<String> processBatch(List<String> inputStrings) throws InterruptedException, ExecutionException {
        return CompletableFuture.allOf(inputStrings.stream()
                .map(this::processString)
                .toArray(CompletableFuture[]::new))
                .thenApply(v -> inputStrings.stream().map(this::getHashResult).collect(Collectors.toList()))
                .get();
    }

    private String processString(String input) {
        return executorService.submit(() -> {
            try {
                String hash = hashingStrategy.computeHash(input);
                saveToCache(input, hash);
                return hash;
            } catch (Exception e) {
                logError(e);
                return computeLocalHash(input); // Fallback to local hash computation
            }
        }).join();
    }

    private String getHashResult(String input) {
        return cachingStrategy.getHash(input).orElseCompute(() -> processString(input));
    }

    private void saveToCache(String input, String hash) {
        cachingStrategy.putHash(input, hash);
    }

    private String computeLocalHash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Hash algorithm not supported", e);
        }
    }

    public void shutdown() throws InterruptedException {
        executorService.shutdown();
        if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
            executorService.shutdownNow();
        }
    }

    private void logError(Exception e) {
        // Implement logging logic here
    }
}

interface HashingStrategy {
    String computeHash(String input) throws Exception;
}

class ApiHashingStrategy implements HashingStrategy {
    private final String apiEndpoint;

    public ApiHashingStrategy(String apiEndpoint) {
        this.apiEndpoint = apiEndpoint;
    }

    @Override
    public String computeHash(String input) throws IOException, InterruptedException {
        // Implement API call to compute hash here
        return "api_hash_result";
    }
}

interface CachingStrategy {
    void putHash(String key, String value);
    String getHash(String key);
}

class CacheCachingStrategy implements CachingStrategy {
    private final java.util.Map<String, String> cache = new java.util.concurrent.ConcurrentHashMap<>();

    @Override
    public void putHash(String key, String value) {
        cache.put(key, value);
    }

    @Override
    public String getHash(String key) {
        return cache.get(key);
    }
}
