#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct ChannelQualityIndication {
    int signal_strength;
    int noise_level;
    int interference_level;
} ChannelQualityIndication;

typedef struct FrameMetadata {
    int frame_id;
    long timestamp;
    ChannelQualityIndication* channel_indications;
    int num_channel_indications;
    struct FrameMetadata* prev;
    struct FrameMetadata* next;
} FrameMetadata;

typedef struct DoublyLinkedList {
    FrameMetadata* head;
    FrameMetadata* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* create_doubly_linked_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insert_frame_metadata(DoublyLinkedList* list, FrameMetadata* frame) {
    pthread_mutex_lock(&list->lock);
    if (list->tail == NULL) {
        list->head = list->tail = frame;
        frame->prev = frame->next = NULL;
    } else {
        list->tail->next = frame;
        frame->prev = list->tail;
        list->tail = frame;
        frame->next = NULL;
    }
    pthread_mutex_unlock(&list->lock);
}

void delete_frame_metadata(DoublyLinkedList* list, FrameMetadata* frame) {
    pthread_mutex_lock(&list->lock);
    if (frame == list->head) {
        list->head = frame->next;
        if (frame->next) frame->next->prev = NULL;
    } else if (frame == list->tail) {
        list->tail = frame->prev;
        if (frame->prev) frame->prev->next = NULL;
    } else {
        frame->prev->next = frame->next;
        frame->next->prev = frame->prev;
    }
    free(frame);
    pthread_mutex_unlock(&list->lock);
}

void destroy_doubly_linked_list(DoublyLinkedList* list) {
    FrameMetadata* current = list->head;
    while (current != NULL) {
        FrameMetadata* next = current->next;
        delete_frame_metadata(list, current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
