        if self.provider == 'aws':
            self.client.upload_file(file_path, bucket_name, file_path.split('/')[-1])
        elif self.provider == 'gcp':
            bucket = self.client.bucket(bucket_name)
            blob = bucket.blob(file_path.split('/')[-1])
            blob.upload_from_filename(file_path)
        elif self.provider == 'azure':
            container_client = self.client.get_container_client("<your-container-name>")
            blob_client = container_client.get_blob_client(file_path.split('/')[-1])
            with open(file_path, "rb") as data:
                blob_client.upload_blob(data)

    def list_buckets(self):
        if self.provider == 'aws':
            return [bucket['Name'] for bucket in self.client.list_buckets()]
        elif self.provider == 'gcp':
            buckets = self.client.list_buckets()
            return [bucket.name for bucket in buckets]
