import threading
import queue
import time
import random

class DynamicImageProcessor:
    def __init__(self):
        self.image_queue = queue.Queue()
        self.resource_pool = []
        self.lock = threading.Lock()

    def add_image(self, image_data, priority=1):
        # Add image to the queue with a priority level
        self.image_queue.put((priority, image_data))

    def allocate_resource(self):
        # Allocate a resource from the pool if available
        with self.lock:
            if self.resource_pool:
                return self.resource_pool.pop()
            else:
                return None

    def release_resource(self, resource):
        # Release a resource back to the pool
        with self.lock:
            self.resource_pool.append(resource)

    def process_images(self):
        while True:
            if not self.image_queue.empty():
                priority, image_data = self.image_queue.get()
                resource = self.allocate_resource()
                if resource is not None:
                    # Simulate image processing
                    time.sleep(random.uniform(0.1, 1.0))
                    print(f"Processed image with priority {priority}")
                    self.release_resource(resource)
            else:
                time.sleep(0.1)

    def start_processing(self):
        # Start the image processing thread
        processor_thread = threading.Thread(target=self.process_images)
        processor_thread.daemon = True
        processor_thread.start()

# Example usage
processor = DynamicImageProcessor()
processor.start_processing()

for i in range(5):
    processor.add_image(f"image_{i}.jpg", priority=i % 3 + 1)

