// This code block represents a high-level structure for an encryption library in C.
// It is designed to be modular, extensible, and performant.

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <pthread.h>

typedef enum {
    SHA256,
    ARGON2
} HashAlgorithm;

typedef struct {
    char *password;
    int iterationCount;
    HashAlgorithm hashAlgorithm;
} PBKDF2Config;

typedef struct {
    unsigned char iv[16];
} IVGenerator;

typedef struct {
    // Key management data structure
} EncryptionKey;

// Function to derive a key using PBKDF2
void deriveKey(PBKDF2Config config, const char *salt, unsigned char *key) {
    switch (config.hashAlgorithm) {
        case SHA256:
            PKCS5_PBKDF2_HMAC(config.password, strlen(config.password), salt,
                               16, config.iterationCount, EVP_sha256(), 32, key);
            break;
        case ARGON2:
            // Argon2 implementation would go here
            break;
    }
}

// Function to generate a secure IV
void generateIV(IVGenerator *generator) {
    RAND_bytes(generator->iv, sizeof(generator->iv));
}

// Function for cryptographic operations (encryption/decryption)
int encryptData(const unsigned char *data, size_t dataLen,
                const unsigned char *key, const unsigned char *iv,
                unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &dataLen, data, dataLen)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int final_len = 0;
    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + dataLen, &final_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    ciphertext[dataLen + final_len] = '\0';
    EVP_CIPHER_CTX_free(ctx);

    return dataLen + final_len;
}

// Function for key management
EncryptionKey *createKey(const char *password) {
    EncryptionKey *key = malloc(sizeof(EncryptionKey));
    if (!key) return NULL;

    PBKDF2Config config = { password, 100000, SHA256 };
    deriveKey(config, "salt", key->derivedKey);

    IVGenerator generator;
    generateIV(&generator);
    memcpy(key->iv, generator.iv, sizeof(generator.iv));

    return key;
}

// Function for encrypting a file
int encryptFile(const char *inputFilename, const char *outputFilename,
                EncryptionKey *key) {
    FILE *in = fopen(inputFilename, "rb");
    if (!in) return -1;

    FILE *out = fopen(outputFilename, "wb");
    if (!out) {
        fclose(in);
        return -1;
    }

    unsigned char buffer[4096];
    size_t bytesRead;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), in)) > 0) {
        encryptData(buffer, bytesRead, key->derivedKey, key->iv, buffer);
        fwrite(buffer, 1, bytesRead, out);
    }

    fclose(in);
    fclose(out);

    return 0;
}

int main() {
    EncryptionKey *key = createKey("myPassword");
    if (!key) {
        fprintf(stderr, "Failed to create encryption key.\n");
        return -1;
    }

    int result = encryptFile("input.txt", "output.enc", key);
    if (result != 0) {
        fprintf(stderr, "Failed to encrypt file.\n");
        free(key);
        return -1;
    }

    free(key);
    return 0;
}
```

