    void add(const std::string& key, const std::string& value, std::time_t ttl, int version);
    bool get(const std::string& key, Entry& entry);
    void remove(const std::string& key);

private:
    std::unordered_map<std::string, Entry> cache;
    std::mutex cacheMutex;

    void evictLeastFrequent();
};

void DistributedCache::add(const std::string& key, const std::string& value, std::time_t ttl, int version) {
    std::lock_guard<std::mutex> lock(cacheMutex);
    Entry entry = {value, std::chrono::system_clock::to_time_t(std::chrono::system_clock::now() + std::chrono::seconds(ttl)), version};
    cache[key] = entry;
}

bool DistributedCache::get(const std::string& key, Entry& entry) {
    std::lock_guard<std::mutex> lock(cacheMutex);
    auto it = cache.find(key);
    if (it != cache.end()) {
        if (std::chrono::system_clock::to_time_t(std::chrono::system_clock::now()) < it->second.expiration) {
            entry = it->second;
            return true;
        } else {
            cache.erase(it);
        }
    }
    return false;
}

void DistributedCache::remove(const std::string& key) {
    std::lock_guard<std::mutex> lock(cacheMutex);
    cache.erase(key);
}

