#include <iostream>
#include <unordered_map>
#include <thread>
#include <atomic>

class CacheNode {
public:
    std::string key;
    std::string value;
    size_t version;
    size_t transactionId;
    time_t expirationTime;

    CacheNode(const std::string& k, const std::string& v)
        : key(k), value(v), version(0), transactionId(0), expirationTime(time(nullptr)) {}

    bool isExpired() const {
        return time(nullptr) > expirationTime;
    }
};

class DistributedCacheSystem {
private:
    std::unordered_map<std::string, CacheNode> cache;
    std::atomic<size_t> globalVersion;

public:
    void put(const std::string& key, const std::string& value, size_t transactionId, time_t expirationTime) {
        cache[key] = CacheNode(key, value);
        cache[key].version++;
        cache[key].transactionId = transactionId;
        cache[key].expirationTime = expirationTime;
    }

    bool get(const std::string& key, std::string& value, size_t& version, size_t& transactionId) const {
        auto it = cache.find(key);
        if (it != cache.end() && !it->second.isExpired()) {
            value = it->second.value;
            version = it->second.version;
            transactionId = it->second.transactionId;
            return true;
        }
        return false;
    }

    bool update(const std::string& key, const std::string& newValue, size_t currentVersion, size_t transactionId) {
        auto it = cache.find(key);
        if (it != cache.end() && !it->second.isExpired() && it->second.version == currentVersion) {
            it->second.value = newValue;
            it->second.version++;
            it->second.transactionId = transactionId;
            return true;
        }
        return false;
    }

    void remove(const std::string& key, size_t currentVersion, size_t transactionId) {
        auto it = cache.find(key);
        if (it != cache.end() && !it->second.isExpired() && it->second.version == currentVersion) {
            cache.erase(it);
        }
    }
};

int main() {
    DistributedCacheSystem cache;
    std::string value;
    size_t version, transactionId;

    cache.put("key1", "value1", 1, time(nullptr) + 60); // key1: value1, expire in 60 seconds

    if (cache.get("key1", value, version, transactionId)) {
        std::cout << "Got value: " << value << ", version: " << version << ", transactionId: " << transactionId << std::endl;
    }

    cache.update("key1", "value2", 1, 2); // Update key1 to value2, version should be 2

    if (cache.get("key1", value, version, transactionId)) {
        std::cout << "Updated value: " << value << ", version: " << version << ", transactionId: " << transactionId << std::endl;
    }

    cache.remove("key1", 2, 3); // Remove key1

    if (!cache.get("key1", value, version, transactionId)) {
        std::cout << "Key removed successfully" << std::endl;
    }

    return 0;
}
