#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_NODES 1000
#define MAX_EDGES 5000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Edge {
    int src, dest;
    int latency, bandwidth;
    sem_t lock;
} Edge;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    int numEdges;
    Edge *edges[MAX_EDGES];
    sem_t lock;
} Node;

Node graph[MAX_NODES];
pthread_mutex_t global_lock;

void init_graph() {
    for (int i = 0; i < MAX_NODES; i++) {
        pthread_mutex_init(&graph[i].lock, NULL);
        graph[i].numEdges = 0;
    }
    pthread_mutex_init(&global_lock, NULL);
}

void add_node(int node_id, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&global_lock);
    graph[node_id].data = data;
    pthread_mutex_unlock(&global_lock);
}

void add_edge(int src, int dest, int latency, int bandwidth) {
    sem_init(&graph[src].edges[graph[src].numEdges]->lock, 0, 1);
    sem_wait(&graph[src].edges[graph[src].numEdges]->lock);
    graph[src].edges[graph[src].numEdges]->src = src;
    graph[src].edges[graph[src].numEdges]->dest = dest;
    graph[src].edges[graph[src].numEdges]->latency = latency;
    graph[src].edges[graph[src].numEdges]->bandwidth = bandwidth;
    sem_post(&graph[src].edges[graph[src].numEdges]->lock);
    graph[src].numEdges++;
}

void *process_data(void *arg) {
    int node_id = *(int *)arg;
    NFAPI_CRC_INDICATION_PDU_T data = {rand() % 100, rand() % 100, rand() % 100, rand() % 2};
    add_node(node_id, data);
    for (int i = 0; i < MAX_EDGES / MAX_NODES; i++) {
        add_edge(node_id, node_id + i % (MAX_NODES - 1), rand() % 100, rand() % 100);
    }
    free(arg);
    return NULL;
}

int main() {
    init_graph();
    pthread_t threads[MAX_NODES];
    for (int i = 0; i < MAX_NODES; i++) {
        int *arg = malloc(sizeof(int));
        *arg = i;
        pthread_create(&threads[i], NULL, process_data, arg);
    }
    for (int i = 0; i < MAX_NODES; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}
