#define N 1000 // Number of structures to manage

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint64_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *pdu_list[N];

pthread_mutex_t pdu_list_lock = PTHREAD_MUTEX_INITIALIZER;

void generate_random_data(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = (uint64_t)(rand() << 32) | rand();
    pdu->CRC_INDICATION_REL8_TAG = (rand() % 2);
}

void* manage_pdu_list(void *arg) {
    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&pdu_list_lock);
        if (pdu_list[i] == NULL) {
            pdu_list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            generate_random_data(pdu_list[i]);
        }
        pthread_mutex_unlock(&pdu_list_lock);
    }
    return NULL;
}

int main() {
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, manage_pdu_list, NULL);
    }
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up allocated memory
    for (int i = 0; i < N; i++) {
        if (pdu_list[i] != NULL) {
            free(pdu_list[i]);
        }
    }

    return 0;
}
