// This code snippet is a simplified example of how you might start designing a modular C++ library for integrating with a cloud-based object storage service.
#include <iostream>
#include <string>
#include <vector>
#include <memory>

// Define an interface for the storage service
class StorageService {
public:
    virtual ~StorageService() {}
    virtual void upload(const std::string& data, const std::string& key) = 0;
    virtual std::string download(const std::string& key) = 0;
    virtual void transformData(const std::string& key, const std::function<std::string(std::string)>& transformer) = 0;
};

// Implement a concrete storage service using an in-memory data structure
class InMemoryStorage : public StorageService {
public:
    void upload(const std::string& data, const std::string& key) override {
        // Simulate uploading data to memory
        storage[key] = data;
    }

    std::string download(const std::string& key) override {
        // Simulate downloading data from memory
        auto it = storage.find(key);
        if (it != storage.end()) return it->second;
        throw std::runtime_error("Key not found");
    }

    void transformData(const std::string& key, const std::function<std::string(std::string)>& transformer) override {
        // Simulate transforming data
        auto it = storage.find(key);
        if (it != storage.end()) it->second = transformer(it->second);
    }

private:
    std::unordered_map<std::string, std::string> storage;
};

// Define a class for handling RESTful API operations
class DataPipelineAPI {
public:
    DataPipelineAPI(std::shared_ptr<StorageService> storage) : storage(storage) {}

    void uploadData(const std::string& data, const std::string& key) {
        storage->upload(data, key);
    }

    std::string downloadData(const std::string& key) {
        return storage->download(key);
    }

private:
    std::shared_ptr<StorageService> storage;
};

// Example usage
int main() {
    auto storage = std::make_shared<InMemoryStorage>();
    DataPipelineAPI api(storage);

    api.uploadData("{\"name\":\"John\", \"age\":30}", "user1");
    std::cout << api.downloadData("user1") << std::endl;

    return 0;
}
