#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Graph node structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* neighbors[10]; // Maximum 10 neighbors for simplicity
    int neighborCount;
    pthread_mutex_t mutex;
} Node;

// Edge structure to store latency and bandwidth
typedef struct Edge {
    float latency;
    float bandwidth;
} Edge;

// Graph structure
typedef struct Graph {
    Node** nodes;
    int nodeCount;
    pthread_mutex_t graphMutex;
} Graph;

// Function to create a new graph node
Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->neighborCount = 0;
    for (int i = 0; i < 10; i++) {
        newNode->neighbors[i] = NULL;
    }
    pthread_mutex_init(&newNode->mutex, NULL);
    return newNode;
}

// Function to add an edge between two nodes
void addEdge(Graph* graph, Node* node1, Node* node2, float latency, float bandwidth) {
    pthread_mutex_lock(&node1->mutex);
    pthread_mutex_lock(&node2->mutex);

    if (node1->neighborCount < 10) {
        node1->neighbors[node1->neighborCount++] = node2;
    }

    Edge* edge = (Edge*)malloc(sizeof(Edge));
    edge->latency = latency;
    edge->bandwidth = bandwidth;

    pthread_mutex_unlock(&node1->mutex);
    pthread_mutex_unlock(&node2->mutex);
}

// Function to initialize a new graph
Graph* createGraph() {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    graph->nodes = (Node**)malloc(10 * sizeof(Node*)); // Maximum 10 nodes for simplicity
    graph->nodeCount = 0;
    pthread_mutex_init(&graph->graphMutex, NULL);
    return graph;
}

// Function to add a node to the graph
void addNode(Graph* graph, Node* newNode) {
    pthread_mutex_lock(&graph->graphMutex);

    if (graph->nodeCount < 10) {
        graph->nodes[graph->nodeCount++] = newNode;
    }

    pthread_mutex_unlock(&graph->graphMutex);
}

// Function to simulate data ingestion
void* ingestData(void* arg) {
    Graph* graph = (Graph*)arg;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    // Simulate data generation and add nodes
    for (int i = 0; i < 5; i++) {
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand();
        pdu.CRC_INDICATION_REL8_TAG = rand();
        pdu.CRCFLAG = rand();
        Node* newNode = createNode(pdu);
        addNode(graph, newNode);
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    Graph* graph = createGraph();

    pthread_t dataIngestThread;
    if (pthread_create(&dataIngestThread, NULL, ingestData, (void*)graph) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    pthread_join(dataIngestThread, NULL);

    // Simulate adding edges between nodes
    Node* node1 = graph->nodes[0];
    Node* node2 = graph->nodes[1];
    addEdge(graph, node1, node2, 0.5, 100);

    return EXIT_SUCCESS;
}
```

