// string_trunc.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char *log_buffer;
    size_t log_size;
    FILE *external_log;
} LogService;

char* truncate_string(const char* input, size_t limit, LogService* log_service) {
    if (input == NULL || log_service == NULL) return NULL;
    size_t len = strlen(input);
    if (len <= limit) {
        char* result = malloc(len + 1);
        strcpy(result, input);
        return result;
    } else if (limit > 0 && limit < len) {
        char* truncated = malloc(limit + 2); // Space for '/' and null terminator
        strncpy(truncated, input, limit);
        truncated[limit] = '/';
        truncated[limit + 1] = '\0';

        // Log truncation if necessary
        if (log_service->external_log) {
            time_t current_time;
            time(&current_time);
            fprintf(log_service->external_log, "%s - Truncated string: %s\n", ctime(&current_time), input);
            fflush(log_service->external_log);
        }

        return truncated;
    }
    return NULL;
}

int log_external(LogService* service, const char* message, int level) {
    if (service == NULL || service->external_log == NULL) return -1;

    // Implement OAuth2 authentication and exponential backoff here
    // ...

    return 0; // Success
}

void initialize_logger(LogService* service, size_t buffer_size, const char* log_file_path) {
    service->log_buffer = malloc(buffer_size);
    service->log_size = buffer_size;
    service->external_log = fopen(log_file_path, "a");
    if (service->external_log == NULL) {
        perror("Failed to open external log file");
        exit(EXIT_FAILURE);
    }
}

void cleanup_logger(LogService* service) {
    if (service->log_buffer) free(service->log_buffer);
    if (service->external_log) fclose(service->external_log);
}
