    private readonly HttpClient _httpClient;
    private readonly Dictionary<string, ValidationRule> _validationRulesCache = new Dictionary<string, ValidationRule>();
    private int _errorCount;
    private const int ErrorThreshold = 10; // Trigger alert after X consecutive errors

    public DynamicOAuth2TokenValidator(HttpClient httpClient)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
    }

    public async Task<bool> ValidateTokenAsync(string token)
    {
        var rules = await FetchValidationRulesAsync();
        if (rules == null) return false;

        foreach (var rule in rules)
        {
            switch (rule.RuleType)
            {
                case "RangeCheck":
                    if (!IsWithinRange(rule, token)) return false;
                    break;
                // Add more rule types as needed
            }
        }

        return true;
    }

    private async Task<List<ValidationRule>> FetchValidationRulesAsync()
    {
        try
        {
            var response = await _httpClient.GetAsync("/api/validation-rules");
            if (response.IsSuccessStatusCode)
            {
                return await response.Content.ReadAsAsync<List<ValidationRule>>();
            }
            else
            {
                LogError("Failed to fetch validation rules.");
                return null;
            }
        }
        catch (HttpRequestException ex)
        {
            LogError($"Network error: {ex.Message}");
            return null;
        }
    }

    private bool IsWithinRange(ValidationRule rule, string tokenValue)
    {
        if (!double.TryParse(tokenValue, out var value)) return false;

        switch (rule.Inclusive)
        {
            case true:
                return value >= rule.Min && value <= rule.Max;
            case false:
                return value > rule.Min && value < rule.Max;
            default:
                throw new InvalidOperationException("Inclusive flag must be set.");
        }
    }

    private void LogError(string message)
    {
        // Implement logging logic here
        Console.WriteLine($"ERROR: {message}");
    }
}

public class ValidationRule
{
    public string RuleType { get; set; }
    public double Min { get; set; }
    public double Max { get; set; }
    public bool Inclusive { get; set; }

    // Add more properties as needed
}
