        // Simulated versioning conflict
        if (id == "conflict") throw std::runtime_error("Versioning conflict");

        std::cout << "Resource updated successfully with ID: " << id << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error updating resource: " << e.what() << std::endl;
    }
