# Python Service for Real-Time Data Replication

import boto3
from google.cloud import storage
from azure.storage.blob import BlobServiceClient

class DataService:
    def __init__(self):
        self.s3_client = boto3.client('s3')
        self.gcs_client = storage.Client()
        self.azure_blob_service = BlobServiceClient.from_connection_string('your_azure_connection_string')

    def replicate_data(self, source_provider, source_bucket, destination_provider, destination_bucket, object_key):
        if source_provider == 'aws':
            data = self.s3_client.get_object(Bucket=source_bucket, Key=object_key)['Body'].read()
        elif source_provider == 'gcs':
            bucket = self.gcs_client.bucket(source_bucket)
            blob = bucket.blob(object_key)
            data = blob.download_as_bytes()
        elif source_provider == 'azure':
            container_name = object_key.split('/')[0]
            blob_name = '/'.join(object_key.split('/')[1:])
            blob_client = self.azure_blob_service.get_blob_client(container=container_name, blob=blob_name)
            data = blob_client.download_blob().readall()

        if destination_provider == 'aws':
            self.s3_client.put_object(Bucket=destination_bucket, Key=object_key, Body=data)
        elif destination_provider == 'gcs':
            bucket = self.gcs_client.bucket(destination_bucket)
            blob = bucket.blob(object_key)
            blob.upload_from_string(data)
        elif destination_provider == 'azure':
            container_name = object_key.split('/')[0]
            blob_name = '/'.join(object_key.split('/')[1:])
            blob_client = self.azure_blob_service.get_blob_client(container=container_name, blob=blob_name)
            blob_client.upload_blob(data)

