#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <future>
#include <chrono>
#include <cmath>
#include <zlib.h>

struct DataPacket {
    std::chrono::time_point<std::chrono::system_clock> timestamp;
    int packetID;
    std::string payload;
};

class PacketManager {
private:
    std::vector<DataPacket*> packets;
    std::mutex mtx;
    std::condition_variable cv;
    int maxRetries;

public:
    PacketManager(int retries) : maxRetries(retries) {}

    void insertPacket(DataPacket* packet) {
        std::lock_guard<std::mutex> lock(mtx);
        packets.push_back(packet);
        cv.notify_one();
    }

    DataPacket* retrievePacket() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return !packets.empty(); });
        DataPacket* packet = packets.front();
        packets.erase(packets.begin());
        return packet;
    }

    void deletePacket(DataPacket* packet) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = std::find(packets.begin(), packets.end(), packet);
        if (it != packets.end()) {
            packets.erase(it);
        }
    }

    int getPacketCount() {
        std::lock_guard<std::mutex> lock(mtx);
        return packets.size();
    }
};

class ExternalAPIClient {
private:
    int maxRetries;

public:
    ExternalAPIClient(int retries) : maxRetries(retries) {}

    void sendPacket(DataPacket* packet, std::function<void()> callback) {
        // Simulate unreliable external API call
        bool success = false;
        for (int i = 0; i <= maxRetries; ++i) {
            try {
                // Simulate network error
                if (i % 2 == 0 && packet->payload.size() > 1000) {
                    throw std::runtime_error("Network timeout");
                }
                success = true;
                break;
            } catch (...) {
                if (i == maxRetries) {
                    callback();
                    return;
                }
                std::this_thread::sleep_for(std::chrono::milliseconds(static_cast<int>(pow(2, i) * 100)));
            }
        }
        if (success) {
            // Process packet
        } else {
            callback();
        }
    }
};

class PacketProcessor {
private:
    PacketManager& pm;
    ExternalAPIClient& apiClient;
    std::thread workerThread;
    bool running;

public:
    PacketProcessor(PacketManager& pm, ExternalAPIClient& apiClient)
        : pm(pm), apiClient(apiClient), running(false) {}

    void start() {
        running = true;
        workerThread = std::thread([this] { processPackets(); });
    }

    void stop() {
        running = false;
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }

private:
    void processPackets() {
        while (running) {
            DataPacket* packet = pm.retrievePacket();
            if (packet != nullptr) {
                apiClient.sendPacket(packet, [this, packet] {
                    deletePacket(packet);
                });
            } else {
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            }
        }
    }

    void deletePacket(DataPacket* packet) {
        pm.deletePacket(packet);
        delete packet;
    }
};

int main() {
    PacketManager pm(5);
    ExternalAPIClient apiClient(3);

    PacketProcessor processor(pm, apiClient);
    processor.start();

    // Simulate inserting packets
    for (int i = 0; i < 10000; ++i) {
        DataPacket* packet = new DataPacket{std::chrono::system_clock::now(), i, "Payload" + std::to_string(i)};
        pm.insertPacket(packet);
    }

    processor.stop();

    return 0;
}
