#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <pthread.h>
#include <jansson.h>

#define MAX_THREADS 10

typedef struct {
    char *filename;
    pthread_mutex_t *mutex;
} FileData;

void *process_file(void *arg) {
    FileData *data = (FileData *)arg;
    FILE *file = fopen(data->filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    json_error_t error;
    json_t *root = json_loadf(file, 0, &error);
    fclose(file);

    if (root == NULL) {
        fprintf(stderr, "Error parsing JSON from %s: on line %d, column %d\n", data->filename, error.line, error.column);
        return NULL;
    }

    // Validate JSON object
    json_t *access_token = json_object_get(root, "access_token");
    json_t *expires_in = json_object_get(root, "expires_in");
    json_t *token_type = json_object_get(root, "token_type");

    if (!json_is_string(access_token) || !json_is_integer(expires_in) || !json_is_string(token_type)) {
        fprintf(stderr, "Invalid JSON format in %s\n", data->filename);
        json_decref(root);
        return NULL;
    }

    int expires_value = (int)json_integer_value(expires_in);
    if (expires_value <= 0 || strcmp(json_string_value(token_type), "Bearer") != 0) {
        fprintf(stderr, "Token validation failed in %s\n", data->filename);
        json_decref(root);
        return NULL;
    }

    // Process valid token
    FILE *output = fopen("valid_tokens.csv", "a");
    if (output == NULL) {
        perror("Failed to open output file");
        json_decref(root);
        return NULL;
    }

    fprintf(output, "%s,%d,Bearer\n", json_string_value(access_token), expires_value);
    fclose(output);

    json_decref(root);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s -i <input_directory> -o <output_file>\n", argv[0]);
        return 1;
    }

    DIR *dir = opendir(argv[2]);
    if (!dir) {
        perror("Failed to open directory");
        return 1;
    }

    pthread_t threads[MAX_THREADS];
    FileData data[MAX_THREADS];
    int thread_count = 0;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL && thread_count < MAX_THREADS) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        data[thread_count].filename = malloc(strlen(argv[2]) + strlen(entry->d_name) + 2);
        sprintf(data[thread_count].filename, "%s/%s", argv[2], entry->d_name);

        pthread_mutex_t *mutex = (pthread_mutex_t *)malloc(sizeof(pthread_mutex_t));
        pthread_mutex_init(mutex, NULL);
        data[thread_count].mutex = mutex;

        if (pthread_create(&threads[thread_count], NULL, process_file, &data[thread_count]) != 0) {
            perror("Failed to create thread");
            free(data[thread_count].filename);
            pthread_mutex_destroy(data[thread_count].mutex);
            free(data[thread_count].mutex);
            break;
        }

        thread_count++;
    }

    closedir(dir);

    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
        free(data[i].filename);
        pthread_mutex_destroy(data[i].mutex);
        free(data[i].mutex);
    }

    return 0;
}
```

