#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_RETRIES 10
#define BACKOFF_FACTOR 2

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    pthread_mutex_t lock;
} CRC_List;

void* generate_random_rnti(void* arg) {
    // Simulate external RNTI generation service
    sleep(rand() % 5); // Simulate delay
    return (void*)((rand() % 1024) + 1);
}

int populate_crc_list(CRC_List *list, int N, void* (*rnti_gen_service)(void*)) {
    pthread_mutex_lock(&list->lock);
    list->data = realloc(list->data, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    for (int i = 0; i < N; ++i) {
        void* rnti_result;
        int retries = MAX_RETRIES;
        while (retries--) {
            rnti_result = rnti_gen_service();
            if (rnti_result != NULL) break;
            sleep(retries * BACKOFF_FACTOR); // Exponential backoff
        }
        if (!rnti_result) {
            pthread_mutex_unlock(&list->lock);
            return -2; // RNTI generation failed after retries
        }
        list->data[i].RX_UE_INFORMATION_TAG = i + 1;
        list->data[i].RNTI = (int)rnti_result;
        list->data[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRC flag
    }
    list->count = N;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int main() {
    srand(time(NULL));
    CRC_List crc_list = { .lock = PTHREAD_MUTEX_INITIALIZER };
    if (populate_crc_list(&crc_list, 10, generate_random_rnti) == 0) {
        for (size_t i = 0; i < crc_list.count; ++i) {
            printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n",
                   crc_list.data[i].RX_UE_INFORMATION_TAG,
                   crc_list.data[i].RNTI,
                   crc_list.data[i].CRC_INDICATION_REL8_TAG);
        }
    } else {
        printf("Failed to populate CRC list.\n");
    }
    free(crc_list.data);
    return 0;
}
