    for (int i = 0; i < stream.source_count; i++) {
        pthread_create(&threads[i], NULL, data_source_reader, &stream.sources[i]);
    }

    // Join all threads to wait for completion
    for (int i = 0; i < stream.source_count; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

