# Define the ApplicationEnvironment class
class ApplicationEnvironment:
    def __init__(self, name, config, logs=None, version_history=None, metrics=None):
        self.name = name
        self.config = config
        self.logs = logs or []
        self.version_history = version_history or []
        self.metrics = metrics or {}

    def update_config(self, new_config):
        self.config = new_config

    def add_log(self, log_entry):
        self.logs.append(log_entry)

    def record_version(self, version):
        self.version_history.append(version)

    def update_metric(self, key, value):
        self.metrics[key] = value

# Define the EnvironmentManager class
class EnvironmentManager:
    def __init__(self):
        self.environments = {}

    def add_environment(self, env_name, config):
        if env_name not in self.environments:
            new_env = ApplicationEnvironment(env_name, config)
            self.environments[env_name] = new_env
            return new_env
        else:
            raise ValueError("Environment already exists")

    def remove_environment(self, env_name):
        if env_name in self.environments:
            del self.environments[env_name]
        else:
            raise ValueError("Environment does not exist")

    def update_environment_config(self, env_name, new_config):
        if env_name in self.environments:
            self.environments[env_name].update_config(new_config)
        else:
            raise ValueError("Environment does not exist")

