// Define the linked list structure
typedef struct LinkedList {
    Node* head;
    pthread_mutex_t mutex;
} LinkedList;

// Function to initialize the linked list
void initLinkedList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

// Function to add a new frame metadata to the linked list
void addFrameMetadata(LinkedList* list, FrameMetadata data) {
    pthread_mutex_lock(&list->mutex);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->mutex);
}

// Function to iterate over the linked list
void iterateList(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        // Process each frame metadata entry
        printf("Frame ID: %d, Timestamp: %ld\n", current->data.frame_id, current->data.timestamp);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to clean up the linked list and free memory
void cleanupLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
}

