#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define ChannelQualityIndication structure
typedef struct {
    int signal_strength;
    int noise_level;
    int interference_level;
} ChannelQualityIndication;

// Define FrameMetadata structure
typedef struct FrameMetadata {
    int frame_id;
    long timestamp;
    ChannelQualityIndication *channel_quality_indications;
    struct FrameMetadata *next;
} FrameMetadata;

// Function to create a new FrameMetadata node
FrameMetadata* create_frame_metadata(int frame_id, long timestamp) {
    FrameMetadata* new_node = (FrameMetadata*)malloc(sizeof(FrameMetadata));
    new_node->frame_id = frame_id;
    new_node->timestamp = timestamp;
    new_node->channel_quality_indications = NULL;
    new_node->next = NULL;
    return new_node;
}

// Function to add ChannelQualityIndication to FrameMetadata
void add_channel_quality_indication(FrameMetadata* metadata, int signal_strength, int noise_level, int interference_level) {
    ChannelQualityIndication* new_cqi = (ChannelQualityIndication*)malloc(sizeof(ChannelQualityIndication));
    new_cqi->signal_strength = signal_strength;
    new_cqi->noise_level = noise_level;
    new_cqi->interference_level = interference_level;

    if (metadata->channel_quality_indications == NULL) {
        metadata->channel_quality_indications = new_cqi;
        new_cqi->next = NULL;
    } else {
        ChannelQualityIndication* current = metadata->channel_quality_indications;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_cqi;
        new_cqi->next = NULL;
    }
}

// Function to free memory allocated for FrameMetadata and its components
void free_frame_metadata(FrameMetadata* metadata) {
    if (metadata != NULL) {
        ChannelQualityIndication* cqi = metadata->channel_quality_indications;
        while (cqi != NULL) {
            ChannelQualityIndication* temp = cqi;
            cqi = cqi->next;
            free(temp);
        }
        free_frame_metadata(metadata->next);
        free(metadata);
    }
}

// Function to add a new FrameMetadata node to the linked list
void add_to_list(FrameMetadata** head, int frame_id, long timestamp) {
    FrameMetadata* new_node = create_frame_metadata(frame_id, timestamp);

    if (*head == NULL) {
        *head = new_node;
    } else {
        FrameMetadata* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Function to iterate over the linked list and print FrameMetadata
void iterate_list(FrameMetadata* head) {
    FrameMetadata* current = head;
    while (current != NULL) {
        printf("Frame ID: %d, Timestamp: %ld\n", current->frame_id, current->timestamp);
        ChannelQualityIndication* cqi = current->channel_quality_indications;
        while (cqi != NULL) {
            printf("  Signal Strength: %d, Noise Level: %d, Interference Level: %d\n",
                   cqi->signal_strength, cqi->noise_level, cqi->interference_level);
            cqi = cqi->next;
        }
        current = current->next;
    }
}

// Function to free all memory allocated for the linked list
void free_list(FrameMetadata* head) {
    while (head != NULL) {
        FrameMetadata* temp = head;
        head = head->next;
        free_frame_metadata(temp);
    }
}
```

