typedef struct {
    pthread_mutex_t lock;
    int n_pdus;
    NFAPI_CRC_INDICATION_PDU_T* pdus;
} DynamicList;

void initialize_list(DynamicList* list, int capacity) {
    list->n_pdus = 0;
    list->pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->lock, NULL);
}

void add_pdu(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->n_pdus < capacity) {
        list->pdus[list->n_pdus++] = pdu;
    }
    pthread_mutex_unlock(&list->lock);
}

void clean_up_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    free(list->pdus);
    pthread_mutex_destroy(&list->lock);
}
