#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct FrameMetadata {
    int frame_id;
    time_t timestamp;
    // Add other fields as needed
} FrameMetadata;

typedef struct ChannelQualityIndication {
    float signal_strength;
    float noise_level;
    float interference_level;
    // Add other fields as needed
} ChannelQualityIndication;

typedef struct Node {
    FrameMetadata data;
    ChannelQualityIndication cqis;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    sem_t lock;
} LinkedList;

void init_list(LinkedList* list) {
    list->head = NULL;
    sem_init(&list->lock, 0, 1);
}

void insert_node(LinkedList* list, FrameMetadata metadata, ChannelQualityIndication cqis) {
    sem_wait(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        // Handle memory allocation failure
        sem_post(&list->lock);
        return;
    }
    new_node->data = metadata;
    new_node->cqis = cqis;
    new_node->next = list->head;
    list->head = new_node;
    sem_post(&list->lock);
}

void remove_node(LinkedList* list, int frame_id) {
    sem_wait(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;
    while (current != NULL && current->data.frame_id != frame_id) {
        prev = current;
        current = current->next;
    }
    if (current == NULL) {
        // Node not found
        sem_post(&list->lock);
        return;
    }
    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }
    free(current);
    sem_post(&list->lock);
}

void iterate_list(LinkedList* list, void (*callback)(FrameMetadata, ChannelQualityIndication)) {
    sem_wait(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        callback(current->data, current->cqis);
        current = current->next;
    }
    sem_post(&list->lock);
}

void cleanup_list(LinkedList* list) {
    sem_wait(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    sem_destroy(&list->lock);
}
```

