} FrameMetadata;

// ChannelQualityIndication structure definition
typedef struct {
    float signal_strength;
    float noise_level;
    float interference_level;
} ChannelQualityIndication;

// Function to initialize a new FrameMetadata instance
FrameMetadata* create_frame_metadata(int frame_id, time_t timestamp) {
    FrameMetadata* meta = (FrameMetadata*)malloc(sizeof(FrameMetadata));
    if (meta == NULL) return NULL; // Handle memory allocation failure
    meta->frame_id = frame_id;
    meta->timestamp = timestamp;
    meta->cqis = NULL;
    meta->cq_count = 0;
    return meta;
}

// Function to add a ChannelQualityIndication to FrameMetadata
void add_cqi(FrameMetadata* meta, float signal_strength, float noise_level, float interference_level) {
    meta->cq_count++;
    meta->cqis = (ChannelQualityIndication*)realloc(meta->cqis, sizeof(ChannelQualityIndication) * meta->cq_count);
    if (meta->cqis == NULL) return; // Handle memory allocation failure
    ChannelQualityIndication* cqi = &meta->cqis[meta->cq_count - 1];
    cqi->signal_strength = signal_strength;
    cqi->noise_level = noise_level;
    cqi->interference_level = interference_level;
}

// Function to free FrameMetadata instance and its associated memory
void free_frame_metadata(FrameMetadata* meta) {
    if (meta != NULL) {
        if (meta->cqis != NULL) {
            free(meta->cqis);
        }
        free(meta);
    }
}
