import logging
from logging.handlers import RotatingFileHandler
from oauthlib.oauth2 import BackendApplicationClient
from requests_oauthlib import OAuth2Session
import time
import random

class ConfigModifier:
    def __init__(self, template_path):
        self.template = self.load_template(template_path)
        self.logger = self.setup_logger()

    def load_template(self, path):
        with open(path, 'r') as file:
            return yaml.safe_load(file)  # or json.load(file)

    def setup_logger(self):
        handler = RotatingFileHandler('app.log', maxBytes=1*1024*1024, backupCount=3)
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        logger = logging.getLogger(__name__)
        logger.setLevel(logging.INFO)
        logger.addHandler(handler)
        return logger

    def truncate_string(self, s, max_length):
        if len(s) <= max_length:
            return s
        elif len(s[:max_length]) > 0 and s[max_length - 1] == '/':
            return s[:max_length]
        else:
            self.logger.error(f"String too long: {s}")
            return "NULL"

    def update_config(self, params):
        for key, value in params.items():
            if isinstance(value, str):
                params[key] = self.truncate_string(value, 100)  # Example max length
            else:
                params[key] = value
        updated_template = {k: v.format(**params) for k, v in self.template.items()}
        return updated_template

class Logger:
    def __init__(self, client_id, client_secret):
        self.client_id = client_id
        self.client_secret = client_secret
        self.session = None

    def authenticate(self):
        client = BackendApplicationClient(client_id=self.client_id)
        oauth = OAuth2Session(client=client)
        token = oauth.fetch_token(token_url='https://api.example.com/oauth/token', client_id=self.client_id, client_secret=self.client_secret)
        self.session = oauth

    def log_message(self, message):
        if not self.session:
            raise Exception("Not authenticated")
        for _ in range(3):  # Retry up to three times
            try:
                response = self.session.post('https://api.example.com/log', json={'message': message})
                response.raise_for_status()
                break
            except requests.RequestException as e:
                time.sleep(2**random.randint(0, 3))  # Exponential backoff

    def __call__(self, level, msg):
        self.log_message(msg)

# Example usage
config_modifier = ConfigModifier('template.yaml')
params = {'name': 'example', 'description': 'This is a very long description that needs to be truncated'}
updated_config = config_modifier.update_config(params)
logger = Logger('client_id', 'client_secret')
logging.setLoggerClass(Logger)
logger_instance = logging.getLogger('app_logger')
logger_instance.setLevel(logging.INFO)

# Logging example
logger_instance.info("Configuration updated successfully")
