    private Object value;
    private long expirationTime;

    public CacheEntry(String key, Object value, long expirationTime) {
        this.key = key;
        this.value = value;
        this.expirationTime = System.currentTimeMillis() + expirationTime;
    }

    // Getters and setters
}

// DistributedCache.java
import java.util.HashMap;
import java.util.Map;

public class DistributedCache {
    private Map<String, CacheEntry> cacheMap;
    private final int capacity;

    public DistributedCache(int capacity) {
        this.capacity = capacity;
        this.cacheMap = new HashMap<>();
    }

    public void put(String key, Object value, long expirationTime) {
        if (cacheMap.size() >= capacity) {
            // Remove the least recently used item
            cacheMap.remove(getLeastRecentlyUsedKey());
        }
        cacheMap.put(key, new CacheEntry(key, value, expirationTime));
    }

    public Object get(String key) {
        CacheEntry entry = cacheMap.get(key);
        if (entry != null && entry.expirationTime > System.currentTimeMillis()) {
            return entry.value;
        } else {
            cacheMap.remove(key);
            return null;
        }
    }

    private String getLeastRecentlyUsedKey() {
        // Implement logic to find the least recently used key
        return "least_recent_key";
    }
}

// CacheManager.java
public class CacheManager {
    private DistributedCache distributedCache;

    public CacheManager(int capacity) {
        this.distributedCache = new DistributedCache(capacity);
    }

    public void put(String key, Object value, long expirationTime) {
        distributedCache.put(key, value, expirationTime);
    }

    public Object get(String key) {
        return distributedCache.get(key);
    }
}

// Main.java
public class Main {
    public static void main(String[] args) {
        CacheManager cacheManager = new CacheManager(100);

        // Example usage
        cacheManager.put("user:123", "John Doe", 60 * 1000); // Store for 1 minute
        Object user = cacheManager.get("user:123");
        System.out.println(user);
    }
}
