struct Transaction {
    int id;
    std::chrono::system_clock::time_point timestamp;
    double amount;
    std::string type;
    std::string status;
};

class PaymentGatewayClient {
public:
    bool processTransaction(const Transaction& transaction) {
        // Simulate processing with a random success rate
        return rand() % 2 == 0;
    }
};

void batchProcessTransactions(std::vector<Transaction>& buffer, size_t bufferSize, size_t batchSize,
                             std::chrono::milliseconds timeout, bool logDetails, PaymentGatewayClient& client) {
    std::mutex mtx;
    std::condition_variable cv;
    std::atomic<bool> stop(false);
    size_t processed = 0;

    auto worker = [&]() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [processed] { return stop || processed >= bufferSize; });

            if (stop && processed == bufferSize) break;

            for (size_t i = 0; i < batchSize && processed < bufferSize; ++i) {
                auto& transaction = buffer[processed % bufferSize];
                bool success = false;
                size_t attempts = 0;

                while (!success && attempts < 5) {
                    try {
                        success = client.processTransaction(transaction);
                    } catch (const std::exception& e) {
                        // Log exception
                    }

                    if (!success) {
                        std::this_thread::sleep_for(std::chrono::milliseconds(1 << attempts));
                        ++attempts;
                    }
                }

                if (logDetails) {
                    // Log transaction details
                }

                processed++;
            }
        }
    };

    std::thread t(worker);

    auto start = std::chrono::high_resolution_clock::now();
    while (!stop && std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::high_resolution_clock::now() - start) < timeout) {
        std::this_thread::yield();
    }

    stop = true;
    cv.notify_all();
    t.join();
}
