#include <curl/curl.h>

struct ComponentState {
    std::string id;
    std::string status;
    std::time_t timestamp;
    ComponentState* prev;
    ComponentState* next;

    ComponentState(const std::string& id, const std::string& status)
        : id(id), status(status), timestamp(std::time(nullptr)), prev(nullptr), next(nullptr) {}
};

class StateManager {
public:
    static void registerOrLogComponentStateChange(ComponentState* newState);
private:
    static void logToExternalService(const ComponentState& oldState, const ComponentState& newState);
    static bool sendRequest(const std::string& url, const std::string& payload);
    static void handleRetryFailure(const ComponentState& oldState, const ComponentState& newState);
};

std::atomic<bool> loggingEnabled(true);

void StateManager::registerOrLogComponentStateChange(ComponentState* newState) {
    if (newState == nullptr || !loggingEnabled) return;

    ComponentState* oldState = nullptr;
    {
        std::lock_guard<std::mutex> lock(mutex_);
        if (head_ != nullptr && head_->id == newState->id) {
            oldState = head_;
            oldState->status = newState->status;
            oldState->timestamp = newState->timestamp;
            oldState->next = newState;
            newState->prev = oldState;
            newState->next = nullptr;
        }
    }

    if (oldState != nullptr && oldState->id == newState->id) {
        logToExternalService(*oldState, *newState);
    }
}

void StateManager::logToExternalService(const ComponentState& oldState, const ComponentState& newState) {
    std::string url = "https://monitoring.service/log";
    std::string payload = createPayload(oldState, newState);

    if (!sendRequest(url, payload)) {
        handleRetryFailure(oldState, newState);
    }
}

bool StateManager::sendRequest(const std::string& url, const std::string& payload) {
    CURL* curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, payload.c_str());

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << std::endl;
            return false;
        }
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    return true;
}

void StateManager::handleRetryFailure(const ComponentState& oldState, const ComponentState& newState) {
    // Implement exponential backoff with retry logic here
    std::this_thread::sleep_for(std::chrono::seconds(1));
    if (!sendRequest("https://monitoring.service/log", createPayload(oldState, newState))) {
        // Fallback mechanism to log locally
        std::cerr << "Failed to log state change: Local logging fallback" << std::endl;
    }
}

std::string StateManager::createPayload(const ComponentState& oldState, const ComponentState& newState) {
    // Create JSON payload here
    return "{\"old_state\": {\"id\": \"" + oldState.id + "\", \"status\": \"" + oldState.status + "\"}, "
           "\"new_state\": {\"id\": \"" + newState.id + "\", \"status\": \"" + newState.status + "\"}}";
}

std::mutex StateManager::mutex_;
ComponentState* StateManager::head_ = nullptr;
