    AttackModule(const Config& config) : config_(config), db_pool_(config_.getDBConfig()), cache_(config_.getCacheConfig()) {}

    void selectAttack() {
        while (true) {
            std::string attack = chooseAttack();
            int cooldown = config_.getCooldown();
            executeCooldown(cooldown);
            printSelectedAttack(attack);
            handleErrors();
        }
