using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using Microsoft.Extensions.Caching.Memory;

public class LegacySQLDataAccessLayer : IDisposable
{
    private readonly string _connectionString;
    private readonly IMemoryCache _cache;

    public LegacySQLDataAccessLayer(string connectionString, IMemoryCache cache)
    {
        _connectionString = connectionString;
        _cache = cache;
    }

    public T ExecuteStoredProcedure<T>(string storedProcedureName, Dictionary<string, object> parameters) where T : new()
    {
        var cacheKey = $"{storedProcedureName}_{GenerateParameterKey(parameters)}";
        if (_cache.TryGetValue(cacheKey, out T cachedResult))
        {
            return cachedResult;
        }

        using (var connection = new SqlConnection(_connectionString))
        {
            connection.Open();
            using (var command = new SqlCommand(storedProcedureName, connection) { CommandType = CommandType.StoredProcedure })
            {
                foreach (var param in parameters)
                {
                    var sqlParam = new SqlParameter(param.Key, param.Value);
                    if (param.Value != null)
                    {
                        sqlParam.DbType = TypeToDbType(param.Value.GetType());
                    }
                    command.Parameters.Add(sqlParam);
                }

                using (var reader = command.ExecuteReader())
                {
                    if (reader.Read())
                    {
                        var result = new T();
                        foreach (DataColumn column in reader.GetSchemaTable().Rows)
                        {
                            var propertyName = column.ColumnName;
                            var propertyInfo = typeof(T).GetProperty(propertyName);
                            if (propertyInfo != null)
                            {
                                propertyInfo.SetValue(result, Convert.ChangeType(reader[propertyName], propertyInfo.PropertyType));
                            }
                        }
                        _cache.Set(cacheKey, result, new MemoryCacheEntryOptions().SetAbsoluteExpiration(TimeSpan.FromMinutes(5)));
                        return result;
                    }
                }
            }
        }

        throw new InvalidOperationException("No data returned from stored procedure.");
    }

    private static string GenerateParameterKey(Dictionary<string, object> parameters)
    {
        var key = "";
        foreach (var param in parameters)
        {
            key += $"{param.Key}_{param.Value}";
        }
        return key;
    }

    private static SqlDbType TypeToDbType(Type type)
    {
        switch (Type.GetTypeCode(type))
        {
            case TypeCode.String: return SqlDbType.NVarChar;
            case TypeCode.Int32: return SqlDbType.Int;
            case TypeCode.DateTime: return SqlDbType.DateTime;
            // Add other types as needed
            default: throw new ArgumentException("Unsupported data type.");
        }
    }

    public void Dispose()
    {
        // Cleanup if necessary
    }
}
