#include <pthread.h>
#include <semaphore.h>
#include <sqlite3.h>
#include <time.h>

#define MAX_NFAPI_PDUS 10000
#define MAX_THREADS 16
#define RETRY_DELAY_BASE 250

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_NFAPI_PDUS];
    int count;
} BatchData;

BatchData batch_data;
sem_t batch_semaphore;
pthread_mutex_t mutex;
sqlite3 *db_handle;
char *retry_delay;

void* process_batch(void* arg) {
    while (1) {
        sem_wait(&batch_semaphore);
        pthread_mutex_lock(&mutex);

        // Process and validate pdus
        for (int i = 0; i < batch_data.count; i++) {
            if (!is_valid_rx_ue_information_tag(batch_data.pdus[i].rx_ue_information_tag)) {
                log_error("Invalid RX_UE_INFORMATION_TAG");
                continue;
            }
            if (!is_valid_rnti(batch_data.pdus[i].rnti)) {
                log_error("Invalid RNTI");
                continue;
            }
            if (!is_valid_crc_indication_rel8_tag(batch_data.pdus[i].crc_indication_rel8_tag)) {
                log_error("Invalid CRC_INDICATION_REL8_TAG");
                continue;
            }

            // Batch update SQL database
            retry_sql_update(batch_data.pdus[i]);
        }

        batch_data.count = 0;
        pthread_mutex_unlock(&mutex);
    }
}

void enqueue_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&mutex);

    if (batch_data.count < MAX_NFAPI_PDUS) {
        batch_data.pdus[batch_data.count++] = pdu;
        sem_post(&batch_semaphore);
    } else {
        log_warning("Batch full, dropping PDU");
    }

    pthread_mutex_unlock(&mutex);
}

void retry_sql_update(NFAPI_CRC_INDICATION_PDU_T pdu) {
    int delay = atoi(retry_delay);
    while (1) {
        if (sqlite3_exec(db_handle, "UPDATE ...", NULL, NULL, &error_message) == SQLITE_OK) {
            break;
        } else {
            log_error("SQL Update Failed: %s", error_message);
            sqlite3_free(error_message);
            usleep(delay * 1000); // Convert milliseconds to microseconds
            delay *= 2; // Exponential backoff
        }
    }
}

void init_system() {
    sem_init(&batch_semaphore, 0, 0);
    pthread_mutex_init(&mutex, NULL);

    sqlite3_open("nfapi.db", &db_handle);

    char *argv[] = {"-g"};
    char *azArgv[1];
    azArgv[0] = argv[0];
    int argc = sizeof(argv) / sizeof(argv[0]);

    sqlite3_config(SQLITE_CONFIG_LOG, sqlite3_log, NULL);
    sqlite3_initialize();
}

void cleanup_system() {
    sem_destroy(&batch_semaphore);
    pthread_mutex_destroy(&mutex);
    sqlite3_close(db_handle);
}
