from flask import Flask, request, jsonify
import redis
from flask_cors import CORS

app = Flask(__name__)
CORS(app)

# Connect to Redis for document versioning
redis_client = redis.StrictRedis(host='localhost', port=6379, db=0)

@app.route('/documents/<document_id>', methods=['GET'])
def get_document(document_id):
    """Retrieve a specific version of a document."""
    version_key = f"{document_id}:version"
    content_key = f"{document_id}:content"

    # Get the latest version number
    version = redis_client.get(version_key)
    if version:
        version = int(version.decode('utf-8'))
    else:
        return jsonify({"error": "Document not found"}), 404

    # Get the content for the specified version
    content = redis_client.get(f"{content_key}:{version}")
    if content:
        return jsonify({"document_id": document_id, "version": version, "content": content.decode('utf-8')})
    else:
        return jsonify({"error": "Version not found"}), 404

@app.route('/documents/<document_id>', methods=['POST'])
def create_document(document_id):
    """Create a new version of a document."""
    content = request.json.get('content')
    if not content:
        return jsonify({"error": "Content is required"}), 400

    # Get the latest version number or start at version 1
    current_version = redis_client.get(f"{document_id}:version")
    if current_version:
        current_version = int(current_version.decode('utf-8'))
    else:
        current_version = 1

    # Store the new content and update the version number
    redis_client.set(f"{document_id}:content:{current_version}", content)
    redis_client.set(f"{document_id}:version", current_version + 1)

    return jsonify({"document_id": document_id, "version": current_version + 1}), 201

@app.route('/documents/<document_id>', methods=['PUT'])
def update_document(document_id):
    """Update the latest version of a document."""
    content = request.json.get('content')
    if not content:
        return jsonify({"error": "Content is required"}), 400

    # Get the latest version number
    current_version = redis_client.get(f"{document_id}:version")
    if current_version:
        current_version = int(current_version.decode('utf-8'))
    else:
        return jsonify({"error": "Document not found"}), 404

    # Update the content for the latest version
    redis_client.set(f"{document_id}:content:{current_version}", content)

    return jsonify({"document_id": document_id, "version": current_version}), 200

@app.route('/documents/<document_id>', methods=['DELETE'])
def delete_document(document_id):
    """Delete a specific version of a document."""
    version = request.json.get('version')
    if not version:
        return jsonify({"error": "Version is required"}), 400

    # Delete the content for the specified version
    redis_client.delete(f"{document_id}:content:{version}")

    return jsonify({"document_id": document_id, "version": version, "action": "deleted"}), 200

if __name__ == '__main__':
    app.run(debug=True)
```

This Flask application provides a basic microservice for managing document versions using Redis for data storage and retrieval. It supports HTTP GET, POST, PUT, and DELETE requests to create, retrieve, update, and delete document versions. The application uses Redis to store the content of each version and manages versioning with a separate key. This setup is designed to be stateless, scalable, and efficient for handling concurrent requests in a microservices architecture.']

