class TextProcessorImpl : public TextProcessor {
private:
  ThreadSafeAllocator allocator;
  Logger logger;

  static const int MAX_TOKENS_PER_MINUTE = 10000000;
  std::atomic<int> tokenCount;

public:
  TextProcessorImpl() : tokenCount(0) {}

  void processText(const std::string& text, const CallbackFunction& callback) override {
    if (tokenCount > MAX_TOKENS_PER_MINUTE) {
      logger.log("Error: Token limit exceeded");
      return;
    }

    // Process the text
    for (const auto& token : split(text)) {
      allocator.allocate(token.size());
      ++tokenCount;
    }

    callback(text);
  }

private:
  std::vector<std::string> split(const std::string& text) {
    // Split text into tokens
    return {};
  }
};

