```cpp
// RateLimiter.cpp
#include "RateLimiter.h"
#include <chrono>
#include <mutex>

class RateLimiter {
private:
  std::mutex mutex;
  std::chrono::time_point<std::chrono::system_clock> lastReset;
  int requests;

public:
  RateLimiter() : lastReset(std::chrono::system_clock::now()), requests(0) {}

  bool allowRequest(const std::string& ip) {
    std::lock_guard<std::mutex> lock(mutex);
    auto now = std::chrono::system_clock::now();
    if (std::chrono::duration_cast<std::chrono::seconds>(now - lastReset).count() >= 60) {
      requests = 1;
      lastReset = now;
    } else if (requests >= 10) {
      return false;
    }
    ++requests;
    return true;
  }
};
