using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Memory;

[ApiController]
[Route("api/[controller]")]
public class OctreeController : ControllerBase
{
    private readonly IMemoryCache _memoryCache;
    private readonly HttpClient _httpClient;
    private readonly string _octreeServiceUrl = "https://external-octree-service.com";

    public OctreeController(IMemoryCache memoryCache, IHttpClientFactory httpClientFactory)
    {
        _memoryCache = memoryCache;
        _httpClient = httpClientFactory.CreateClient();
    }

    [HttpPut("update")]
    public async Task<IActionResult> UpdateOctreeElementAsync(
        int categoryId,
        int productId,
        string updatedProductDetails,
        double featureSize,
        int reviewCount)
    {
        try
        {
            // Attempt to update in-memory cache first
            await UpdateInMemoryCache(categoryId, productId, updatedProductDetails);

            // If successful, attempt to update external service
            await UpdateExternalService(categoryId, productId, updatedProductDetails, featureSize, reviewCount);

            return Ok("Update successful");
        }
        catch (Exception ex)
        {
            // Log error and retry logic here
            return StatusCode(500, "Internal server error");
        }
    }

    private async Task UpdateInMemoryCache(int categoryId, int productId, string updatedProductDetails)
    {
        var cacheKey = $"Product:{categoryId}:{productId}";
        _memoryCache.Set(cacheKey, updatedProductDetails, DateTimeOffset.UtcNow.AddMinutes(10));
    }

    private async Task UpdateExternalService(int categoryId, int productId, string updatedProductDetails, double featureSize, int reviewCount)
    {
        using (var content = new StringContent(updatedProductDetails))
        {
            var response = await _httpClient.PutAsync($"{_octreeServiceUrl}/update/{categoryId}/{productId}", content);
            if (!response.IsSuccessStatusCode)
            {
                throw new Exception("Failed to update external service");
            }
        }
    }
}
