app.service('DialogFieldService', ['$http', '$q', function($http, $q) {
    var cache = {};

    this.refreshFields = function(fieldIds, priorityList) {
        var promises = [];
        fieldIds.forEach(function(id) {
            if (priorityList.includes(id)) {
                promises.push(refreshField(id));
            }
        });
        return $q.all(promises);
    };

    function refreshField(id) {
        if (cache[id] && cache[id].timestamp + 60000 > Date.now()) { // Cache expires after 1 minute
            return Promise.resolve(cache[id].data);
        } else {
            var promise = $http.get('https://api.example.com/field/' + id)
                .then(function(response) {
                    cache[id] = {
                        data: response.data,
                        timestamp: Date.now()
                    };
                    return response.data;
                });
            return promise;
        }
    }
}]);

