    private HealthChecker healthChecker;
    private AlertManager alertManager;

    public SystemHealthService(HealthChecker healthChecker, AlertManager alertManager) {
        this.healthChecker = healthChecker;
        this.alertManager = alertManager;
        this.scheduler = Executors.newScheduledThreadPool(2);
    }

    public void start() {
        scheduler.scheduleAtFixedRate(() -> {
            try {
                if (!healthChecker.check()) {
                    alertManager.sendAlert("System Health Alert");
                }
            } catch (Exception e) {
                alertManager.logError(e);
            }
        }, 0, 1, TimeUnit.MINUTES); // Check every minute
    }

    public void stop() {
        scheduler.shutdown();
        try {
            if (!scheduler.awaitTermination(60, TimeUnit.SECONDS)) {
                scheduler.shutdownNow();
            }
        } catch (InterruptedException e) {
            scheduler.shutdownNow();
        }
    }

    public void restart() {
        stop();
        start();
    }

    // HealthChecker interface
    interface HealthChecker {
        boolean check() throws Exception;
    }

    // AlertManager class
    class AlertManager {
        public void sendAlert(String message) {
            // Implement alert sending logic
        }

        public void logError(Exception e) {
            // Implement error logging logic
        }
    }
}

// Example usage
public class Main {
    public static void main(String[] args) {
        HealthChecker healthChecker = new HealthChecker() {
            @Override
            public boolean check() throws Exception {
                // Implement system health check logic
                return true;
            }
        };

        AlertManager alertManager = new SystemHealthService.AlertManager();
        SystemHealthService service = new SystemHealthService(healthChecker, alertManager);
        service.start();

        // Simulate stopping after 10 minutes
        try {
            Thread.sleep(600000);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        service.stop();
    }
}
