$logger = new Logger('microservice');
$logger->pushHandler(new StreamHandler(__DIR__.'/microservice.log', Logger::DEBUG));

$httpClient = new Client(['base_uri' => 'https://api.example.com']);
$redisClient = new RedisClient();

// RBAC configuration
$roleBasedAccessControl = [
    'admin' => ['update_status'],
    'user' => []
];

// Function to update clinic status
function updateClinicStatus($clinicId, $status, $userId) {
    global $httpClient, $logger, $redisClient, $roleBasedAccessControl;

    // Validate user role
    if (!isset($roleBasedAccessControl[$userId]) || !in_array('update_status', $roleBasedAccessControl[$userId])) {
        return ['error' => 'Unauthorized'];
    }

    // Check rate limiting using Redis
    $key = "rate_limit:$clinicId:$userId";
    $currentCount = $redisClient->get($key) ?: 0;
    if ($currentCount >= 10) { // Limit to 10 requests per hour
        return ['error' => 'Rate limit exceeded'];
    }

    // Increment request count in Redis
    $redisClient->incr($key);
    $redisClient->expire($key, 3600);

    // Make API call to update status
    try {
        $response = $httpClient->request('POST', '/update_status', [
            'json' => ['clinic_id' => $clinicId, 'status' => $status]
        ]);

        if ($response->getStatusCode() == 200) {
            // Update database and cache
            $data = json_decode($response->getBody(), true);
            updateDatabase($data);
            $redisClient->setex("clinic:$clinicId", 3600, json_encode($data));

            return ['message' => 'Status updated successfully'];
        } else {
            $logger->error('API call failed with status: ' . $response->getStatusCode());
            return ['error' => 'API call failed'];
        }
    } catch (\GuzzleHttp\Exception\RequestException $e) {
        $logger->error('Request exception: ' . $e->getMessage());
        return ['error' => 'API request error'];
    }
}

// Function to update database
function updateDatabase($data) {
    // Database operations here
}

// Example usage
$response = updateClinicStatus(123, 'open', 'user1');
echo json_encode($response);

?>
