['```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <atomic>
#include <condition_variable>
#include <chrono>
#include <cmath>

class Transaction {
public:
    std::int64_t id;
    double amount;
    std::time_t timestamp;

    // Deserialize from binary data
    static Transaction deserialize(const std::vector<char>& data);
};

class TransactionProcessor {
private:
    std::atomic<bool> running{false};
    std::thread consumerThread;
    std::queue<Transaction> transactionQueue;
    std::mutex queueMutex;
    std::condition_variable queueCondVar;
    double totalTransactions = 0;
    double averageTransactionAmount = 0;
    double highestWeightedSum = 0;

    void consume() {
        while (running) {
            std::unique_lock<std::mutex> lock(queueMutex);
            queueCondVar.wait(lock, [this] { return !transactionQueue.empty() || !running; });
            if (!running && transactionQueue.empty()) break;
            Transaction txn = transactionQueue.front();
            transactionQueue.pop();
            lock.unlock();

            // Process transaction
            evaluateTransaction(txn);
        }
    }

    void evaluateTransaction(const Transaction& txn) {
        double age = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now()) - txn.timestamp;
        double weightedSum = txn.amount * age;

        // Update metrics
        totalTransactions++;
        averageTransactionAmount = (totalTransactions * averageTransactionAmount + txn.amount) / totalTransactions;
        highestWeightedSum = std::max(highestWeightedSum, weightedSum);

        // Log transaction details or perform other actions
        std::cout << "Processed transaction: ID=" << txn.id << ", Amount=" << txn.amount << ", Age=" << age << ", Weighted Sum=" << weightedSum << std::endl;
    }

public:
    TransactionProcessor() {
        consumerThread = std::thread(&TransactionProcessor::consume, this);
    }

    ~TransactionProcessor() {
        running = false;
        queueCondVar.notify_all();
        if (consumerThread.joinable()) consumerThread.join();
    }

    void addTransaction(const Transaction& txn) {
        std::lock_guard<std::mutex> lock(queueMutex);
        transactionQueue.push(txn);
        queueCondVar.notify_one();
    }
};

int main() {
    TransactionProcessor processor;
    // Simulate receiving transactions from a WebSocket
    for (int i = 0; i < 1000; ++i) {
        Transaction txn{static_cast<std::int64_t>(i), static_cast<double>(i * 10), std::chrono::system_clock::to_time_t(std::chrono::system_clock::now())};
        processor.addTransaction(txn);
    }

    return 0;
}
```']

