#include <string.h>
#include <math.h>

#define MAX_LINE_LENGTH 1024

double calculate_median(int values[], int count) {
    qsort(values, count, sizeof(int), (int (*)(const void *, const void *))strcmp);
    if (count % 2 == 0)
        return (values[count / 2 - 1] + values[count / 2]) / 2.0;
    else
        return values[count / 2];
}

void process_file(char *filename, char *db_connection_string) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    int line_number = 0;
    int last_three_values[3] = {0};
    int values_count = 0;

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        line_number++;
        char *field = strtok(line, " ");
        int field_index = 0;

        while (field != NULL) {
            if (sscanf(field, "%d", &last_three_values[field_index]) == 1) {
                values_count = (values_count + 1) % 3;
                field_index = (field_index + 1) % 3;
            }
            field = strtok(NULL, " ");
        }

        if (values_count > 0) {
            double median = calculate_median(last_three_values, values_count);
            // Store result in distributed database
            printf("File: %s, Line: %d, Median: %.2f\n", filename, line_number, median);
        }
    }

    fclose(file);
}
