class VideoStreamService {
public:
    VideoStreamService(int numWebcams, int metadataSources)
        : stop(false), webcamCount(numWebcams), metadataCount(metadataSources) {}

    void start() {
        for (int i = 0; i < webcamCount; ++i) {
            webcams.emplace_back([this, i]() { processWebcam(i); });
        }
        for (int i = 0; i < metadataCount; ++i) {
            metadataSources.emplace_back([this, i]() { processMetadata(i); });
        }
    }

    void stop() {
        std::unique_lock<std::mutex> lock(mutex);
        stop = true;
        lock.unlock();
        cv.notify_all();
        for (auto& thread : webcams) thread.join();
        for (auto& thread : metadataSources) thread.join();
    }

private:
    std::vector<std::thread> webcams;
    std::vector<std::thread> metadataSources;
    std::mutex mutex;
    std::condition_variable cv;
    std::atomic<bool> stop;
    int webcamCount;
    int metadataCount;

    void processWebcam(int id) {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return stop || !webcamQueue.empty(); });
            if (stop && webcamQueue.empty()) break;
            auto frame = webcamQueue.front();
            webcamQueue.pop();
            lock.unlock();

            // Process the webcam frame
            processFrame(frame, id);
        }
    }

    void processMetadata(int id) {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return stop || !metadataQueue.empty(); });
            if (stop && metadataQueue.empty()) break;
            auto data = metadataQueue.front();
            metadataQueue.pop();
            lock.unlock();

            // Process the metadata
            processMetadataData(data, id);
        }
    }

    void processFrame(const Frame& frame, int id) {
        // Implement frame processing logic here
        std::cout << "Processing frame from webcam " << id << std::endl;
    }

    void processMetadataData(const Metadata& data, int id) {
        // Implement metadata processing logic here
        std::cout << "Processing metadata from source " << id << std::endl;
    }
};

class Frame {
public:
    // Define the frame structure
};

class Metadata {
public:
    // Define the metadata structure
};
