#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <future>
#include <chrono>
#include <kafka/producer.h>
#include <openssl/evp.h>

struct LTE_TRANSPORT_CHANNEL_MESSAGE {
    int TRANSPORT_CHANNEL_ID;
    std::string PREAMBLE_SEQUENCE;
    int TRANSPORT_FORMAT;
};

class MessageManager {
public:
    using MessageQueue = std::vector<LTE_TRANSPORT_CHANNEL_MESSAGE>;
    using Mutex = std::mutex;
    using LockGuard = std::lock_guard<Mutex>;

    MessageManager(const std::string& kafkaTopic, size_t batchSize, double backoffFactor)
        : kafkaTopic(kafkaTopic), batchSize(batchSize), backoffFactor(backoffFactor), stop(false) {
        producer = std::make_unique<KafkaProducer>(kafkaTopic);
    }

    void addMessage(const LTE_TRANSPORT_CHANNEL_MESSAGE& message) {
        LockGuard lock(mutex);
        queue.push_back(message);
    }

    void startProcessing() {
        processingThread = std::thread(&MessageManager::processQueue, this);
    }

    void stopProcessing() {
        {
            LockGuard lock(mutex);
            stop = true;
        }
        cv.notify_all();
        if (processingThread.joinable()) {
            processingThread.join();
        }
    }

private:
    void processQueue() {
        while (true) {
            MessageQueue batch;
            {
                LockGuard lock(mutex);
                for (; !queue.empty(); queue.pop_back()) {
                    batch.push_back(queue.back());
                    if (batch.size() == batchSize) break;
                }
                if (stop && batch.empty()) break;
            }

            if (!batch.empty()) {
                sendBatch(batch);
            } else {
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
            }
        }
    }

    void sendBatch(const MessageQueue& batch) {
        try {
            producer->publish(batch);
        } catch (const KafkaException& e) {
            retrySendBatch(batch, 1.0);
        }
    }

    void retrySendBatch(const MessageQueue& batch, double delay) {
        std::this_thread::sleep_for(std::chrono::milliseconds(static_cast<int>(delay * 1000)));
        if (!stop) sendBatch(batch);
    }

    std::string kafkaTopic;
    size_t batchSize;
    double backoffFactor;
    std::unique_ptr<KafkaProducer> producer;
    MessageQueue queue;
    Mutex mutex;
    std::condition_variable cv;
    std::thread processingThread;
    std::atomic<bool> stop;
};
