#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define FrameMetadata structure
typedef struct {
    int frame_id;
    long timestamp;
    // Add more fields as needed
} FrameMetadata;

// Define ChannelQualityIndication structure
typedef struct {
    float signal_strength;
    float noise_level;
    float interference_level;
    // Add more fields as needed
} ChannelQualityIndication;

// Define Node structure for linked list
typedef struct Node {
    FrameMetadata *metadata;
    ChannelQualityIndication *cqis;
    struct Node *next;
} Node;

// Define LinkedList structure
typedef struct LinkedList {
    Node *head;
    pthread_mutex_t lock;  // Mutex for thread-safe access
} LinkedList;

// Function to initialize linked list
void init_list(LinkedList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to insert a new node into the linked list
void insert_node(LinkedList *list, FrameMetadata *metadata, ChannelQualityIndication *cqis) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->metadata = metadata;
    new_node->cqis = cqis;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to iterate over the list and compute aggregate metrics
void compute_aggregate_metrics(LinkedList *list, float *avg_signal_quality, float *avg_interference_level) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    int count = 0;
    float total_signal_quality = 0.0;
    float total_interference_level = 0.0;

    while (current != NULL) {
        for (int i = 0; current->cqis[i] != NULL; i++) {
            total_signal_quality += current->cqis[i]->signal_strength;
            total_interference_level += current->cqis[i]->interference_level;
            count++;
        }
        current = current->next;
    }

    if (count > 0) {
        *avg_signal_quality = total_signal_quality / count;
        *avg_interference_level = total_interference_level / count;
    } else {
        *avg_signal_quality = 0.0;
        *avg_interference_level = 0.0;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to free the linked list and its nodes
void free_list(LinkedList *list) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp->metadata);
        free(temp->cqis);
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
