from typing import Any, Dict, List, Optional

class GraphNode:
    def __init__(self, id: str, data: Dict[str, Any]):
        self.id = id
        self.data = data
        self.neighbors = set()

    def add_neighbor(self, neighbor_node: 'GraphNode') -> None:
        self.neighbors.add(neighbor_node)

    def remove_neighbor(self, neighbor_node: 'GraphNode') -> None:
        self.neighbors.remove(neighbor_node)


class DistributedGraphDatabase:
    def __init__(self):
        self.nodes = {}
        self.locks = {}

    def add_vertex(self, vertex_id: str, data: Dict[str, Any]) -> None:
        if vertex_id in self.nodes:
            raise ValueError("Vertex already exists")
        new_node = GraphNode(vertex_id, data)
        self.nodes[vertex_id] = new_node

    def remove_vertex(self, vertex_id: str) -> None:
        if vertex_id not in self.nodes:
            raise ValueError("Vertex does not exist")
        for neighbor in self.nodes[vertex_id].neighbors.copy():
            neighbor.remove_neighbor(self.nodes[vertex_id])
        del self.nodes[vertex_id]

    def add_edge(self, vertex_id1: str, vertex_id2: str) -> None:
        if vertex_id1 not in self.nodes or vertex_id2 not in self.nodes:
            raise ValueError("One or both vertices do not exist")
        self.nodes[vertex_id1].add_neighbor(self.nodes[vertex_id2])
        self.nodes[vertex_id2].add_neighbor(self.nodes[vertex_id1])

    def remove_edge(self, vertex_id1: str, vertex_id2: str) -> None:
        if vertex_id1 not in self.nodes or vertex_id2 not in self.nodes:
            raise ValueError("One or both vertices do not exist")
        self.nodes[vertex_id1].remove_neighbor(self.nodes[vertex_id2])
        self.nodes[vertex_id2].remove_neighbor(self.nodes[vertex_id1])

    def get_vertex_data(self, vertex_id: str) -> Dict[str, Any]:
        if vertex_id not in self.nodes:
            raise ValueError("Vertex does not exist")
        return self.nodes[vertex_id].data

    def set_vertex_data(self, vertex_id: str, data: Dict[str, Any]) -> None:
        if vertex_id not in self.nodes:
            raise ValueError("Vertex does not exist")
        self.nodes[vertex_id].data = data

    def get_neighbors(self, vertex_id: str) -> List[Dict[str, Any]]:
        if vertex_id not in self.nodes:
            raise ValueError("Vertex does not exist")
        return [node.data for node in self.nodes[vertex_id].neighbors]
