from flask import Flask, request, jsonify
from functools import wraps
import time
import redis
import requests
import logging

app = Flask(__name__)
cache = redis.StrictRedis(host='localhost', port=6379, db=0)
logging.basicConfig(level=logging.INFO)

# Decorator for rate limiting
def ratelimit(limit=100, period=60):
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            key = request.remote_addr + request.path
            current_time = time.time()
            recent_requests = cache.zrangebyscore(key, 0, current_time - period)
            if len(recent_requests) >= limit:
                return jsonify({"error": "Too many requests"}), 429
            cache.zremrangebyscore(key, 0, current_time - period)
            cache.zadd(key, {current_time: time.time()})
            return f(*args, **kwargs)
        return decorated_function
    return decorator

# Decorator for caching responses
def cache_response(ttl=3600):
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            key = request.path
            cached_data = cache.get(key)
            if cached_data:
                logging.info("Serving from cache")
                return jsonify(cached_data.decode()), 200
            response = f(*args, **kwargs)
            cache.setex(key, ttl, response.json())
            logging.info("Caching response")
            return response
        return decorated_function
    return decorator

# Example API endpoint
@app.route('/recommendations', methods=['GET'])
@ratelimit()
@cache_response()
def recommendations():
    # Simulate fetching data from third-party APIs and combining results
    product_data = requests.get('https://api.example.com/products').json()
    user_profile = requests.get('https://api.example.com/user').json()
    market_trend_data = requests.get('https://api.example.com/market').json()

    # Process data to generate recommendations
    recommendations = process_data(product_data, user_profile, market_trend_data)

    return jsonify(recommendations)

def process_data(product_data, user_profile, market_trend_data):
    # Placeholder for recommendation logic
    return {"items": ["item1", "item2"]}

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
