#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure fields here
    uint32_t RX_UE_INFORMATION_TAG;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct LinkedListNode* next;
} LinkedListNode;

typedef struct LinkedList {
    pthread_mutex_t lock;
    LinkedListNode* head;
    size_t size;
} LinkedList;

LinkedList* linkedListCreate() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->size = 0;
    return list;
}

void linkedListDestroy(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    LinkedListNode* current = list->head;
    while (current) {
        LinkedListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int linkedListInsert(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    LinkedListNode* newNode = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failure
    }
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int linkedListDelete(LinkedList* list, uint32_t tag) {
    pthread_mutex_lock(&list->lock);
    LinkedListNode* current = list->head;
    LinkedListNode* previous = NULL;

    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG == tag) {
            if (previous) {
                previous->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            list->size--;
            pthread_mutex_unlock(&list->lock);
            return 0; // Node deleted successfully
        }
        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Tag not found
}

NFAPI_CRC_INDICATION_PDU_T* linkedListGet(LinkedList* list, uint32_t tag) {
    pthread_mutex_lock(&list->lock);
    LinkedListNode* current = list->head;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG == tag) {
            pthread_mutex_unlock(&list->lock);
            return &current->data; // Return a pointer to the data
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Tag not found
}
```

