import asyncio
from kafka import KafkaConsumer
import aiohttp
import json
from aioredis import Redis
import logging
from cachetools import TTLCache, cached

# Initialize Kafka Consumer
consumer = KafkaConsumer('topic_name', bootstrap_servers=['localhost:9092'], auto_offset_reset='earliest')

# Initialize Redis for caching and backpressure management
redis_client = Redis(host='localhost', port=6379, db=0)

# Initialize logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Backpressure mechanism
@cached(cache=TTLCache(maxsize=100, ttl=5))
async def process_data(data):
    try:
        # Asynchronous transformations and filtering
        transformed_data = {k: v * 2 for k, v in data.items() if v > 5}

        # Enrichment using external API
        async with aiohttp.ClientSession() as session:
            async with session.get('https://api.example.com/enrich', params=transformed_data) as response:
                enrichment_data = await response.json()

        # Store data in Redis
        await redis_client.setex(f"data:{data['id']}", 3600, json.dumps(enrichment_data))

        logger.info(f"Processed data: {enrichment_data}")
    except Exception as e:
        logger.error(f"Error processing data: {e}")

# Stress testing framework
async def stress_test():
    for _ in range(1000):
        data = {'id': 1, 'value': 6}
        await process_data(data)
        await asyncio.sleep(0.1)

# Main function to run the system
async def main():
    try:
        while True:
            messages = consumer.poll(timeout_ms=1000)
            if messages:
                for message in messages.values():
                    data = json.loads(message.value.decode('utf-8'))
                    await process_data(data)
            await asyncio.sleep(0.1)
    except KeyboardInterrupt:
        logger.info("Shutting down the system")

# Run the system
asyncio.run(main())
