### Java Code Block for Union-Find Data Structure

```java
import java.util.HashMap;
import java.util.Map;

public class UnionFind {
    private Map<Integer, Integer> parent;
    private Map<Integer, Integer> rank;

    public UnionFind() {
        parent = new HashMap<>();
        rank = new HashMap<>();
    }

    public int find(int x) {
        if (!parent.containsKey(x)) {
            parent.put(x, x);
            rank.put(x, 0);
        }
        if (parent.get(x) != x) {
            parent.put(x, find(parent.get(x)));
        }
        return parent.get(x);
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY) return;

        if (rank.get(rootX) > rank.get(rootY)) {
            parent.put(rootY, rootX);
        } else if (rank.get(rootX) < rank.get(rootY)) {
            parent.put(rootX, rootY);
        } else {
            parent.put(rootY, rootX);
            rank.put(rootX, rank.get(rootX) + 1);
        }
    }

    public int countDisjointPairs(int[] array) {
        for (int num : array) {
            union(num, num + 1);
        }
        Map<Integer, Integer> groups = new HashMap<>();
        for (int key : parent.keySet()) {
            int root = find(key);
            groups.put(root, groups.getOrDefault(root, 0) + 1);
        }
        return groups.size();
    }

    public static void main(String[] args) {
        UnionFind uf = new UnionFind();
        int[] array = {1, 2, 3, 4, 5};
        int count = uf.countDisjointPairs(array);
        System.out.println("Count of disjoint pairs: " + count);
    }
}
```

