// JavaScript code for uploading files from URLs

const axios = require('axios');
const fs = require('fs');
const path = require('path');

async function uploadFileFromUrl(url, destinationPath) {
    try {
        const response = await axios({
            method: 'get',
            url: url,
            responseType: 'stream'
        });

        const writer = fs.createWriteStream(destinationPath);
        response.data.pipe(writer);

        return new Promise((resolve, reject) => {
            writer.on('finish', resolve);
            writer.on('error', reject);
        });
    } catch (error) {
        console.error(`Error uploading file from ${url}:`, error);
        throw error;
    }
}

// Example usage
uploadFileFromUrl('http://example.com/file.txt', 'downloaded_file.txt')
    .then(() => console.log('File uploaded successfully'))
    .catch(error => console.error('Failed to upload file:', error));
```

