void insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate memory for node");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void delete_node(LinkedList* list, int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;
    while (current != NULL && current->data.RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        prev = current;
        current = current->next;
    }
    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }
    free(current);
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_node(LinkedList* list, int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL && current->data.RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        current = current->next;
    }
    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (data == NULL) {
        perror("Failed to allocate memory for data");
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }
    *data = current->data;
    pthread_mutex_unlock(&list->lock);
    return data;
}

void free_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
