using System;
using System.Collections.Generic;
using System.Data;
using System.Linq;
using System.Threading.Tasks;
using Newtonsoft.Json;

public interface IDataAccessLayer
{
    Task<List<T>> ExecuteQueryAsync<T>(string connectionString, string query, dynamic parameters = null);
    Task InsertDataAsync(string connectionString, string insertQuery, dynamic data);
}

public class SqlDataAccess : IDataAccessLayer
{
    public async Task<List<T>> ExecuteQueryAsync<T>(string connectionString, string query, dynamic parameters = null)
    {
        using (var connection = new System.Data.SqlClient.SqlConnection(connectionString))
        {
            await connection.OpenAsync();
            using (var command = new System.Data.SqlClient.SqlCommand(query, connection))
            {
                if (parameters != null)
                {
                    foreach (var param in parameters)
                    {
                        command.Parameters.AddWithValue(param.Key, param.Value);
                    }
                }

                using (var reader = await command.ExecuteReaderAsync())
                {
                    return await reader.ReadToListAsync<T>();
                }
            }
        }
    }

    public async Task InsertDataAsync(string connectionString, string insertQuery, dynamic data)
    {
        using (var connection = new System.Data.SqlClient.SqlConnection(connectionString))
        {
            await connection.OpenAsync();
            using (var command = new System.Data.SqlClient.SqlCommand(insertQuery, connection))
            {
                foreach (var property in data.GetType().GetProperties())
                {
                    command.Parameters.AddWithValue(property.Name, property.GetValue(data));
                }

                await command.ExecuteNonQueryAsync();
            }
        }
    }
}

public class NoSqlDataAccess : IDataAccessLayer
{
    private readonly string _connectionString;

    public NoSqlDataAccess(string connectionString)
    {
        _connectionString = connectionString;
    }

    public async Task<List<T>> ExecuteQueryAsync<T>(string query, dynamic parameters = null)
    {
        using (var client = new MongoClient(_connectionString))
        {
            var database = client.GetDatabase("YourDatabaseName");
            var collection = database.GetCollection<T>("YourCollectionName");

            return await collection.Find(Builders<T>.Filter.Regex("_id", new BsonRegularExpression(query))).ToListAsync();
        }
    }

    public async Task InsertDataAsync(string insertQuery, dynamic data)
    {
        using (var client = new MongoClient(_connectionString))
        {
            var database = client.GetDatabase("YourDatabaseName");
            var collection = database.GetCollection<dynamic>("YourCollectionName");

            await collection.InsertOneAsync(data);
        }
    }
}

public class ThirdPartyApiDataAccess : IDataAccessLayer
{
    private readonly HttpClient _httpClient;

    public ThirdPartyApiDataAccess()
    {
        _httpClient = new HttpClient();
    }

    public async Task<List<T>> ExecuteQueryAsync<T>(string apiUrl, string method, dynamic parameters = null)
    {
        var response = await _httpClient.SendAsync(new HttpRequestMessage
        {
            Method = HttpMethod.Get,
            RequestUri = new Uri(apiUrl),
            Content = new StringContent(JsonConvert.SerializeObject(parameters), Encoding.UTF8, "application/json")
        });

        response.EnsureSuccessStatusCode();
        var content = await response.Content.ReadAsStringAsync();
        return JsonConvert.DeserializeObject<List<T>>(content);
    }

    public async Task InsertDataAsync(string apiUrl, string method, dynamic data)
    {
        var response = await _httpClient.SendAsync(new HttpRequestMessage
        {
            Method = HttpMethod.Post,
            RequestUri = new Uri(apiUrl),
            Content = new StringContent(JsonConvert.SerializeObject(data), Encoding.UTF8, "application/json")
        });

        response.EnsureSuccessStatusCode();
    }
}
