}

fn generate_unique_id(input_data: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(input_data);
    let hash = hasher.finalize();
    format!("{}-{}", OsRng.gen::<u32>(), Utc::now().timestamp_nanos(), hex::encode(hash))
}

async fn build_form_element(form_element: FormElement) -> Result<String, String> {
