#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <future>
#include <chrono>
#include <queue>
#include <string>

class ExternalDataSource {
public:
    bool fetchData(const std::string& query) {
        // Simulate network call
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        return true;
    }
};

class ThirdPartyLogger {
public:
    void logError(const std::string& error) {
        // Simulate logging to a remote service
        std::cout << "Logged Error: " << error << std::endl;
    }
};

class BackgroundTask {
public:
    BackgroundTask(ExternalDataSource* dataSource, ThirdPartyLogger* logger)
        : dataSource(dataSource), logger(logger), running(false) {}

    void start() {
        if (!running) {
            running = true;
            worker = std::thread(&BackgroundTask::run, this);
        }
    }

    void stop() {
        if (running) {
            running = false;
            taskQueue.push(nullptr); // Signal thread to exit
            worker.join();
        }
    }

    bool isRunning() const { return running; }

private:
    ExternalDataSource* dataSource;
    ThirdPartyLogger* logger;
    std::thread worker;
    std::queue<std::function<void()>> taskQueue;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool running;

    void run() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            condition.wait(lock, [this] { return !taskQueue.empty() || !running; });
            if (!running && taskQueue.empty()) break;

            auto task = taskQueue.front();
            taskQueue.pop();
            lock.unlock();

            if (task) {
                try {
                    task();
                } catch (const std::exception& e) {
                    logger->logError(e.what());
                }
            }
        }
    }
};

class BackgroundProcessManager {
public:
    BackgroundProcessManager() : dataSource(new ExternalDataSource()), logger(new ThirdPartyLogger()) {}

    ~BackgroundProcessManager() {
        for (auto& task : tasks) {
            task.stop();
        }
        delete dataSource;
        delete logger;
    }

    void addTask(const std::string& taskId, const std::function<void()>& taskFunction) {
        tasks.emplace_back(dataSource, logger);
        tasks.back().start();
        addTaskToQueue(taskId, taskFunction);
    }

    int startAllTasks() {
        for (auto& task : tasks) {
            if (!task.isRunning()) {
                return 0;
            }
        }
        return 1;
    }

    int stopAllTasks() {
        for (auto& task : tasks) {
            task.stop();
        }
        return 1;
    }

private:
    ExternalDataSource* dataSource;
    ThirdPartyLogger* logger;
    std::vector<BackgroundTask> tasks;

    void addTaskToQueue(const std::string& taskId, const std::function<void()>& taskFunction) {
        for (auto& task : tasks) {
            task.taskQueue.push([this, taskId, &taskFunction] {
                try {
                    taskFunction();
                } catch (...) {
                    logger->logError("Exception in task: " + taskId);
                }
            });
        }
    }
};

int main() {
    BackgroundProcessManager manager;
    manager.addTask("Task1", [] { std::cout << "Processing Task 1" << std::endl; });
    manager.addTask("Task2", [] { std::cout << "Processing Task 2" << std::endl; });

    if (manager.startAllTasks() == 1) {
        std::this_thread::sleep_for(std::chrono::seconds(5));
        manager.stopAllTasks();
    }

    return 0;
}
