#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    pthread_mutex_t lock;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t list_lock;
} LinkedList;

void initList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->list_lock, NULL);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&newNode->lock, NULL);
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->list_lock);
    Node* newNode = createNode(data);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            pthread_mutex_unlock(&current->lock);
            pthread_mutex_lock(&current->next->lock);
            current = current->next;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(&list->list_lock);
}

// Other functions for deletion, retrieval, etc. would be implemented here
```

