#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

#define MAX_RETRIES 3

typedef struct {
    char *file_path;
    size_t max_size;
} FileHandle;

FileHandle* open_file(const char *file_path, size_t max_size) {
    FileHandle *fh = (FileHandle*)malloc(sizeof(FileHandle));
    if (!fh) {
        perror("Failed to allocate memory for file handle");
        return NULL;
    }

    fh->file_path = strdup(file_path);
    if (!fh->file_path) {
        perror("Failed to duplicate file path");
        free(fh);
        return NULL;
    }

    fh->max_size = max_size;

    int retries = 0;
    while (retries < MAX_RETRIES) {
        int fd = open(file_path, O_RDONLY);
        if (fd == -1) {
            perror("Failed to open file");
            if (errno != EAGAIN && errno != ENOENT) {
                break; // Stop retrying on permanent errors
            }
            retries++;
            sleep(1); // Wait before retrying
            continue;
        }

        struct stat file_stat;
        if (fstat(fd, &file_stat) == -1) {
            perror("Failed to get file statistics");
            close(fd);
            break;
        }

        if (file_stat.st_size > max_size) {
            printf("File size exceeds limit: %zu bytes\n", file_stat.st_size);
            close(fd);
            break;
        }

        fh->fd = fd;
        return fh;
    }

    free(fh->file_path);
    free(fh);
    return NULL;
}

void close_file(FileHandle *fh) {
    if (fh && fh->fd != -1) {
        close(fh->fd);
    }
    free(fh->file_path);
    free(fh);
}
