import java.util.concurrent.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class RandomServiceManager {
    private static final Logger logger = LoggerFactory.getLogger(RandomServiceManager.class);
    private final MessageBroker messageBroker;
    private final ServiceController serviceController;
    private final RandomDelayGenerator delayGenerator;
    private ExecutorService executorService;
    private volatile boolean running;

    public RandomServiceManager(MessageBroker messageBroker, ServiceController serviceController) {
        this.messageBroker = messageBroker;
        this.serviceController = serviceController;
        this.delayGenerator = new RandomDelayGenerator();
        this.executorService = Executors.newSingleThreadExecutor();
        this.running = true;
    }

    public void start() {
        logger.info("Starting RandomServiceManager");
        executorService.submit(() -> {
            while (running) {
                try {
                    handleServiceOperation();
                } catch (Exception e) {
                    logger.error("Error during service operation", e);
                }
                long delay = delayGenerator.generateDelay();
                logger.debug("Sleeping for {} ms before next operation", delay);
                Thread.sleep(delay);
            }
        });
    }

    public void stop() throws InterruptedException {
        logger.info("Stopping RandomServiceManager");
        running = false;
        executorService.shutdown();
        executorService.awaitTermination(1, TimeUnit.MINUTES);
        logger.info("RandomServiceManager stopped");
    }

    private void handleServiceOperation() {
        try {
            serviceController.performTask();
            messageBroker.sendSuccessMessage();
        } catch (Exception e) {
            logger.error("Failed to perform task", e);
            messageBroker.sendMessageWithRetry(e);
        }
    }

    public static class RandomDelayGenerator {
        private final Random random = new Random();

        public long generateDelay() {
            // Generate a random delay between 100ms and 5000ms
            return 100 + (long) (random.nextDouble() * 4900);
        }

        public float generateFloatDelay() {
            // Generate a random delay between 0.1s and 0.5s
            return 0.1f + (float) (random.nextDouble() * 0.4f);
        }
    }
}
