#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>

// Function to derive a key using PBKDF2 with configurable parameters
void pbkdf2(const char *password, const unsigned char *salt, size_t salt_len,
            int iterations, int key_length, unsigned char *output) {
    EVP_PKEY_CTX *ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_PBKDF2, NULL);
    EVP_PKEY_derive_init(ctx);
    EVP_PKEY_CTX_set_pbkdf2_passphrase(ctx, (const unsigned char *)password, strlen(password));
    EVP_PKEY_CTX_set_pbkdf2_salt(ctx, salt, salt_len);
    EVP_PKEY_CTX_set_pbkdf2_iterations(ctx, iterations);
    EVP_PKEY_derive_key(ctx, output, &key_length, key_length);
    EVP_PKEY_CTX_free(ctx);
}

// Function to generate a secure IV
void generate_iv(unsigned char *iv, size_t iv_len) {
    if (!RAND_bytes(iv, iv_len)) {
        fprintf(stderr, "Error generating IV\n");
        exit(1);
    }
}

// Function to encrypt data using AES-256-CBC with a given key and IV
void encrypt_data(const unsigned char *key, const unsigned char *iv,
                   const unsigned char *plaintext, size_t plaintext_len,
                   unsigned char **ciphertext, size_t *ciphertext_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    if (!EVP_EncryptUpdate(ctx, *ciphertext, ciphertext_len, plaintext, plaintext_len)) {
        fprintf(stderr, "Error encrypting data\n");
        EVP_CIPHER_CTX_free(ctx);
        exit(1);
    }
    if (!EVP_EncryptFinal_ex(ctx, (*ciphertext) + *ciphertext_len, &plaintext_len)) {
        fprintf(stderr, "Error finalizing encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        exit(1);
    }
    *ciphertext_len += plaintext_len;
    EVP_CIPHER_CTX_free(ctx);
}

// Function to decrypt data using AES-256-CBC with a given key and IV
void decrypt_data(const unsigned char *key, const unsigned char *iv,
                   const unsigned char *ciphertext, size_t ciphertext_len,
                   unsigned char **plaintext, size_t *plaintext_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    if (!EVP_DecryptUpdate(ctx, *plaintext, plaintext_len, ciphertext, ciphertext_len)) {
        fprintf(stderr, "Error decrypting data\n");
        EVP_CIPHER_CTX_free(ctx);
        exit(1);
    }
    if (!EVP_DecryptFinal_ex(ctx, (*plaintext) + *plaintext_len, &ciphertext_len)) {
        fprintf(stderr, "Error finalizing decryption\n");
        EVP_CIPHER_CTX_free(ctx);
        exit(1);
    }
    *plaintext_len += ciphertext_len;
    EVP_CIPHER_CTX_free(ctx);
}

// Function to generate an HMAC-SHA256 for a given message and key
void hmac_sha256(const unsigned char *key, size_t key_len,
                 const unsigned char *message, size_t message_len,
                 unsigned char *output, size_t *output_len) {
    HMAC_CTX *ctx = HMAC_CTX_new();
    if (!HMAC_Init_ex(ctx, key, key_len, EVP_sha256(), NULL)) {
        fprintf(stderr, "Error initializing HMAC context\n");
        HMAC_CTX_free(ctx);
        exit(1);
    }
    if (!HMAC_Update(ctx, message, message_len)) {
        fprintf(stderr, "Error updating HMAC with data\n");
        HMAC_CTX_free(ctx);
        exit(1);
    }
    if (!HMAC_Final(ctx, output, output_len)) {
        fprintf(stderr, "Error finalizing HMAC computation\n");
        HMAC_CTX_free(ctx);
        exit(1);
    }
    HMAC_CTX_free(ctx);
}

int main() {
    // Example usage of the encryption and decryption functions
    unsigned char key[32] = {0};
    unsigned char iv[16] = {0};
    unsigned char plaintext[] = "Hello, World!";
    size_t plaintext_len = strlen((char *)plaintext);
    unsigned char ciphertext[plaintext_len + EVP_CIPHER_block_size(EVP_aes_256_cbc())];
    size_t ciphertext_len = 0;
    unsigned char decryptedtext[plaintext_len];
    size_t decryptedtext_len = 0;

    pbkdf2("password", NULL, 0, 100000, sizeof(key), key);
    generate_iv(iv, sizeof(iv));
    encrypt_data(key, iv, plaintext, plaintext_len, &ciphertext, &ciphertext_len);
    decrypt_data(key, iv, ciphertext, ciphertext_len, &decryptedtext, &decryptedtext_len);

    printf("Decrypted text: %s\n", decryptedtext);

    return 0;
}
