class DeviceStatus {
public:
    std::string ip_address;
    int64_t last_online_timestamp;
    std::unordered_map<std::string, double> sensor_readings;
    std::unordered_map<std::string, std::string> versioned_configurations;
    std::unordered_map<std::string, double> health_metrics;

    DeviceStatus() : last_online_timestamp(0) {}
};

class TreeNode {
public:
    DeviceStatus device_status;
    std::vector<TreeNode*> children;

    TreeNode(const DeviceStatus& status) : device_status(status) {}

    ~TreeNode() {
        for (auto child : children) {
            delete child;
        }
    }

    void addChild(TreeNode* child) {
        children.push_back(child);
    }
};

class TreeManager {
public:
    std::unordered_map<std::string, TreeNode*> nodes;

    void addNode(const std::string& id, const DeviceStatus& status) {
        if (nodes.find(id) == nodes.end()) {
            nodes[id] = new TreeNode(status);
        } else {
            nodes[id]->device_status = status;
        }
    }

    void removeNode(const std::string& id) {
        if (nodes.find(id) != nodes.end()) {
            delete nodes[id];
            nodes.erase(id);
        }
    }

    TreeNode* getNode(const std::string& id) {
        auto it = nodes.find(id);
        return it != nodes.end() ? it->second : nullptr;
    }
};

class RESTfulAPI {
public:
    TreeManager tree_manager;

    void fetchDeviceStatusesFromCloud(const std::function<void(const std::unordered_map<std::string, DeviceStatus>&)>& callback) {
        // Simulate fetching from cloud
        std::unordered_map<std::string, DeviceStatus> statuses = {
            {"192.168.1.1", {{"ip_address", "192.168.1.1"}, {"last_online_timestamp", 1633072800}, {"sensor_readings", {{"temp", 25.0}}}}},
            // Add more statuses as needed
        };
        callback(statuses);
    }

    void computeHealthScores() {
        std::unordered_map<std::string, DeviceStatus> statuses;
        fetchDeviceStatusesFromCloud([&](const auto& fetched_statuses) {
            statuses = fetched_statuses;

            for (auto& status : statuses) {
                double healthScore = 0.0;
                for (const auto& [sensor, reading] : status.second.sensor_readings) {
                    healthScore += reading * 10; // Example calculation
                }
                status.second.health_metrics["health_score"] = healthScore;

                TreeNode* node = tree_manager.getNode(status.first);
                if (node) {
                    node->device_status = status.second;
                }
            }
        });

        // Push health scores to central dashboard
        for (const auto& [id, status] : statuses) {
            std::cout << "Device: " << id << ", Health Score: " << status.health_metrics["health_score"] << std::endl;
        }
    }

    void handleAlerts(const std::function<void(const DeviceStatus&)>& alertCallback) {
        // Check for alerts
        for (auto& node : tree_manager.nodes) {
            if (node.second->device_status.health_metrics["health_score"] > 80.0) {
                alertCallback(node.second->device_status);
            }
        }
    }

    void sendDataToCloud(const std::function<void(const std::unordered_map<std::string, DeviceStatus>&)>& callback) {
        // Simulate sending data to cloud
        std::unordered_map<std::string, DeviceStatus> statuses;
        for (auto& node : tree_manager.nodes) {
            statuses[node.first] = node.second->device_status;
        }
        callback(statuses);
    }

private:
    asio::io_context io_context;
};

int main() {
    RESTfulAPI api;
    api.computeHealthScores();
    api.handleAlerts([](const DeviceStatus& status) {
        std::cout << "Alert: Health score exceeded for device " << status.ip_address << std::endl;
    });
    api.sendDataToCloud([](const auto& statuses) {
        // Simulate sending data to cloud
        std::cout << "Sending data to cloud:" << std::endl;
        for (const auto& [id, status] : statuses) {
            std::cout << id << ": ";
            for (const auto& [sensor, reading] : status.sensor_readings) {
                std::cout << sensor << "=" << reading << ", ";
            }
            std::cout << std::endl;
        }
    });
    return 0;
}
