// Define constants for KDF settings
#define MAX_ITERATIONS 1024 * 1024
#define DEFAULT_ITERATIONS 10000

// Function to derive key using PBKDF2 with configurable iteration counts and hash algorithms
void pbkdf2_derive_key(const char *password, const unsigned char *salt, size_t salt_len, int iterations, EVP_MD *digest, unsigned char *key, size_t key_len) {
    PKCS5_PBKDF2_HMAC(password, strlen(password), salt, salt_len, iterations, digest, key_len, key);
}

// Function to generate a cryptographically secure IV
void generate_iv(unsigned char *iv, size_t iv_len) {
    if (!RAND_bytes(iv, iv_len)) {
        fprintf(stderr, "Failed to generate random bytes for IV\n");
        exit(EXIT_FAILURE);
    }
}

// Thread-safe function to handle encryption
void encrypt(const unsigned char *plaintext, size_t plaintext_len, const unsigned char *key, const unsigned char *iv, unsigned char **ciphertext, size_t *ciphertext_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return;
    }

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Encryption initialization failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    *ciphertext_len = plaintext_len + EVP_CIPHER_block_size(EVP_aes_256_cbc());
    *ciphertext = malloc(*ciphertext_len);
    if (!*ciphertext) {
        fprintf(stderr, "Failed to allocate memory for ciphertext\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    int len;
    if (1 != EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintext_len)) {
        fprintf(stderr, "Encryption update failed\n");
        free(*ciphertext);
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    size_t ciphertext_written = len;

    if (1 != EVP_EncryptFinal_ex(ctx, (*ciphertext + len), &len)) {
        fprintf(stderr, "Encryption finalization failed\n");
        free(*ciphertext);
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    *ciphertext_len = ciphertext_written + len;

    EVP_CIPHER_CTX_free(ctx);
}

// Thread-safe function to handle decryption
void decrypt(const unsigned char *ciphertext, size_t ciphertext_len, const unsigned char *key, const unsigned char *iv, unsigned char **plaintext, size_t *plaintext_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return;
    }

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Decryption initialization failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    *plaintext_len = ciphertext_len;
    *plaintext = malloc(*plaintext_len);
    if (!*plaintext) {
        fprintf(stderr, "Failed to allocate memory for plaintext\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    int len;
    if (1 != EVP_DecryptUpdate(ctx, *plaintext, &len, ciphertext, ciphertext_len)) {
        fprintf(stderr, "Decryption update failed\n");
        free(*plaintext);
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    size_t plaintext_written = len;

    if (1 != EVP_DecryptFinal_ex(ctx, (*plaintext + len), &len)) {
        fprintf(stderr, "Decryption finalization failed\n");
        free(*plaintext);
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    *plaintext_len = plaintext_written + len;

    EVP_CIPHER_CTX_free(ctx);
}

