#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>

// Configuration Manager Interface
class ConfigurationManager {
public:
    virtual ~ConfigurationManager() = default;
    virtual void updateConfig(const std::string& tenantId, const std::string& config) = 0;
    virtual std::string getConfig(const std::string& tenantId) = 0;
    virtual void subscribeToChanges(const std::string& tenantId, std::function<void(const std::string&, const std::string&)> callback) = 0;
};

// Configuration Manager Implementation
class ConfigManager : public ConfigurationManager {
private:
    std::unordered_map<std::string, std::string> configs;
    std::unordered_map<std::string, std::vector<std::function<void(const std::string&, const std::string&)>>> subscribers;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void updateConfig(const std::string& tenantId, const std::string& config) override {
        std::unique_lock<std::mutex> lock(mtx);
        configs[tenantId] = config;
        cv.notify_all();
        for (auto& sub : subscribers[tenantId]) {
            sub(tenantId, config);
        }
    }

    std::string getConfig(const std::string& tenantId) override {
        std::unique_lock<std::mutex> lock(mtx);
        return configs[tenantId];
    }

    void subscribeToChanges(const std::string& tenantId, std::function<void(const std::string&, const std::string&)> callback) override {
        subscribers[tenantId].push_back(callback);
    }
};

// Secure Configuration Manager with Encryption
class SecureConfigManager : public ConfigurationManager {
private:
    ConfigManager configManager;
    std::mutex encryptionMtx;

public:
    void updateConfig(const std::string& tenantId, const std::string& config) override {
        std::unique_lock<std::mutex> lock(encryptionMtx);
        // Simulate encryption
        auto encryptedConfig = "encrypted_" + config;
        configManager.updateConfig(tenantId, encryptedConfig);
    }

    std::string getConfig(const std::string& tenantId) override {
        std::unique_lock<std::mutex> lock(encryptionMtx);
        // Simulate decryption
        auto encryptedConfig = configManager.getConfig(tenantId);
        return encryptedConfig.substr(9); // Remove "encrypted_" prefix
    }

    void subscribeToChanges(const std::string& tenantId, std::function<void(const std::string&, const std::string&)> callback) override {
        configManager.subscribeToChanges(tenantId, callback);
    }
};

// Distributed Cache Manager with Automatic Invalidation
class DistributedCacheManager : public ConfigurationManager {
private:
    SecureConfigManager secureConfigManager;
    std::unordered_map<std::string, std::string> cache;
    std::mutex cacheMtx;

public:
    void updateConfig(const std::string& tenantId, const std::string& config) override {
        secureConfigManager.updateConfig(tenantId, config);
        std::unique_lock<std::mutex> lock(cacheMtx);
        cache[tenantId] = "cached_" + config; // Simulate caching
    }

    std::string getConfig(const std::string& tenantId) override {
        std::unique_lock<std::mutex> lock(cacheMtx);
        return cache[tenantId].substr(7); // Remove "cached_" prefix
    }

    void subscribeToChanges(const std::string& tenantId, std::function<void(const std::string&, const std::string&)> callback) override {
        secureConfigManager.subscribeToChanges(tenantId, [this, callback](const std::string& tId, const std::string& config){
            cache[tId] = "cached_" + config; // Update cache on change
            callback(tId, cache[tId]);
        });
    }
};

int main() {
    DistributedCacheManager manager;
    manager.updateConfig("tenant1", "configValue1");
    std::cout << "Config for tenant1: " << manager.getConfig("tenant1") << std::endl;

    return 0;
}
