// Define the NFAPI_CRC_INDICATION_PDU_T structure
struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    // Other fields...
};

// Graph node class representing an NFAPI_CRC_INDICATION_PDU_T
class GraphNode {
private:
    std::mutex mutex_;
    NFAPI_CRC_INDICATION_PDU_T data_;
    std::vector<std::pair<GraphNode*, double>> edges_; // Edges with latency metrics

public:
    GraphNode(const NFAPI_CRC_INDICATION_PDU_T& data) : data_(data), edges_() {}

    void addEdge(GraphNode* neighbor, double latency) {
        std::lock_guard<std::mutex> lock(mutex_);
        edges_.push_back({neighbor, latency});
    }

    // Thread-safe operations
    NFAPI_CRC_INDICATION_PDU_T getData() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return data_;
    }

    void setData(const NFAPI_CRC_INDICATION_PDU_T& newData) {
        std::lock_guard<std::mutex> lock(mutex_);
        data_ = newData;
    }

    // Efficient memory management
    ~GraphNode() {
        for (auto& edge : edges_) {
            delete edge.first; // Assuming ownership of neighbor nodes
        }
    }
};

// Network management platform class
class NetworkManagementPlatform {
private:
    std::vector<GraphNode*> nodes_;

public:
    void addNode(const NFAPI_CRC_INDICATION_PDU_T& data) {
        nodes_.push_back(new GraphNode(data));
    }

    void connectNodes(GraphNode* node1, GraphNode* node2, double latency) {
        node1->addEdge(node2, latency);
        node2->addEdge(node1, latency); // For an undirected graph
    }

    ~NetworkManagementPlatform() {
        for (auto& node : nodes_) {
            delete node;
        }
    }
};

int main() {
    NetworkManagementPlatform platform;

    NFAPI_CRC_INDICATION_PDU_T data1 = {1, 2};
    NFAPI_CRC_INDICATION_PDU_T data2 = {3, 4};

    platform.addNode(data1);
    platform.addNode(data2);

    GraphNode* node1 = platform.nodes_.front();
    GraphNode* node2 = platform.nodes_.back();

    platform.connectNodes(node1, node2, 0.5); // Simulating latency

    return 0;
}
