// src/lib.rs

#![deny(missing_docs)]

use aes_gcm::{Aes128Gcm, Key, Nonce};
use pbkdf2::pbkdf2;
use rand::{self, RngCore};
use sha2::{Sha256, Digest};
use std::sync::Mutex;
use tokio::sync::RwLock;

#[derive(Debug)]
pub struct EncryptionLibrary {
    key: Mutex<Key<Aes128Gcm>>,
}

impl EncryptionLibrary {
    pub fn new(password: &str, salt: &[u8], iteration_count: u32) -> Result<Self, Box<dyn std::error::Error>> {
        let mut hasher = Sha256::new();
        pbkdf2(password.as_bytes(), salt, iteration_count as usize, hasher.output_size(), |i| hasher.update(i));
        let key = Key::<Aes128Gcm>::from_slice(&hasher.finalize());
        Ok(Self { key: Mutex::new(key) })
    }

    pub async fn encrypt(&self, plaintext: &[u8]) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
        let mut rng = rand::thread_rng();
        let nonce: [u8; 12] = rng.generate();
        let cipher = Aes128Gcm::new(self.key.lock().unwrap());
        Ok(cipher.encrypt(&Nonce::from_slice(&nonce), plaintext))
    }

    pub async fn decrypt(&self, ciphertext: &[u8]) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
        let cipher = Aes128Gcm::new(self.key.lock().unwrap());
        Ok(cipher.decrypt(&Nonce::from_slice(&ciphertext[..12]), &ciphertext[12..]))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_encrypt_decrypt() -> Result<(), Box<dyn std::error::Error>> {
        let password = "my_secure_password";
        let salt: &[u8] = b"unique_salt_1234567890";
        let iteration_count = 10000;
        let lib = EncryptionLibrary::new(password, salt, iteration_count)?;
        let plaintext = b"Hello, secure world!";
        let encrypted = lib.encrypt(plaintext).await?;
        let decrypted = lib.decrypt(&encrypted).await?;
        assert_eq!(decrypted, plaintext);
        Ok(())
    }
}
```

