#define CRC_INDICATION_REL8_TAG unsigned char

NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_pdu(int num_pdus) {
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdus == NULL) {
        perror("Failed to allocate memory for PDUs");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_pdus; i++) {
        pdus[i].rx_ue_information_tag = rand();
        pdus[i].rnti = rand() % 65536;
        pdus[i].crc_indication_rel8_tag = rand() & 1;
    }

    return pdus;
}

