        fprintf(stderr, "Usage: %s <num_pdus>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int num_pdus = atoi(argv[1]);
    NFAPI_CRC_INDICATION_PDU_T* pdus = create_nfaapi_pdu(num_pdus);

    if (pdus != NULL) {
        printf("Successfully created %d NFAPI CRC INDICATION PDUs\n", num_pdus);
