typedef struct ChannelQualityIndication {
    double signal_strength;
    double noise_level;
    double interference_level;
} ChannelQualityIndication;

typedef struct FrameMetadata {
    int frame_id;
    time_t timestamp;
    ChannelQualityIndication *cqis;
    int cqis_count;
} FrameMetadata;

typedef struct ListNode {
    FrameMetadata metadata;
    struct ListNode *next;
} ListNode;

typedef struct LinkedList {
    ListNode *head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* linked_list_create() {
    LinkedList *list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void linked_list_destroy(LinkedList *list) {
    ListNode *current = list->head;
    while (current != NULL) {
        ListNode *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void linked_list_append(LinkedList *list, FrameMetadata metadata) {
    pthread_mutex_lock(&list->lock);
    ListNode *new_node = (ListNode*)malloc(sizeof(ListNode));
    new_node->metadata = metadata;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void linked_list_iterate(LinkedList *list, void (*callback)(FrameMetadata)) {
    pthread_mutex_lock(&list->lock);
    ListNode *current = list->head;
    while (current != NULL) {
        callback(current->metadata);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Add more functions as needed for filtering, average computation, etc.

int main() {
    // Example usage
    LinkedList *list = linked_list_create();
    FrameMetadata metadata = {1, time(NULL), NULL, 0};
    linked_list_append(list, metadata);
    linked_list_iterate(list, [](FrameMetadata md) {
        printf("Frame ID: %d\n", md.frame_id);
        // Add more processing as needed
    });
    linked_list_destroy(list);
    return 0;
}
