// Simulated market data vendor interface
class MarketDataVendor {
public:
    virtual std::string getMarketData() = 0;
    virtual ~MarketDataVendor() {}
};

// Example of a simple market data vendor implementation
class SampleVendor : public MarketDataVendor {
public:
    std::string getMarketData() override {
        // Simulate network delay and random data generation
        std::this_thread::sleep_for(std::chrono::milliseconds(rand() % 100));
        return "Sample Data";
    }
};

// Thread pool to manage concurrent processing
class ThreadPool {
private:
    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;
    std::atomic<bool> stop;

public:
    ThreadPool(size_t numThreads) : stop(false) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    if (tasks.wait_and_pop(task, stop)) {
                        task();
                    } else {
                        break;
                    }
                }
            });
        }
    }

    ~ThreadPool() {
        stop.store(true);
        for (auto& worker : workers) {
            worker.join();
        }
    }

    template<class F, class... Args>
    auto enqueue(F&& f, Args&&... args) -> std::future<typename std::result_of<F(Args...)>::type> {
        using return_type = typename std::result_of<F(Args...)>::type;

        auto task = std::make_shared<std::packaged_task<return_type()>>(
            std::bind(std::forward<F>(f), std::forward<Args>(args)...)
        );

        std::future<return_type> res = task->get_future();
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            if (stop.load()) {
                throw std::runtime_error("enqueue on stopped ThreadPool");
            }
            tasks.emplace([task]() { (*task)(); });
        }
        condition.notify_one();
        return res;
    }

private:
    mutable std::mutex queue_mutex;
    std::condition_variable condition;
};

// Example function to process market data
void processMarketData(const std::string& data) {
    // Simulate processing time and output result
    std::this_thread::sleep_for(std::chrono::milliseconds(rand() % 50));
    std::cout << "Processed Data: " << data << std::endl;
}

int main() {
    // Create a thread pool with 4 threads
    ThreadPool pool(4);

    // Simulate connecting to 15 market data vendors
    std::vector<MarketDataVendor*> vendors;
    for (int i = 0; i < 15; ++i) {
        vendors.push_back(new SampleVendor());
    }

    // Submit tasks to process data from each vendor
    for (auto& vendor : vendors) {
        pool.enqueue([vendor]() {
            try {
                std::string data = vendor->getMarketData();
                processMarketData(data);
            } catch (const std::exception& e) {
                std::cerr << "Error processing data: " << e.what() << std::endl;
            }
        });
    }

    // Clean up vendors
    for (auto& vendor : vendors) {
        delete vendor;
    }

    return 0;
}
