    GeolocationServiceCache cache;

    // Add new entries to the cache or update existing ones
    CacheEntry entry1;
    entry1.location = "New York";
    entry1.latency = 50 ms;
    entry1.failureRate = 2%;
    cache.updateEntry("New York", entry1);

    CacheEntry entry2;
    entry2.location = "Los Angeles";
    entry2.latency = 70 ms;
    entry2.failureRate = 3%;
    cache.updateEntry("Los Angeles", entry2);

    // Query the cache for specific locations and compute aggregated metrics such as average latency and failure rates
    CacheEntry result1 = cache.queryCache("New York");
    std::cout << "Latency for New York: " << result1.latency.count() << " ms" << std::endl;
    std::cout << "Failure rate for New York: " << result1.failureRate << std::endl;

    // Offer filtering capabilities based on time ranges or geographic proximity
    auto filteredEntries = cache.filterEntries("North America", std::chrono::system_clock::now() - std::chrono::hours(24), std::chrono::system_clock::now());
    for (const auto& entry : filteredEntries) {
        std::cout << "Location: " << entry.location << ", Latency: " << entry.latency.count() << " ms, Failure rate: " << entry.failureRate << std::endl;
    }

    // Implement a sophisticated backoff strategy and fallback mechanism using cached data to ensure system responsiveness and reliability under high load and network disruptions
    CacheEntry result2 = cache.getEntryWithFallback("New York", std::chrono::system_clock::now());
    std::cout << "Latency for New York (with fallback): " << result2.latency.count() << " ms" << std::endl;
    std::cout << "Failure rate for New York (with fallback): " << result2.failureRate << std::endl;

    return 0;
}
