class DynamicMetricsAggregator {
public:
    DynamicMetricsAggregator(size_t numThreads) : stop(false), threadPool(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            threadPool[i] = std::thread(&DynamicMetricsAggregator::worker, this);
        }
    }

    ~DynamicMetricsAggregator() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& th : threadPool) {
            th.join();
        }
    }

    void addMetric(const std::string& source, const double& value) {
        {
            std::lock_guard<std::mutex> lock(mutex);
            metricsQueue.push({source, value});
        }
        condition.notify_one();
    }

private:
    struct Metric {
        std::string source;
        double value;
    };

    std::atomic<bool> stop;
    std::vector<std::thread> threadPool;
    std::queue<Metric> metricsQueue;
    std::mutex mutex;
    std::condition_variable condition;

    void worker() {
        while (true) {
            Metric metric;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condition.wait(lock, [this] { return !metricsQueue.empty() || stop; });
                if (stop && metricsQueue.empty()) {
                    return;
                }
                metric = std::move(metricsQueue.front());
                metricsQueue.pop();
            }
            processMetric(metric);
        }
    }

    void processMetric(const Metric& metric) {
        // Implement metric processing logic here
        std::cout << "Processing metric from " << metric.source << ": " << metric.value << std::endl;
    }
};

int main() {
    DynamicMetricsAggregator aggregator(4);

    aggregator.addMetric("internal_system", 123.45);
    aggregator.addMetric("external_api", 67.89);

    return 0;
}
