// Define encryption modes
typedef enum {
    ECB,
    EDE3,
    CFB,
    NULL_ENCRYPTION
} EncryptionMode;

// Define cryptographic context structure
typedef struct {
    EncryptionMode mode;
    unsigned char key[24]; // Maximum key length for Triple DES
    int key_length; // Actual key length used
    void (*encrypt)(unsigned char *, const unsigned char *, int);
    void (*decrypt)(unsigned char *, const unsigned char *, int);
} CryptoContext;

// Function prototypes for encryption modes
void ecb_encrypt(unsigned char *output, const unsigned char *input, int length);
void ecb_decrypt(unsigned char *output, const unsigned char *input, int length);
void ede3_encrypt(unsigned char *output, const unsigned char *input, int length);
void ede3_decrypt(unsigned char *output, const unsigned char *input, int length);
void cfb_encrypt(unsigned char *output, const unsigned char *input, int length);
void cfb_decrypt(unsigned char *output, const unsigned char *input, int length);

// Initialize cryptographic context
CryptoContext* crypto_context_init(EncryptionMode mode, const unsigned char *key, int key_length) {
    CryptoContext *ctx = (CryptoContext *)malloc(sizeof(CryptoContext));
    ctx->mode = mode;
    memcpy(ctx->key, key, key_length);
    ctx->key_length = key_length;

    switch(mode) {
        case ECB:
            ctx->encrypt = ecb_encrypt;
            ctx->decrypt = ecb_decrypt;
            break;
        case EDE3:
            ctx->encrypt = ede3_encrypt;
            ctx->decrypt = ede3_decrypt;
            break;
        case CFB:
            ctx->encrypt = cfb_encrypt;
            ctx->decrypt = cfb_decrypt;
            break;
        case NULL_ENCRYPTION:
            ctx->encrypt = NULL;
            ctx->decrypt = NULL;
            break;
    }

    return ctx;
}

// Function to perform encryption
void crypto_encrypt(CryptoContext *ctx, unsigned char *output, const unsigned char *input, int length) {
    if (ctx->encrypt != NULL) {
        ctx->encrypt(output, input, length);
    } else {
        memcpy(output, input, length); // Null encryption copies data as is
    }
}

// Function to perform decryption
void crypto_decrypt(CryptoContext *ctx, unsigned char *output, const unsigned char *input, int length) {
    if (ctx->decrypt != NULL) {
        ctx->decrypt(output, input, length);
    } else {
        memcpy(output, input, length); // Null encryption copies data as is
    }
}

// Free cryptographic context
void crypto_context_free(CryptoContext *ctx) {
    free(ctx);
}
