typedef struct Logger {
    void (*log)(const char*);
} Logger;

typedef struct ConfigManager {
    int (*getConfigInt)(const char* key);
} ConfigManager;

char* process_and_append_slash(const char* source, size_t size_limit, char* output_buffer, size_t buffer_size, Logger* logger, ConfigManager* config_manager) {
    // Check if the source string is empty or null
    if (source == NULL || *source == '\0') {
        logger->log("Empty or null source string.");
        return NULL;
    }

    // Calculate the required length for the output buffer
    size_t required_length = strlen(source) + 1 + 1; // +1 for slash, +1 for null terminator

    // Check if the required length exceeds the buffer size
    if (required_length > buffer_size) {
        logger->log("Buffer overflow detected. Source string too long.");
        return NULL;
    }

    // Append a slash and null-terminate the output buffer
    snprintf(output_buffer, buffer_size, "%s/", source);

    // Log successful operation
    logger->log("Successfully appended slash to string.");

    return output_buffer;
}

// Example usage
int main() {
    Logger logger = { .log = printf };
    ConfigManager config_manager = { .getConfigInt = NULL };

    char source[] = "example";
    size_t size_limit = 1024;
    char output_buffer[1024];

    process_and_append_slash(source, size_limit, output_buffer, sizeof(output_buffer), &logger, &config_manager);

    printf("Output: %s\n", output_buffer);

    return 0;
}
