#include <iostream>
#include <vector>
#include <thread>
#include <atomic>
#include <mutex>
#include <condition_variable>

// Define record structure
struct Record {
    int key;
    long offset;
    std::int64_t value;
};

class DistributedCache {
public:
    DistributedCache(size_t num_threads, size_t memory_limit)
        : max_memory(memory_limit), thread_pool(num_threads) {}

    void populateRecords(size_t num_records, int range_min, int range_max) {
        std::vector<std::thread> threads;
        for (size_t i = 0; i < num_records; ++i) {
            threads.emplace_back(&DistributedCache::populateRecord, this, range_min, range_max);
        }
        for (auto& t : threads) {
            t.join();
        }
    }

    int getAverageValue() const {
        std::lock_guard<std::mutex> lock(mutex);
        return total_value / record_count;
    }

private:
    size_t max_memory = 0;
    size_t current_memory = 0;
    size_t record_count = 0;
    int64_t total_value = 0;
    std::vector<Record> records;
    std::mutex mutex;
    std::condition_variable cv;
    std::vector<std::thread> thread_pool;

    void populateRecord(int range_min, int range_max) {
        Record record;
        record.key = rand() % (range_max - range_min + 1) + range_min;
        record.offset = rand() % 1024; // Assuming a small offset for simplicity
        record.value = rand();

        std::lock_guard<std::mutex> lock(mutex);
        if (current_memory + sizeof(Record) <= max_memory) {
            records.push_back(record);
            current_memory += sizeof(Record);
            total_value += record.value;
            ++record_count;
        } else {
            cv.notify_one(); // Signal that memory is available
        }
    }
};

int main() {
    DistributedCache cache(4, 1024 * 1024 * 1024); // 1 GB limit
    cache.populateRecords(1000000, 1, 1000);
    std::cout << "Average Value: " << cache.getAverageValue() << std::endl;
    return 0;
}
```

This code snippet defines a `DistributedCache` class that manages a distributed cache system with thread pooling and adaptive memory management. It includes methods to populate records asynchronously and retrieve the average value from the cached data. The main function demonstrates initializing and populating the cache with records and then computing the average value.']

