#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define FrameMetadata structure
typedef struct {
    int frame_id;
    time_t timestamp;
    // Other fields as needed
} FrameMetadata;

// Define ChannelQualityIndication structure
typedef struct {
    float signal_strength;
    float noise_level;
    float interference_level;
    // Other fields as needed
} ChannelQualityIndication;

// Define Node structure for linked list
typedef struct Node {
    FrameMetadata metadata;
    ChannelQualityIndication *channel_quality_indications;
    struct Node *next;
} Node;

// Define the FrameProcessor library
typedef struct {
    Node *head;
    // Other fields as needed
} FrameProcessor;

// Initialize FrameProcessor
void frame_processor_init(FrameProcessor *fp) {
    fp->head = NULL;
}

// Add a new frame to the linked list
void frame_processor_add_frame(FrameProcessor *fp, int frame_id, time_t timestamp, ChannelQualityIndication *channel_quality_indications) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate memory for new node");
        return;
    }

    new_node->metadata.frame_id = frame_id;
    new_node->metadata.timestamp = timestamp;
    new_node->channel_quality_indications = channel_quality_indications;
    new_node->next = fp->head;
    fp->head = new_node;
}

// Remove a frame from the linked list
void frame_processor_remove_frame(FrameProcessor *fp, int frame_id) {
    Node *current = fp->head;
    Node *previous = NULL;

    while (current != NULL) {
        if (current->metadata.frame_id == frame_id) {
            if (previous == NULL) {
                fp->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
}

// Get the head of the linked list
Node* frame_processor_get_head(FrameProcessor *fp) {
    return fp->head;
}

// Clean up FrameProcessor
void frame_processor_cleanup(FrameProcessor *fp) {
    Node *current = fp->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current);
        current = next;
    }
    fp->head = NULL;
}
