#define MAX_SLOTS 100000

typedef struct LTE_Uplink_Slot_Data {
    // Define the structure fields here
} LTE_Uplink_Slot_Data;

LTE_Uplink_Slot_Data *slot_pool[MAX_SLOTS];
int slot_count = 0;
pthread_mutex_t pool_mutex;

void init_uplink_slots() {
    pthread_mutex_init(&pool_mutex, NULL);

    for (int i = 0; i < MAX_SLOTS; i++) {
        slot_pool[i] = malloc(sizeof(LTE_Uplink_Slot_Data));
        if (!slot_pool[i]) {
            perror("Failed to allocate memory for LTE_Uplink_Slot_Data");
            exit(EXIT_FAILURE);
        }
        memset(slot_pool[i], 0, sizeof(LTE_Uplink_Slot_Data));
    }

    slot_count = MAX_SLOTS;
}

void *get_slot() {
    LTE_Uplink_Slot_Data *slot;

    pthread_mutex_lock(&pool_mutex);
    if (slot_count > 0) {
        slot = slot_pool[--slot_count];
    } else {
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }
    pthread_mutex_unlock(&pool_mutex);

    return slot;
}

void release_slot(LTE_Uplink_Slot_Data *slot) {
    pthread_mutex_lock(&pool_mutex);
    if (slot_count < MAX_SLOTS) {
        slot_pool[slot_count++] = slot;
    } else {
        // Handle overflow, e.g., log error
    }
    pthread_mutex_unlock(&pool_mutex);
}

void cleanup_slots() {
    pthread_mutex_lock(&pool_mutex);

    for (int i = 0; i < slot_count; i++) {
        free(slot_pool[i]);
    }

    slot_count = 0;
    pthread_mutex_unlock(&pool_mutex);
}
