// Define a structure to hold RSA key pair information
typedef struct {
    RSA *key;
    char *public_key_pem;
    char *private_key_pem;
} RSAKeyPair;

// Function to generate RSA key pair
RSAKeyPair* generate_rsa_key_pair(int key_size) {
    RSAKeyPair *key_pair = (RSAKeyPair *)malloc(sizeof(RSAKeyPair));
    key_pair->key = RSA_generate_key(key_size, 65537, NULL, NULL);
    if (!key_pair->key) {
        fprintf(stderr, "Failed to generate RSA key pair\n");
        free(key_pair);
        return NULL;
    }
    BIO *pub_bio = BIO_new(BIO_s_mem());
    PEM_write_bio_RSA_PUBKEY(pub_bio, key_pair->key);
    key_pair->public_key_pem = (char *)BIO_get_mem_data(pub_bio, NULL);
    BIO_free_all(pub_bio);

    BIO *priv_bio = BIO_new(BIO_s_mem());
    PEM_write_bio_RSAPrivateKey(priv_bio, key_pair->key, NULL, NULL, 0, NULL, NULL);
    key_pair->private_key_pem = (char *)BIO_get_mem_data(priv_bio, NULL);
    BIO_free_all(priv_bio);

    return key_pair;
}

// Function to securely delete RSA key pair from memory and external storage
void secure_delete_rsa_key_pair(RSAKeyPair *key_pair) {
    if (key_pair->public_key_pem) free(key_pair->public_key_pem);
    if (key_pair->private_key_pem) free(key_pair->private_key_pem);
    RSA_free(key_pair->key);
    memset(key_pair, 0, sizeof(RSAKeyPair));
    free(key_pair);
}

// Thread function to generate and manage RSA key pairs
void *rsa_key_management_thread(void *arg) {
    int key_size = *(int *)arg;
    RSAKeyPair *key_pair = generate_rsa_key_pair(key_size);
    if (key_pair) {
        // Code to store the key pair in external KMS goes here
        secure_delete_rsa_key_pair(key_pair);
    }
    return NULL;
}

int main() {
    int num_threads = 10;
    pthread_t threads[num_threads];
    int key_sizes[num_threads];

    for (int i = 0; i < num_threads; i++) {
        key_sizes[i] = 2048 + (i % 3) * 1024; // Variable key sizes from 2048 to 4096 bits
        pthread_create(&threads[i], NULL, rsa_key_management_thread, &key_sizes[i]);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
