const { execFile } = require('child_process');
const fs = require('fs');
const path = require('path');
const EventEmitter = require('events');

class CommandExecutionService extends EventEmitter {
    constructor(config) {
        super();
        this.config = config;
        this.database = new Database(config.database);
    }

    async executeCommand(command, params, onOutput, onError) {
        const child = execFile(command, params, { maxBuffer: Infinity }, (error, stdout, stderr) => {
            if (error) {
                onError(error);
                return;
            }
            onOutput(stdout, stderr);
        });

        child.stdout.on('data', data => this.emit('stdout', data));
        child.stderr.on('data', data => this.emit('stderr', data));
    }

    async fetchDataFromAPI(url, params) {
        const response = await fetch(`${this.config.apiUrl}/${url}`, { method: 'GET', headers: { 'Content-Type': 'application/json' } });
        if (!response.ok) {
            throw new Error(`API request failed with status ${response.status}`);
        }
        return await response.json();
    }

    async storeData(data, strategy) {
        try {
            switch (strategy) {
                case 'local':
                    await this.database.storeLocal(data);
                    break;
                case 'cloud':
                    await this.database.storeCloud(data);
                    break;
                default:
                    throw new Error('Invalid storage strategy');
            }
        } catch (error) {
            if (this.config.fallbackStrategy === 'in-memory') {
                await this.database.storeInMemory(data);
            } else {
                throw error;
            }
        }
    }

    async handleAPIUnavailability(backupUrl) {
        try {
            return await this.fetchDataFromAPI(backupUrl);
        } catch (error) {
            this.emit('alert', 'Primary API unavailable, using backup');
            return null; // or take other appropriate action
        }
    }

    processString(input, sizeLimit, onRestrictionExceeded) {
        if (input.length > sizeLimit) {
            console.warn(`Input exceeds size limit: ${input}`);
            onRestrictionExceeded(input);
            return input;
        }
        const result = `${input}/`;
        return result;
    }

    async startStressTest() {
        // Implement stress testing logic here
    }

    async deployService(containerOrchestration) {
        // Implement deployment logic using container orchestration
    }
}

class Database {
    constructor(config) {
        this.config = config;
    }

    async storeLocal(data) {
        await fs.promises.writeFile(path.join(this.config.dataPath, 'data.json'), JSON.stringify(data));
    }

    async storeCloud(data) {
        // Implement cloud storage logic here
    }

    async storeInMemory(data) {
        // Implement in-memory storage logic here
    }
}

// Usage example
const config = {
    apiUrl: 'https://api.example.com',
    database: { dataPath: '/data', fallbackStrategy: 'in-memory' },
};

const service = new CommandExecutionService(config);
service.on('stdout', data => console.log(`STDOUT: ${data}`));
service.on('stderr', data => console.error(`STDERR: ${data}`));
service.on('alert', message => console.warn(message));

service.executeCommand('ls', ['-la'], (stdout, stderr) => {
    console.log(stdout);
}, error => {
    console.error(error);
});

async function fetchData() {
    try {
        const data = await service.fetchDataFromAPI('endpoint', { param: 'value' });
        await service.storeData(data, 'local');
    } catch (error) {
        console.error(error);
    }
}

fetchData();
