public class ResourceService {

    private final ExecutorService executor = Executors.newFixedThreadPool(10);
    private final BlockingQueue<String> queue = new LinkedBlockingQueue<>();
    private final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();

    public String getMD5Hash(String id) {
        // Check cache first
        if (cache.containsKey(id)) {
            return cache.get(id);
        }

        // Retry mechanism with exponential backoff
        int retries = 3;
        for (int i = 0; i <= retries; i++) {
            try {
                String data = fetchDataFromDatabase(id);
                String hash = calculateMD5Hash(data);
                cache.put(id, hash);
                return hash;
            } catch (Exception e) {
                if (i == retries) throw e;
                Thread.sleep((long) Math.pow(2, i) * 100); // Exponential backoff
            }
        }

        throw new RuntimeException("Failed to retrieve data after multiple attempts");
    }

    public String updateResource(String id, String requestBody) {
