import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.TimeUnit;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpMethod;
import org.springframework.http.ResponseEntity;
import org.springframework.web.client.RestTemplate;

public class ResourceService {

    @Autowired
    private RestTemplate restTemplate;

    @Autowired
    private NoSqlDatabase noSqlDatabase;

    @Autowired
    private EventBus eventBus;

    private static final int MAX_RETRIES = 5;
    private static final long RETRY_INTERVAL = 200L; // milliseconds

    public String getMD5Hash(String id) {
        for (int attempt = 0; attempt <= MAX_RETRIES; attempt++) {
            try {
                return noSqlDatabase.retrieveMd5Hash(id);
            } catch (Exception e) {
                if (attempt == MAX_RETRIES) throw new RuntimeException("Failed to retrieve MD5 hash after multiple attempts", e);
                try { TimeUnit.MILLISECONDS.sleep(RETRY_INTERVAL * Math.pow(2, attempt)); } catch (InterruptedException ie) {}
            }
        }
        return null; // Unreachable due to exception throwing
    }

    public void updateResource(String id, String requestBody) {
        HttpHeaders headers = new HttpHeaders();
        headers.set("Content-Type", "application/json");

        HttpEntity<String> entity = new HttpEntity<>(requestBody, headers);
        ResponseEntity<Void> apiResponse = restTemplate.exchange("http://external-api/update", HttpMethod.PUT, entity, Void.class);

        if (apiResponse.getStatusCode().is2xxSuccessful()) {
            noSqlDatabase.updateResource(id, requestBody);
            eventBus.publishUpdateEvent(id);
        } else {
            // Log error and handle versioning conflicts
        }
    }

    public void deleteResource(String id) {
        boolean deletedFromApi = restTemplate.exchange("http://external-api/delete", HttpMethod.DELETE, null, Void.class).getStatusCode().is2xxSuccessful();
        if (deletedFromApi) {
            noSqlDatabase.markAsDeleted(id);
            eventBus.publishDeletionEvent(id);
        }
    }

    private String calculateMd5Hash(String data) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] hashBytes = md.digest(data.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
