@RestController
@RequestMapping("/resources")
public class ResourceController {
    private final ResourceHashService resourceHashService;

    public ResourceController(ResourceHashService resourceHashService) {
        this.resourceHashService = resourceHashService;
    }

    @GetMapping("/{id}/hash")
    public ResponseEntity<String> getResourceHash(@PathVariable String id) {
