        return new ResponseEntity<>(hash, HttpStatus.OK);
    }

    @PutMapping("/{id}")
    public ResponseEntity<Void> updateResource(@PathVariable String id, @RequestBody String requestBody) {
        resourceHashService.updateResource(id, requestBody);
        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<String> deleteResource(@PathVariable String id) {
        ResponseEntity<String> response = resourceHashService.deleteResource(id);
        return response;
    }
