    }

    void stopProcessing() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stopProcessingFlag = true;
        }
        cv.notify_all();
        if (dataProcessingThread.joinable()) {
            dataProcessingThread.join();
        }
    }

    void pushData(const std::string& data) {
        {
            std::unique_lock<std::mutex> lock(mutex);
            dataQueue.push(data);
        }
        cv.notify_one();
    }

private:
    void processData() {
        while (true) {
            std::string data;
            {
                std::unique_lock<std::mutex> lock(mutex);
                cv.wait(lock, [this] { return stopProcessingFlag || !dataQueue.empty(); });
                if (stopProcessingFlag && dataQueue.empty()) {
                    break;
                }
                data = dataQueue.front();
                dataQueue.pop();
            }

            // Process data
            std::cout << "Processing data: " << data << std::endl;

            // Simulate sending to analytics service with retry mechanism and exponential backoff
            sendToAnalyticsService(data);
