class DynamicDataPipeline {
public:
    DynamicDataPipeline(size_t queueCapacity, size_t numThreads)
        : queueCapacity(queueCapacity), numThreads(numThreads), running(true) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] { workerThread(); });
        }
    }

    ~DynamicDataPipeline() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            running = false;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void submitData(const std::string& data, int priority) {
        std::unique_lock<std::mutex> lock(mutex);
        while (queue.size() >= queueCapacity) {
            cv.wait(lock, [this] { return !running || queue.size() < queueCapacity; });
        }
        queue.push({data, priority});
        cv.notify_one();
    }

private:
    struct DataItem {
        std::string data;
        int priority;
    };

    void workerThread() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return !queue.empty() || !running; });
            if (!running && queue.empty()) {
                break;
            }
            DataItem item = queue.front();
            queue.pop();
            lock.unlock();

            processData(item.data);
        }
    }

    void processData(const std::string& data) {
        // Placeholder for actual data processing logic
        std::cout << "Processing: " << data << std::endl;
    }

    size_t queueCapacity;
    size_t numThreads;
    bool running;
    std::queue<DataItem> queue;
    std::vector<std::thread> workers;
    std::mutex mutex;
    std::condition_variable cv;
};

int main() {
    DynamicDataPipeline pipeline(100, 4);

    // Simulate data submission
    for (int i = 0; i < 200; ++i) {
        pipeline.submitData("Sensor Data " + std::to_string(i), i % 5);
    }

    return 0;
}
```

