            }
        } catch (DataRetrievalError e) {
            // Handle specific data retrieval errors
            if (attempt < maxRetries) {
                Thread.sleep((long) Math.pow(2, attempt) * 100);
            } else {
                throw new DataRetrievalException("Failed to retrieve resource after " + maxRetries + " attempts", e);
            }
        }
    }
