    private static final Logger logger = LoggerFactory.getLogger(ResourceManagementService.class);

    public void logMessageIfConditionMet(String condition, String... arguments) {
        if (evaluateCondition(condition)) {
            int maxAttempts = 3;
            for (int attempt = 1; attempt <= maxAttempts; attempt++) {
                try {
                    logFormattedMessage(arguments);
                    break; // Success, exit the loop
                } catch (LoggingException e) {
                    if (attempt == maxAttempts) {
                        logger.error("Failed to log message after {} attempts", maxAttempts, e);
                        throw e; // Re-throw exception if all attempts fail
                    }
                    long delay = calculateExponentialBackoff(attempt);
                    Thread.sleep(delay); // Wait before retrying
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                    logger.error("Logging thread interrupted", ie);
                    throw new LoggingException("Interrupted while logging message", ie);
                }
            }
        }
    }

    private boolean evaluateCondition(String condition) {
        // Implement condition evaluation logic here
        return true; // Placeholder
    }

    private void logFormattedMessage(String... arguments) throws LoggingException {
        try (Formatter formatter = new Formatter()) {
            String formattedMessage = formatter.format(arguments).toString();
            logger.error(formattedMessage);
        } catch (Exception e) {
            throw new LoggingException("Failed to format and log message", e);
        }
    }

    private long calculateExponentialBackoff(int attempt) {
        return 100 * (1L << attempt); // Simple exponential backoff
    }
}

class LoggingException extends Exception {
