class VideoStreamProcessor {
public:
    VideoStreamProcessor(int numStreams) : running(true), numConcurrentStreams(0) {
        for (int i = 0; i < numStreams; ++i) {
            workers.emplace_back(&VideoStreamProcessor::processStream, this);
        }
    }

    ~VideoStreamProcessor() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            running = false;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void addStream(const VideoStream& stream) {
        std::unique_lock<std::mutex> lock(mutex);
        streams.push(stream);
        condition.notify_one();
    }

private:
    void processStream() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !streams.empty() || !running; });
            if (!running && streams.empty()) {
                break;
            }
            VideoStream stream = streams.front();
            streams.pop();
            lock.unlock();

            // Process video stream
            processVideoStream(stream);
        }
    }

    void processVideoStream(const VideoStream& stream) {
        // Implement video processing logic here
    }

private:
    std::vector<std::thread> workers;
    std::queue<VideoStream> streams;
    std::mutex mutex;
    std::condition_variable condition;
    bool running;
    int numConcurrentStreams;
};
