    FrameMetadata metadata;
    ChannelQualityIndication *quality_indications;
    struct FrameNode *next;
} FrameNode;

typedef struct MediaStreamAnalyzer {
    FrameNode *head;
    pthread_mutex_t lock;
    // ... other fields
} MediaStreamAnalyzer;

void initializeMediaStreamAnalyzer(MediaStreamAnalyzer *analyzer) {
    analyzer->head = NULL;
    pthread_mutex_init(&analyzer->lock, NULL);
}

void addFrameToAnalyzer(MediaStreamAnalyzer *analyzer, FrameMetadata metadata, ChannelQualityIndication *quality_indications) {
    pthread_mutex_lock(&analyzer->lock);
    FrameNode *new_node = (FrameNode *)malloc(sizeof(FrameNode));
    new_node->metadata = metadata;
    new_node->quality_indications = quality_indications;
    new_node->next = analyzer->head;
    analyzer->head = new_node;
    pthread_mutex_unlock(&analyzer->lock);
}

double calculateAverageSignalQuality(MediaStreamAnalyzer *analyzer) {
    pthread_mutex_lock(&analyzer->lock);
    double total_signal = 0.0;
    int count = 0;
    FrameNode *current = analyzer->head;
    while (current != NULL) {
        for (int i = 0; current->quality_indications[i].signal_strength > 0; i++) {
            total_signal += current->quality_indications[i].signal_strength;
            count++;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&analyzer->lock);
    return (count > 0) ? (total_signal / count) : 0.0;
}

// ... other functions and data structures

