function asyncReduce(array, initialValue, callback, onComplete) {
    let accumulator = initialValue;
    const iterate = (index) => {
        if (index < array.length) {
            callback(accumulator, array[index], (newAccumulator) => {
                accumulator = newAccumulator;
                iterate(index + 1);
            });
        } else {
            onComplete(accumulator);
        }
    };
    iterate(0);
}

// Usage example
const numbers = [1, 2, 3, 4];
asyncReduce(numbers, 0, (acc, num) => {
    return new Promise((resolve) => {
        setTimeout(() => resolve(acc + num), 100); // Simulate async operation
    });
}, (result) => {
    console.log('Reduced result:', result);
});
