#include <vector>
#include <functional>
#include <thread>
#include <mutex>

class NetworkPerformanceMonitor {
public:
    void accumulate(const std::vector<int>& packetSizes, int initialValue, const std::function<void(int, int)>& callback) {
        std::lock_guard<std::mutex> lock(mutex_);
        int accumulatedValue = initialValue;
        for (int size : packetSizes) {
            accumulatedValue += size;
            // Asynchronously call the callback
            std::thread([=]() {
                callback(accumulatedValue, size);
            }).detach();
        }
    }

private:
    std::mutex mutex_;
};

// Example usage
void exampleCallback(int accumulatedValue, int currentPacketSize) {
    std::cout << "Accumulated Value: " << accumulatedValue << ", Current Packet Size: " << currentPacketSize << std::endl;
}

int main() {
    NetworkPerformanceMonitor monitor;
    std::vector<int> packetSizes = {1024, 2048, 512, 2048, 1024};
    int initialValue = 0;

    monitor.accumulate(packetSizes, initialValue, exampleCallback);

    return 0;
}
