import java.util.concurrent.TimeUnit;

public class LogService {
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(3);

    public void logMessageIfConditionMet(String condition, String... arguments) {
        if (evaluatesToTrue(condition)) {
            CompletableFuture.runAsync(() -> logWithRetry(arguments), scheduler);
        }
    }

    private boolean evaluatesToTrue(String condition) {
        // Implement condition evaluation logic here
        return true;
    }

    private void logWithRetry(String[] arguments) {
        int maxRetries = 3;
        long initialDelay = 100; // milliseconds
        for (int attempt = 0; attempt < maxRetries; attempt++) {
            try {
                performLog(arguments);
                return; // Log successful, exit retry loop
            } catch (Exception e) {
                if (attempt == maxRetries - 1) throw e;
                long delay = initialDelay * (1 << attempt); // Exponential backoff
                scheduler.schedule(() -> logWithRetry(arguments), delay, TimeUnit.MILLISECONDS);
            }
        }
    }

    private void performLog(String[] arguments) {
        // Implement actual logging logic here
        System.err.printf("Logging: %s\n", String.format(condition, (Object[]) arguments));
    }

    public static void main(String[] args) {
        LogService logService = new LogService();
        logService.logMessageIfConditionMet("%d > %d", 5, 3);
    }
}
