#include <iostream>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <future>
#include <queue>

template<typename T>
class KeyValueStore {
private:
    struct Value {
        T metrics;
        std::vector<T> transactionLog;
        size_t referenceCount = 0;
    };

    std::unordered_map<std::string, Value> data_;
    mutable std::mutex mutex_;
    std::condition_variable cv_;

public:
    void setValue(const std::string& key, const T& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (data_.find(key) != data_.end()) {
            data_[key].metrics = value;
        } else {
            data_[key] = {value};
        }
        cv_.notify_all();
    }

    T getValue(const std::string& key) const {
        std::lock_guard<std::mutex> lock(mutex_);
        if (data_.find(key) != data_.end()) {
            return data_[key].metrics;
        } else {
            throw std::runtime_error("Key not found");
        }
    }

    void incrementReferenceCount(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (data_.find(key) != data_.end()) {
            data_[key].referenceCount++;
        } else {
            throw std::runtime_error("Key not found");
        }
    }

    void decrementReferenceCount(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (data_.find(key) != data_.end()) {
            data_[key].referenceCount--;
            if (data_[key].referenceCount == 0) {
                data_.erase(key);
            }
        } else {
            throw std::runtime_error("Key not found");
        }
    }

    void iterateKeys(const std::string& start, const std::string& end, std::function<void(const std::string&, const T&)> callback) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = data_.lower_bound(start); it != data_.end() && it->first <= end; ++it) {
            callback(it->first, it->second.metrics);
        }
    }

    void asynchronousWrite(const std::string& key, const T& value, std::function<void()> onComplete) {
        auto future = std::async(std::launch::async, [this, key, value]() {
            setValue(key, value);
        });
        future.then(std::move(onComplete));
    }
};

int main() {
    KeyValueStore<int> store;
    store.setValue("key1", 42);
    int value = store.getValue("key1");
    std::cout << "Value: " << value << std::endl;

    store.asynchronousWrite("key2", 99, [](){
        std::cout << "Async write completed" << std::endl;
    });

    return 0;
}
