// batchReduceAsync.js
function batchReduceAsync(promises, initialValue, reducer) {
    let accumulator = initialValue;
    const limit = 5; // API rate limit
    const interval = 1000; // 1 second

    return new Promise((resolve, reject) => {
        function processNext() {
            if (promises.length === 0) {
                resolve(accumulator);
                return;
            }

            const promise = promises.shift();
            promise()
                .then(response => {
                    accumulator = reducer(accumulator, response);
                    setTimeout(processNext, interval);
                })
                .catch(error => {
                    console.error('Transient failure:', error);
                    setTimeout(() => processNext(), interval);
                });
        }

        for (let i = 0; i < limit && promises.length > 0; i++) {
            processNext();
        }
    });
}
