typedef struct ChannelQualityIndication {
    float signal_strength;
    float noise_level;
    float interference_level;
} ChannelQualityIndication;

typedef struct FrameMetadata {
    int frame_id;
    time_t timestamp;
    ChannelQualityIndication* quality_indications;
    size_t num_quality_indications;
} FrameMetadata;

typedef struct ListNode {
    FrameMetadata* data;
    struct ListNode* next;
} ListNode;

typedef struct LinkedList {
    ListNode* head;
    ListNode* tail;
    size_t length;
} LinkedList;

LinkedList* linked_list_create() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list) {
        list->head = NULL;
        list->tail = NULL;
        list->length = 0;
    }
    return list;
}

void linked_list_destroy(LinkedList* list) {
    ListNode* current = list->head;
    while (current) {
        ListNode* next = current->next;
        free(current->data->quality_indications);
        free(current->data);
        free(current);
        current = next;
    }
    free(list);
}

void linked_list_append(LinkedList* list, FrameMetadata* data) {
    ListNode* node = (ListNode*)malloc(sizeof(ListNode));
    if (node) {
        node->data = data;
        node->next = NULL;
        if (list->tail) {
            list->tail->next = node;
        } else {
            list->head = node;
        }
        list->tail = node;
        list->length++;
    }
}

FrameMetadata* linked_list_get(LinkedList* list, size_t index) {
    ListNode* current = list->head;
    for (size_t i = 0; i < index && current; i++) {
        current = current->next;
    }
    return current ? current->data : NULL;
}

