import java.util.Arrays;

public class DisjointPairsCounter {

    public static int countDisjointPairs(int[] nums) {
        if (nums == null || nums.length < 2) {
            return 0;
        }

        Arrays.sort(nums);

        UnionFind uf = new UnionFind(nums.length);
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] - nums[i - 1] > 1) {
                uf.union(i, i - 1);
            }
        }

        int disjointPairs = 0;
        for (int i = 1; i < nums.length; i++) {
            if (!uf.find(i).equals(uf.find(i - 1))) {
                disjointPairs++;
            }
        }

        return disjointPairs;
    }

    static class UnionFind {
        private final int[] parent;

        public UnionFind(int size) {
            this.parent = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public void union(int x, int y) {
            parent[find(x)] = find(y);
        }

        @Override
        public boolean equals(Object obj) {
            if (!(obj instanceof UnionFind)) {
                return false;
            }
            return Arrays.equals(((UnionFind) obj).parent, this.parent);
        }
    }

    public static void main(String[] args) {
        int[] nums = {1, 2, 3, 5, 6, 8, 9};
        System.out.println("Number of disjoint pairs: " + countDisjointPairs(nums));
    }
}
