use async_trait::async_trait;
use std::sync::Arc;
use tokio::sync::Mutex;
use reqwest::{Client, Error};
use chrono::Utc;
use serde_json::Value;

#[async_trait]
trait MetricsSource {
    async fn fetch_metrics(&self) -> Result<Value, Error>;
}

struct InternalSystem {}

#[async_trait]
impl MetricsSource for InternalSystem {
    async fn fetch_metrics(&self) -> Result<Value, Error> {
        // Implementation to fetch metrics from internal system
        Ok(json!({}))
    }
}

struct ThirdPartyAPI {
    client: Client,
}

#[async_trait]
impl MetricsSource for ThirdPartyAPI {
    async fn fetch_metrics(&self) -> Result<Value, Error> {
        // Implementation to fetch metrics from third-party API
        self.client.get("https://api.example.com/metrics").send().await?.json().await
    }
}

struct RateLimiter {
    limit: u32,
    remaining: u32,
    reset_time: chrono::DateTime<Utc>,
}

impl RateLimiter {
    fn new(limit: u32) -> Self {
        RateLimiter {
            limit,
            remaining: limit,
            reset_time: Utc::now() + chrono::Duration::minutes(1),
        }
    }

    async fn can_fetch(&mut self) -> bool {
        if self.remaining == 0 {
            if Utc::now() < self.reset_time {
                return false;
            } else {
                self.remaining = self.limit;
                self.reset_time = Utc::now() + chrono::Duration::minutes(1);
            }
        }
        self.remaining -= 1;
        true
    }
}

struct MetricAggregator {
    sources: Vec<Box<dyn MetricsSource>>,
    rate_limiter: Arc<Mutex<RateLimiter>>,
    cache: Arc<Mutex<Vec<Value>>>,
}

impl MetricAggregator {
    fn new(sources: Vec<Box<dyn MetricsSource>>, limit: u32) -> Self {
        MetricAggregator {
            sources,
            rate_limiter: Arc::new(Mutex::new(RateLimiter::new(limit))),
            cache: Arc::new(Mutex::new(Vec::new())),
        }
    }

    async fn aggregate_metrics(&self) -> Result<Vec<Value>, Error> {
        let mut aggregated = Vec::new();
        for source in &self.sources {
            if self.rate_limiter.lock().await.can_fetch().await {
                let metrics = source.fetch_metrics().await?;
                aggregated.extend(metrics.as_array().unwrap());
            } else {
                // Handle rate limiting
            }
        }
        // Cache aggregation results
        *self.cache.lock().await = aggregated.clone();
        Ok(aggregated)
    }
}

#[tokio::main]
async fn main() -> Result<(), Error> {
    let sources: Vec<Box<dyn MetricsSource>> = vec![
        Box::new(InternalSystem {}),
        Box::new(ThirdPartyAPI { client: Client::new() }),
    ];
    let aggregator = MetricAggregator::new(sources, 10);
    let metrics = aggregator.aggregate_metrics().await?;
    println!("{:?}", metrics);
    Ok(())
}
