class CachingSystem {
public:
    void AddURL(const std::string& url, const std::string& headerData) {
        std::unique_lock<std::mutex> lock(mutex_);
        cache_[url] = headerData;
        cv_.notify_all();
    }

    std::string GetHeaderData(const std::string& url) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (cache_.find(url) == cache_.end()) {
            cv_.wait(lock);
        }
        return cache_[url];
    }

private:
    std::unordered_map<std::string, std::string> cache_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

int main() {
    CachingSystem system;
    system.AddURL("https://example.com", "HTTP/1.1 200 OK");
    std::cout << system.GetHeaderData("https://example.com") << std::endl;
    return 0;
}
