impl CompilationCache {
    fn new() -> Self {
        CompilationCache {
            cache: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    async fn get_or_compile(&self, lang: Language, source_code: &[u8]) -> Option<String> {
        // Check if LLVM IR is already in the cache
        let mut cache = self.cache.lock().unwrap();
        if let Some(ir) = cache.get(lang.as_str()) {
