using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Polly;
using Prometheus;

namespace FinancialTransactionProcessor
{
    public class TransactionProcessor
    {
        private readonly ILogger<TransactionProcessor> _logger;
        private readonly IMarketDataApiClient _marketDataApi;
        private readonly IRegulatoryComplianceApiClient _regulatoryComplianceApi;
        private readonly IPaymentGatewayClient _paymentGateway;
        private readonly IDistributedTransactionManager _distributedTransactionManager;

        public TransactionProcessor(ILogger<TransactionProcessor> logger, IMarketDataApiClient marketDataApi, 
            IRegulatoryComplianceApiClient regulatoryComplianceApi, IPaymentGatewayClient paymentGateway,
            IDistributedTransactionManager distributedTransactionManager)
        {
            _logger = logger;
            _marketDataApi = marketDataApi;
            _regulatoryComplianceApi = regulatoryComplianceApi;
            _paymentGateway = paymentGateway;
            _distributedTransactionManager = distributedTransactionManager;
        }

        [Prometheus.GaugeMetricAttribute("transaction_processing_time_seconds", "Time taken to process a transaction")]
        private readonly Gauge _transactionProcessingTime;

        public async Task ProcessTransaction(Transaction transaction)
        {
            using (var timer = new Timer())
            {
                try
                {
                    _logger.LogInformation($"Starting processing of transaction {transaction.Id}");

                    // Fetch market data
                    var marketData = await Policy.Handle<Exception>()
                        .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)))
                        .ExecuteAsync(() => _marketDataApi.GetMarketData(transaction.Symbol));

                    // Check regulatory compliance
                    if (!await _regulatoryComplianceApi.CheckCompliance(transaction))
                    {
                        _logger.LogError($"Transaction {transaction.Id} failed regulatory compliance check");
                        return;
                    }

                    // Process payment
                    await _paymentGateway.ProcessPayment(transaction);

                    // Commit transaction using distributed transaction manager
                    await _distributedTransactionManager.CommitTransaction(transaction, marketData);

                    _logger.LogInformation($"Processed transaction {transaction.Id} successfully");
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, $"Error processing transaction {transaction.Id}");
                }
                finally
                {
                    _transactionProcessingTime.Set(timer.Elapsed.TotalSeconds);
                }
            }
        }
    }

    public interface IMarketDataApiClient
    {
        Task<MarketData> GetMarketData(string symbol);
    }

    public interface IRegulatoryComplianceApiClient
    {
        Task<bool> CheckCompliance(Transaction transaction);
    }

    public interface IPaymentGatewayClient
    {
        Task ProcessPayment(Transaction transaction);
    }

    public interface IDistributedTransactionManager
    {
        Task CommitTransaction(Transaction transaction, MarketData marketData);
    }

    [Prometheus.GaugeMetricAttribute("transaction_count", "Number of transactions processed")]
    private readonly Gauge _transactionCount;

    [Prometheus.CounterMetricAttribute("error_count", "Total number of errors encountered")]
    private readonly Counter _errorCount;
}
