public class IoTAnomalyDetectionApplication {

    @Bean
    public KStream<String, String> processIoTData(StreamsBuilder streamsBuilder) {
        return streamsBuilder
                .stream("iot-sensor-data", Consumed.with(Serdes.String(), Serdes.String()))
                .peek((key, value) -> System.out.println("Processing IoT data: " + value))
                .to("processed-iot-data", Produced.with(Serdes.String(), Serdes.String()));
    }
}
