    public static void ValidateToken(string filePath)
    {
        try
        {
            string jsonContent = File.ReadAllText(filePath);
            var tokenData = Newtonsoft.Json.Linq.JObject.Parse(jsonContent);

            if (!tokenData.ContainsKey("access_token") ||
                !tokenData.ContainsKey("expires_in") ||
                !tokenData.ContainsKey("token_type"))
            {
                Console.WriteLine($"Error: Missing required fields in {filePath}");
                return;
            }

            string accessToken = tokenData["access_token"].ToString();
            int expiresIn = 0;

            if (!int.TryParse(tokenData["expires_in"].ToString(), out expiresIn) || expires <= 0)
            {
                Console.WriteLine($"Error: Invalid 'expires_in' value in {filePath}");
                return;
            }

            string tokenType = tokenData["token_type"].ToString();

            if (tokenType != "Bearer")
            {
                Console.WriteLine($"Error: Invalid 'token_type' value in {filePath}");
                return;
            }

            if (tokenData.ContainsKey("refresh_token"))
            {
                // Optional validation for refresh_token
                string refreshToken = tokenData["refresh_token"].ToString();
                // Additional checks can be added here
            }

            Console.WriteLine($"Token in {filePath} is valid.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error reading file or parsing JSON: {ex.Message}");
        }
    }

    static void Main(string[] args)
