    async fn convert(&self, input: String, output_format: &str) -> Result<String, String> {
        // Convert the media file to the specified format
        // Handle errors and return appropriate results
    }

    async fn handle_requests(&self, mut receiver: mpsc::Receiver<(String, String)>) {
        while let Some((input, output_format)) = receiver.recv().await {
            task::spawn(async move {
                if let Err(e) = self.convert(input.clone(), &output_format).await {
                    // Handle errors and log them
                    println!("Error converting {}: {}", input, e);
                } else {
                    // Log successful conversion
                    println!("Successfully converted {} to {}", input, output_format);
                }
            });
        }
    }

    async fn start_server(&self) {
        let (sender, receiver) = mpsc::channel(32);

        for _ in 0..4 { // Example: Start with 4 worker threads
            self.clone().handle_requests(receiver.clone()).await;
        }

        // Simulate incoming requests
