class ClinicStatusUpdaterController
{
    private $entityManager;

    public function __construct(EntityManagerInterface $entityManager)
    {
        $this->entityManager = $entityManager;
    }

    /**
     * @Route("/clinics/{id}/status", methods={"PUT"})
     */
    public function updateClinicStatus(Request $request, int $id): Response
    {
        $status = $request->get('status');

        try {
            // Validate input
            if (!is_numeric($id) || !in_array($status, ['open', 'closed'])) {
                throw new \InvalidArgumentException("Invalid clinic ID or status");
            }

            // Fetch clinic from external API
            $clinicData = $this->fetchClinicFromApi($id);
            if (!$clinicData) {
                throw new \Exception("Failed to fetch clinic data from API");
            }

            // Update clinic entity
            $clinic = $this->entityManager->getRepository(Clinic::class)->find($id);
            if ($clinic) {
                $clinic->setStatus($status);
                $clinic->setLastModifiedIp($request->server('REMOTE_ADDR'));
                $clinic->setLastModifiedDate(new \DateTime());
            } else {
                throw new \Exception("Clinic not found");
            }

            // Persist and flush changes
            $this->entityManager->flush();

            return new Response(json_encode(['message' => 'Clinic status updated successfully']), 200, ['Content-Type' => 'application/json']);
        } catch (\Exception $e) {
            // Log error details
            file_put_contents('error.log', date('Y-m-d H:i:s') . ' - ' . $e->getMessage() . "\n", FILE_APPEND);

            return new Response(json_encode(['error' => $e->getMessage()]), 500, ['Content-Type' => 'application/json']);
