package main

import (
	"crypto/rand"
	"crypto/rsa"
	"crypto/x509"
	"encoding/base64"
	"encoding/pem"
	"errors"
	"fmt"
	"log"
	"net/http"
	"os"
	"strconv"
	"strings"
	"time"

	"github.com/dgrijalva/jwt-go"
)

type JWTSigner struct {
	kmsClient KMSClient
	rsaKey    *rsa.PrivateKey
	cert      *x509.Certificate
}

func NewJWTSigner(kmsClient KMSClient) (*JWTSigner, error) {
	rsaKey, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		return nil, fmt.Errorf("failed to generate RSA key: %w", err)
	}

	cert, err := kmsClient.GetCertificate()
	if err != nil {
		return nil, fmt.Errorf("failed to get certificate from KMS: %w", err)
	}

	return &JWTSigner{
		kmsClient: kmsClient,
		rsaKey:    rsaKey,
		cert:      cert,
	}, nil
}

func (s *JWTSigner) GenerateJWT() (string, error) {
	now := time.Now()
	expiration := now.Add(10 * time.Minute)

	claims := jwt.StandardClaims{
		ExpiresAt: expiration.Unix(),
		IssuedAt:  now.Unix(),
	}

	token := jwt.NewWithClaims(jwt.SigningMethodRS256, claims)
	return token.SignedString(s.rsaKey)
}

func main() {
	kmsClient := NewKMSClient()

	signer, err := NewJWTSigner(kmsClient)
	if err != nil {
		log.Fatalf("Failed to create JWT signer: %v", err)
	}

	http.HandleFunc("/generate-jwt", func(w http.ResponseWriter, r *http.Request) {
		jwtToken, err := signer.GenerateJWT()
		if err != nil {
			http.Error(w, "Internal Server Error", http.StatusInternalServerError)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		fmt.Fprintf(w, `{"token": "%s"}`, jwtToken)
	})

	log.Println("Starting JWT service on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatalf("Failed to start server: %v", err)
	}
}

type KMSClient interface {
	GetCertificate() (*x509.Certificate, error)
}

type kmsClient struct{}

func NewKMSClient() KMSClient {
	return &kmsClient{}
}

func (c *kmsClient) GetCertificate() (*x509.Certificate, error) {
	// Implement logic to retrieve certificate from KMS
	certPEM := os.Getenv("KMS_CERTIFICATE")
	if certPEM == "" {
		return nil, errors.New("KMS_CERTIFICATE environment variable not set")
	}

	block, _ := pem.Decode([]byte(certPEM))
	if block == nil || block.Type != "CERTIFICATE" {
		return nil, errors.New("invalid certificate PEM format")
	}

	cert, err := x509.ParseCertificate(block.Bytes)
	if err != nil {
		return nil, fmt.Errorf("failed to parse certificate: %w", err)
	}

	return cert, nil
}
