using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

public class EventProcessor
{
    private readonly string _connectionString;

    public EventProcessor(string connectionString)
    {
        _connectionString = connectionString;
    }

    public void ExecuteParameterizedSqlCommand(string query, List<SqlParameter> parameters)
    {
        if (string.IsNullOrEmpty(query))
        {
            throw new ArgumentException("Query cannot be null or empty.", nameof(query));
        }

        if (parameters == null || parameters.Count == 0)
        {
            throw new ArgumentException("Parameters list cannot be null or empty.", nameof(parameters));
        }

        using (SqlConnection connection = new SqlConnection(_connectionString))
        {
            try
            {
                connection.Open();
                SqlCommand command = new SqlCommand(query, connection);
                command.Parameters.AddRange(parameters.ToArray());
                int rowsAffected = command.ExecuteNonQuery();
                Console.WriteLine($"{rowsAffected} row(s) affected.");
            }
            catch (SqlException ex)
            {
                Console.WriteLine($"SQL Error: {ex.Message}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"General Error: {ex.Message}");
            }
        }
    }
}
