// Function to dynamically load AES and Camellia ciphers
void load_ciphers() {
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_cipher(EVP_camellia_256_ecb());
}

// Function to dynamically load MD5 and SHA digest algorithms
void load_digests() {
    EVP_add_digest(EVP_md5());
    EVP_add_digest_alias("MD5", "md5");
    EVP_add_digest_alias("SHA", "sha1");
}

// Function to generate RSA key pair with SHA1 signatures
RSA* generate_rsa_key(int bits) {
    RSA *rsa = RSA_new();
    BIGNUM *e = BN_new();
    BN_set_word(e, RSA_F4);
    if (!RSA_generate_key_ex(rsa, bits, e, NULL)) {
        RSA_free(rsa);
        BN_free(e);
        return NULL;
    }
    BN_free(e);
    return rsa;
}

// Function to encrypt data using AES
int aes_encrypt(const unsigned char *plaintext, int plaintext_len,
               const unsigned char *key, const unsigned char *iv,
               unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int len;
    if (!EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int ciphertext_len = len;
    if (!EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len += len;
    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

// Function to decrypt data using AES
int aes_decrypt(const unsigned char *ciphertext, int ciphertext_len,
               const unsigned char *key, const unsigned char *iv,
               unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int len;
    if (!EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int plaintext_len = len;
    if (!EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext_len += len;
    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;
}

// Function to compute MD5 hash
void md5_hash(const unsigned char *data, int length, unsigned char *md5sum) {
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, data, length);
    MD5_Final(md5sum, &ctx);
}

// Function to compute SHA1 hash
void sha1_hash(const unsigned char *data, int length, unsigned char *sha1sum) {
    SHA_CTX sha1_ctx;
    SHA1_Init(&sha1_ctx);
    SHA1_Update(&sha1_ctx, data, length);
    SHA1_Final(sha1sum, &sha1_ctx);
}

// Function to sign data using RSA with SHA1
int rsa_sign(const unsigned char *data, int data_len,
             const RSA *rsa, unsigned char *signature) {
    EVP_MD_CTX *mdctx = EVP_MD_CTX_new();
    if (!EVP_SignInit_ex(mdctx, EVP_sha1(), NULL)) {
        EVP_MD_CTX_free(mdctx);
        return -1;
    }
    if (!EVP_SignUpdate(mdctx, data, data_len)) {
        EVP_MD_CTX_free(mdctx);
        return -1;
    }
    int siglen = RSA_size(rsa);
    if (!EVP_SignFinal_ex(mdctx, signature, &siglen, (RSA *)rsa)) {
        EVP_MD_CTX_free(mdctx);
        return -1;
    }
    EVP_MD_CTX_free(mdctx);
    return siglen;
}

// Function to verify signature using RSA with SHA1
int rsa_verify(const unsigned char *data, int data_len,
              const unsigned char *signature, int sig_len,
              const RSA *rsa) {
    EVP_MD_CTX *mdctx = EVP_MD_CTX_new();
    if (!EVP_VerifyInit_ex(mdctx, EVP_sha1(), NULL)) {
        EVP_MD_CTX_free(mdctx);
        return -1;
    }
    if (!EVP_VerifyUpdate(mdctx, data, data_len)) {
        EVP_MD_CTX_free(mdctx);
        return -1;
    }
    int ret = EVP_VerifyFinal_ex(mdctx, signature, sig_len, (RSA *)rsa);
    EVP_MD_CTX_free(mdctx);
    return ret;
}

// Thread function for handling requests
void* handle_request(void *arg) {
