    load_ciphers();
    load_digests();

    RSA *rsa = generate_rsa_key(2048);
    if (!rsa) {
        fprintf(stderr, "Failed to generate RSA key\n");
        return 1;
    }

    // Example usage of encryption and decryption
    unsigned char plaintext[] = "Hello, World!";
    unsigned char iv[16];
    unsigned char ciphertext[128];
    unsigned char decryptedtext[128];

    RAND_bytes(iv, sizeof(iv));
    int len = aes_encrypt(plaintext, strlen((char *)plaintext), (unsigned char *)"0123456789abcdef", iv, ciphertext);
    if (len == -1) {
        fprintf(stderr, "Encryption failed\n");
        RSA_free(rsa);
        return 1;
    }

    len = aes_decrypt(ciphertext, len, (unsigned char *)"0123456789abcdef", iv, decryptedtext);
    if (len == -1) {
        fprintf(stderr, "Decryption failed\n");
        RSA_free(rsa);
        return 1;
    }
    decryptedtext[len] = '\0';
    printf("Decrypted text: %s\n", decryptedtext);

    // Example usage of MD5 and SHA1 hashing
    unsigned char md5sum[MD5_DIGEST_LENGTH];
    unsigned char sha1sum[SHA_DIGEST_LENGTH];

    md5_hash(plaintext, strlen((char *)plaintext), md5sum);
    sha1_hash(plaintext, strlen((char *)plaintext), sha1sum);

    printf("MD5: ");
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        printf("%02x", md5sum[i]);
    }
    printf("\n");

    printf("SHA1: ");
    for (int i = 0; i < SHA_DIGEST_LENGTH; i++) {
        printf("%02x", sha1sum[i]);
    }
    printf("\n");

    // Example usage of RSA signing and verification
    unsigned char signature[256];
    int sig_len = rsa_sign(plaintext, strlen((char *)plaintext), rsa, signature);
    if (sig_len == -1) {
        fprintf(stderr, "Signature generation failed\n");
        RSA_free(rsa);
        return 1;
    }

    int verify_result = rsa_verify(plaintext, strlen((char *)plaintext), signature, sig_len, rsa);
    if (verify_result != 1) {
        fprintf(stderr, "Signature verification failed\n");
        RSA_free(rsa);
        return 1;
    }

    RSA_free(rsa);

    // Create a thread pool to handle concurrent requests
    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, handle_request, NULL);
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
