// Function to handle AES encryption and decryption
int aes_encrypt_decrypt(const unsigned char *plaintext, int plaintext_len, const unsigned char *key,
                       const unsigned char *iv, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new())) return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) goto err;
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) goto err;
    ciphertext_len = len;
    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) goto err;
    ciphertext_len += len;

err:
    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

// Function to handle RSA with SHA1 signatures
int rsa_sign_verify(const unsigned char *data, int data_len, const unsigned char *private_key,
                    unsigned char *signature, int signature_len, const unsigned char *public_key) {
