    if (!(pkey = d2i_PrivateKey(EVP_PKEY_RSA, NULL, &private_key, private_key_len))) goto err;
    rsa = EVP_PKEY_get0_RSA(pkey);
    if (1 != RSA_sign(NID_sha1, data, data_len, signature, &signature_len, rsa)) goto err;

    ret = 1;

err:
    EVP_PKEY_free(pkey);
    return ret;
}

