    private static readonly int MaxRetries = 5;
    private static readonly TimeSpan[] RetryIntervals = new TimeSpan[]
    {
        TimeSpan.FromSeconds(1),
        TimeSpan.FromSeconds(2),
        TimeSpan.FromSeconds(4),
        TimeSpan.FromSeconds(8),
        TimeSpan.FromSeconds(16)
    };

    public ServiceDeployer(string kubeConfigPath)
    {
        _kubernetesClient = KubernetesClientFactory.Create(kubeConfigPath);
    }

    public async Task<bool?> DeployServiceAsync(
        string serviceName,
        string dockerImageVersion,
        Dictionary<string, string> environmentVariables,
        string projectRootPath)
    {
        if (!File.Exists(Path.Combine(projectRootPath, "docker-compose.yml")) ||
            !File.Exists(Path.Combine(projectRootPath, "kubernetes-deployment.yaml")))
        {
            LogError("Missing configuration files.");
            return null;
        }

        for (int attempt = 0; attempt < MaxRetries; attempt++)
        {
            try
            {
                await DeployServiceCoreAsync(serviceName, dockerImageVersion, environmentVariables, projectRootPath);
                LogInfo($"Deployment of {serviceName} successful.");
                return true;
            }
            catch (Exception ex)
            {
                if (attempt == MaxRetries - 1)
                {
                    LogError($"Failed to deploy {serviceName} after {MaxRetries} attempts. Error: {ex.Message}");
                }
                else
                {
                    LogWarning($"Attempt {attempt + 1} failed. Retrying in {RetryIntervals[attempt]}...");
                    await Task.Delay(RetryIntervals[attempt]);
                }
            }
        }

        return null;
    }

    private async Task DeployServiceCoreAsync(
        string serviceName,
        string dockerImageVersion,
        Dictionary<string, string> environmentVariables,
        string projectRootPath)
