#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_PROVIDERS 10
#define CACHE_SIZE 1000

typedef struct {
    char token[256];
    time_t expiration;
} TokenEntry;

typedef struct {
    TokenEntry entries[CACHE_SIZE];
    int size;
    pthread_mutex_t lock;
} Cache;

Cache cache;

void init_cache() {
    memset(&cache, 0, sizeof(cache));
    pthread_mutex_init(&cache.lock, NULL);
}

int find_token(const char* token) {
    pthread_mutex_lock(&cache.lock);
    for (int i = 0; i < cache.size; ++i) {
        if (strcmp(cache.entries[i].token, token) == 0) {
            pthread_mutex_unlock(&cache.lock);
            return i;
        }
    }
    pthread_mutex_unlock(&cache.lock);
    return -1;
}

void add_token(const char* token, time_t expiration) {
    pthread_mutex_lock(&cache.lock);
    if (cache.size >= CACHE_SIZE) {
        // Evict the least recently used item
        int min_index = 0;
        time_t min_expiration = cache.entries[0].expiration;
        for (int i = 1; i < cache.size; ++i) {
            if (cache.entries[i].expiration < min_expiration) {
                min_index = i;
                min_expiration = cache.entries[i].expiration;
            }
        }
        memmove(&cache.entries[min_index], &cache.entries[min_index + 1], sizeof(TokenEntry) * (cache.size - min_index - 1));
        --cache.size;
    }
    strcpy(cache.entries[cache.size].token, token);
    cache.entries[cache.size].expiration = expiration;
    ++cache.size;
    pthread_mutex_unlock(&cache.lock);
}

void invalidate_token(const char* token) {
    pthread_mutex_lock(&cache.lock);
    for (int i = 0; i < cache.size; ++i) {
        if (strcmp(cache.entries[i].token, token) == 0) {
            memmove(&cache.entries[i], &cache.entries[i + 1], sizeof(TokenEntry) * (cache.size - i - 1));
            --cache.size;
            break;
        }
    }
    pthread_mutex_unlock(&cache.lock);
}

int main() {
    init_cache();

    // Example usage
    add_token("abc123", time(NULL) + 3600); // Token expires in 1 hour

    int index = find_token("abc123");
    if (index != -1) {
        printf("Token found in cache.\n");
    } else {
        printf("Token not found in cache.\n");
    }

    invalidate_token("abc123");

    return 0;
}
