#define MAX_THREADS 10

typedef struct {
    int frame_id;
    time_t timestamp;
    // Assume ChannelQualityIndication and FrameMetadata are defined elsewhere
} FrameMetadata;

typedef struct Node {
    FrameMetadata data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int list_size = 0;
const int max_list_size = 1000; // Example limit

void add_frame(FrameMetadata data) {
    pthread_mutex_lock(&mutex);
    while (list_size >= max_list_size) {
        pthread_cond_wait(&cond, &mutex); // Wait until there's space
    }
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&mutex);
        return;
    }
    new_node->data = data;
    new_node->next = head;
    head = new_node;
    list_size++;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);
}

FrameMetadata get_frame(int frame_id) {
    FrameMetadata result = {0};
    pthread_mutex_lock(&mutex);
    Node* current = head;
    while (current != NULL) {
        if (current->data.frame_id == frame_id) {
            result = current->data;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&mutex);
    return result;
}

void* worker_thread(void* arg) {
    int id = *(int*)arg;
    while (1) {
        FrameMetadata data;
        // Simulate asynchronous I/O operation to fetch data
        sleep(1); // Simulating delay
        add_frame(data);

        pthread_mutex_lock(&mutex);
        printf("Thread %d added frame with ID %d\n", id, data.frame_id);
        if (list_size == 0) {
            pthread_cond_signal(&cond); // Notify any waiting threads
        }
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

int main() {
    int thread_ids[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&thread_ids[i], NULL, worker_thread, &i);
    }

    // Simulate adding frames from the main thread
    FrameMetadata data_to_add = {1, time(NULL), {/* initialize ChannelQualityIndication objects */}};
    add_frame(data_to_add);

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(thread_ids[i], NULL);
    }

    return 0;
}
