    new_node->data = frame;
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&list_lock);
}

void *process_frames(void *arg) {
    while(1) {
        pthread_mutex_lock(&list_lock);
        if(head != NULL) {
            LinkedListNode *current = head;
            head = current->next;
            FrameMetadata *frame = current->data;
            update_channel_quality(frame);
            free(current);
        }
        pthread_mutex_unlock(&list_lock);
        // Sleep for a short duration to prevent busy-waiting
        usleep(1000);
    }
    return NULL;
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, process_frames, NULL);

    // Simulate adding frames to the list
    FrameMetadata *frame = (FrameMetadata *)malloc(sizeof(FrameMetadata));
    frame->frame_id = 12345;
    frame->timestamp = time(NULL);
    frame->indications = NULL;
    frame->indications_count = 0;

    add_frame_to_list(frame);

    pthread_join(thread, NULL);
    return 0;
}
