#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CLIENTS 1024
#define MAX_HOSTNAME_LEN 256
#define DNS_SERVER_PORT 53

typedef struct {
    char hostname[MAX_HOSTNAME_LEN];
    int client_socket;
    pthread_t thread_id;
} ClientRequest;

ClientRequest clients[MAX_CLIENTS];
int client_count = 0;

void* handle_client(void* arg) {
    ClientRequest* request = (ClientRequest*)arg;
    char ip_address[INET_ADDRSTRLEN];

    inet_ntop(AF_INET, &(request->client_socket), ip_address, INET_ADDRSTRLEN);
    printf("Handling DNS request for %s from %s\n", request->hostname, ip_address);

    // Perform DNS resolution logic here
    // This is a placeholder for actual DNS resolution code

    close(request->client_socket);
    free(request);
    return NULL;
}

void accept_connections() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(DNS_SERVER_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, MAX_CLIENTS) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue;
        }

        ClientRequest* request = (ClientRequest*)malloc(sizeof(ClientRequest));
        strncpy(request->hostname, "example.com", MAX_HOSTNAME_LEN);
        request->client_socket = new_socket;

        if (pthread_create(&request->thread_id, NULL, handle_client, (void*)request) != 0) {
            perror("pthread_create");
            free(request);
            close(new_socket);
        }
    }

    close(server_fd);
}

int main() {
    accept_connections();
    return 0;
}
