    }
}

class HttpClientSettings
{
    public string BaseAddress { get; set; }
    public int TimeoutSeconds { get; set; }
}

class DataRepository : IDataRepository
{
    private readonly string _connectionString;

    public DataRepository(IConfiguration configuration)
    {
        _connectionString = configuration.GetConnectionString("Database");
    }

    public async Task SaveDataAsync(byte[] data, long size)
    {
        using (var client = new HttpClient())
        {
            var content = new ByteArrayContent(data);
            content.Headers.ContentLength = size;
            var response = await client.PostAsync(_connectionString, content);
            response.EnsureSuccessStatusCode();
        }
    }
}

class QueueService : IQueueService
{
    private readonly string _queueUrl;

    public QueueService(IConfiguration configuration)
    {
        _queueUrl = configuration.GetSection("Queue").GetValue<string>("Url");
    }

    public async Task EnqueueMessageAsync(byte[] data, long size)
    {
        using (var client = new HttpClient())
        {
            var content = new ByteArrayContent(data);
            content.Headers.ContentLength = size;
