interface IDataRepository
{
    Task SaveDataAsync(byte[] data, long size);
}

interface IQueueService
{
    Task EnqueueMessageAsync(byte[] data, long size);
}

interface IConfigurationManager
{
    string GetConfigValue(string key);
}

class DataIngestionPipeline : IHostedService
{
    private readonly IDataRepository _dataRepository;
    private readonly IQueueService _queueService;
    private readonly IConfigurationManager _configurationManager;
    private Timer _timer;

    public DataIngestionPipeline(IDataRepository dataRepository, IQueueService queueService, IConfigurationManager configurationManager)
    {
        _dataRepository = dataRepository;
        _queueService = queueService;
        _configurationManager = configurationManager;
    }

    public Task StartAsync(CancellationToken cancellationToken)
    {
        _timer = new Timer(ProcessData, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
        return Task.CompletedTask;
    }

    private async void ProcessData(object state)
    {
        var batchSize = int.Parse(_configurationManager.GetConfigValue("BatchSize"));
        var dataQueue = await GetDataFromSource(batchSize);
        foreach (var batch in dataQueue)
        {
            await _dataRepository.SaveDataAsync(batch.Data, batch.Size);
            await _queueService.EnqueueMessageAsync(batch.Data, batch.Size);
        }
    }

    public Task StopAsync(CancellationToken cancellationToken)
    {
        _timer?.Change(Timeout.Infinite, 0);
        return Task.CompletedTask;
    }

    private async Task<ConcurrentQueue<DataBatch>> GetDataFromSource(int batchSize)
    {
        var dataQueue = new ConcurrentQueue<DataBatch>();
        using (var client = new HttpClient())
        {
            while (true)
            {
                var response = await client.GetAsync("https://data-source.com/api/data");
                if (!response.IsSuccessStatusCode) break;

                var data = await response.Content.ReadAsByteArrayAsync();
                if (data.Length == 0) break;

                dataQueue.Enqueue(new DataBatch { Data = data, Size = data.Length });
            }
        }

        while (dataQueue.Count > batchSize)
        {
            dataQueue.TryDequeue(out _);
        }

        return dataQueue;
    }
}

class DataBatch
{
    public byte[] Data { get; set; }
    public long Size { get; set; }
}
