<?php

use PDO;
use PasswordHash;

class DAO {
    private $pdo;

    public function __construct($dsn, $username, $password) {
        $this->pdo = new PDO($dsn, $username, $password);
        $this->pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
    }

    public function updateUserPassword($userId, $newPassword) {
        // Validate password strength
        if (!self::isValidPassword($newPassword)) {
            throw new InvalidArgumentException("Invalid password. Password must be at least 8 characters long and contain a mix of uppercase, lowercase, numbers, and special characters.");
        }

        // Hash the password with a unique salt
        $passwordHash = new PasswordHash(12);
        $hashedPassword = $passwordHash->hash($newPassword);

        try {
            // Update user's password in the database
            $stmt = $this->pdo->prepare("UPDATE users SET password = :password WHERE id = :userId");
            $stmt->bindParam(':password', $hashedPassword, PDO::PARAM_STR);
            $stmt->bindParam(':userId', $userId, PDO::PARAM_INT);
            $stmt->execute();

            if ($stmt->rowCount() === 0) {
                throw new Exception("No user found with the provided ID.");
            }

        } catch (PDOException $e) {
            throw new Exception("Database error: " . $e->getMessage());
        }
    }

    private static function isValidPassword($password) {
        // Basic password strength check
        return strlen($password) >= 8 && preg_match('/[A-Za-z]/', $password) && preg_match('/\d/', $password) && preg_match('/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/', $password);
    }
}
```

