# Define a class for the distributed graph database system
class DistributedGraphDatabase:
    def __init__(self):
        self.nodes = {}
        self.edges = {}

    # Method to add a vertex (node)
    def add_vertex(self, node_id, data):
        if node_id not in self.nodes:
            self.nodes[node_id] = data
            return True
        return False

    # Method to add an edge between two vertices
    def add_edge(self, from_node, to_node, weight=1):
        if from_node in self.nodes and to_node in self.nodes:
            if from_node not in self.edges:
                self.edges[from_node] = {}
            self.edges[from_node][to_node] = weight
            return True
        return False

    # Method to remove a vertex (node)
    def remove_vertex(self, node_id):
        if node_id in self.nodes:
            del self.nodes[node_id]
            for edge_from in self.edges:
                if node_id in self.edges[edge_from]:
                    del self.edges[edge_from][node_id]
            return True
        return False

    # Method to remove an edge between two vertices
    def remove_edge(self, from_node, to_node):
        if from_node in self.nodes and to_node in self.nodes:
            if to_node in self.edges[from_node]:
                del self.edges[from_node][to_node]
                return True
        return False

    # Method to get neighbors of a vertex
    def get_neighbors(self, node_id):
        if node_id in self.nodes:
            return self.edges.get(node_id, {})
        return {}

# Example usage
graph = DistributedGraphDatabase()
graph.add_vertex('A', {'data': 'Node A'})
graph.add_vertex('B', {'data': 'Node B'})
graph.add_edge('A', 'B', 2)
print(graph.get_neighbors('A'))  # Output: {'B': 2}
```"]

