use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use backoff::{backoff, ExponentialBackoff};
use log::{info, warn};

#[derive(Debug)]
enum ConfigurationError {
    InvalidPath,
    PermissionDenied,
}

trait ConfigManager {
    fn get_config(&self) -> Result<PathBuf, ConfigurationError>;
    fn validate_path(&self, path: &Path) -> bool;
}

struct ExternalConfigManager {
    // Implementation details
}

impl ConfigManager for ExternalConfigManager {
    fn get_config(&self) -> Result<PathBuf, ConfigurationError> {
        // Retrieve configuration from external system
        unimplemented!()
    }

    fn validate_path(&self, path: &Path) -> bool {
        // Validate path based on external system rules
        unimplemented!()
    }
}

struct DefaultConfigManager;

impl ConfigManager for DefaultConfigManager {
    fn get_config(&self) -> Result<PathBuf, ConfigurationError> {
        Ok(PathBuf::from("/default/data/dir"))
    }

    fn validate_path(&self, path: &Path) -> bool {
        // Basic validation rules
        path.exists() && path.is_dir()
    }
}

struct ConfigManagerFactory {
    strategy: Box<dyn ConfigManager>,
}

impl ConfigManagerFactory {
    fn new(strategy: Box<dyn ConfigManager>) -> Self {
        ConfigManagerFactory { strategy }
    }

    fn get_config(&self) -> Result<PathBuf, ConfigurationError> {
        let mut backoff = ExponentialBackoff::default();
        loop {
            match self.strategy.get_config() {
                Ok(path) => {
                    if !path.exists() {
                        info!("Creating directory: {:?}", path);
                        std::fs::create_dir_all(&path)?;
                    }
                    return Ok(path);
                }
                Err(_) => {
                    warn!("Failed to get config, retrying in {:?}...", backoff.next_backoff());
                    std::thread::sleep(backoff.next_backoff().unwrap());
                }
            }
        }
    }
}

struct DataDirectoryManager {
    config_manager: Arc<Mutex<ConfigManagerFactory>>,
}

impl DataDirectoryManager {
    fn new(strategy: Box<dyn ConfigManager>) -> Self {
        DataDirectoryManager {
            config_manager: Arc::new(Mutex::new(ConfigManagerFactory::new(strategy))),
        }
    }

    fn get_data_dir(&self) -> Result<PathBuf, ConfigurationError> {
        self.config_manager.lock().unwrap().get_config()
    }
}

fn main() {
    let strategy = Box::new(ExternalConfigManager);
    let manager = DataDirectoryManager::new(strategy);

    match manager.get_data_dir() {
        Ok(path) => println!("Data directory: {:?}", path),
        Err(e) => eprintln!("Error getting data directory: {:?}", e),
    }
}
