#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef void (*CallbackFunction)(const char*);

void on_restriction_exceeded(const char* input) {
    // Log the event
    printf("Input exceeds size limit: %s\n", input);
}

char* process_string(const char* input, int size_limit, CallbackFunction callback) {
    if (strlen(input) < size_limit) {
        char* new_input = realloc((char*)input, strlen(input) + 2); // Allocate memory for the new string
        if (new_input != NULL) {
            strcat(new_input, "/"); // Append a forward slash
            return new_input;
        } else {
            printf("Memory allocation failed\n");
            return NULL;
        }
    } else {
        callback(input);
        return NULL; // Input exceeds size limit
    }
}

int main() {
    const char* input = "example";
    int size_limit = 10;

    char* result = process_string(input, size_limit, on_restriction_exceeded);

    if (result != NULL) {
        printf("Processed string: %s\n", result);
        free(result); // Free the allocated memory
    }

    return 0;
}
