import io.grpc.Server;
import io.grpc.ServerBuilder;
import io.grpc.stub.StreamObserver;

public class ApiGatewayServer {

    private Server server;

    private void start() throws IOException {
        int port = 50051;
        server = ServerBuilder.forPort(port)
                .addService(new BackendMicroserviceImpl())
                .build()
                .start();
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            // Use stderr here since the main thread uses stdout for logging.
            System.err.println("*** shutting down gRPC server since JVM is shutting down");
            ApiGatewayServer.this.stop();
            System.err.println("*** server shut down");
        }));
    }

    private void stop() {
        if (server != null) {
            server.shutdown();
        }
    }

    /**
     * Await termination on the main thread since the grpc library uses daemon threads.
     */
    private void blockUntilShutdown() throws InterruptedException {
        if (server != null) {
            server.awaitTermination();
        }
    }

    public static void main(String[] args) throws IOException, InterruptedException {
        final ApiGatewayServer apiGatewayServer = new ApiGatewayServer();
        apiGatewayServer.start();
        apiGatewayServer.blockUntilShutdown();
    }

    static class BackendMicroserviceImpl extends BackendMicroserviceGrpc.BackendMicroserviceImplBase {

        @Override
        public void processRequest(Request request, StreamObserver<Response> responseObserver) {
            // Logic to route request to appropriate backend microservice based on request characteristics
            Response response = new Response();
            // Set response details
            responseObserver.onNext(response);
            responseObserver.onCompleted();
        }
    }
}
