    switch (code) {
        case SUCCESS:
            break;
        case FAILURE:
            fprintf(stderr, "Error: General failure\n");
            exit(EXIT_FAILURE);
        case INVALID_ALGORITHM:
            fprintf(stderr, "Error: Invalid cryptographic algorithm\n");
            exit(EXIT_FAILURE);
        case INSUFFICIENT_MEMORY:
            fprintf(stderr, "Error: Insufficient memory allocated\n");
            exit(EXIT_FAILURE);
        case CONCURRENT_ACCESS_ERROR:
            fprintf(stderr, "Error: Concurrent access issues\n");
            exit(EXIT_FAILURE);
        default:
            fprintf(stderr, "Error: Unknown error code\n");
            exit(EXIT_FAILURE);
    }
}

// Thread safety
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

void lock() {
    pthread_mutex_lock(&global_lock);
}

void unlock() {
    pthread_mutex_unlock(&global_lock);
}

// Versioning and deployment
