struct LTE_TRANSPORT_CHANNEL_MESSAGE {
    int TRANSPORT_CHANNEL_ID;
    std::string PREAMBLE_SEQUENCE;
    int TRANSPORT_FORMAT;
};

class MessageManager {
public:
    MessageManager(const std::string& kafka_broker, const std::string& kafka_topic);
    ~MessageManager();

    bool add_message(const LTE_TRANSPORT_CHANNEL_MESSAGE& message);

private:
    void producer_thread();
    void batch_and_publish();
    void self_monitoring_thread();

    std::vector<LTE_TRANSPORT_CHANNEL_MESSAGE> messages_;
    std::mutex mutex_;
    std::condition_variable cv_;
    std::thread producer_thread_;
    std::thread self_monitoring_thread_;
    std::queue<std::vector<LTE_TRANSPORT_CHANNEL_MESSAGE>> batch_queue_;
    std::atomic<bool> running_{true};
};

MessageManager::MessageManager(const std::string& kafka_broker, const std::string& kafka_topic)
    : producer_thread_(std::bind(&MessageManager::producer_thread, this)),
      self_monitoring_thread_(std::bind(&MessageManager::self_monitoring_thread, this)) {
    // Initialize Kafka producer
}

MessageManager::~MessageManager() {
    running_ = false;
    cv_.notify_all();
    producer_thread_.join();
    self_monitoring_thread_.join();
    // Clean up Kafka resources
}

bool MessageManager::add_message(const LTE_TRANSPORT_CHANNEL_MESSAGE& message) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (message.TRANSPORT_CHANNEL_ID < 0 || message.TRANSPORT_FORMAT < 0 || message.PREAMBLE_SEQUENCE.empty()) {
        return false; // Validation error
    }
    messages_.push_back(message);
    cv_.notify_one();
    return true;
}

void MessageManager::producer_thread() {
    while (running_) {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this] { return !messages_.empty() || !running_; });
        if (!messages_.empty()) {
            batch_queue_.push(messages_);
            messages_.clear();
        }
    }
}

void MessageManager::batch_and_publish() {
    while (true) {
        std::vector<LTE_TRANSPORT_CHANNEL_MESSAGE> batch;
        {
            std::unique_lock<std::mutex> lock(mutex_);
            if (!batch_queue_.empty()) {
                batch = std::move(batch_queue_.front());
                batch_queue_.pop();
            }
        }
        if (batch.empty()) {
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            continue;
        }

        // Publish batch to Kafka
        for (const auto& msg : batch) {
            // Kafka publishing code here
        }
    }
}

void MessageManager::self_monitoring_thread() {
    while (running_) {
        // Check Kafka broker health
        std::this_thread::sleep_for(std::chrono::seconds(60));
    }
}
