char* secure_process_and_format_path(const char *source_path, size_t size_limit, OutputBuffer *output_buffer, Logger *logger, ConfigManager *config_manager) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int append_slash = get_config_value("APPEND_SLASH") != 0;

    pthread_mutex_lock(&lock);
    char modified_path[256];
    strncpy(modified_path, source_path, sizeof(modified_path) - 1);
    modified_path[sizeof(modified_path) - 1] = '\0';

    if (strchr(source_path, '/') != NULL || strchr(source_path, '\\') != NULL) {
        logger->log_message("Potential injection attempt detected");
    }

    size_t path_length = strlen(modified_path);

    if (append_slash && path_length + 2 <= size_limit) {
        modified_path[path_length] = '/';
        modified_path[path_length + 1] = '\0';
    } else if (path_length >= size_limit - 1) {
        logger->log_message("Path length exceeds size limit");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    if (output_buffer->size < strlen(modified_path) + 1) {
        logger->log_message("Output buffer is too small");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    strcpy(output_buffer->buffer, modified_path);
    pthread_mutex_unlock(&lock);
    return output_buffer->buffer;
}
