# Load balancing algorithm
def dynamic_load_balancing(requests):
    worker_nodes = ['worker1', 'worker2', 'worker3']  # Example worker nodes
    request_count = {}

    for node in worker_nodes:
        request_count[node] = redis_client.get(node) or 0

    least_loaded_node = min(worker_nodes, key=lambda x: request_count[x])
    request_count[least_loaded_node] += requests
    redis_client.set(least_loaded_node, request_count[least_loaded_node])

    return least_loaded_node

# Data ingestion and processing
