    def wrapper(*args, **kwargs):
        try:
            result = func(*args, **kwargs)
        except Exception as e:
            print(f"Error occurred: {e}. Retrying...")
            return handle_failure(func)(*args, **kwargs)  # Retry the function
        return result
    return wrapper

@handle_failure
