#include <iostream>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <functional>
#include <chrono>

class DynamicDataPipeline {
public:
    DynamicDataPipeline(int maxPriority, int maxStreams)
        : maxPriority(maxPriority), maxStreams(maxStreams) {}

    void addStream(std::function<void()> stream, int priority) {
        std::unique_lock<std::mutex> lock(mutex);
        queue.emplace(stream, priority);
        condition.notify_one();
    }

private:
    struct StreamTask {
        std::function<void()> task;
        int priority;

        StreamTask(std::function<void()> t, int p) : task(t), priority(p) {}
    };

    bool operator<(const StreamTask& a, const StreamTask& b) {
        return a.priority < b.priority;
    }

    std::priority_queue<StreamTask> queue;
    std::mutex mutex;
    std::condition_variable condition;
    int maxPriority;
    int maxStreams;

    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !queue.empty(); });
            auto task = queue.top();
            queue.pop();
            lock.unlock();

            try {
                task.task();
            } catch (...) {
                // Handle exceptions
            }
        }
    }

public:
    void start() {
        for (int i = 0; i < maxStreams; ++i) {
            std::thread(&DynamicDataPipeline::worker, this).detach();
        }
    }
};

int main() {
    DynamicDataPipeline pipeline(5, 10);
    pipeline.start();

    // Add streams with varying priorities
    for (int i = 0; i < 10; ++i) {
        int priority = rand() % 5;
        pipeline.addStream([i] { std::cout << "Processing stream " << i << std::endl; }, priority);
    }

    return 0;
}
```

