        std::string data;
        int priority;
    };

    std::priority_queue<DataItem> dataQueue;
    std::mutex queueMutex;
    std::condition_variable queueCondition;
};

void manageNFAPI_CRC_INDICATION_PDU_T(int N) {
    DynamicDataPipeline pipeline;
    pipeline.start();

    std::vector<std::thread> threads;
    for (int i = 0; i < N; ++i) {
        threads.emplace_back([&pipeline]() {
            while (true) {
                std::string data;
                int priority;

                // Wait for data
                pipeline.queueCondition.wait(pipeline.queueMutex, [&pipeline]{ return !pipeline.dataQueue.empty(); });
                {
                    std::lock_guard<std::mutex> lock(pipeline.queueMutex);
                    auto item = pipeline.dataQueue.top();
                    data = item.data;
                    priority = item.priority;
                    pipeline.dataQueue.pop();
                }

                // Process data
                NFAPI_CRC_INDICATION_PDU_T pdu;
                generateRNTI(pdu.RNTI);
                pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

                // Store data locally if external service is unavailable
                storeLocally(&pdu);

                // Optionally compress and send to external service
                std::string compressedData;
                compressData(data, compressedData);
                sendDataToService(compressedData);
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    pipeline.stop();
}

void generateRNTI(std::string& RNTI) {
    // Generate unique RNTI from external service or local algorithm
}

void storeLocally(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    std::ofstream file("local_data.bin", std::ios::binary | std::ios::app);
    if (file.is_open()) {
        file.write(reinterpret_cast<char*>(pdu), sizeof(NFAPI_CRC_INDICATION_PDU_T));
        file.close();
    }
}

void compressData(const std::string& data, std::string& compressedData) {
    z_stream stream;
    stream.zalloc = Z_NULL;
    stream.zfree = Z_NULL;
    stream.opaque = Z_NULL;
    deflateInit(&stream, Z_DEFAULT_COMPRESSION);
    stream.avail_in = data.size();
    stream.next_in = reinterpret_cast<Bytef*>(const_cast<char*>(data.c_str()));
    do {
        stream.avail_out = 1024;
        stream.next_out = reinterpret_cast<Bytef*>(&compressedData[compressedData.size()]);
        deflate(&stream, Z_FINISH);
        compressedData.resize(compressedData.size() + 1024 - stream.avail_out);
    } while (stream.avail_out == 0);
    deflateEnd(&stream);
}

void sendDataToService(const std::string& data) {
    // Send data to external service
}
