// Include necessary headers
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define structures
typedef struct ChannelQualityIndication {
    int signal_strength;
    int noise_level;
    int interference_level;
} ChannelQualityIndication;

typedef struct FrameMetadata {
    int frame_id;
    time_t timestamp;
    ChannelQualityIndication *cqis;
    int cq_count;
} FrameMetadata;

typedef struct Node {
    FrameMetadata metadata;
    struct Node *next;
} Node;

// Global variables
Node *head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function declarations
void init_library();
void add_frame(FrameMetadata metadata);
FrameMetadata* get_frame_by_id(int id);
double calculate_average_signal_quality(time_t start_time, time_t end_time);

// Implementation of library functions
void init_library() {
    pthread_mutex_init(&mutex, NULL);
}

void add_frame(FrameMetadata metadata) {
    pthread_mutex_lock(&mutex);
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->metadata = metadata;
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&mutex);
}

FrameMetadata* get_frame_by_id(int id) {
    pthread_mutex_lock(&mutex);
    Node *current = head;
    while (current != NULL) {
        if (current->metadata.frame_id == id) {
            FrameMetadata *result = &current->metadata;
            pthread_mutex_unlock(&mutex);
            return result;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

double calculate_average_signal_quality(time_t start_time, time_t end_time) {
    pthread_mutex_lock(&mutex);
    Node *current = head;
    int count = 0;
    double total_quality = 0;
    while (current != NULL) {
        if (current->metadata.timestamp >= start_time && current->metadata.timestamp <= end_time) {
            for (int i = 0; i < current->metadata.cq_count; i++) {
                total_quality += current->metadata.cqis[i].signal_strength;
                count++;
            }
        }
        current = current->next;
    }
    pthread_mutex_unlock(&mutex);
    if (count == 0) return 0;
    return total_quality / count;
}

// Main function to demonstrate usage
int main() {
    init_library();

    // Example usage
    FrameMetadata metadata1 = {1, time(NULL), NULL, 0};
    add_frame(metadata1);

    FrameMetadata *frame = get_frame_by_id(1);
    if (frame != NULL) {
        printf("Frame ID: %d\n", frame->frame_id);
    }

    double avg_quality = calculate_average_signal_quality(time(NULL) - 3600, time(NULL));
    printf("Average Signal Quality in last hour: %f\n", avg_quality);

    return 0;
}
