#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct ChannelQualityIndication {
    int quality;
} ChannelQualityIndication;

typedef struct FrameMetadata {
    int id;
    time_t timestamp;
    ChannelQualityIndication *qualities;
    size_t qualities_count;
} FrameMetadata;

typedef struct Node {
    FrameMetadata data;
    struct Node *next;
} Node;

typedef struct LinkedList {
    Node *head;
    pthread_mutex_t mutex;
} LinkedList;

void init_linked_list(LinkedList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

void insert_frame_metadata(LinkedList *list, FrameMetadata metadata) {
    pthread_mutex_lock(&list->mutex);
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->data = metadata;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
}

void iterate_linked_list(LinkedList *list, void (*callback)(FrameMetadata *)) {
    pthread_mutex_lock(&list->mutex);
    Node *current = list->head;
    while (current != NULL) {
        callback(&current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

void free_linked_list(LinkedList *list) {
    pthread_mutex_lock(&list->mutex);
    Node *current = list->head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp->data.qualities);
        free(temp);
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
