class KeyValueStore {
public:
    virtual ~KeyValueStore() = default;

    virtual std::future<std::optional<std::string>> get(const std::string& key) const = 0;
    virtual std::future<bool> set(const std::string& key, const std::string& value, int ttl = -1) = 0;
    virtual std::future<bool> remove(const std::string& key) = 0;

    static KeyValueStore* createInstance();
};

// kvstore_impl.h
#pragma once

#include "kvstore.h"
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>

class KeyValueStoreImpl : public KeyValueStore {
public:
    ~KeyValueStoreImpl() override;

    std::future<std::optional<std::string>> get(const std::string& key) const override;
    std::future<bool> set(const std::string& key, const std::string& value, int ttl = -1) override;
    std::future<bool> remove(const std::string& key) override;

private:
    mutable std::mutex mtx_;
    std::unordered_map<std::string, std::pair<std::string, std::chrono::time_point<std::chrono::steady_clock>>> data_;
};

// kvstore_impl.cpp
#include "kvstore_impl.h"

KeyValueStoreImpl::~KeyValueStoreImpl() {
    // Cleanup resources if necessary
}

std::future<std::optional<std::string>> KeyValueStoreImpl::get(const std::string& key) const {
    auto result = std::make_shared<std::promise<std::optional<std::string>>>();
    std::thread([this, result, &key]() mutable {
        std::lock_guard<std::mutex> lock(mtx_);
        if (data_.find(key) != data_.end() && data_[key].second > std::chrono::steady_clock::now()) {
            result->set_value(data_[key].first);
        } else {
            result->set_value(std::nullopt);
        }
    }).detach();
    return result->get_future();
}

std::future<bool> KeyValueStoreImpl::set(const std::string& key, const std::string& value, int ttl) {
    auto result = std::make_shared<std::promise<bool>>();
    std::thread([this, result, &key, &value, ttl]() mutable {
        std::lock_guard<std::mutex> lock(mtx_);
        data_[key] = {value, ttl == -1 ? std::chrono::steady_clock::time_point::max() : std::chrono::steady_clock::now() + std::chrono::seconds(ttl)};
        result->set_value(true);
    }).detach();
    return result->get_future();
}

std::future<bool> KeyValueStoreImpl::remove(const std::string& key) {
    auto result = std::make_shared<std::promise<bool>>();
    std::thread([this, result, &key]() mutable {
        std::lock_guard<std::mutex> lock(mtx_);
        if (data_.find(key) != data_.end()) {
            data_.erase(key);
            result->set_value(true);
        } else {
            result->set_value(false);
        }
    }).detach();
    return result->get_future();
}

KeyValueStore* KeyValueStore::createInstance() {
    return new KeyValueStoreImpl();
}
```

