// Define a simple interface for market data vendors
class MarketDataVendor {
public:
    virtual std::string getName() = 0;
    virtual void fetchData() = 0;
};

// Implement a concrete vendor class
class ExampleVendor : public MarketDataVendor {
private:
    std::string name;

public:
    ExampleVendor(std::string n) : name(n) {}

    std::string getName() override { return name; }

    void fetchData() override {
        // Simulate fetching data from the vendor
        std::cout << "Fetching data from " << name << std::endl;
    }
};

// Thread pool implementation
class ThreadPool {
private:
    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;
    std::mutex queue_mutex;
    std::condition_variable condition;
    bool stop;

public:
    ThreadPool(size_t threads) : stop(false) {
        for(size_t i = 0; i < threads; ++i)
            workers.emplace_back([this] {
                for(;;) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(this->queue_mutex);
                        this->condition.wait(lock, [this]{ return this->stop || !this->tasks.empty(); });
                        if(this->stop && this->tasks.empty())
                            return;
                        task = std::move(this->tasks.front());
                        this->tasks.pop();
                    }
                    task();
                }
            });
    }

    ~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        condition.notify_all();
        for(std::thread &worker: workers)
            worker.join();
    }

    template<class F, class... Args>
    auto enqueue(F&& f, Args&&... args) -> std::future<typename std::result_of<F(Args...)>::type> {
        using return_type = typename std::result_of<F(Args...)>::type;

        auto task = std::make_shared<std::packaged_task<return_type()>>(
            std::bind(std::forward<F>(f), std::forward<Args>(args)...)
        );

        std::future<return_type> res = task->get_future();
        {
            std::unique_lock<std::mutex> lock(queue_mutex);

            // don't allow enqueueing after stopping the pool
            if(stop)
                throw std::runtime_error("enqueue on stopped ThreadPool");

            tasks.emplace([task](){ (*task)(); });
        }
        condition.notify_one();
        return res;
    }
};

// Main function to demonstrate the use of the ThreadPool and MarketDataVendor
int main() {
    ThreadPool pool(4);

    // Create a list of vendors
    std::vector<MarketDataVendor*> vendors = {
        new ExampleVendor("Vendor1"),
        new ExampleVendor("Vendor2"),
        // Add more vendors as needed
    };

    // Enqueue tasks to fetch data from each vendor
    for(auto& vendor : vendors) {
        pool.enqueue([vendor]() { vendor->fetchData(); });
    }

    // Clean up vendor objects
    for(auto& vendor : vendors) {
        delete vendor;
    }

    return 0;
}
```

