    pthread_mutex_unlock(&sessions[sessionID].mutex);
    return NULL;
}

void stressTest(int numSessions, int iterations) {
    pthread_t threads[numSessions * iterations];
    for (int i = 0; i < numSessions * iterations; ++i) {
        int sessionID = i % numSessions;
        pthread_create(&threads[i], NULL, simulateNetworkTraffic, &sessionID);
    }
    for (int i = 0; i < numSessions * iterations; ++i) {
        pthread_join(threads[i], NULL);
    }
}
