#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
    char *payload;
} DataPacket;

typedef struct PacketNode {
    DataPacket packet;
    struct PacketNode *next;
} PacketNode;

typedef struct {
    PacketNode *head;
    pthread_mutex_t mutex;
} PacketManager;

void init_packet_manager(PacketManager *manager) {
    manager->head = NULL;
    pthread_mutex_init(&manager->mutex, NULL);
}

void add_packet(PacketManager *manager, DataPacket packet) {
    pthread_mutex_lock(&manager->mutex);
    PacketNode *new_node = (PacketNode *)malloc(sizeof(PacketNode));
    new_node->packet = packet;
    new_node->next = manager->head;
    manager->head = new_node;
    pthread_mutex_unlock(&manager->mutex);
}

DataPacket *get_packet_by_id(PacketManager *manager, int packet_id) {
    pthread_mutex_lock(&manager->mutex);
    PacketNode *current = manager->head;
    while (current != NULL) {
        if (current->packet.packet_id == packet_id) {
            pthread_mutex_unlock(&manager->mutex);
            return &current->packet;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->mutex);
    return NULL;
}

void update_packet(PacketManager *manager, DataPacket new_packet) {
    pthread_mutex_lock(&manager->mutex);
    PacketNode *current = manager->head;
    while (current != NULL) {
        if (current->packet.packet_id == new_packet.packet_id) {
            current->packet = new_packet;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->mutex);
}

void remove_packet(PacketManager *manager, int packet_id) {
    pthread_mutex_lock(&manager->mutex);
    PacketNode *current = manager->head;
    PacketNode *prev = NULL;
    while (current != NULL) {
        if (current->packet.packet_id == packet_id) {
            if (prev == NULL) {
                manager->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->mutex);
}

void destroy_packet_manager(PacketManager *manager) {
    PacketNode *current = manager->head;
    while (current != NULL) {
        PacketNode *temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&manager->mutex);
}
```

