#include <iostream>
#include <string>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <future>
#include <functional>

// Forward declarations
class CacheStore;
template <typename T> class CacheEntry;

// Interface for serialization and deserialization
class Serializer {
public:
    virtual std::string serialize(const void* data, size_t size) = 0;
    virtual void deserialize(const std::string& serializedData, void* data, size_t size) = 0;
};

// Cache entry template class
template <typename T>
class CacheEntry {
private:
    T data_;
    Serializer* serializer_;

public:
    CacheEntry(Serializer* serializer) : serializer_(serializer), data_() {}

    void setData(const T& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        data_ = data;
    }

    T getData() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return data_;
    }

    std::string serialize() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return serializer_->serialize(&data_, sizeof(data_));
    }

    void deserialize(const std::string& serializedData) {
        std::lock_guard<std::mutex> lock(mutex_);
        serializer_->deserialize(serializedData, &data_, sizeof(data_));
    }

private:
    mutable std::mutex mutex_;
};

// Cache store class
class CacheStore {
private:
    std::unordered_map<std::string, std::shared_ptr<CacheEntry<void>>> entries_;
    std::mutex mutex_;

public:
    template <typename T>
    void set(const std::string& key, const T& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (!entries_.count(key)) {
            entries_[key] = std::make_shared<CacheEntry<T>>(new Serializer());
        }
        entries_[key]->setData(data);
    }

    template <typename T>
    T get(const std::string& key) const {
        std::lock_guard<std::mutex> lock(mutex_);
        if (entries_.count(key)) {
            return entries_[key]->getData();
        }
        throw std::runtime_error("Key not found");
    }

    template <typename T>
    std::string serialize(const std::string& key) const {
        std::lock_guard<std::mutex> lock(mutex_);
        if (entries_.count(key)) {
            return entries_[key]->serialize();
        }
        throw std::runtime_error("Key not found");
    }

    template <typename T>
    void deserialize(const std::string& key, const std::string& serializedData) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (entries_.count(key)) {
            entries_[key]->deserialize(serializedData);
        } else {
            throw std::runtime_error("Key not found");
        }
    }
};

// Asynchronous cache access using futures
template <typename T>
std::future<T> asyncGet(CacheStore& store, const std::string& key) {
    return std::async(std::launch::async, [&store, key]() -> T {
        return store.get<T>(key);
    });
}

int main() {
    CacheStore cache;
    Serializer serializer;

    // Example usage
    cache.set<int>("exampleKey", 42);
    auto futureData = asyncGet<int>(cache, "exampleKey");
    int data = futureData.get();
    std::cout << "Cached data: " << data << std::endl;

    return 0;
}
