#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_CONCURRENT_SOURCES 200

typedef struct {
    int id;
    char data[1024];
} DataPacket;

typedef struct {
    pthread_mutex_t lock;
    DataPacket packets[MAX_CONCURRENT_SOURCES];
    int count;
} PacketQueue;

PacketQueue queue;

void* process_packet(void* arg) {
    while (1) {
        pthread_mutex_lock(&queue.lock);
        if (queue.count > 0) {
            DataPacket packet = queue.packets[--queue.count];
            pthread_mutex_unlock(&queue.lock);

            // Process the data here
            printf("Processing data from source %d: %s\n", packet.id, packet.data);

            // Simulate processing time
            sleep(1);
        } else {
            pthread_mutex_unlock(&queue.lock);
            usleep(100); // Sleep briefly if no packets are available
        }
    }
}

void enqueue_packet(DataPacket packet) {
    pthread_mutex_lock(&queue.lock);
    if (queue.count < MAX_CONCURRENT_SOURCES) {
        queue.packets[queue.count++] = packet;
    } else {
        printf("Queue is full, discarding data from source %d\n", packet.id);
    }
    pthread_mutex_unlock(&queue.lock);
}

int main() {
    pthread_t threads[MAX_CONCURRENT_SOURCES];
    int i;

    // Initialize the queue
    pthread_mutex_init(&queue.lock, NULL);
    queue.count = 0;

    // Create worker threads
    for (i = 0; i < MAX_CONCURRENT_SOURCES; i++) {
        pthread_create(&threads[i], NULL, process_packet, NULL);
    }

    // Simulate data generation and processing
    for (i = 0; i < 1000; i++) {
        DataPacket packet;
        packet.id = i % MAX_CONCURRENT_SOURCES;
        snprintf(packet.data, sizeof(packet.data), "Data from source %d", packet.id);
        enqueue_packet(packet);
    }

    // Wait for all threads to finish (for demonstration purposes)
    for (i = 0; i < MAX_CONCURRENT_SOURCES; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    pthread_mutex_destroy(&queue.lock);

    return 0;
}
