    }

    std::pair<bool, std::string> get(const std::string& key) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        if (cache.find(key) != cache.end()) {
            return {true, cache[key].first};
        }
        return {false, ""};
    }

    void update(const std::string& key, const std::string& value, int version) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        if (cache.find(key) != cache.end()) {
            if (cache[key].second < version) {
                cache[key] = {value, version};
            }
        } else {
            set(key, value, version);
        }
    }

    void deleteEntry(const std::string& key) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        cache.erase(key);
    }
};

int main() {
    DistributedCache cache;
    cache.set("key1", "value1", 1);

    auto [found, value] = cache.get("key1");
    if (found) {
        std::cout << "Value: " << value << std::endl;
    } else {
        std::cout << "Key not found" << std::endl;
    }

    cache.update("key1", "value2", 2);

    auto [updatedFound, updatedValue] = cache.get("key1");
    if (updatedFound) {
        std::cout << "Updated Value: " << updatedValue << std::endl;
    } else {
        std::cout << "Key not found" << std::endl;
    }

    return 0;
}
