import hashlib
import os
import time
from typing import Callable

class FileHasher:
    def __init__(self, db_client, chunk_size=1024*1024, max_retries=5):
        self.db_client = db_client
        self.chunk_size = chunk_size
        self.max_retries = max_retries

    def hash_file(self, file_path: str) -> None:
        with open(file_path, 'rb') as f:
            hasher = hashlib.md5()
            for chunk in iter(lambda: f.read(self.chunk_size), b''):
                hasher.update(chunk)
        file_hash = hasher.hexdigest()
        self.store_hash(file_hash, file_path)

    def store_hash(self, file_hash: str, file_path: str) -> None:
        for attempt in range(self.max_retries + 1):
            try:
                self.db_client.insert({'file_path': file_path, 'hash': file_hash})
                break
            except Exception as e:
                if attempt == self.max_retries:
                    raise e
                time.sleep(2 ** attempt)

class ExternalDatabaseClient:
    def __init__(self):
        # Initialize database connection here

    def insert(self, data: dict) -> None:
        # Implement database insertion logic here

def retry_with_exponential_backoff(func: Callable[[], None], max_retries: int = 5) -> Callable[[], None]:
    def wrapper(*args, **kwargs):
        for attempt in range(max_retries + 1):
            try:
                func(*args, **kwargs)
                break
            except Exception as e:
                if attempt == max_retries:
                    raise e
                time.sleep(2 ** attempt)
    return wrapper

# Usage example
