import hashlib
import os
import threading
from concurrent.futures import ThreadPoolExecutor
import requests

class FileHasher:
    def __init__(self, api_url, chunk_size=1024*1024):
        self.api_url = api_url
        self.chunk_size = chunk_size

    def calculate_hash(self, file_path):
        try:
            hash_md5 = hashlib.md5()
            with open(file_path, "rb") as f:
                for chunk in iter(lambda: f.read(self.chunk_size), b""):
                    hash_md5.update(chunk)
            return hash_md5.hexdigest()
        except Exception as e:
            print(f"Error calculating hash for {file_path}: {e}")
            return None

    def store_hash(self, file_path, file_hash):
        try:
            response = requests.post(self.api_url, json={"path": file_path, "hash": file_hash})
            if response.status_code != 200:
                print(f"Failed to store hash for {file_path}: {response.text}")
        except Exception as e:
            print(f"Error storing hash for {file_path}: {e}")

    def verify_integrity(self, file_path, expected_hash):
        actual_hash = self.calculate_hash(file_path)
        if actual_hash != expected_hash:
            print(f"Integrity check failed for {file_path}. Expected: {expected_hash}, Actual: {actual_hash}")
            return False
        return True

def main():
    api_url = "http://example.com/api/store_hash"
    file_paths = ["path/to/file1.txt", "path/to/file2.bin"]
    expected_hashes = {"path/to/file1.txt": "expected_md5_hash_1", "path/to/file2.bin": "expected_md5_hash_2"}

    hasher = FileHasher(api_url)
    results = {}

    with ThreadPoolExecutor(max_workers=10) as executor:
        futures = {executor.submit(hasher.calculate_hash, file_path): file_path for file_path in file_paths}
        for future in concurrent.futures.as_completed(futures):
            file_path = futures[future]
            try:
                file_hash = future.result()
                if file_hash:
                    hasher.store_hash(file_path, file_hash)
                    results[file_path] = file_hash
            except Exception as e:
                print(f"Error processing {file_path}: {e}")

    for file_path, expected_hash in expected_hashes.items():
        hasher.verify_integrity(file_path, expected_hash)

if __name__ == "__main__":
    main()
