import hashlib
import logging
from pathlib import Path

# Set up basic configuration for logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def compute_md5(file_path):
    """Compute the MD5 hash of a file in chunks to handle large files efficiently."""
    hasher = hashlib.md5()
    try:
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                hasher.update(chunk)
    except FileNotFoundError:
        logging.error(f"File not found: {file_path}")
        return None
    except PermissionError:
        logging.error(f"Permission denied for file: {file_path}")
        return None
    except Exception as e:
        logging.error(f"An error occurred: {e}")
        return None
    return hasher.hexdigest()

def process_files(file_paths):
    """Process a list of files and log their MD5 hashes."""
    for file_path in file_paths:
        md5_hash = compute_md5(file_path)
        if md5_hash:
            logging.info(f"File: {file_path}, MD5: {md5_hash}")

if __name__ == "__main__":
    import sys
    if len(sys.argv) < 2 or '--manpage' in sys.argv:
        print("Usage: python script.py <input_file> [-cs] -o output_file")
        sys.exit(1)

    input_file = Path(sys.argv[1])
    if not input_file.exists():
        logging.error(f"Input file does not exist: {input_file}")
        sys.exit(1)

    process_files([input_file])
