import boto3
from botocore.exceptions import NoCredentialsError
from concurrent.futures import ThreadPoolExecutor, as_completed
import hashlib
import json
import os

s3_client = boto3.client('s3')
lambda_client = boto3.client('lambda')

def hash_chunk(chunk):
    return hashlib.sha256(chunk).hexdigest()

def hash_file(file_key, bucket_name, chunk_size=1024*1024*10):  # 10 MB chunks
    response = s3_client.get_object(Bucket=bucket_name, Key=file_key)
    file_hash = hashlib.sha256()

    with ThreadPoolExecutor(max_workers=5) as executor:
        futures = {executor.submit(hash_chunk, chunk): i for i, chunk in enumerate(response['Body'].iter_chunks(chunk_size))}

        for future in as_completed(futures):
            try:
                partial_hash = future.result()
                file_hash.update(partial_hash.encode())
            except Exception as e:
                print(f"Error hashing chunk: {e}")

    return file_hash.hexdigest()

def lambda_handler(event, context):
    bucket_name = event['bucket_name']
    file_key = event['file_key']

    try:
        hash_value = hash_file(file_key, bucket_name)
        response = {
            'statusCode': 200,
            'body': json.dumps({'file_key': file_key, 'hash_value': hash_value})
        }
    except NoCredentialsError:
        response = {
            'statusCode': 403,
            'body': json.dumps({'error': 'No AWS credentials available'})
        }
    except Exception as e:
        response = {
            'statusCode': 500,
            'body': json.dumps({'error': str(e)})
        }

    return response
