#include <iostream>
#include <fstream>
#include <vector>

struct TiffImageInfo {
    int bitsPerSample;
    int samplesPerPixel;
    std::vector<int> extraSamples;
};

int parseTiff(const std::string& filename, TiffImageInfo& info) {
    std::ifstream file(filename, std::ios::binary);
    if (!file.is_open()) {
        std::cerr << "Failed to open file: " << filename << std::endl;
        return -1;
    }

    // Read TIFF header and tags
    uint16_t magicNumber;
    file.read(reinterpret_cast<char*>(&magicNumber), sizeof(magicNumber));
    if (magicNumber != 0x4D4D && magicNumber != 0x4949) {
        std::cerr << "Not a valid TIFF file." << std::endl;
        return -1;
    }

    // Skip to the directory
    uint32_t nextIFDOffset;
    file.seekg(4, std::ios::cur);
    file.read(reinterpret_cast<char*>(&nextIFDOffset), sizeof(nextIFDOffset));
    if (nextIFDOffset == 0) {
        std::cerr << "No image data found." << std::endl;
        return -1;
    }

    // Read the IFD
    file.seekg(nextIFDOffset, std::ios::beg);
    uint16_t tagCount;
    file.read(reinterpret_cast<char*>(&tagCount), sizeof(tagCount));
    for (uint16_t i = 0; i < tagCount; ++i) {
        uint16_t tag, type;
        uint32_t count;
        file.read(reinterpret_cast<char*>(&tag), sizeof(tag));
        file.read(reinterpret_cast<char*>(&type), sizeof(type));
        file.read(reinterpret_cast<char*>(&count), sizeof(count));

        if (tag == 256) { // Bits per sample
            info.bitsPerSample = type == 4 ? count : -1;
        } else if (tag == 277) { // Samples per pixel
            info.samplesPerPixel = type == 3 ? count : -1;
        } else if (tag == 338) { // Extra samples
            std::vector<int> extra(count);
            file.read(reinterpret_cast<char*>(extra.data()), sizeof(int) * count);
            info.extraSamples = extra;
        }
    }

    // Validate bits per sample
    if (info.bitsPerSample != 1 && info.bitsPerSample != 2 && 
        info.bitsPerSample != 4 && info.bitsPerSample != 8 && 
        info.bitsPerSample != 16) {
        std::cerr << "Unsupported bits per sample: " << info.bitsPerSample << std::endl;
        return -1;
    }

    file.close();
    return 0;
}

int main() {
    TiffImageInfo info;
    if (parseTiff("example.tiff", info) == 0) {
        std::cout << "Bits per sample: " << info.bitsPerSample << std::endl;
        std::cout << "Samples per pixel: " << info.samplesPerPixel << std::endl;
        for (int sample : info.extraSamples) {
            std::cout << "Extra sample: " << sample << std::endl;
        }
    }
    return 0;
}
