    if (TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel)) {
        std::cout << "Samples per Pixel: " << samplesPerPixel << std::endl;
    } else {
        std::cerr << "Failed to get Samples per Pixel" << std::endl;
    }

    uint16_t extraSamples;
    if (TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extraSamples)) {
        std::cout << "Extra Samples: " << extraSamples << std::endl;
    } else {
        std::cerr << "Failed to get Extra Samples" << std::endl;
    }

    TIFFClose(tif);
}

