#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <openssl/pem.h>
#include <openssl/rsa.h>
#include <string>

class EncryptionLibrary {
public:
    static void aesEncrypt(const std::string& data, const std::string& key, std::string& encryptedData);
    static void camelliaEncrypt(const std::string& data, const std::string& key, std::string& encryptedData);
    static std::string sha256Hash(const std::string& data);
    static bool rsaSign(const std::string& data, const RSA* privateKey, std::string& signature);
};

void EncryptionLibrary::aesEncrypt(const std::string& data, const std::string& key, std::string& encryptedData) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, reinterpret_cast<const unsigned char*>(key.c_str()), reinterpret_cast<const unsigned char*>("0123456789abcdef"));
    encryptedData.resize(data.size() + EVP_CIPHER_block_size(EVP_aes_256_cbc()));
    int len;
    EVP_EncryptUpdate(ctx, reinterpret_cast<unsigned char*>(&encryptedData[0]), &len, reinterpret_cast<const unsigned char*>(data.c_str()), data.size());
    int finalLen;
    EVP_EncryptFinal_ex(ctx, reinterpret_cast<unsigned char*>(&encryptedData[len]), &finalLen);
    encryptedData.resize(len + finalLen);
    EVP_CIPHER_CTX_free(ctx);
}

void EncryptionLibrary::camelliaEncrypt(const std::string& data, const std::string& key, std::string& encryptedData) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_camellia_256_cbc(), NULL, reinterpret_cast<const unsigned char*>(key.c_str()), reinterpret_cast<const unsigned char*>("0123456789abcdef"));
    encryptedData.resize(data.size() + EVP_CIPHER_block_size(EVP_camellia_256_cbc()));
    int len;
    EVP_EncryptUpdate(ctx, reinterpret_cast<unsigned char*>(&encryptedData[0]), &len, reinterpret_cast<const unsigned char*>(data.c_str()), data.size());
    int finalLen;
    EVP_EncryptFinal_ex(ctx, reinterpret_cast<unsigned char*>(&encryptedData[len]), &finalLen);
    encryptedData.resize(len + finalLen);
    EVP_CIPHER_CTX_free(ctx);
}

std::string EncryptionLibrary::sha256Hash(const std::string& data) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256(reinterpret_cast<const unsigned char*>(data.c_str()), data.size(), hash);
    std::stringstream ss;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        ss << std::hex << std::setw(2) << std::setfill('0') << (int)hash[i];
    }
    return ss.str();
}

bool EncryptionLibrary::rsaSign(const std::string& data, const RSA* privateKey, std::string& signature) {
    unsigned char buffer[1024];
    int len = RSA_sign(NID_sha256, reinterpret_cast<const unsigned char*>(data.c_str()), data.size(), buffer, &len, privateKey);
    if (len > 0) {
        signature.assign(reinterpret_cast<char*>(buffer), len);
        return true;
    }
    return false;
}
