```c
// network_session.c

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

NetworkSession* createNetworkSession(int sessionID, const char* peerAddress, size_t maxDataSize) {
    NetworkSession* session = (NetworkSession*)malloc(sizeof(NetworkSession));
    if (!session) return NULL;

    session->sessionID = sessionID;
    strcpy(session->remotePeerAddress, peerAddress);
    session->buffer = (char*)malloc(maxDataSize * sizeof(char));
    if (!session->buffer) {
        free(session);
        return NULL;
    }
    session->bufferSize = maxDataSize;
    session->dataLength = 0;

    return session;
}

void destroyNetworkSession(NetworkSession* session) {
    free(session->buffer);
    free(session);
}

int sendToNetworkSession(NetworkSession* session, const char* data, size_t length) {
    if (session->dataLength + length > session->bufferSize) {
        session->buffer = realloc(session->buffer, (session->dataLength + length) * sizeof(char));
        if (!session->buffer) return -1;
        session->bufferSize = session->dataLength + length;
    }
    memcpy(&session->buffer[session->dataLength], data, length);
    session->dataLength += length;
    return 0;
}

int receiveFromNetworkSession(NetworkSession* session, char** buffer, size_t* bufferSize) {
    *buffer = (char*)malloc(session->dataLength * sizeof(char));
    if (!*buffer) return -1;
    *bufferSize = session->dataLength;

    memcpy(*buffer, session->buffer, session->dataLength);
    free(session->buffer);
    session->buffer = NULL;
    session->bufferSize = 0;
    session->dataLength = 0;

    return 0;
}
