```c
// main.c

#include <stdio.h>
#include "network_session.h"

int main() {
    NetworkSession* session = createNetworkSession(1, "192.168.1.1", 1024);
    if (!session) {
        printf("Failed to create network session\n");
        return 1;
    }

    char data[] = "Hello, world!";
    if (sendToNetworkSession(session, data, strlen(data)) != 0) {
        printf("Failed to send data\n");
        destroyNetworkSession(session);
        return 1;
    }

    char* receivedData;
    size_t receivedSize;
    if (receiveFromNetworkSession(session, &receivedData, &receivedSize) != 0) {
        printf("Failed to receive data\n");
        destroyNetworkSession(session);
        free(receivedData);
        return 1;
    }

    printf("Received: %.*s\n", (int)receivedSize, receivedData);

