["```javascript
const { execFile } = require('child_process');
const cluster = require('cluster');
const os = require('os');

function executeCommand(command, args, options) {
    return new Promise((resolve, reject) => {
        const child = execFile(command, args, options, (error, stdout, stderr) => {
            if (error) {
                return reject(error);
            }
            resolve({ stdout, stderr });
        });

        child.stdout.on('data', data => {
            // Stream stdout to minimize latency
            process.stdout.write(data);
        });

        child.stderr.on('data', data => {
            // Handle errors as they occur
            console.error(`stderr: ${data}`);
        });

        child.on('close', code => {
            if (code !== 0) {
                reject(new Error(`Command exited with code ${code}`));
            }
        });
    });
}

async function processString(input, size_limit, on_restriction_exceeded) {
    const inputLength = Buffer.byteLength(input);

    if (inputLength <= size_limit) {
        const newInput = Buffer.alloc(inputLength + 1);
        input.copy(newInput, 0, 0, inputLength);
        newInput[inputLength] = 47; // ASCII for '/'
        return newInput.toString('utf-8');
    } else {
        try {
            on_restriction_exceeded(input);
        } catch (err) {
            console.error(`Callback error: ${err}`);
        }
        return null;
    }
}

// Example usage:
if (cluster.isMaster) {
    const numCPUs = os.cpus().length;

    for (let i = 0; i < numCPUs; i++) {
        cluster.fork();
    }

    cluster.on('exit', (worker, code, signal) => {
        console.log(`worker ${worker.process.pid} died`);
    });
} else {
    executeCommand('/path/to/your/command', ['arg1', 'arg2'], { maxBuffer: 1024 * 1024 })
        .then(result => {
            console.log('stdout:', result.stdout);
            console.error('stderr:', result.stderr);
        })
        .catch(error => {
            console.error(`Error executing command: ${error.message}`);
        });

    cluster.worker.send({ processString });
}
