from functools import wraps
import requests

app = Flask(__name__)
CORS(app)

# Mock backend services
services = {
    'service1': 'http://localhost:5001',
    'service2': 'http://localhost:5002'
}

def auth_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'error': 'Authentication required'}), 401
        # Validate JWT or OAuth2 token here
        return f(*args, **kwargs)
    return decorated_function

@app.route('/api/<service_name>', methods=['GET', 'POST'])
@auth_required
def proxy_request(service_name):
    if service_name in services:
        url = f'{services[service_name]}/{request.path[len("/api/"):]}'
        response = requests.request(
            method=request.method,
            url=url,
            headers={key: value for key, value in request.headers.items() if key != 'Host'},
            data=request.data,
            json=request.json
        )
        return jsonify(response.json()), response.status_code
    else:
        return jsonify({'error': 'Service not found'}), 404

if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0', port=5000)
