using System.Threading.Tasks;

public class DataService
{
    private readonly HttpClient _httpClient;
    private readonly Queue<string> _dataQueue = new Queue<string>();
    private readonly string _apiUrl;
    private bool _isRunning;

    public DataService(string apiUrl)
    {
        _apiUrl = apiUrl;
        _httpClient = new HttpClient();
    }

    public void Start()
    {
        _isRunning = true;
        Task.Run(() => FetchDataAsync());
        Task.Run(() => ProcessData());
    }

    public void Stop()
    {
        _isRunning = false;
    }

    private async Task FetchDataAsync()
    {
        while (_isRunning)
        {
            try
            {
                var response = await _httpClient.GetAsync(_apiUrl);
                if (response.IsSuccessStatusCode)
                {
                    string data = await response.Content.ReadAsStringAsync();
                    lock (_dataQueue)
                    {
                        _dataQueue.Enqueue(data);
                    }
                }
                else
                {
                    Console.WriteLine("Failed to fetch data. Status code: " + response.StatusCode);
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error fetching data: " + ex.Message);
            }

            await Task.Delay(500); // Adjust delay based on network latency and volume
        }
    }

    private async Task ProcessData()
    {
        while (_isRunning)
        {
            lock (_dataQueue)
            {
                if (_dataQueue.Count > 0)
                {
                    string data = _dataQueue.Dequeue();
                    await PersistDataAsync(data);
                    Console.WriteLine("Processed and persisted: " + data);
                }
            }

            await Task.Delay(100); // Adjust delay based on processing requirements
        }
    }

    private async Task PersistDataAsync(string data)
    {
        try
        {
            // Implement logic to persist data to disk
            System.IO.File.AppendAllText("data.txt", data + Environment.NewLine);
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error persisting data: " + ex.Message);
        }
    }

    public async Task<string> GetDataAsync()
    {
        lock (_dataQueue)
        {
            if (_dataQueue.Count > 0)
                return _dataQueue.Dequeue();
        }

        return null;
    }

    // Additional methods for configuration, monitoring, and maintenance tasks can be added here
}
