public class ResourceService {

    private static final int MAX_CONCURRENCY = 10;
    private static final AtomicInteger CONCURRENT_REQUESTS = new AtomicInteger(0);
    private static final int RETRY_DELAY = 500; // milliseconds
    private static final int MAX_RETRIES = 5;

    public String getMD5Hash(String id) {
        int retries = 0;
        while (retries < MAX_RETRIES) {
            try {
                if (CONCURRENT_REQUESTS.incrementAndGet() > MAX_CONCURRENCY) {
                    throw new IllegalStateException("Too many concurrent requests");
                }
                byte[] data = database.fetchResourceData(id);
                String md5Hash = MessageDigest.getInstance("MD5").digestToString(data);
                CONCURRENT_REQUESTS.decrementAndGet();
                return md5Hash;
            } catch (Exception e) {
                if (e instanceof InterruptedException || retries == MAX_RETRIES - 1) {
                    throw new RuntimeException("Failed to retrieve MD5 hash after " + MAX_RETRIES + " attempts", e);
                }
                try {
                    Thread.sleep(RETRY_DELAY * (1 << retries));
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            } finally {
                if (CONCURRENT_REQUESTS.decrementAndGet() < 0) {
                    CONCURRENT_REQUESTS.set(0);
                }
            }
            retries++;
        }
        throw new RuntimeException("Failed to retrieve MD5 hash after " + MAX_RETRIES + " attempts");
    }

