use std::collections::HashMap;
use std::env;
use std::time::{Duration, Instant};
use tokio::sync::{mpsc, RwLock};
use tokio::task;
use reqwest::Client;
use serde_json::Value;

#[derive(Clone)]
struct Config {
    cache_max_size: usize,
    cache_ttl: Duration,
    api_rate_limit_per_minute: u32,
}

struct StreamAggregator {
    client: Client,
    config: Config,
    cache: RwLock<HashMap<String, (Value, Instant)>>,
    rate_limiter: RateLimiter,
}

impl StreamAggregator {
    async fn new(config: Config) -> Self {
        let client = Client::new();
        let cache = HashMap::with_capacity(config.cache_max_size);
        let rate_limiter = RateLimiter::new(config.api_rate_limit_per_minute);
        StreamAggregator {
            client,
            config,
            cache: RwLock::new(cache),
            rate_limiter,
        }
    }

    async fn aggregate_metrics(&self) -> Result<Value, String> {
        // Fetch metrics from various sources
        let sources = vec![
            "internal_system_1",
            "third_party_api_2",
            "legacy_system_3",
        ];

        let mut tasks = Vec::new();
        for source in sources {
            tasks.push(task::spawn(async move {
                self.fetch_and_aggregate(source).await
            }));
        }

        let mut results = Vec::new();
        for task in tasks {
            match task.await {
                Ok(result) => results.extend(result),
                Err(e) => log_error(&e),
            }
        }

        // Aggregate results from all sources
        let aggregated_result = aggregate(results);
        Ok(aggregated_result)
    }

    async fn fetch_and_aggregate(&self, source: &str) -> Vec<Value> {
        match source {
            "internal_system_1" => self.fetch_from_internal_system().await,
            "third_party_api_2" => self.fetch_from_third_party_api().await,
            "legacy_system_3" => self.fetch_from_legacy_system().await,
            _ => panic!("Unknown source"),
        }
    }

    async fn fetch_from_internal_system(&self) -> Vec<Value> {
        // Fetch metrics from internal system
        vec![/* parsed data */]
    }

    async fn fetch_from_third_party_api(&self) -> Vec<Value> {
        self.rate_limiter.wait().await;
        let response = self.client.get("https://api.example.com/metrics").send().await?;
        match response.status() {
            reqwest::StatusCode::OK => parse_json_response(response).await,
            status => {
                log_error(&format!("API error: {}", status));
                Vec::new()
            }
        }
    }

    async fn fetch_from_legacy_system(&self) -> Vec<Value> {
        // Fetch metrics from legacy system
        vec![/* parsed data */]
    }
}

struct RateLimiter {
    limit: u32,
    count: u32,
    last_reset: Instant,
}

impl RateLimiter {
    fn new(limit: u32) -> Self {
        RateLimiter {
            limit,
            count: 0,
            last_reset: Instant::now(),
        }
    }

    async fn wait(&self) {
        let mut lock = self.count.lock().await;
        while *lock >= self.limit {
            task::yield_now().await;
        }
        if Instant::now() - self.last_reset > Duration::from_secs(60) {
            *lock = 0;
            self.last_reset = Instant::now();
        }
        *lock += 1;
    }
}

async fn parse_json_response(response: reqwest::Response) -> Vec<Value> {
    let body = response.text().await.unwrap_or_default();
    serde_json::from_str::<Value>(&body).unwrap_or_default()
        .as_array()
        .cloned()
        .unwrap_or_default()
}

fn aggregate(results: Vec<Value>) -> Value {
    // Aggregate results
    serde_json::json!({})
}

fn log_error(message: &str) {
    eprintln!("ERROR: {}", message);
}
