    AuthenticationAPI api;
    LoggingService logger;
    ResourceAllocator allocator;

    std::thread consumer([&]() {
        ConnectionRequest request;
        while (manager.tryGetNextConnection(request)) {
            if (api.authenticate(request)) {
                logger.logRequest(request, "Authentication successful");
                allocator.allocateResource();
