typedef struct {
    int packet_id;
    long timestamp;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PacketManager;

PacketManager* create_packet_manager() {
    PacketManager *manager = (PacketManager*)malloc(sizeof(PacketManager));
    if (!manager) return NULL;

    manager->capacity = 1024;
    manager->size = 0;
    manager->packets = (DataPacket*)malloc(manager->capacity * sizeof(DataPacket));
    pthread_mutex_init(&manager->lock, NULL);

    if (!manager->packets) {
        free(manager);
        return NULL;
    }

    return manager;
}

void destroy_packet_manager(PacketManager *manager) {
    if (!manager) return;

    pthread_mutex_destroy(&manager->lock);
    free(manager->packets);
    free(manager);
}

int add_packet(PacketManager *manager, DataPacket packet) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        DataPacket *new_packets = (DataPacket*)realloc(manager->packets, new_capacity * sizeof(DataPacket));

        if (!new_packets) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }

        manager->packets = new_packets;
        manager->capacity = new_capacity;
    }

    manager->packets[manager->size++] = packet;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Other functions for retrieving, updating, and removing packets would be implemented here

int main() {
    PacketManager *manager = create_packet_manager();
    if (!manager) return -1; // Memory allocation failed

    DataPacket packet;
    packet.packet_id = 1;
    packet.timestamp = time(NULL);
    packet.payload_size = 1024;

    if (add_packet(manager, packet) != 0) {
        destroy_packet_manager(manager);
        return -1; // Failed to add packet
    }

    // Additional operations would be performed here

    destroy_packet_manager(manager);
    return 0;
}
