import java.util.List;

public class RuleEngine implements TransactionValidator {
    private List<Rule> rules;

    public RuleEngine(List<Rule> rules) {
        this.rules = rules;
    }

    @Override
    public boolean validate(TransactionDTO transaction) {
        for (Rule rule : rules) {
            if (!rule.apply(transaction)) {
                return false;
            }
        }
        return true;
    }
}

