// Java Microservice Implementation

import io.micronaut.http.annotation.*;
import reactor.core.publisher.Flux;
import org.springframework.beans.factory.annotation.Autowired;

@Controller("/transactions")
public class TransactionController {

    @Autowired
    private TransactionService transactionService;

    @Post("/")
    public Mono<String> processTransaction(@Body TransactionRequest request) {
        return transactionService.process(request);
    }

    @Get("/status")
    public Mono<StatusResponse> getStatus() {
        return transactionService.getStatus();
    }
}

@Service
public class TransactionService {

    @Autowired
    private PaymentGatewayClient paymentGatewayClient;

    @Autowired
    private ExternalLoggingService loggingService;

    public Mono<String> process(TransactionRequest request) {
        return paymentGatewayClient.authorize(request)
            .flatMap(paymentResponse -> {
                if (paymentResponse.isSuccess()) {
                    // Log transaction details
                    loggingService.logTransaction(request, paymentResponse);
                    return paymentGatewayClient.settle(request, paymentResponse.getPaymentId());
                } else {
                    // Handle authorization failure
                    return Mono.error(new RuntimeException("Authorization failed"));
                }
            })
            .doOnError(error -> loggingService.logError(request, error));
    }

    public Mono<StatusResponse> getStatus() {
        // Retrieve and return system status
        return Mono.just(StatusResponse.builder().status("UP").build());
    }
}

