    private final EventRepository mongoRepository;
    private final CassandraEventRepository cassandraRepository;

    public EventProcessorService(EventRepository mongoRepository, CassandraEventRepository cassandraRepository) {
        this.mongoRepository = mongoRepository;
        this.cassandraRepository = cassandraRepository;
    }

    @StreamListener(Sink.INPUT)
    public void processEvent(String event) {
        // Process the event
        try {
            mongoRepository.save(event);
            cassandraRepository.save(event);
        } catch (Exception e) {
            handleFailure(event, e);
        }
    }

    private void handleFailure(String event, Exception e) {
        // Implement retry logic and fallback mechanisms
        logError(e);
        if (!isRetrySuccessful(event)) {
            sendToFallbackQueue(event);
        }
    }

    private boolean isRetrySuccessful(String event) {
        // Logic to check if retry is successful
        return false;
    }

    private void sendToFallbackQueue(String event) {
        // Send the event to a fallback queue
    }

    private void logError(Exception e) {
        // Log the error for monitoring and debugging
    }
}
