function reduceArray(arr, initialValue, callback) {
    let accumulator = initialValue;

    for (let i = 0; i < arr.length; i++) {
        try {
            accumulator = callback(accumulator, arr[i]);
        } catch (error) {
            console.error("Error during reduction:", error);
            return Promise.reject(error);
        }
    }

    return Promise.resolve(accumulator);
}

// Example usage:
const numbers = [1, 2, 3, 4, 5];
const initialValue = 0;

reduceArray(numbers, initialValue, (acc, num) => acc + num)
    .then(result => {
        console.log("Reduced value:", result); // Output: Reduced value: 15
    })
    .catch(error => {
        console.error("Error in reduction:", error);
    });
```

