        this.channel = ManagedChannelBuilder.forAddress(host, port)
                .usePlaintext()
                .build();
        this.stub = PaymentGatewayGrpc.newBlockingStub(channel);
    }

    public TransactionResponse processTransaction(TransactionRequest request) {
        try {
            return stub.processTransaction(request);
        } catch (Exception e) {
            // Handle error, retry mechanism, circuit breaker, etc.
            throw new RuntimeException("Failed to process transaction", e);
        }
    }

    public void shutdown() throws InterruptedException {
        channel.shutdown().awaitTermination(5, TimeUnit.SECONDS);
    }

    public static void main(String[] args) {
        PaymentMicroservice service = new PaymentMicroservice("payment-gateway-api.example.com", 8080);
        TransactionRequest request = // Initialize transaction request
        try {
            TransactionResponse response = service.processTransaction(request);
            System.out.println("Transaction processed: " + response);
        } finally {
            service.shutdown();
        }
    }
}
