#include <iostream>
#include <thread>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <future>
#include <chrono>
#include <unordered_map>

class paymentProcessor {
private:
    std::queue<std::shared_ptr<paymentTransaction>> transactionQueue;
    std::mutex queueMutex;
    std::condition_variable queueCondition;
    bool running;

public:
    paymentProcessor() : running(true) {
        // Start worker threads
        for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
            std::thread([this]() { processTransactions(); }).detach();
        }
    }

    ~paymentProcessor() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            running = false;
        }
        queueCondition.notify_all();
    }

    void enqueueTransaction(std::shared_ptr<paymentTransaction> transaction) {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            transactionQueue.push(transaction);
        }
        queueCondition.notify_one();
    }

private:
    void processTransactions() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            queueCondition.wait(lock, [this]() { return !running || !transactionQueue.empty(); });

            if (!running && transactionQueue.empty()) {
                break;
            }

            auto transaction = transactionQueue.front();
            transactionQueue.pop();
            lock.unlock();

            try {
                processTransaction(transaction);
            } catch (const std::exception& e) {
                handleException(transaction, e);
            }
        }
    }

    void processTransaction(std::shared_ptr<paymentTransaction> transaction) {
