// Java code for a robust distributed cache system

import java.util.concurrent.ConcurrentHashMap;
import java.util.Map;

public class DistributedCacheSystem {
    private Map<String, String> cache = new ConcurrentHashMap<>();
    private KeyManagementService kms;

    public DistributedCacheSystem(KeyManagementService kms) {
        this.kms = kms;
    }

    public void put(String key, String value) {
        if (value == null || value.isEmpty()) return;
        try {
            // Encrypt the value using KMS
            String encryptedValue = kms.encrypt(value);
            cache.put(key, encryptedValue);
        } catch (Exception e) {
            System.err.println("Encryption failed: " + e.getMessage());
        }
    }

    public String get(String key) {
        String encryptedValue = cache.get(key);
        if (encryptedValue == null) return null;
        try {
            // Decrypt the value using KMS
            return kms.decrypt(encryptedValue);
        } catch (Exception e) {
            System.err.println("Decryption failed: " + e.getMessage());
            return null;
        }
    }

    public void delete(String key) {
        cache.remove(key);
    }

    interface KeyManagementService {
        String encrypt(String data) throws Exception;
        String decrypt(String encryptedData) throws Exception;
    }
}

