#include <mutex>
#include <condition_variable>
#include <queue>
#include <vector>
#include <atomic>
#include <functional>
#include <memory>

class DynamicEntropyService {
public:
    using RngFunction = std::function<void(size_t, void*)>;

    DynamicEntropyService(RngFunction rngFunc) : rngFunc_(rngFunc), stopFlag_(false) {}

    ~DynamicEntropyService() {
        stopFlag_ = true;
        cv_.notify_all();
        for (auto& t : workers_) {
            if (t.joinable()) {
                t.join();
            }
        }
    }

    void start(size_t numThreads) {
        workers_.resize(numThreads);
        for (size_t i = 0; i < numThreads; ++i) {
            workers_[i] = std::thread(&DynamicEntropyService::workerThread, this);
        }
    }

    void generateRngData(void* data, size_t size) {
        std::unique_lock<std::mutex> lock(queueMutex_);
        queue_.push({data, size});
        cv_.notify_one();
    }

private:
    RngFunction rngFunc_;
    std::vector<std::thread> workers_;
    std::queue<std::pair<void*, size_t>> queue_;
    std::mutex queueMutex_;
    std::condition_variable cv_;
    std::atomic<bool> stopFlag_;

    void workerThread() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex_);
            cv_.wait(lock, [this] { return !queue_.empty() || stopFlag_; });

            if (stopFlag_) {
                break;
            }

            auto request = queue_.front();
            queue_.pop();
            lock.unlock();

            rngFunc_(request.second, request.first);
        }
    }
};

int main() {
    DynamicEntropyService service([](size_t size, void* data) {
        // Implement your RNG logic here
