public class FinancialTransactionProcessor
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<FinancialTransactionProcessor> _logger;
    private readonly ITransactionCache _transactionCache;
    private readonly IPaymentGateway _paymentGateway;
    private readonly IRegulatoryChecker _regulatoryChecker;
    private readonly INetworkManager _networkManager;

    public FinancialTransactionProcessor(
        HttpClient httpClient,
        ILogger<FinancialTransactionProcessor> logger,
        ITransactionCache transactionCache,
        IPaymentGateway paymentGateway,
        IRegulatoryChecker regulatoryChecker,
        INetworkManager networkManager)
    {
        _httpClient = httpClient;
        _logger = logger;
        _transactionCache = transactionCache;
        _paymentGateway = paymentGateway;
        _regulatoryChecker = regulatoryChecker;
        _networkManager = networkManager;
    }

    public async Task ProcessTransactionAsync(FinancialTransaction transaction)
    {
        try
        {
            // Deduplication check
            if (_transactionCache.Contains(transaction.Id))
            {
                _logger.LogInformation("Transaction {Id} is a duplicate, skipping.", transaction.Id);
                return;
            }

            // Rate limiting
            if (!_rateLimiter.AllowRequest(transaction.UserId))
            {
                _logger.LogWarning("Rate limit exceeded for user {UserId}.", transaction.UserId);
                return;
            }

            // Regulatory checks
            if (!await _regulatoryChecker.CheckComplianceAsync(transaction))
            {
                _logger.LogError("Transaction {Id} failed regulatory checks.", transaction.Id);
                return;
            }

            // Payment processing
            var paymentResult = await _paymentGateway.ProcessPaymentAsync(transaction);
            if (!paymentResult.Success)
            {
                _logger.LogError("Payment for transaction {Id} failed: {Error}.", transaction.Id, paymentResult.ErrorMessage);
                return;
            }

            // Update graph model asynchronously
            Task.Run(async () => await _graphDatabase.UpdateTransactionAsync(transaction));

            _transactionCache.Add(transaction.Id);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to process transaction {Id}.", transaction.Id);
        }
    }
}

