    public function createUser($data) {
        // Validation and persistence logic here
        $stmt = $this->db->prepare("INSERT INTO users (email, password, name) VALUES (?, ?, ?)");
        $stmt->execute([$data['email'], $data['password'], $data['name']]);
        return $stmt->rowCount();
    }

    public function readUser($id) {
        // Validation and persistence logic here
        $stmt = $this->db->prepare("SELECT * FROM users WHERE id = ?");
        $stmt->execute([$id]);
        return $stmt->fetch(PDO::FETCH_ASSOC);
    }

    public function updateUser($id, $data) {
        // Validation and persistence logic here
        $stmt = $this->db->prepare("UPDATE users SET email = ?, password = ?, name = ? WHERE id = ?");
        $stmt->execute([$data['email'], $data['password'], $data['name'], $id]);
        return $stmt->rowCount();
    }

    public function deleteUser($id) {
        // Validation and persistence logic here
        $stmt = $this->db->prepare("DELETE FROM users WHERE id = ?");
        $stmt->execute([$id]);
        return $stmt->rowCount();
    }
}

