using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading.Tasks;

public class OctreeServiceClient
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, object> _locks = new();

    public OctreeServiceClient()
    {
        _httpClient = new HttpClient();
    }

    public async Task UpdateOctreeElementAsync(string pageSectionId, string elementId, string htmlContent, double featureSize, int numberOfLeafNodes)
    {
        var lockKey = $"{pageSectionId}-{elementId}";
        if (!_locks.TryGetValue(lockKey, out var lockObj))
        {
            _locks.TryAdd(lockKey, new object());
            lockObj = _locks[lockKey];
        }

        await Task.Run(() => UpdateOctreeElement(pageSectionId, elementId, htmlContent, featureSize, numberOfLeafNodes), lockObj);
    }

    private async Task UpdateOctreeElement(string pageSectionId, string elementId, string htmlContent, double featureSize, int numberOfLeafNodes)
    {
        try
        {
            var request = new HttpRequestMessage(HttpMethod.Post, "https://octreeservice.com/update")
            {
                Content = new StringContent(JsonConvert.SerializeObject(new { 
                    PageSectionId = pageSectionId, 
                    ElementId = elementId, 
                    HtmlContent = htmlContent, 
                    FeatureSize = featureSize, 
                    NumberOfLeafNodes = numberOfLeafNodes 
                }), System.Text.Encoding.UTF8, "application/json")
            };

            var response = await _httpClient.SendAsync(request);

            if (!response.IsSuccessStatusCode)
            {
                throw new Exception($"Failed to update octree element: {response.StatusCode}");
            }
        }
        catch (Exception ex)
        {
            // Log exception and retry logic here
            throw;
        }
    }
}
```

