    {
        services.AddControllersWithViews();

        services.AddAuthentication(options =>
        {
            options.DefaultAuthenticateScheme = OAuthDefaults.AuthenticationScheme;
            options.DefaultSignInScheme = OAuthDefaults.AuthenticationScheme;
            options.DefaultChallengeScheme = OAuthDefaults.AuthenticationScheme;
        })
        .AddOAuth("ExternalOAuth", options =>
        {
            options.ClientId = Configuration["OAuth:ClientId"];
            options.ClientSecret = Configuration["OAuth:ClientSecret"];
            options.AuthorizationEndpointUrl = new Uri(Configuration["OAuth:AuthorizationEndpoint"]);
            options.TokenEndpointUrl = new Uri(Configuration["OAuth:TokenEndpoint"]);
            options.CallbackPath = "/signin-externaloauth";
        });

        services.AddDistributedMemoryCache();

        services.AddSession(options =>
        {
            options.IdleTimeout = TimeSpan.FromMinutes(30);
            options.Cookie.HttpOnly = true;
            options.Cookie.IsEssential = true;
        });
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
