#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>

class DistributedCache {
private:
    std::unordered_map<std::string, std::pair<std::string, int>> cache;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void set(const std::string& key, const std::string& value) {
        std::unique_lock<std::mutex> lock(mtx);
        cache[key] = {value, 1};
        cv.notify_one();
    }

    std::optional<std::string> get(const std::string& key) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this, &key]() { return cache.find(key) != cache.end(); });
        if (cache[key].second > 0) {
            --cache[key].second;
            return cache[key].first;
        }
        return std::nullopt;
    }

    void del(const std::string& key) {
        std::unique_lock<std::mutex> lock(mtx);
        if (cache.find(key) != cache.end()) {
            cache.erase(key);
        }
    }
};

int main() {
    DistributedCache cache;
    std::thread t1([&cache]() {
        for (int i = 0; i < 1000000; ++i) {
            cache.set("key" + std::to_string(i), "value" + std::to_string(i));
        }
    });

    std::thread t2([&cache]() {
        for (int i = 0; i < 500000; ++i) {
            cache.get("key" + std::to_string(i));
        }
    });

    std::thread t3([&cache]() {
        for (int i = 0; i < 250000; ++i) {
            cache.del("key" + std::to_string(i));
        }
    });

    t1.join();
    t2.join();
    t3.join();

    return 0;
}
```

This code snippet defines a basic distributed caching framework in C++ that supports concurrent access, including setting, getting, and deleting keys. It uses a mutex to ensure thread safety and a condition variable to manage synchronization between threads. The `main` function demonstrates how the cache can be used by multiple threads simultaneously.']

