int createSession(int sessionID, const char* peerAddress, size_t initialSize) {
    pthread_mutex_lock(&sessionMutex);
    if (sessionCount >= MAX_SESSIONS) {
        pthread_mutex_unlock(&sessionMutex);
        return -1;
    }
    NetworkSession* newSession = &sessions[sessionCount++];
    newSession->sessionID = sessionID;
    newSession->bufferSize = initialSize;
    newSession->dataLength = 0;
    strcpy(newSession->remotePeerAddress, peerAddress);
    newSession->buffer = (char*)malloc(initialSize * sizeof(char));
    pthread_mutex_unlock(&sessionMutex);
    return 0;
}

void freeSessions() {
    for (int i = 0; i < sessionCount; i++) {
        free(sessions[i].buffer);
    }
    sessionCount = 0;
    pthread_mutex_destroy(&sessionMutex);
