class SensorData {
    // Define the structure of sensor data
};

class DataProcessor {
private:
    std::queue<SensorData> dataQueue;
    std::mutex queueMutex;
    std::condition_variable dataCondition;
    bool running;

public:
    DataProcessor() : running(true) {}

    void startProcessing() {
        std::thread processingThread(&DataProcessor::processData, this);
        processingThread.detach();
    }

    void enqueueData(const SensorData& data) {
        std::lock_guard<std::mutex> lock(queueMutex);
        dataQueue.push(data);
        dataCondition.notify_one();
    }

private:
    void processData() {
        while (running) {
            std::unique_lock<std::mutex> lock(queueMutex);
            dataCondition.wait(lock, [this] { return !dataQueue.empty() || !running; });

            if (!running && dataQueue.empty()) break;

            SensorData data = dataQueue.front();
            dataQueue.pop();
            lock.unlock();

            // Process the data
            processSensorData(data);
        }
    }

    void processSensorData(const SensorData& data) {
        // Implement the processing logic here
    }
};

class DataSink {
public:
    virtual void sendData(const SensorData& data) = 0;
};

class ConsoleDataSink : public DataSink {
public:
    void sendData(const SensorData& data) override {
        std::cout << "Sending data to console: " << data /* Serialize data */ << std::endl;
    }
};

class IIoTLibrary {
private:
    DataProcessor processor;
    std::vector<DataSink*> sinks;

public:
    IIoTLibrary() {
        processor.startProcessing();
        // Add default sinks
        sinks.push_back(new ConsoleDataSink());
    }

    ~IIoTLibrary() {
        for (auto sink : sinks) {
            delete sink;
        }
    }

    void addSink(DataSink* sink) {
        sinks.push_back(sink);
    }

    void receiveData(const SensorData& data) {
        processor.enqueueData(data);

        // Send data to all sinks
        for (auto sink : sinks) {
            sink->sendData(data);
        }
    }
};

int main() {
    IIoTLibrary library;
    library.receiveData(/* Example sensor data */);
    return 0;
}
