#include <thread>
#include <mutex>
#include <condition_variable>
#include <future>
#include <chrono>

class KeyValueStore {
private:
    std::unordered_map<std::string, std::string> data;
    mutable std::mutex mutex;
    std::condition_variable cv;

public:
    void set(const std::string& key, const std::string& value) {
        std::unique_lock<std::mutex> lock(mutex);
        data[key] = value;
        cv.notify_all();
    }

    std::future<std::optional<std::string>> get(const std::string& key) {
        auto future = std::async(std::launch::async, [this, &key]() -> std::optional<std::string> {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this, &key] { return data.find(key) != data.end(); });
            return data[key];
        });
        return future;
    }

    void remove(const std::string& key) {
        std::unique_lock<std::mutex> lock(mutex);
        data.erase(key);
        cv.notify_all();
    }
};

int main() {
    KeyValueStore store;

    auto future1 = store.get("key1");
    store.set("key1", "value1");

    std::cout << "Value: " << future1.get().value_or("Not Found") << std::endl;

    store.remove("key1");

    return 0;
}
```

This code snippet provides a basic implementation of a thread-safe, asynchronous key-value store in C++. It uses an unordered map to store data and mutexes/condition variables for synchronization. The `set` method updates the value and notifies waiting threads, while the `get` method asynchronously waits for the key to be available before returning its value. The `remove` method removes a key and notifies waiting threads.

This example demonstrates fundamental concepts like thread safety, asynchronous operations, and condition variables. For a highly available and scalable distributed key-value store, you would need to build upon this with features like network communication, fault tolerance, load balancing, and more complex data structures and algorithms as described in the task.']

