['```cpp
#include <iostream>
#include <unordered_map>
#include <vector>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>

class KeyValueStore {
public:
    void set(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        store_[key] = value;
        notifyListeners(key, value);
    }

    std::string get(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (store_.find(key) != store_.end()) {
            return store_[key];
        }
        return "";
    }

    void addListener(std::function<void(const std::string&, const std::string&)> listener) {
        listeners_.push_back(listener);
    }

private:
    void notifyListeners(const std::string& key, const std::string& value) {
        for (auto& listener : listeners_) {
            listener(key, value);
        }
    }

    std::unordered_map<std::string, std::string> store_;
    std::vector<std::function<void(const std::string&, const std::string&)>> listeners_;
    std::mutex mutex_;
};

int main() {
    KeyValueStore kvs;
    kvs.addListener([](const std::string& key, const std::string& value) {
        std::cout << "Key: " << key << ", Value: " << value << std::endl;
    });

    kvs.set("name", "Alice");
    kvs.set("age", "30");

    return 0;
}
