// Define the ResourceLoader interface
public interface ResourceLoader {
    String loadResource(String resourceUrl, String protocol) throws Exception;
}

// Implement the ResourceLoader using a factory pattern
public class ResourceLoaderFactory {
    public static ResourceLoader getResourceLoader(String protocol) {
        switch (protocol.toLowerCase()) {
            case "http":
            case "https":
                return new HttpResourceLoader();
            case "file":
                return new FileResourceLoader();
            default:
                throw new IllegalArgumentException("Unsupported protocol: " + protocol);
        }
    }
}

// Implement the HTTP/HTTPS ResourceLoader using OAuth 2.0 and TLS 1.3
public class HttpResourceLoader implements ResourceLoader {
    private final HttpClient client;

    public HttpResourceLoader() {
        this.client = HttpClient.newBuilder()
                .sslParameters(SSLContext.getDefault().getSocketFactory())
                .build();
    }

    @Override
    public String loadResource(String resourceUrl, String protocol) throws Exception {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(new URI(resourceUrl))
                .header("Authorization", "Bearer " + getAccessToken())
                .version(HttpClient.Version.HTTP_1_1)
                .GET()
                .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

        if (response.statusCode() == 200) {
            return response.body();
        } else {
            throw new IOException("Failed to load resource: " + response.statusCode());
        }
    }

    private String getAccessToken() {
        // Implement OAuth 2.0 token retrieval logic here
        return "oauth_token";
    }
}

// Implement the File ResourceLoader for local file access
public class FileResourceLoader implements ResourceLoader {
    @Override
    public String loadResource(String resourceUrl, String protocol) throws Exception {
        Path path = Paths.get(resourceUrl);
        if (Files.exists(path)) {
            return new String(Files.readAllBytes(path));
        } else {
            throw new FileNotFoundException("File not found: " + resourceUrl);
        }
    }
}

// Main class to demonstrate the usage of ResourceLoader
public class Main {
    public static void main(String[] args) {
        try {
            ResourceLoader loader = ResourceLoaderFactory.getResourceLoader("https");
            String resource = loader.loadResource("https://api.example.com/data", "https");
            System.out.println(resource);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
