import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import org.apache.commons.dbcp2.BasicDataSource;

public class DisjointPairService {
    private final BasicDataSource dataSource;
    private final ExecutorService executorService;
    private final ConcurrentHashMap<Integer, Integer> parentMap = new ConcurrentHashMap<>();

    public DisjointPairService(int maxClients) {
        dataSource = configureDataSource();
        executorService = Executors.newFixedThreadPool(maxClients);
    }

    public void processDataStream(int[] dataArray) {
        for (int i = 0; i < dataArray.length - 1; i++) {
            int a = dataArray[i];
            int b = dataArray[i + 1];
            executeConcurrently(a, b);
        }
    }

    private void executeConcurrently(int a, int b) {
        executorService.submit(() -> {
            try {
                if (find(a) != find(b)) {
                    union(a, b);
                    storeResult(a, b);
                }
            } catch (Exception e) {
                logError(e);
            }
        });
    }

    private void union(int a, int b) {
        parentMap.merge(a, find(b), Math.min);
        parentMap.merge(b, find(a), Math.min);
    }

    private int find(int x) {
        return parentMap.computeIfAbsent(x, k -> k);
    }

    private void storeResult(int a, int b) throws Exception {
        // Insert into database logic here
    }

    private BasicDataSource configureDataSource() {
        BasicDataSource dataSource = new BasicDataSource();
        dataSource.setUrl("jdbc:mysql://localhost:3306/disjoint_pairs");
        dataSource.setUsername("user");
        dataSource.setPassword("password");
        return dataSource;
    }

    private void logError(Exception e) {
        // Log error logic here
    }

    public void shutdown() throws InterruptedException {
        executorService.shutdown();
        if (!executorService.awaitTermination(1, TimeUnit.MINUTES)) {
            executorService.shutdownNow();
        }
        try (var conn = dataSource.getConnection()) {
            // Clean up database resources
        } catch (Exception e) {
            logError(e);
        }
    }

    public static void main(String[] args) throws InterruptedException {
        DisjointPairService service = new DisjointPairService(1000);
        int[] largeArray = generateLargeDataArray(); // Implement this method to generate data
        service.processDataStream(largeArray);
        service.shutdown();
    }
}
