public class DistributedClientService {

    private ExecutorService executorService;
    private HealthCheckService healthCheckService;
    private ConfigService configService;
    private MessageSystem messageSystem;

    public DistributedClientService(int poolSize, HealthCheckService healthCheckService, ConfigService configService, MessageSystem messageSystem) {
        this.executorService = Executors.newFixedThreadPool(poolSize);
        this.healthCheckService = healthCheckService;
        this.configService = configService;
        this.messageSystem = messageSystem;
    }

    public void start() {
        // Start monitoring and adjusting connection pool size
        new Thread(() -> {
            while (true) {
                int currentPoolSize = executorService.getCorePoolSize();
                int targetPoolSize = calculateTargetPoolSize();
                if (targetPoolSize != currentPoolSize) {
                    executorService.setCorePoolSize(targetPoolSize);
                }
                try {
                    TimeUnit.MINUTES.sleep(1);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }).start();

        // Start processing client requests
        while (true) {
            Runnable task = new ClientRequestTask(healthCheckService, configService, messageSystem);
            executorService.execute(task);
        }
