// Function to fetch clinic data from legacy system with retries and exponential backoff
function fetchClinicData($clinicId) {
    $retries = 5;
    for ($i = 0; $i < $retries; $i++) {
        try {
            // Simulate API call
            $response = file_get_contents("http://legacy_system/api/clinics/{$clinicId}");
            return json_decode($response, true);
        } catch (Exception $e) {
            if ($i === $retries - 1) throw $e;
            sleep(2 ** $i); // Exponential backoff
        }
    }
}

// Function to update clinic status in the database with RBAC checks and caching
function updateClinicStatus($clinicId, $newStatus, $userId) {
    if (!isAuthorized($userId, 'update_clinic')) throw new Exception('Unauthorized');

    // Fetch clinic data from legacy system
    $clinicData = fetchClinicData($clinicId);

    // Update clinic status in database with transactional integrity
    $pdo = new PDO("mysql:host={$DATABASE_HOST};dbname={$DATABASE_NAME}", DATABASE_USER, DATABASE_PASSWORD);
    $pdo->beginTransaction();
    try {
        $stmt = $pdo->prepare('UPDATE clinics SET status = :status WHERE id = :id');
        $stmt->execute([':status' => $newStatus, ':id' => $clinicId]);
        $pdo->commit();
    } catch (Exception $e) {
        $pdo->rollBack();
        throw $e;
    }

    // Cache updated clinic data
    $redis->set("clinic:{$clinicId}", json_encode($clinicData));
}

// Function to check user authorization for a specific role
function isAuthorized($userId, $role) {
    // Simulate RBAC logic
