// Function to append a slash to the end of a URL if its length does not exceed a specified size limit
#[no_mangle]
pub extern "C" fn append_slash(url: *const c_char, max_len: usize) -> *mut c_char {
    unsafe {
        let url_str = CStr::from_ptr(url).to_str().unwrap();
        if url_str.len() + 1 <= max_len && !url_str.ends_with('/') {
            let mut new_url = String::from(url_str);
            new_url.push('/');
            CString::new(new_url).ok().map_or(std::ptr::null_mut(), |s| s.into_raw())
        } else {
            std::ptr::null_mut()
        }
    }
}

