use reqwest::Client;
use tokio::time::{self, Duration};
use std::error::Error;

#[derive(Debug)]
enum TransactionError {
    ApiError(reqwest::Error),
    ParseError(std::num::ParseIntError),
    Custom(String),
}

async fn processTransactionStream(
    api_url: String,
    validate_cert: bool,
    error_handler: Box<dyn Fn(TransactionError) -> () + Send + Sync>,
) -> Result<(u32, String), TransactionError> {
    let client = Client::builder()
        .danger_accept_invalid_certs(!validate_cert)
        .build()
        .map_err(|e| TransactionError::ApiError(e))?;

    let mut last_processed_time: Option<time::Instant> = None;
    let mut max_weighted_sum = 0u32;
    let mut corresponding_transaction_id = String::new();

    loop {
        match client.get(&api_url).send().await {
            Ok(response) => {
                if response.status().is_success() {
                    let transactions: Vec<Transaction> = response.json().await.map_err(|e| TransactionError::ApiError(e))?;

                    for transaction in transactions {
                        if let Some(last_time) = last_processed_time {
                            let time_difference = transaction.timestamp - last_time.elapsed().as_secs();
                            if time_difference < 3 {
                                continue; // Skip transactions within the same 3-second window
                            }
                        }

                        let weighted_sum = calculate_weighted_sum(&transaction);
                        if weighted_sum > max_weighted_sum {
                            max_weighted_sum = weighted_sum;
                            corresponding_transaction_id = transaction.id.clone();
                        }

                        last_processed_time = Some(time::Instant::now());
                    }
                } else {
                    return Err(TransactionError::ApiError(reqwest::Error::from_status(response.status())));
                }
            },
            Err(e) => {
                error_handler(TransactionError::ApiError(e));
                time::sleep(Duration::from_secs(5)).await; // Backoff strategy
            },
        }

        if max_weighted_sum > 0 {
            return Ok((max_weighted_sum, corresponding_transaction_id));
        }
    }
}

fn calculate_weighted_sum(transaction: &Transaction) -> u32 {
    // Implement the logic to calculate the weighted sum based on transaction details
    // Example: transaction.amount * transaction.time_since_last_processed
