fn main() {
    let api_url = "https://example.com/transactions";
    let validate_cert = true;
    let error_handler = Box::new(|e| println!("Error: {:?}", e));

    match processTransactionStream(api_url.to_string(), validate_cert, error_handler).await {
        Ok((max_weighted_sum, transaction_id)) => println!("Max Weighted Sum: {}, Transaction ID: {}", max_weighted_sum, transaction_id),
        Err(e) => println!("Failed to process transactions: {:?}", e),
    }
}
