#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure for each item in the bundle
typedef struct ResourceItem {
    char *key;
    void *data;
    struct ResourceItem *next;
} ResourceItem;

// Function to load a resource bundle from a file
int loadResourceBundle(const char *filePath, void **bundle, size_t *items) {
    // Open the file for reading
    FILE *file = fopen(filePath, "r");
    if (file == NULL) {
        return -1; // File open failed
    }

    // Initialize variables
    ResourceItem *head = NULL;
    ResourceItem *current = NULL;
    char line[256];
    size_t itemCount = 0;

    // Read the file line by line
    while (fgets(line, sizeof(line), file)) {
        // Parse each line to extract key and data
        char *key = strtok(line, ":");
        if (key == NULL) {
            continue; // Skip invalid lines
        }
        char *data = strtok(NULL, "\n");
        if (data == NULL) {
            continue; // Skip invalid lines
        }

        // Allocate memory for the new item
        ResourceItem *newItem = malloc(sizeof(ResourceItem));
        if (newItem == NULL) {
            fclose(file);
            return -2; // Memory allocation failed
        }

        // Store key and data in the new item
        newItem->key = strdup(key);
        newItem->data = strdup(data);
        newItem->next = NULL;

        // Add the new item to the linked list
        if (head == NULL) {
            head = newItem;
        } else {
            current->next = newItem;
        }
        current = newItem;
        itemCount++;
    }

    // Close the file
    fclose(file);

    // Store the bundle and item count in output parameters
    *bundle = head;
    *items = itemCount;

    return 0; // Success
}
