    {
        try
        {
            var parameters = await _configService.GetParametersAsync(siteName);
            if (parameters == null)
            {
                _logger.LogError("No configuration parameters found for site: {SiteName}", siteName);
                return;
            }

            var webConfigPath = Path.Combine(parameters.RootDirectory, "web.config");
            if (!File.Exists(webConfigPath))
            {
                _logger.LogError("Missing web.config file for site: {SiteName}", siteName);
                return;
            }

            var xmlDoc = new System.Xml.XmlDocument();
            xmlDoc.Load(webConfigPath);

            if (!xmlDoc.DocumentElement.HasChildNodes)
            {
                _logger.LogError("Invalid web.config file for site: {SiteName}", siteName);
                return;
            }

            _sites.TryAdd(siteName, new IISWebsite(siteName, parameters));
            _logger.LogInformation("Added site: {SiteName}", siteName);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error adding site: {SiteName}", siteName);
        }
    }

    public async Task MonitorSitesAsync()
    {
        while (true)
        {
            foreach (var site in _sites.Values)
            {
                try
                {
                    var status = await site.CheckStatusAsync();
                    if (status != SiteStatus.Healthy)
                    {
                        _logger.LogWarning("Site {SiteName} is not healthy: {Status}", site.Name, status);
                    }
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error monitoring site: {SiteName}", site.Name);
                }
            }

            await Task.Delay(TimeSpan.FromSeconds(60));
        }
    }

    public void RemoveSite(string siteName)
    {
        if (_sites.TryRemove(siteName, out var _))
        {
            _logger.LogInformation("Removed site: {SiteName}", siteName);
        }
        else
        {
            _logger.LogWarning("Site {SiteName} not found", siteName);
        }
    }

    public async Task UpdateSiteAsync(string siteName)
    {
        try
        {
            var parameters = await _configService.GetParametersAsync(siteName);
            if (parameters == null)
            {
                _logger.LogError("No configuration parameters found for site: {SiteName}", siteName);
                return;
            }

            if (_sites.TryUpdate(siteName, new IISWebsite(siteName, parameters), existing =>
                existing != null && existing.Parameters.Equals(parameters)))
            {
                _logger.LogInformation("Updated site: {SiteName}", siteName);
            }
            else
            {
                _logger.LogWarning("Failed to update site: {SiteName}", siteName);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating site: {SiteName}", siteName);
        }
    }

    public class IISWebsite
    {
        public string Name { get; }
        public WebsiteParameters Parameters { get; }

        public IISWebsite(string name, WebsiteParameters parameters)
        {
            Name = name;
            Parameters = parameters;
        }

        public async Task<SiteStatus> CheckStatusAsync()
        {
            // Simulate checking the status of an IIS website
            await Task.Delay(TimeSpan.FromSeconds(1));
            return SiteStatus.Healthy; // Return actual status based on checks
        }
    }

    public class WebsiteParameters
    {
        public string RootDirectory { get; set; }
        public int PoolId { get; set; }

        public bool Equals(WebsiteParameters other)
        {
            if (other == null) return false;
            return RootDirectory == other.RootDirectory && PoolId == other.PoolId;
        }
    }

    public enum SiteStatus
    {
        Healthy,
        Unhealthy,
        Degraded
    }
}

public interface IConfigurationService
{
    Task<WebsiteParameters> GetParametersAsync(string siteName);
}

public class ConfigurationService : IConfigurationService
{
    private readonly HttpClient _httpClient;

    public ConfigurationService(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<WebsiteParameters> GetParametersAsync(string siteName)
    {
        try
        {
            var response = await _httpClient.GetAsync($"https://configservice.com/sites/{siteName}");
            if (!response.IsSuccessStatusCode)
            {
                return null;
            }

            var json = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<WebsiteParameters>(json);
        }
        catch (Exception ex)
        {
            Log.Error(ex, "Error fetching configuration parameters for site: {SiteName}", siteName);
            return null;
        }
    }
}
