using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text.Json;
using System.Threading.Tasks;

public interface IOAuth2TokenProvider
{
    Task<OAuth2Token> DecryptAndDeserializeTokenAsync(string encryptedJson);
}

public class OAuth2TokenProvider : IOAuth2TokenProvider
{
    private readonly IKeyManager _keyManager;
    private readonly IVGenerator _ivGenerator;
    private readonly IRetryStrategy _retryStrategy;

    public OAuth2TokenProvider(IKeyManager keyManager, IVGenerator ivGenerator, IRetryStrategy retryStrategy)
    {
        _keyManager = keyManager;
        _ivGenerator = ivGenerator;
        _retryStrategy = retryStrategy;
    }

    public async Task<OAuth2Token> DecryptAndDeserializeTokenAsync(string encryptedJson)
    {
        try
        {
            var decryptedData = await _retryStrategy.ExecuteAsync(async () =>
            {
                var key = _keyManager.GetEncryptionKey();
                var iv = _ivGenerator.GenerateIV();
                var cipherText = Convert.FromBase64String(encryptedJson);
                using (var aesGcm = Aes.Create())
                {
                    aesGcm.Key = key;
                    aesGcm.IV = iv;
                    var plainText = aesGcm.Decrypt(cipherText, true);
                    return Encoding.UTF8.GetString(plainText);
                }
            });

            if (string.IsNullOrEmpty(decryptedData))
            {
                throw new InvalidOperationException("Decryption failed.");
            }

            var tokenJson = JsonDocument.Parse(decryptedData).RootElement;
            if (!tokenJson.TryGetProperty("access_token", out var accessToken) ||
                !tokenJson.TryGetInt32("expires_in", out var expiresIn) ||
                !tokenJson.TryGetProperty("token_type", out var tokenType))
            {
                throw new InvalidOperationException("Invalid token data.");
            }

            if (accessToken.ValueKind != JsonValueKind.String || tokenType.ValueKind != JsonValueKind.String)
            {
                throw new InvalidOperationException("Token properties must be of type string.");
            }

            if (expiresIn < 0)
            {
                throw new InvalidOperationException("Expires_in must be a positive integer.");
            }

            var token = new OAuth2Token
            {
                AccessToken = accessToken.GetString(),
                ExpiresIn = expiresIn,
                TokenType = tokenType.GetString()
            };

            if (!token.TokenType.Equals("Bearer", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException("Token type must be 'Bearer'.");
            }

            return token;
        }
        catch (Exception ex)
        {
            // Log error and retry strategy
            throw;
        }
    }
}

public class OAuth2Token
{
    public string AccessToken { get; set; }
    public int ExpiresIn { get; set; }
    public string TokenType { get; set; }
}

public interface IKeyManager
{
    byte[] GetEncryptionKey();
}

public class KeyManager : IKeyManager
{
    private readonly byte[] _encryptionKey;

    public KeyManager(byte[] encryptionKey)
    {
        _encryptionKey = encryptionKey;
    }

    public byte[] GetEncryptionKey()
    {
        return _encryptionKey;
    }
}

public interface IVGenerator
{
    byte[] GenerateIV();
}

public class IVGenerator : IVGenerator
{
    private readonly RandomNumberGenerator _rng;

    public IVGenerator()
    {
        _rng = new RNGCryptoServiceProvider();
    }

    public byte[] GenerateIV()
    {
        var iv = new byte[12]; // AES-GCM IV length is 12 bytes
        _rng.GetBytes(iv);
        return iv;
    }
}

public interface IRetryStrategy
{
    Task<T> ExecuteAsync<T>(Func<Task<T>> action);
}

public class RetryStrategy : IRetryStrategy
{
    private readonly int _maxRetries;

    public RetryStrategy(int maxRetries)
    {
        _maxRetries = maxRetries;
    }

    public async Task<T> ExecuteAsync<T>(Func<Task<T>> action)
    {
        for (int attempt = 0; attempt <= _maxRetries; attempt++)
        {
            try
            {
                return await action();
            }
            catch when (attempt < _maxRetries) // Retry on failure if not max attempts reached
            {
                await Task.Delay((int)Math.Pow(2, attempt) * 100); // Exponential backoff
            }
        }

        throw new InvalidOperationException("Operation failed after maximum retries.");
    }
}
```

This code defines a modular OAuth2 token provider library in C#. The `OAuth2TokenProvider` class implements the `IOAuth2TokenProvider` interface and provides the functionality to decrypt and deserialize encrypted JSON strings into an `OAuth2Token` object. It uses dependency injection for key management, IV generation, and retry strategy.

The `KeyManager` and `IVGenerator` classes implement interfaces to manage encryption keys and generate initialization vectors, respectively. The `RetryStrategy` class implements a simple exponential backoff retry mechanism with configurable maximum retries.

This design adheres to the principles of modularity, extensibility, security, and robust error handling, while providing flexibility for integration with multiple external services and databases.']

