import os
import hashlib
import logging
from datetime import datetime
import click

# Setup logging configuration
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

def calculate_md5(file_path, chunk_size=4*1024*1024):
    """Calculate MD5 hash of a file in chunks to handle large files efficiently."""
    md5_hash = hashlib.md5()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(chunk_size), b""):
            md5_hash.update(chunk)
    return md5_hash.hexdigest()

def log_file_info(file_path, metadata=None):
    """Log file hash and additional metadata to an external logging service."""
    try:
        md5 = calculate_md5(file_path)
        file_stats = os.stat(file_path)
        size = file_stats.st_size
        last_modified = datetime.fromtimestamp(file_stats.st_mtime).strftime('%Y-%m-%d %H:%M:%S')

        log_entry = {
            'file_path': file_path,
            'md5_hash': md5,
            'size': size,
            'last_modified': last_modified,
            **(metadata or {})
        }

        # Simulate logging to an external service
        logger.info(f"Logged file info: {log_entry}")
    except FileNotFoundError:
        logger.error(f"File not found: {file_path}")
    except Exception as e:
        logger.error(f"Error processing file: {file_path}, Error: {str(e)}")

@click.command()
@click.argument('file_paths', nargs=-1, type=click.Path(exists=True))
@click.option('--purpose', help='Purpose of the file.')
@click.option('--owner', help='Owner of the file.')
def process_files(file_paths, purpose=None, owner=None):
    """Process files and log their MD5 hash and additional metadata."""
    for file_path in file_paths:
        metadata = {'purpose': purpose, 'owner': owner}
        log_file_info(file_path, metadata)

if __name__ == '__main__':
    process_files()
