public class FileIntegrityMonitoringSystem {
    private ExecutorService executorService;
    private int maxConcurrentFiles;

    public FileIntegrityMonitoringSystem(int maxConcurrentFiles) {
        this.maxConcurrentFiles = maxConcurrentFiles;
        this.executorService = Executors.newFixedThreadPool(maxConcurrentFiles);
    }

    public void monitorFile(File file) {
        if (executorService.isShutdown()) {
            throw new IllegalStateException("System is shutting down.");
        }
        executorService.submit(() -> processFile(file));
    }

    private void processFile(File file) {
        // Implement file processing logic here
        System.out.println("Processing file: " + file.getName());
    }

    public void shutdown() throws InterruptedException {
        executorService.shutdown();
        if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
            executorService.shutdownNow();
        }
    }

    public static void main(String[] args) {
        int maxConcurrentFiles = 10; // Configurable value
        FileIntegrityMonitoringSystem system = new FileIntegrityMonitoringSystem(maxConcurrentFiles);

        // Simulate file monitoring
        for (int i = 0; i < 20; i++) {
            File simulatedFile = new File("file" + i + ".txt");
            system.monitorFile(simulatedFile);
        }

        try {
            system.shutdown();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
