#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PATH_LENGTH 260

typedef struct {
    char *path;
    int path_length;
    pthread_mutex_t lock;
} FilePath;

FilePath* create_file_path(const char *base, const char *filename) {
    FilePath *fp = malloc(sizeof(FilePath));
    if (!fp) return NULL;

    fp->path = malloc(MAX_PATH_LENGTH);
    if (!fp->path) {
        free(fp);
        return NULL;
    }

    snprintf(fp->path, MAX_PATH_LENGTH, "%s%s", base, filename);
    fp->path_length = strlen(fp->path);

    pthread_mutex_init(&fp->lock, NULL);
    return fp;
}

int validate_path(FilePath *fp) {
    pthread_mutex_lock(&fp->lock);
    if (fp->path_length > MAX_PATH_LENGTH) {
        pthread_mutex_unlock(&fp->lock);
        return -1; // Path too long
    }
    // TODO: Add additional checks for invalid characters, existence, etc.
    pthread_mutex_unlock(&fp->lock);
    return 0;
}

void free_file_path(FilePath *fp) {
    if (fp) {
        pthread_mutex_destroy(&fp->lock);
        free(fp->path);
        free(fp);
    }
}
