class HTTPRESTProtocol : public IoTDevice {
public:
    void onDataReceived(const std::string& data) override {
        // Handle HTTP/REST data and store it in the cloud
    }
};

// Data aggregation and deduplication service
class DataAggregator {
private:
    CloudDataLake* cloud;
    std::mutex mutex;
    std::condition_variable cv;
    std::atomic<bool> running{true};
    std::vector<std::string> dataQueue;

public:
    DataAggregator(CloudDataLake* cloud) : cloud(cloud) {}

    void start() {
        std::thread([this]() {
            while (running.load()) {
                std::unique_lock<std::mutex> lock(mutex);
                cv.wait(lock, [this] { return !dataQueue.empty(); });
                std::string data = dataQueue.back();
                dataQueue.pop_back();
                lock.unlock();

                // Aggregate and deduplicate data
                processAndStoreData(data);
            }
        }).detach();
    }

    void stop() {
        running.store(false);
        cv.notify_all();
    }

    void addData(const std::string& data) {
        std::lock_guard<std::mutex> lock(mutex);
        dataQueue.push_back(data);
        cv.notify_one();
    }

private:
    void processAndStoreData(const std::string& data) {
        // Aggregate and deduplicate logic
        if (cloud->storeData(data, "JSON")) {
            std::cout << "Data stored successfully" << std::endl;
        } else {
            std::cerr << "Failed to store data" << std::endl;
        }
    }
};

// Main function to set up the data processing pipeline
int main() {
    CloudDataLake* cloud = new CloudDataLake();
    DataAggregator aggregator(cloud);

    MQTTProtocol mqtt;
    CoAPProtocol coap;
    HTTPRESTProtocol http;

    mqtt.onDataReceived("MQTT data");
    coap.onDataReceived("CoAP data");
    http.onDataReceived("HTTP/REST data");

    // Start the aggregation service
    aggregator.start();

    // Simulate data ingestion
    for (int i = 0; i < 10; ++i) {
        aggregator.addData("Sample Data " + std::to_string(i));
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
    }

    // Stop the aggregation service
    aggregator.stop();

    delete cloud;

    return 0;
}
