struct CacheConfig {
    max_size: usize,
    ttl: Duration,
}

async fn fetch_data(client: &Client, url: &str) -> Result<Value, reqwest::Error> {
    client.get(url).send().await?.json().await
}

async fn process_data(data: Value) -> HashMap<String, f64> {
    // Placeholder for data processing logic
    let mut results = HashMap::new();
    if let Some(metrics) = data["metrics"].as_array() {
        for metric in metrics.iter() {
            if let (Some(name), Some(value)) = (metric["name"].as_str(), metric["value"].as_f64()) {
                results.insert(String::from(name), value);
            }
        }
    }
    results
}

async fn aggregate_metrics(
    client: Client,
    cache: RwLock<HashMap<String, (f64, Instant)>>,
    cache_config: CacheConfig,
) -> Result<(), Box<dyn std::error::Error>> {
    let urls = vec![
        "https://api.example.com/metrics1",
        "https://api.example.com/metrics2",
        // Add more URLs as needed
    ];

    for url in urls {
        if let Some(data) = cache.read().await.get(url) {
            if Instant::now() - data.1 <= cache_config.ttl {
                continue; // Use cached data
            }
        }

        let data = fetch_data(&client, url).await?;
        let metrics = process_data(data).await;

        for (name, value) in metrics {
            if let Some(mut cache_data) = cache.write().await.get_mut(url) {
                cache_data.0 += value;
            } else {
                cache.insert(url.to_string(), (value, Instant::now()));
                if cache.read().await.len() > cache_config.max_size {
                    // Implement eviction policy
                }
            }
        }
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let client = Client::new();
    let cache_config = CacheConfig { max_size: 1000, ttl: Duration::from_secs(60) };
    let cache = RwLock::new(HashMap::new());
    let (tx, mut rx) = mpsc::channel(32);

    tokio::spawn(async move {
        loop {
            if let Err(e) = aggregate_metrics(client.clone(), cache.clone(), cache_config.clone()).await {
                eprintln!("Error aggregating metrics: {}", e);
            }
            tokio::time::sleep(Duration::from_secs(1)).await;
        }
    });

    while let Some(message) = rx.recv().await {
        println!("Received message: {}", message);
    }

    Ok(())
}
