#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define FrameMetadata structure
typedef struct {
    int frame_id;
    time_t timestamp;
    // Other members of FrameMetadata
} FrameMetadata;

// Define ChannelQualityIndication structure
typedef struct {
    float signal_strength;
    float noise_level;
    float interference_level;
    // Other members of ChannelQualityIndication
} ChannelQualityIndication;

// Linked list node
typedef struct Node {
    FrameMetadata data;
    struct Node* next;
} Node;

// Head of the linked list
Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new node at the end of the linked list
void append_node(FrameMetadata metadata) {
    pthread_mutex_lock(&lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        // Handle memory allocation failure
        perror("Memory allocation failed");
        pthread_mutex_unlock(&lock);
        return;
    }
    new_node->data = metadata;
    new_node->next = NULL;

    if (head == NULL) {
        head = new_node;
    } else {
        Node* last = head;
        while (last->next != NULL) {
            last = last->next;
        }
        last->next = new_node;
    }
    pthread_mutex_unlock(&lock);
}

// Function to iterate over the linked list and compute aggregate metrics
void compute_aggregate_metrics() {
    pthread_mutex_lock(&lock);
    Node* current = head;
    float total_signal_strength = 0.0;
    int count = 0;

    while (current != NULL) {
        // Compute aggregate metrics based on FrameMetadata and ChannelQualityIndication
        for (int i = 0; i < current->data.num_channel_quality_indications; i++) {
            total_signal_strength += current->data.channel_quality_indications[i].signal_strength;
        }
        count++;
        current = current->next;
    }

    if (count > 0) {
        float average_signal_strength = total_signal_strength / count;
        printf("Average Signal Strength: %f\n", average_signal_strength);
    } else {
        printf("No data available for aggregation.\n");
    }
    pthread_mutex_unlock(&lock);
}

// Function to clean up and free memory allocated for the linked list
void cleanup() {
    pthread_mutex_lock(&lock);
    Node* current = head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
    pthread_mutex_unlock(&lock);
}

int main() {
    // Example usage
    FrameMetadata metadata1 = {1, time(NULL), {{2.5, -3.0, 1.2}, {2.4, -2.9, 1.1}}};
    FrameMetadata metadata2 = {2, time(NULL) + 1, {{2.6, -3.1, 1.3}, {2.5, -3.0, 1.2}}};

    append_node(metadata1);
    append_node(metadata2);

    compute_aggregate_metrics();

    cleanup();

    return 0;
}
