#include <string.h>

typedef struct {
    char* algorithm_name;
    void (*encrypt)(char*, char*);
} CryptoAlgorithm;

CryptoAlgorithm* algorithms[10];
int num_algorithms = 0;

void add_algorithm(char* name, void (*encrypt_func)(char*, char*)) {
    if (num_algorithms >= 10) return; // Limit to 10 algorithms for simplicity
    algorithms[num_algorithms++] = (CryptoAlgorithm*)malloc(sizeof(CryptoAlgorithm));
    algorithms[num_algorithms - 1].algorithm_name = strdup(name);
    algorithms[num_algorithms - 1].encrypt = encrypt_func;
}

void encrypt_data(char* data, char* algorithm_name) {
    int i;
    for (i = 0; i < num_algorithms; i++) {
        if (strcmp(algorithms[i]->algorithm_name, algorithm_name) == 0) {
            algorithms[i]->encrypt(data, "encrypted_data");
            return;
        }
    }
    printf("Algorithm %s not found\n", algorithm_name);
}

void simple_encrypt(char* data, char* encrypted_data) {
    // Simple encryption logic
    strcpy(encrypted_data, data);
}

int main() {
    add_algorithm("SimpleEncrypt", simple_encrypt);

    char data[] = "Hello, World!";
    encrypt_data(data, "SimpleEncrypt");

    return 0;
}
