                // Simple encryption logic
                encryptedData = data;
            }
        });

        String data = "Hello, World!";
        encryptData(data, "SimpleEncrypt");
    }

    interface EncryptionAlgorithm {
        void encrypt(String data, String encryptedData);
    }
}
