    new_node->next = *head;
    *head = new_node;
}

// Function to remove a node from the concurrent linked list
void remove_node(Node** head, int frame_id) {
    Node* current = *head;
    Node* previous = NULL;

    while (current != NULL) {
        pthread_mutex_lock(&current->mutex);
        if (current->data.frame_id == frame_id) {
            if (previous == NULL) {
                *head = current->next;
            } else {
                previous->next = current->next;
            }
            pthread_mutex_unlock(&current->mutex);
            pthread_mutex_destroy(&current->mutex);
            free(current);
            return;
        }
        pthread_mutex_unlock(&current->mutex);
        previous = current;
        current = current->next;
    }
}

