// Define NetworkSession structure
typedef struct {
    char sessionID[256];
    char* buffer;
    size_t bufferSize;
    size_t dataLength;
    char remotePeerAddress[128];
} NetworkSession;

// Function prototypes
NetworkSession* createNetworkSession(const char* sessionID, const char* peerAddress, size_t initialSize);
void destroyNetworkSession(NetworkSession* session);
void resizeBuffer(NetworkSession* session, size_t newSize);

// Create a new network session
NetworkSession* createNetworkSession(const char* sessionID, const char* peerAddress, size_t initialSize) {
    NetworkSession* session = (NetworkSession*)malloc(sizeof(NetworkSession));
    if (session == NULL) {
        perror("Failed to allocate memory for NetworkSession");
        return NULL;
    }

    strncpy(session->sessionID, sessionID, sizeof(session->sessionID) - 1);
    session->buffer = (char*)malloc(initialSize);
    if (session->buffer == NULL) {
        perror("Failed to allocate initial buffer for NetworkSession");
        free(session);
        return NULL;
    }
    session->bufferSize = initialSize;
    session->dataLength = 0;
    strncpy(session->remotePeerAddress, peerAddress, sizeof(session->remotePeerAddress) - 1);

    return session;
}

// Destroy a network session
void destroyNetworkSession(NetworkSession* session) {
    if (session != NULL) {
        free(session->buffer);
        free(session);
    }
}

// Resize the buffer of a network session
void resizeBuffer(NetworkSession* session, size_t newSize) {
    char* newBuffer = (char*)realloc(session->buffer, newSize);
    if (newBuffer == NULL) {
        perror("Failed to reallocate memory for NetworkSession buffer");
        return;
    }

    session->buffer = newBuffer;
    session->bufferSize = newSize;

    // Ensure the dataLength does not exceed the new buffer size
    if (session->dataLength > newSize) {
        session->dataLength = newSize;
    }
}

// Example usage
int main() {
    NetworkSession* session = createNetworkSession("12345", "192.168.1.1", 1024);
    if (session != NULL) {
        printf("Network session created: %s\n", session->sessionID);

        // Simulate receiving data
        resizeBuffer(session, 2048);
        memcpy(session->buffer, "Hello, world!", 13);
        session->dataLength = 13;

        // Clean up
        destroyNetworkSession(session);
    }

    return 0;
}
```

