CRC_LIST_T crc_list;

void init_crc_list() {
    pthread_mutex_init(&crc_list.lock, NULL);
    pthread_cond_init(&crc_list.cond, NULL);
    crc_list.count = 0;
}

void add_entry(NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&crc_list.lock);
    if (crc_list.count < MAX_ENTRIES) {
        crc_list.entries[crc_list.count++] = entry;
        pthread_cond_signal(&crc_list.cond);
    } else {
        // Handle list full
    }
    pthread_mutex_unlock(&crc_list.lock);
}

void* crc_validation_thread(void* arg) {
    while (1) {
        pthread_mutex_lock(&crc_list.lock);
        if (crc_list.count > 0) {
            NFAPI_CRC_INDICATION_PDU_T entry = crc_list.entries[0];
            for (int i = 0; i < crc_list.count - 1; i++) {
                crc_list.entries[i] = crc_list.entries[i + 1];
            }
            crc_list.count--;
            pthread_cond_signal(&crc_list.cond);
            pthread_mutex_unlock(&crc_list.lock);

            // Perform CRC validation and API request here
            // Implement retry logic with exponential backoff
            // Handle token bucket algorithm for rate limiting

        } else {
            pthread_cond_wait(&crc_list.cond, &crc_list.lock);
        }
    }
    return NULL;
}

void* expiration_thread(void* arg) {
    while (1) {
        time_t now = time(NULL);
        pthread_mutex_lock(&crc_list.lock);
        if (crc_list.count > 0) {
            for (int i = 0; i < crc_list.count; i++) {
                NFAPI_CRC_INDICATION_PDU_T* entry = &crc_list.entries[i];
                if (now - entry->rx_ue_information_tag > 3600) {
                    // Handle expiration
                    memmove(entry, entry + 1, (crc_list.count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                    crc_list.count--;
                } else {
                    break;
                }
            }
        }
        pthread_mutex_unlock(&crc_list.lock);
        sleep(60); // Check every minute
    }
    return NULL;
}

int main() {
    init_crc_list();
    pthread_t validation_thread, expiration_thread;
    pthread_create(&validation_thread, NULL, crc_validation_thread, NULL);
    pthread_create(&expiration_thread, NULL, expiration_thread, NULL);

    // Add entries to the list here

    pthread_join(validation_thread, NULL);
    pthread_join(expiration_thread, NULL);

    return 0;
