// Import necessary modules
const { exec } = require('child_process');
const fs = require('fs');
const os = require('os');

// Function to securely execute shell commands with async output streaming
async function executeCommand(command) {
    return new Promise((resolve, reject) => {
        const childProcess = exec(command, (error, stdout, stderr) => {
            if (error) {
                reject(error);
            } else {
                resolve({ stdout, stderr });
            }
        });

        childProcess.stdout.on('data', (chunk) => {
            // Stream output to minimize latency
            process.stdout.write(chunk);
        });

        childProcess.stderr.on('data', (chunk) => {
            // Stream errors to minimize latency
            process.stderr.write(chunk);
        });
    });
}

// Function to handle command outputs and invoke callback on exceeding size limit
function processString(input, sizeLimit, onRestrictionExceeded) {
    const trimmedInput = input.trim();
    if (trimmedInput.length <= sizeLimit) {
        return new Promise((resolve) => {
            resolve(`${trimmedInput}/`);
        });
    } else {
        console.warn(`Input exceeds size limit: ${input}`);
        return new Promise((_, reject) => {
            onRestrictionExceeded(input);
            reject(new Error('Size restriction exceeded'));
        });
    }
}

// Example usage of executeCommand
executeCommand('ls -la').then(result => {
    console.log('Standard Output:', result.stdout);
}).catch(error => {
    console.error('Error:', error.stderr);
});

// Example usage of processString
processString('example input', 10, (input) => {
    console.warn(`Callback invoked for: ${input}`);
}).then(newInput => {
    console.log('Processed Input:', newInput);
}).catch(error => {
    console.error('Error processing string:', error.message);
});
