    private readonly ILogger<ExternalApiService> _logger;

    public ExternalApiService(HttpClient httpClient, ILogger<ExternalApiService> logger)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<string> GetRealTimeDataAsync(string apiUrl)
    {
        // Implement real-time data retrieval logic here
        return await _httpClient.GetStringAsync(apiUrl);
    }

    public async Task<string> GetHistoricalDataAsync(string apiUrl, DateTime startDate, DateTime endDate)
    {
        // Implement historical data retrieval logic here
        var queryString = $"start={startDate.ToString("yyyy-MM-dd")}&end={endDate.ToString("yyyy-MM-dd")}";
        return await _httpClient.GetStringAsync($"{apiUrl}?{queryString}");
    }
}

