#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_INTS 1000000

typedef struct {
    int* buffer;
    size_t capacity;
    size_t count;
} InputBuffer;

void init_buffer(InputBuffer* buf, size_t capacity) {
    buf->buffer = (int*)malloc(capacity * sizeof(int));
    buf->capacity = capacity;
    buf->count = 0;
}

void free_buffer(InputBuffer* buf) {
    free(buf->buffer);
    buf->buffer = NULL;
    buf->capacity = 0;
    buf->count = 0;
}

int read_ints_from_file(InputBuffer* buf, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    int num;
    while (fread(&num, sizeof(int), 1, file)) {
        if (buf->count >= buf->capacity) {
            // Resize buffer or handle error
            return -1;
        }
        buf->buffer[buf->count++] = num;
    }

    fclose(file);
    return 0;
}

void* process_buffer(void* arg) {
    InputBuffer* buf = (InputBuffer*)arg;
    for (size_t i = 0; i < buf->count; ++i) {
        // Apply transformation rules
        printf("Processed: %d\n", buf->buffer[i]);
    }
    return NULL;
}

int main() {
    InputBuffer buffer;
    init_buffer(&buffer, MAX_INTS);

    if (read_ints_from_file(&buffer, "input.bin") == 0) {
        pthread_t thread;
        pthread_create(&thread, NULL, process_buffer, &buffer);
        pthread_join(thread, NULL);
    } else {
        fprintf(stderr, "Failed to read integers from file.\n");
    }

    free_buffer(&buffer);
    return 0;
}
```

