#define MAX_STRUCTS 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRCFLAG[SHA256_DIGEST_LENGTH];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **list;
    size_t count;
    pthread_mutex_t lock;
} CRC_LIST;

CRC_LIST *create_crc_list(size_t N) {
    if (N < 1 || N > MAX_STRUCTS) {
        fprintf(stderr, "Error: Invalid number of structures. Must be between 1 and %zu\n", MAX_STRUCTS);
        return NULL;
    }

    CRC_LIST *list = malloc(sizeof(CRC_LIST));
    list->list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    list->count = N;
    pthread_mutex_init(&list->lock, NULL);

    for (size_t i = 0; i < N; i++) {
        list->list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    return list;
}

void destroy_crc_list(CRC_LIST *list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; i++) {
        free(list->list[i]);
    }
    free(list->list);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void compute_crc(NFAPI_CRC_INDICATION_PDU_T *pdu, int use_sha256) {
    unsigned char combined[8];
    memcpy(combined, &pdu->RX_UE_INFORMATION_TAG, sizeof(int));
    memcpy(combined + sizeof(int), &pdu->RNTI, sizeof(int));

    if (use_sha256) {
        SHA256(combined, sizeof(combined), pdu->CRCFLAG);
    } else {
        // Placeholder for alternative hashing algorithm
        memset(pdu->CRCFLAG, 0, SHA256_DIGEST_LENGTH);
    }
}

void add_to_crc_list(CRC_LIST *list, NFAPI_CRC_INDICATION_PDU_T *pdu, int use_sha256) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; i++) {
        if (!list->list[i]) {
            memcpy(list->list[i], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            compute_crc(list->list[i], use_sha256);
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }
    pthread_mutex_unlock(&list->lock);
    fprintf(stderr, "Error: List is full\n");
}

