DynamicListManager* createDynamicListManager(HashAlgorithm hashAlgorithm, PersistenceStrategy persistenceStrategy) {
    DynamicListManager* manager = (DynamicListManager*)malloc(sizeof(DynamicListManager));
    if (!manager) return NULL;

    manager->count = 0;
    manager->hashAlgorithm = hashAlgorithm;
    manager->persistenceStrategy = persistenceStrategy;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroyDynamicListManager(DynamicListManager* manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int addStructToDynamicList(DynamicListManager* manager, NFAPI_CRC_INDICATION_PDU_T* newStruct) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_STRUCTS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // List is full
    }
