import hashlib
import logging
from multiprocessing import Pool
import os

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class FileHasher:
    def __init__(self, log_service):
        self.log_service = log_service

    def calculate_md5(self, file_path):
        md5_hash = hashlib.md5()
        with open(file_path, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                md5_hash.update(chunk)
        return md5_hash.hexdigest()

    def log_file_info(self, file_path, metadata):
        file_size = os.path.getsize(file_path)
        last_modified = os.path.getmtime(file_path)
        self.log_service.log({
            'file_path': file_path,
            'md5_hash': self.calculate_md5(file_path),
            'file_size': file_size,
            'last_modified': last_modified,
            **metadata
        })

class DistributedFileHasher:
    def __init__(self, log_service):
        self.file_hasher = FileHasher(log_service)

    def hash_files(self, file_paths, metadata=None):
        if metadata is None:
            metadata = {}
        with Pool() as pool:
            pool.starmap(self.file_hasher.log_file_info, [(file_path, {**metadata, 'file_name': os.path.basename(file_path)}) for file_path in file_paths])

class ExternalLoggingService:
    def log(self, data):
        # Placeholder for actual logging service integration
        logging.info(f"Log data: {data}")

# Usage example
if __name__ == "__main__":
    log_service = ExternalLoggingService()
    hasher = DistributedFileHasher(log_service)
    file_paths = ['path/to/file1', 'path/to/file2']  # Replace with actual file paths
    hasher.hash_files(file_paths, metadata={'owner': 'user1', 'purpose': 'backup'})
```

