#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    // Fields of the structure
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node for the dynamic list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the dynamic list structure
typedef struct {
    Node* head;
    int count;
} DynamicList;

// Function to initialize the dynamic list
void initDynamicList(DynamicList* list) {
    list->head = NULL;
    list->count = 0;
}

// Function to insert an element into the dynamic list
void insertElement(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        // Handle memory allocation failure
        return;
    }
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
}

// Function to delete an element from the dynamic list
void deleteElement(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL) {
        if (memcmp(&current->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            list->count--;
            return;
        }
        previous = current;
        current = current->next;
    }
}

// Function to search for an element in the dynamic list
Node* searchElement(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* current = list->head;

    while (current != NULL) {
        if (memcmp(&current->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
            return current;
        }
        current = current->next;
    }

    return NULL;
}

// Function to free the dynamic list
void freeDynamicList(DynamicList* list) {
    Node* current = list->head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->count = 0;
}

// Function to get the number of elements in the dynamic list
int getCount(DynamicList* list) {
    return list->count;
}
