// Define ChannelQualityIndication structure
typedef struct {
    float signal_strength;
    float noise_level;
    float interference_level;
} ChannelQualityIndication;

// Define Node structure for the linked list
typedef struct Node {
    FrameMetadata *metadata;
    ChannelQualityIndication *cqis;
    struct Node *next;
} Node;

// Define LinkedList structure to manage the linked list
typedef struct {
    Node *head;
    pthread_mutex_t lock;  // Mutex for thread-safe operations
} LinkedList;

// Initialize the linked list
void initLinkedList(LinkedList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Add a new node to the linked list
void addNode(LinkedList *list, FrameMetadata *metadata, ChannelQualityIndication *cqis) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_node->metadata = metadata;
    new_node->cqis = cqis;
    new_node->next = list->head;
    pthread_mutex_lock(&list->lock);
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

// Free the linked list and its nodes
void freeLinkedList(LinkedList *list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current->metadata);
        free(current->cqis);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

// Example function to simulate asynchronous data processing
void processAsyncData(LinkedList *list, void (*callback)(Node *)) {
    Node *current = list->head;
    while (current != NULL) {
        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, (void *(*)(void *))callback, current) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            return;
        }
        pthread_detach(thread_id);
        current = current->next;
    }
}

// Example callback function
void exampleCallback(Node *node) {
    printf("Frame ID: %d, Timestamp: %ld\n", node->metadata->frame_id, node->metadata->timestamp);
    // Additional processing logic here
}
