#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>

#define MAX_COMMANDS 10000

typedef struct {
    int id;
    char command[256];
    char log[512];
} Command;

Command commands[MAX_COMMANDS];
int command_count = 0;
pthread_mutex_t command_lock;

void* execute_command(void* arg) {
    int index = *(int*)arg;
    pthread_mutex_lock(&command_lock);
    if (index >= 0 && index < command_count) {
        pid_t pid = fork();
        if (pid == 0) {
            execl("/bin/sh", "sh", "-c", commands[index].command, NULL);
            perror("execl");
            exit(EXIT_FAILURE);
        } else if (pid > 0) {
            int status;
            waitpid(pid, &status, 0);
            sprintf(commands[index].log, "Command executed: %s - Status: %d", commands[index].command, WEXITSTATUS(status));
        } else {
            perror("fork");
        }
    }
    pthread_mutex_unlock(&command_lock);
    free(arg);
    return NULL;
}

void add_command(const char* command) {
    if (command_count < MAX_COMMANDS) {
        strcpy(commands[command_count].command, command);
        commands[command_count].id = command_count;
        command_count++;
    } else {
        fprintf(stderr, "Error: Command limit reached\n");
    }
}

void log_commands() {
    for (int i = 0; i < command_count; i++) {
        printf("Command ID: %d, Log: %s\n", commands[i].id, commands[i].log);
    }
}

int main() {
    pthread_t threads[MAX_COMMANDS];
    int* args[MAX_COMMANDS];

    pthread_mutex_init(&command_lock, NULL);

    add_command("echo Hello World");
    add_command("ls -la");

    for (int i = 0; i < command_count; i++) {
        args[i] = malloc(sizeof(int));
        *args[i] = i;
        if (pthread_create(&threads[i], NULL, execute_command, args[i]) != 0) {
            perror("pthread_create");
        }
    }

    for (int i = 0; i < command_count; i++) {
        pthread_join(threads[i], NULL);
        free(args[i]);
    }

    log_commands();

    pthread_mutex_destroy(&command_lock);

    return 0;
}
