public class LogEventSerializer {

    private static final ObjectMapper objectMapper = new ObjectMapper();

    public static String serialize(LogEvent logEvent) {
        try {
            return objectMapper.writeValueAsString(logEvent);
        } catch (Exception e) {
            throw new RuntimeException("Failed to serialize log event", e);
        }
    }

    public static LogEvent deserialize(String json) {
        try {
            return objectMapper.readValue(json, LogEvent.class);
        } catch (Exception e) {
            throw new RuntimeException("Failed to deserialize log event", e);
        }
    }

    public static void main(String[] args) {
        LogEvent event = new LogEvent("INFO", "User logged in");
        String json = serialize(event);
        LogEvent deserializedEvent = deserialize(json);
        System.out.println(deserializedEvent);
    }
}

