#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <pthread.h>
#include <time.h>

#define MAX_COMMAND_LENGTH 256
#define DEFAULT_TIMEOUT 5

typedef struct {
    char command[MAX_COMMAND_LENGTH];
    int timeout;
} Command;

void* execute_command(void* arg) {
    Command* cmd = (Command*)arg;
    pid_t pid = fork();

    if (pid == -1) {
        perror("fork");
        return NULL;
    } else if (pid == 0) {
        // Child process
        execl("/bin/sh", "sh", "-c", cmd->command, NULL);
        perror("execl");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int status;
        struct timespec start_time, end_time;
        clock_gettime(CLOCK_REALTIME, &start_time);

        while (1) {
            if (waitpid(pid, &status, WNOHANG) == -1) {
                perror("waitpid");
                return NULL;
            } else if (WIFEXITED(status)) {
                break;
            }

            clock_gettime(CLOCK_REALTIME, &end_time);
            long elapsed_time = (end_time.tv_sec - start_time.tv_sec) + 
                               (end_time.tv_nsec - start_time.tv_nsec) / 1e9;

            if (elapsed_time > cmd->timeout) {
                kill(pid, SIGKILL);
                waitpid(pid, NULL, 0); // Wait for the process to terminate
                fprintf(stderr, "Command timed out after %ld seconds\n", elapsed_time);
                return NULL;
            }

            sleep(1); // Sleep for a short duration before checking again
        }

        if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
            fprintf(stderr, "Command failed with exit status %d\n", WEXITSTATUS(status));
        }
    }

    return NULL;
}

void run_command(const char* command, int timeout) {
    Command cmd;
    strncpy(cmd.command, command, sizeof(cmd.command) - 1);
    cmd.timeout = timeout;

    pthread_t thread;
    if (pthread_create(&thread, NULL, execute_command, &cmd) != 0) {
        perror("pthread_create");
        return;
    }

    pthread_join(thread, NULL);
}

int main() {
    run_command("ls -l /", DEFAULT_TIMEOUT);
    run_command("sleep 10 && echo 'Done'", 5);

    return 0;
}
```

This code snippet demonstrates a basic implementation of an asynchronous command execution function in C using `fork` and `wait`. It includes handling for timeouts, command failures, and resource cleanup. Note that this is a simplified example and does not include detailed logging or advanced error handling as specified in the requirements.']

