#include <iostream>
#include <unordered_map>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>

class CacheFramework {
public:
    void addURL(const std::string& url, const std::unordered_map<std::string, std::string>& headers) {
        std::lock_guard<std::mutex> lock(mutex_);
        cache_[url] = headers;
        condition_.notify_all();
    }

    std::unordered_map<std::string, std::string> getURL(const std::string& url) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (cache_.find(url) == cache_.end()) {
            condition_.wait(lock);
        }
        return cache_[url];
    }

private:
    std::unordered_map<std::string, std::unordered_map<std::string, std::string>> cache_;
    mutable std::mutex mutex_;
    std::condition_variable condition_;
};

int main() {
    CacheFramework cache;
    // Example usage
    cache.addURL("https://example.com", {{"Authorization", "Bearer token"}, {"Accept", "application/json"}});
    auto headers = cache.getURL("https://example.com");
    for (const auto& header : headers) {
        std::cout << header.first << ": " << header.second << std::endl;
    }
    return 0;
}
```

