#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <oauth2.h>

#define MAX_COMMAND_LENGTH 1024
#define MAX_LOG_LENGTH 2048

typedef struct {
    char command[MAX_COMMAND_LENGTH];
    int timeout;
} Command;

void* execute_command(void* arg) {
    Command* cmd = (Command*)arg;
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return NULL;
    } else if (pid == 0) {
        // Execute the command
        char** args = str_split(cmd->command, " ");
        execvp(args[0], args);
        perror("execvp");
        free(args);
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int status;
        if (waitpid(pid, &status, cmd->timeout ? WNOHANG : 0) == -1) {
            perror("waitpid");
        }
        return NULL;
    }
}

void asyncCmdExecutor(Command* commands, int num_commands, oauth2_client_t* client) {
    pthread_t threads[num_commands];
    for (int i = 0; i < num_commands; i++) {
        if (pthread_create(&threads[i], NULL, execute_command, &commands[i]) != 0) {
            perror("pthread_create");
        }
    }
    for (int i = 0; i < num_commands; i++) {
        pthread_join(threads[i], NULL);
    }
}

void log_error(const char* error_message) {
    FILE* log_file = fopen("error_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", error_message);
        fclose(log_file);
    } else {
        perror("fopen");
    }
}

int main() {
    oauth2_client_t* client = oauth2_client_new();
    if (!client) {
        log_error("Failed to create OAuth 2.0 client");
        return EXIT_FAILURE;
    }

    Command commands[] = {
        {"echo Hello", 5},
        {"sleep 10", 3}
    };
    int num_commands = sizeof(commands) / sizeof(commands[0]);

    asyncCmdExecutor(commands, num_commands, client);

    oauth2_client_free(client);
    return EXIT_SUCCESS;
}
```

