import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class DistributedCachingFramework {
    private ConcurrentHashMap<String, CacheEntry> cache;
    private AtomicInteger cacheHitCount;
    private AtomicInteger cacheMissCount;

    public DistributedCachingFramework() {
        this.cache = new ConcurrentHashMap<>();
        this.cacheHitCount = new AtomicInteger(0);
        this.cacheMissCount = new AtomicInteger(0);
    }

    public void put(String key, String value) {
        cache.put(key, new CacheEntry(value));
    }

    public String get(String key) {
        if (cache.containsKey(key)) {
            cacheHitCount.incrementAndGet();
            return cache.get(key).value;
        } else {
            cacheMissCount.incrementAndGet();
            return null;
        }
    }

    public void remove(String key) {
        cache.remove(key);
    }

    public int getCacheHitRate() {
        int hits = cacheHitCount.get();
        int misses = cacheMissCount.get();
        return (hits + misses > 0) ? (int) ((double) hits / (hits + misses) * 100) : 0;
    }

    private static class CacheEntry {
        final String value;

        public CacheEntry(String value) {
            this.value = value;
        }
    }
}
